\section{Technical Remarks} \label{Se:6}

\subsection{\texorpdfstring{
  Well-Definedness of $U(\xi)$ Distribution
}{Well-Definedness of U(xi) Distribution}
}
\label{well-def}


Based on the Random PDE stated in \eqref{eq:RPDE:v2}, we are interested in approximating
its probability distribution, namely $\pushforward{U}{\gamma}$. We would like to know
under what assumptions can we ensure that this distribution is well-defined. Moreover,
does $\pushforward{U}{\gamma}$ depend on the choice of the underlying probability space
$\lr{\Omega,\FF,\p}$?

To answer this, we first define two mappings. Given a stochastic process
%
\begin{equation*}
  f:D\times\Xi\to \R\quad \text{ with }\quad f(\cdot;\xi)\in \tilde\HH\,,
\end{equation*}
%
and
%
\begin{equation*}
  g:\Gamma\times\Xi\to \R\quad \text{ with }\quad g(\cdot;\xi)\in \overline\HH\,,
\end{equation*}
%
we define the evaluation map
%
\begin{equation*}
  Q_{f,g}:\Xi\to \tilde\HH\times\overline\HH\times\Xi\quad \text{ with }\quad \xi\mapsto
  \lr{f(\cdot;\xi),g(\cdot;\xi),\xi}\,.
\end{equation*}
%
Next, we introduce the solution operator
%
\begin{equation*}
  G: \tilde\HH\times\overline\HH\times\Xi \to \HH \text{ with } \lr{\tilde{f},\tilde{g},
  \tilde\xi}\mapsto \tilde{u}(\cdot;\tilde\xi) \,,
\end{equation*}
%
where $\tilde{u}(\cdot;\xi)$ is the solution to the Random PDE (similar to the one in
\eqref{eq:RPDE:v2}) for a fixed $\xi =\tilde\xi$, and with right hand side replaced by
$\tilde{f}$ and $\tilde{g}$.


Then, the solution $U(\xi)$ to the original problem can be represented as:
%
\begin{equation*}
  U(\xi) = G(f(\cdot;\xi),g(\cdot;\xi),\xi) = G \circ Q_{f,g}(\xi).
\end{equation*}
%
A sufficient condition for ensuring both the well-definedness of $\pushforward{U}{\gamma}$
and its invariance with respect to the abstract probability space $\lr{\Omega,\FF,\p}$ is
the following:
%
\begin{itemize}
%  
\item The solution operator $G$ is well-defined for every point in
$\tilde\HH\times\overline\HH\times \Xi$, and
%
\item The composition $G\circ Q_{f,g}(\xi)$ is measurable on each instance of
$\lr{f,g}\in L^2(\gamma;\tilde\HH)\times L^2(\gamma;\overline\HH)$.
%
\end{itemize}
%
Under these conditions, it follows that for any two probability spaces $\lr{\Omega,\FF,\p}$
and $\lr{\tilde\Omega,\tilde\FF,\tilde\p}$, with corresponding random elements
$\xi:\Omega\to\Xi$ and $\tilde\xi:\tilde\Omega\to\Xi$, both having law $\gamma$, we have:
%
\begin{equation*}
  \pushforward{U\circ\xi}{\p}=\pushforward{G\circ Q_{f,g}\circ\xi}{\p}=\pushforward{G\circ
  Q_{f,g}}{\gamma}=\pushforward{G\circ Q_{f,g}\circ\tilde\xi}{\tilde\p} = \pushforward{U\circ
  \tilde\xi}{\p}\,.
\end{equation*}
%
This confirms that the push-forward measure $\pushforward{U}{\gamma}$ is independent of the
choice of the underlying probability space, provided the stated conditions are met.


\subsection{Discrete Neural Network Spaces}

We describe our notation regarding the generic discrete neural network spaces which we
denote by $V _{\mathcal{N}}.$ These are spaces approximating functions 
%
\begin{equation*}
  v : \R ^ {d_{I}} \to \R ^{d_{O}} \,.
\end{equation*}
%
We have used different choices for $d_{I}$ and $d_{O}$ throughout this
paper. To fix ideas, we present a generic structure of the spaces $V _{\mathcal{N}}.$ Of
course several alternative architectures are possible. A \emph{deep neural network} maps
every point $\overline y\in \R ^ {d_{I}}$ to $v_\theta (\overline y) \in \R ^ {d_{O}}$,
through
%
\begin{equation}\label{C_L}
	v_\theta(\overline y)= \mathcal{C}_L (\overline y) :=C_L \circ \sigma \circ C_{L-1} \cdots
	\circ\sigma \circ C_{1} (\overline y) \quad \forall \overline y \in \R ^ {d_{I}}.
\end{equation}

The intermediate  layers $C_k$,   are affine maps of the form 
%
\begin{equation}
	C_k y =
  W_k y +b_k, \qquad \text{where }  W_k \in \R ^ {d_{k+1}\times d_k}, b_k \in \R ^ {d_{k+1}},
\end{equation} 
%
where the dimensions $d_k$ may vary with each layer $k$ and $\sigma (y)$ denotes the
vector with the same number of components as $y$, where $\sigma (y)_i= \sigma(y_i)\, .$
The index $\theta$ represents collectively all the parameters of the network. The space
of parameters is denoted by $\Theta$:
%
\begin{equation*}
  \Theta=\lrr{\theta:=\lr{b_1,W_1,\dots W_L, b_L}: \text{ for }b_i\in\R^{d_k},\,W_i\in
  \R^{d_{k+1}\times d_k}\,, \ k=1, \dots, L }\, .
\end{equation*}
%
The set of networks $\mathcal{C}_L$ with a given architecture of the form \eqref{C_L},
\eqref{C_k} is called $\mathcal{N}.$ Then $\Theta \in \R ^ {\dim{\mathcal {N}}}$ where
the total number of degrees of freedom of $\mathcal {N} ,$ is $\dim{\mathcal {N}}= \sum
_{k=1} ^L d_{k+1} (d_k +1)  .$ The nonlinear discrete set of functions $V _{\mathcal{N}}$
is defined as 
%
\begin{equation}
	V _{\mathcal{N}}= \{ u_\theta : \varOmega _T \to \R ,  \ \text{where }  u_\theta (\x) 
  = \mathcal{C}_L (\x), \ \text{for some } \mathcal{C}_L\in  \mathcal{N}\, \}  \,. 
\end{equation}


\subsection{Neural Networks with Random Input as Generative Models}

In generative modeling, neural networks receive both a standard input and a random input 
(often called the latent code or noise). Formally, assume a probability distribution 
$\gamma$ over $\R^{d_{random}}$ (also known as the seed or reference distribution), and a 
neural network $g_\theta\in\VV_\NN$. Then, the generative model is the random variable:
%
\begin{equation*}
  g_\theta(x;\xi), \qquad\text{ where } \xi\sim \gamma\,.
\end{equation*}
%
This induces a probability distribution over outputs, defined via the pushforward measure:
%
\begin{equation*}
  g_\theta(x;\xi) \sim \pushforward{ g_\theta(x,\cdot)}{\gamma} \,.
\end{equation*}
%
To simplify notation, define:
%
\begin{equation*}
  Q_{\theta,x}(\xi):= g_\theta(x,\xi)
\end{equation*}
%
Then, the output distribution for a fixed input $x$ is:
%
\begin{equation*}
  \mu_\theta(x,\,A) :=
  \gamma\circ Q_{\theta,x}^{-1} (A) = 
  \int_{\mathbb{R}^{d_{\text{random}}}}
  \mathds{1}_{\{g_\theta(x,\xi)\in A\}} \,\gamma(\ud \xi)\,,
  \qquad\forall A\in\Bor{\R^{d_{output}}}.
\end{equation*}
%
If the mapping $g_\theta: \R^{d_{input}}\times\R^{d_{random}}\to\R^{d_{output}}$ is 
measurable with respect to the Borel $\sigma-$algebras 
$\Bor{\R^{d_{input}}\times\R^{d_{random}}}$ and $\Bor{\R^{d_{output}}}$, then the 
following properties hold:
%
\begin{itemize}
%
\item
For every fixed $x\in\R^{d_{input}}$, $\mu_\theta(x,\cdot)$ is a probability measure 
on $\R^{d_{output}}$
%
\item
For every fixed $A\in\Bor{\R^{d_{output}}}$, the function 
$x\mapsto \mu_\theta(x,\,A)$ is measurable with respect to $\Bor{\R^{d_{input}}}$.
%
\item 
$\mu_\theta(\cdot, A)$ is $\Bor{\R^{d_{input}}}/\Bor{\R^{d_{output}}}-$measurable
%
\end{itemize}
%
Therefore, $g_\theta$ defines a stochastic kernel $\mu_\theta(x,\,\ud y)$ from 
$\R^{d_{input}}$ to $\R^{d_{output}}$.

To establish these properties, one can utilise the fact that 
%
\begin{equation*}
  \Bor{\R^{d_{input}}\times\R^{d_{random}}}= \Bor{\R^{d_{input}}}\otimes\Bor{\R^{d_{random}}}\,,
\end{equation*}
%
since both $\R^{d_{input}}$ and $\R^{d_{random}}$ are Polish spaces, see  Theorem 17.25 
in \cite{kechris2012classical}.


