\section{Bounds on minimum distance and covering radius of IrOAs}

\subsection{Bounds on the minimum distance}

Since an OA$(M,n,q,t)$ has index $\lambda=1$ if and only if 
its minimum distance is $d=n-t+1$, it is straightforward to conclude that $d \leqslant n-t$ whenever $\lambda>1$. One next step 
was done in \cite{Boyvalenkov_2022}.


\begin{Theorem}\cite[Theorem IV.5]{Boyvalenkov_2022}\label{3}
Suppose that $\text{OA}(M, n, q, t)$ has index $\lambda > 1$
and $n-t>\lambda(q-1)/(\lambda-1)$. Then $d \leqslant n - t-1$.
\end{Theorem}

\begin{Corollary}\label{00}
For any $\text{IrOA}(M, n, q, t)$ with index $\lambda > 1$, we have
\begin{enumerate}
    \item[{\rm (1)}]  $t+1\leqslant   d \leqslant n - t$.
    \item[{\rm (2)}]  $t+1\leqslant   d\leqslant n - t-1$ if $n-t>\frac{\lambda(q-1)}{\lambda-1}$ and $n\geqslant 2t+2$.
\end{enumerate}
\end{Corollary}

\begin{proof}
Both statements follow from Lemma \ref{1} and Theorem \ref{3}.
\end{proof}

Compared to the bounds in Corollary \ref{00}, we provide a tighter upper bound on the minimum distance of IrOAs for a sufficiently large index $\lambda$, particularly when $\lambda \geqslant q^m$ for some $m > 2$.

\begin{Theorem}\label{05}
Suppose that $\text{IrOA}(M, n, q, t)$ has index $\lambda > 1$. If $\lambda \geqslant q^m$ and $n \geqslant 2t + m$ for some integer $m \geqslant 1$, then
\begin{align*}
  d \leqslant n - t - m + 1.
\end{align*}
\end{Theorem}

\begin{proof}
Since $M=\lambda q^t \geqslant q^{t+m}$, it follows that $\log_q M \geqslant t + m$. Applying the Singleton bound gives
\begin{align*}
d \leqslant n - \lfloor \log_q M \rfloor + 1 \leqslant  n - t - m + 1.
\end{align*}
Note that the condition $n \geqslant 2t + m$ is necessary since we have to comply with the bound $d \geqslant t + 1$ by Lemma \ref{1}.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Bounds on covering radius}

We recall that the covering radius of a code $C \subseteq H_q^n$ is 
\begin{align*}
    \rho=\rho(C) = \max_{x \in H_q^n} \min_{y \in C} d(x, y).
\end{align*}
Regarding the upper bounds for orthogonal arrays, Delsarte bound (see \cite{Delsarte1_1973,Delsarte2_1973}; cf. \cite{Cohen_1985} for a survey) states that $\rho \leqslant n-t$. Some conditional refinements were obtained in \cite{BRS2020}, namely $\rho \leqslant n-t-1$ if $n>t+q-1$ and $\rho \leqslant n-t-2$ if $n>2(t+q-1)$. Note that the Delsarte bound is attained by the RM codes for $m-3 \leqslant r \leqslant m$ and by the RS codes.  For further results on the covering radius of RM, GRM, RS, and GRS codes, see, e.g., \cite{Bartoli_2014, Hou_1993, Leducq_2012}.



If $C \subset H_q^n$ is a code with covering radius $\rho$, then the sphere covering argument gives 
\begin{equation} \label{cov-arg}
|C| \cdot V_q(t, \rho) \geqslant q^{n}, 
\end{equation}
where $V_q(t, \rho) = \sum_{i=0}^\rho \binom{t}{i}(q-1)^i$ is the volume of a (Hamming) ball in $H_q^n$ of radius $\rho$.



The inequality \eqref{cov-arg} and the OAs and IrOAs properties imply the following restrictions. 

\begin{Theorem}\label{099}
We have $\lambda V_q(t,\rho) \geqslant q^{n-t}$ for any $\text{OA}(M, n, q, t)$ and $ V_q(t, \rho) \geqslant q^{t}$ for any $\text{IrOA}(M, n, q, t)$.
\end{Theorem}

\begin{proof}
For the first inequality, it is enough to use $M=\lambda q^t$.
The second inequality follows from $M\leqslant q^{n-t}$, which is true for any IrOA. 
\end{proof}

In the special case $M=q^{n-t}$, we detemine $\rho$.

\begin{Theorem}
The covering radius of any $\text{IrOA}(q^{n-t}, n, q, t)$ is $\rho= t$.    
\end{Theorem}

\begin{proof}
Let $C$ be an $\text{IrOA}(q^{n-t}, n, q, t)$ and $x \in H_q^n \setminus C$. Fix $n-t$ columns in the matrix formed by the codewords of $C$. Since every $(n-t)$-tuple appears exactly once as a row defined by the chosen $n-t$ columns, the point $x$ coincides with a row of $C$ in these $n-t$ columns. Therefore, $x$ and that row of $C$ are different in at most $t$ positions, i.e. $d(x,C) \leqslant t$, whence $\rho \leqslant t$ from the definition of covering radius. 



Assume that $\rho<t$. By the binomial theorem, we obtain 
\begin{align*}
     V_q(t, \rho) = \sum_{i=0}^\rho \binom{t}{i}(q-1)^i < \sum_{i=0}^t \binom{t}{i}(q-1)^i=(1+(q-1))^t=q^t,
\end{align*}
which contradicts the second inequality of Theorem \ref{099}. Therefore, $\rho=t$.
\end{proof}



\begin{Theorem}
The covering radius of any $\text{IrOA}(M, n, q, t)$ satisfies the inequality $ \lfloor t/2\rfloor\leqslant \rho$.
\end{Theorem}

\begin{proof}
It is a well-known result (see \cite[Section 1.12]{Huffman_2010}) that the covering radius of any code $C$ satisfies 
\begin{align*}
    \left\lfloor \frac{d(C)-1}{2}\right\rfloor\leqslant \rho(C),
\end{align*}
where $d(C)$ is the minimum distance. By Lemma \ref{1}, $t+1\leqslant d(C)$, which completes the proof.
\end{proof}



