    \caption{The training algorithm for Breaker.}\label{algo:breaker}
        \KwIn{training steps $T$, number of clusters $K$, clustering loss weight $\lambda$,  target network update frequency $M$}
        \KwOut{trained neural network}
        \Comment*[l]{$\theta$: parameters of embedding layer, REM and CPMM}
        Initialize the main classification network with $\theta$; \;
        \Comment*[l]{$\theta^{-}$: parameters of user embedding layer and user representation extraction in REM}
        Initialize the clustering target network with weights $\theta^{-}=\theta$;\;
        Calculate user representation $E_u$ through REM with $\theta$;\;
        Initialize $K$ centroids $\mu_k$ for $E_u$ using K-means clustering;\;
        \For{$t=1$ \KwTo $T$ \KwBy $1$}{
            Calculate the probabilities $q_{ij}$ and $q'_{ij}$ within the batch using Eq.(\ref{q_ij}), based on $\theta^{-}$ and $\theta$ respectively;\;
            Calculate clustering pseudo-labels $p_{ij}$ in the target network using Eq.(\ref{p_ij});\;
            Calculate clustering loss $\mathcal{L}_c$ using Eq.(\ref{eq:cluster_loss});\;
            Predict user-item preference $\hat{y}$ using Eq.(\ref{eq:final_estimate}) with tower outputs $\hat{y}_c^k$ and probability $q'_{ij}$;\;
            Calculate the pointwise classification loss $\mathcal{L}_p$ and total loss $\mathcal{L}$ using Eq.(\ref{eq:class_loss},\ref{eq:toal_loss});\;
            Perform a gradient descent step on $\mathcal{L}$ with respect to $\theta$ and cluster centroids $\mu_k$;\;
            \Comment*[l]{Parameter delayed update mechanism for the target clustering network}
            Every $M$ steps, reset $\theta^{-}=\theta$; \;
        }
\end{algorithm}


