\section{Pseudocode of \textsc{AdaCT-H}}
\label{app:adacth}

\begin{function}
{\small
	%\caption{AdaCT--H($\Dataset$, $\delta$)}
	\SetKwFunction{function}{function}
	\SetKwProg{myalg}{}{}{}
  	\myalg{\function{\textsc{AdaCT--H}}}{
	%\label{alg:adact}  Use algorithm name \FAdaCT
	%
	\KwIn{Dataset $\Dataset$ containing $N$ traces in $\Episodes_H$, failure probability $0<\delta<1$}
	\KwOut{Set $\Qs$ of RDP states, transition function $\TransitionFn:\Qs \times \Actions\,\Observations \to \Qs$}
	%
	\BlankLine
	$\Qs_0 \gets \{q_0\}$, $\Multiset(q_0) \gets \Dataset$ \tcp*{initial state}
	\For{$t = 0, \dots, H$}{
		$\Qs_{\mathsf{c},t+1} \gets \{qao \Given q\in\Qs_t, ao\in\Actions\,\Observations \}$ \tcp*{get candidate states}
		\lForEach{$qao\in\Qs_{\mathsf{c},t+1}$}{$\Multiset(qao) \gets \{e_{t+1:H} \Given aroe_{t+1:H}\in\Multiset(q)\}$ \hspace*{.25cm} \tcp*[h]{compute suffixes}}
		$q_{\mathsf{m}}a_{\mathsf{m}}o_{\mathsf{m}} \gets \arg\max_{qao\in\Qs_{\mathsf{c},t+1}} |\Multiset(qao)|$ \tcp*{most common candidate}
		$\Qs_{t+1} \gets \{q_{\mathsf{m}}a_{\mathsf{m}}o_{\mathsf{m}}\}$, $\TransitionFn(q_{\mathsf{m}},a_{\mathsf{m}}o_{\mathsf{m}})=q_{\mathsf{m}}a_{\mathsf{m}}o_{\mathsf{m}}$ \tcp*{promote candidate}
		$\Qs_{\mathsf{c},t+1} \gets \Qs_{\mathsf{c},t+1} \setminus \{q_{\mathsf{m}}a_{\mathsf{m}}o_{\mathsf{m}}\}$ \tcp*{remove from candidate states}
		\For{$qao\in\Qs_{\mathsf{c},t+1}$}{
			$\DSimilar \gets \{q'\in\Qs_{t+1} \Given $ not $\textsc{TestDistinct}(t, \Multiset(qao), \Multiset(q'), \delta)\}$ \hspace*{.01cm} \tcp*[h]{confidence test}

			\lIf{$\DSimilar = \emptyset$}{
