\section{Pseudometrics}
\label{app:pseudometric}

We provide the definition of pseudometric spaces.

\begin{definition}[Pseudometrics]
    Given a set $\mathcal K$ and a non-negative function $d: \cX \times \cX \to \Reals$, we call $(\cX, d)$ a pseudometric space with pseudometric $d$, if for all $x, y, z \in \cX$:
    \begin{itemize}
        \item[(i)] $d(x, x) = 0$,
        \item[(ii)] $d(x, y) = d(y, x)$,
        \item[(iii)] $d(x, y) + d(y, z) \geq d(x, z)$.
    \end{itemize}
\end{definition}

If it also holds that $d(x, y) = 0$ iff $x = y$, then $d$ is a metric. 

\section{Proof of theorems}
\label{app:thms}

In this appendix we prove Theorems~\ref{thm:cms} and~\ref{thm:lang} using a series of lemmas. We first describe how to implement \textsc{AdaCT-H} using CMS.

Given a finite set $\cZ$ and a probability distribution $q\in\Delta(\cZ)$, let $\widehat{q}\in\Delta(\cZ)$ be an empirical estimate of $q$ computed using $n$ samples.
CMS can store an estimate $\widetilde{q}$ of the empirical distribution $\widehat{q}$.
In this setting, the vector $v$ contains the empirical counts of each element of $\cZ$, which implies $\norm{v}_1=n$ and $\widehat{q}(z_i)=v_i/n$ for each $z_i\in\cZ$.
The following lemma shows how to bound the error between $\widetilde{q}$ and $\widehat{q}$.

\begin{lemma}
\label{lemma:cms}
Given a finite set $\cZ$, a probability distribution $q\in\Delta(\cZ)$, and an empirical estimate $\widehat{q}\in\Delta(\cZ)$ of $q$ obtained using $n$ samples, let $\widetilde{q}$ be the estimate of $\widehat{q}$ output by CMS with parameters $\delta_c$ and $\varepsilon$. With probability at least $1-|\cZ|\delta_c$ it holds that $\norm{\widetilde{q}-\widehat{q}}_\infty \leq \epsilon$. 
\end{lemma}

\begin{proof}
\citet{cormodeM05cms} show that for a point query that returns an approximation $\widetilde{v}_i$ of $v_i$, with probability at least $1-\delta_c$ it holds that
\[
\widetilde{v}_i \leq v_i + \varepsilon \norm{v}_1.
\]
In our case, the estimated probability of an element $z_i\in\cZ$ equals $\widetilde{q}(z_i)=\widetilde{v}_i/n$, where $\widetilde{v}_i$ is the point query for $z_i$.
Using the result above, with probability at least $1-\delta_c$ we have
\[
\widetilde{q}(z_i) = \frac {\widetilde{v}_i} n \leq \frac {v_i} n + \frac {\varepsilon \norm{v}_1} n = \widehat{q}(z_i) + \varepsilon.
\]
Since CMS never underestimates a value, $\widehat{q}(z_i)\leq\widetilde{q}(z_i)$ trivially holds. Taking a union bound shows that the inequality above holds simultaneously for all $z_i\in\cZ$ with probability $1-|\cZ|\delta_c$.
\end{proof}

The following two lemmas are analogous to Lemmas 13 and 14 of \citet{cipollone2023}.
\begin{lemma}
\label{lemma:upper}
For $t\in[0,H]$, let $\Multiset_1$ and $\Multiset_2$ be multisets sampled from distributions $p_1$ and $p_2$ on $\Delta(\Episodes_{H-t})$.
Assume that we use CMS with parameters $\delta_c=\delta/8(AOR)^{H-t}$ and $\varepsilon=\sqrt{ \log(2/\delta_c) / 2|\Multiset_i| }$ to store an approximation $\widetilde{p}_i$ of the empirical estimate $\widehat{p}_i$ of $p_i$ due to $\Multiset_i$, $i\in[2]$.
If $p_1=p_2$, with probability at least $1-\delta$ the statistical test satisfies
\[
\PrefL(\widetilde{p}_1, \widetilde{p}_2) \leq \sqrt{ \frac {8\log(16(AOR)^{H-t}/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\]
\end{lemma}

\begin{proof}
Hoeffding's inequality states that for each $i\in[2]$, with probability at least $1-\delta_c$ it holds for each $e\in\Episodes_u$, $u\leq H-t$, that
\[
\abs{ \widehat{p}_i(e) - p_i(e) } \leq \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_i|} }.
\]
We can now use Lemma~\ref{lemma:cms} to upper bound the $\PrefL$ metric as
\begin{align*}
L_\Languages(\widetilde{p}_1, \widetilde{p}_2) &= \max_{u\in[0,H-t],e\in\Episodes_u} \abs{\widetilde{p}_1(e) - \widetilde{p}_2(e)}\\
 &\leq \max_{u\in[0,H-t],e\in\Episodes_u} ( \abs{\widetilde{p}_1(e) - \widehat{p}_1(e)} + \abs{\widehat{p}_1(e) - p_1(e)} + \abs{p_1(e) - p_2(e)}\\
  & \hspace*{2.3cm} + \abs{p_2(e) - \widehat{p}_2(e)} + \abs{\widehat{p}_2(e) - \widetilde{p}_2(e)} )\\
 &\leq \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_1|} } + \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_1|} } + \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_2|} } + \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_2|} } \leq \sqrt{ \frac {8\log(2/\delta_c)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\end{align*}
Taking a union bound implies that this holds with probability at least $1-8(AOR)^{H-t}\delta_c=1-\delta$.
\end{proof}

\begin{lemma}
\label{lemma:lower}
For $t\in[0,H]$, let $\Multiset_1$ and $\Multiset_2$ be multisets sampled from distributions $p_1$ and $p_2$ on $\Delta(\Episodes_{H-t})$.
Assume that we use CMS with parameters $\delta_c=\delta/8(AOR)^{H-t}$ and $\varepsilon=\sqrt{ \log(2/\delta_c) / 2|\Multiset_i| }$ to store an approximation $\widetilde{p}_i$ of the empirical estimate $\widehat{p}_i$ of $p_i$ due to $\Multiset_i$, $i\in[2]$.
If $p_1\neq p_2$ and $\min(|\Multiset_1|,|\Multiset_2|)\geq 32 \log (2/\delta_c)/\mu_0^2$, with probability at least $1-\delta$ the statistical test satisfies
\[
\PrefL(\widetilde{p}_1, \widetilde{p}_2) \geq \sqrt{ \frac {8\log(16(AOR)^{H-t}/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\]
\end{lemma}

\begin{proof}
We can use Lemma~\ref{lemma:cms} to lower bound the $\PrefL$ metric as
\begin{align*}
L_\Languages(\widetilde{p}_1, \widetilde{p}_2) &= \max_{u\in[0,H-t],e\in\Episodes_u} \abs{\widetilde{p}_1(e) - \widetilde{p}_2(e)}\\
 &\geq \max_{u\in[0,H-t],e\in\Episodes_u} ( \abs{p_1(e) - p_2(e)} - \abs{\widetilde{p}_1(e) - \widehat{p}_1(e)} - \abs{\widehat{p}_1(e) - p_1(e)}\\
  & \hspace*{2.3cm} - \abs{p_2(e) - \widehat{p}_2(e)} - \abs{\widehat{p}_2(e) - \widetilde{p}_2(e)} )\\
 &\geq \mu_0 - \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_1|} } - \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_1|} } - \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_2|} } - \sqrt{ \frac {\log(2/\delta_c)} {2|\Multiset_2|} }\\
  &\geq \mu_0 - \sqrt{ \frac {8\log(2/\delta_c)} {\min(|\Multiset_1|,|\Multiset_2|)} } \geq \mu_0 - \frac {\mu_0} 2 \geq \frac {\mu_0} 2 \geq \sqrt{ \frac {8\log(2/\delta_c)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\end{align*}
Taking a union bound implies that this holds with probability at least $1-8(AOR)^{H-t}\delta_c=1-\delta$.
\end{proof}

The remainder of the proof of Theorem~\ref{thm:cms} follows exactly the same steps as in the proof of \citet[Theorem 6]{cipollone2023}.
For completeness, we repeat the steps here.
The proof consists in choosing $N=|\Dataset|$ and $\delta$ such that the condition on $\min(|\Multiset_1|,|\Multiset_2|)$ in Lemma~\ref{lemma:lower} is true with high probability for each application of \textsc{TestDistinct}. Consider an iteration $t\in[0,H]$ of \textsc{AdaCT-H}.
For a candidate state $qao\in\Qs_{\mathsf{c},t+1}$, its associated probability is $\Behav\COccupancy_t(q,ao)$ with empirical estimate $\widehat{p}_t(qao)=|\Multiset(qao)| / N$, i.e.~the proportion of episodes in $\Dataset$ that are consistent with $qao$. We can apply an empirical Bernstein inequality to show that
\begin{align*}
\Pr \pa{ \left\lvert \widehat{p}_t(qao) - \Behav\COccupancy_t(q,ao) \right\rvert \geq \sqrt{\frac{2\widehat{p}_t(qao)\ell} N} + \frac {14\ell} {3N} = \frac { \sqrt{ 2M\ell } + 14\ell/3 } N } \leq \delta,
\end{align*}
where $M=|\Multiset(qao)|$, $\ell=\log(4/\delta)$, and $\delta$ is the failure probability of \textsc{AdaCT-H}. To obtain a bound on $M$ and $N$, assume that we can estimate $\Behav\COccupancy_t(q,ao)$ with  accuracy $\Behav\COccupancy_t(q,ao) / 2$, which yields
\begin{align}
\frac {\Behav\COccupancy_t(q,ao)} 2 &\geq \frac { \sqrt{ 2M\ell } + 14\ell/3 } N\label{eq:Nocc}\\
\widehat{p}_t(qao) &\geq \Behav\COccupancy_t(q,ao) - \frac { \sqrt{ 2M\ell } + 14\ell/3 } N \geq \Behav\COccupancy_t(q,ao) - \frac {\Behav\COccupancy_t(q,ao)} 2 = \frac {\Behav\COccupancy_t(q,ao)} 2.
\end{align}
Combining these two results, we obtain
\begin{align}
M &= N\widehat{p}_t(qao) \geq N\Behav\COccupancy_t(q,ao)/2 \geq \frac N {2N} \pa{ \sqrt{ 2M\ell } + 14\ell/3 } = \frac 1 2 \pa{ \sqrt{ 2M\ell } + 14\ell/3 }.\label{eq:NM}
\end{align}
Solving for $M$ yields $M\geq 4\ell$, which is subsumed by the bound on $M$ in Lemma~\ref{lemma:lower} since $\CDistinguish<1$.
Hence the bound on $M$ in Lemma~\ref{lemma:lower} is sufficient to ensure that we estimate $\Behav\COccupancy_t(q,ao)$ with accuracy $\Behav\COccupancy_t(q,ao) / 2$.
We can now insert the bound on $M$ from Lemma~\ref{lemma:lower} into \eqref{eq:Nocc} to obtain a bound on $N$:
\begin{align}\label{eq:N1}
N &\geq \frac {2 ( \sqrt{ 2M\ell } + 14\ell/3) } {\Behav\COccupancy_t(q,ao)} \geq \frac {2\ell} {\Behav\COccupancy_t(q,ao)} \pa{ \frac 8 \CDistinguish \sqrt{\frac {(H-t)\log(4ARO)} \ell + 1 } + \frac {14} 3 } \equiv N_1.
\end{align}
To simplify the bound, we can choose any value larger than $N_1$:
\begin{align}
N_1 &\leq \frac {2\ell} {\Behav\COccupancy_t(q,ao)} \pa{ \frac 8 \CDistinguish \sqrt{H\log(4ARO) + H\log(4ARO) } + \frac {14} {3\CDistinguish} \sqrt{H\log(4ARO)} }\nonumber\\
 &< \frac {32\ell} {\Behav\COccupancy_{\min}\,\CDistinguish} \sqrt{H\log(4ARO)} \equiv N_0,
\end{align}
where we have used $\Behav\COccupancy_t(q,ao)\geq \Behav\COccupancy_{\min}$, $\CDistinguish<1$, $\ell=\log 4 + \log(1/\delta)\geq 1$, $H\log(4ARO)\geq\log 4\geq 1$ and $8\sqrt{2} + 14/3 < \frac {32} 2$. Choosing $\delta=\delta_0/2QAO$, a union bound implies that accurately estimating $\Behav\COccupancy_t(q,ao)$ for each candidate state $qao$ and accurately estimating $p(e_{0:u}*)$ for each prefix in the multiset $\Multiset(qao)$ associated with $qao$ occurs with probability $1-2QAO\delta=1-\delta_0$, since there are at most $QAO$ candidate states. Ignoring logarithmic terms, this equals the bound in the theorem.

It remains to show that the resulting RDP is minimal. We show the result by induction. The base case is given by the set $\Qs_0$, which is clearly minimal since it only contains the initial state $q_0$. For $t\in[0,H]$, assume that the algorithm has learned a minimal RDP for sets $\Qs_0,\ldots,\Qs_t$. Let $\Qs_{t+1}$ be the set of states at layer $t+1$ of a minimal RDP. Each pair of histories that map to a state $q_{t+1}\in\Qs_{t+1}$ generate the same probability distribution over suffixes. Hence by Lemma~\ref{lemma:upper}, with high probability \textsc{TestDistinct}$(t,\Multiset(qao),\Multiset(q'a'o'),\delta)$ returns false for each pair of candidate states $qao$ and $q'a'o'$ that map to $q_{t+1}$. Consequently, the algorithm merges $qao$ and $q'a'o'$. On the other hand, by assumption, each pair of histories that map to different states of $\Qs_{t+1}$ have $\PrefL$-distinguishability $\CDistinguish$. Hence by Lemma~\ref{lemma:lower}, with high probability \textsc{TestDistinct}$(t,\Multiset(qao),\Multiset(q'a'o'),\delta)$ returns true for each pair of candidate states $qao$ and $q'a'o'$ that map to different states in $\Qs_{t+1}$. Consequently, the algorithm does not merge $qao$ and $q'a'o'$. It follows that with high probability, \FAdaCT will generate exactly the set $\Qs_{t+1}$, which is that of a minimal RDP.

The proof of Theorem~\ref{thm:lang} is achieved by proving two very similar lemmas.

\begin{lemma}
For $t\in[0,H]$, let $\Multiset_1$ and $\Multiset_2$ be multisets sampled from distributions $p_1$ and $p_2$ on $\Delta(\Episodes_{H-t})$, and let $\widehat{p}_1$ and $\widehat{p}_2$ be empirical estimates of $p_1$ and $p_2$ due to $\Multiset_1$ and $\Multiset_2$, respectively.
If $p_1=p_2$, with probability at least $1-\delta$ the statistical test satisfies
\[
L_\Languages(\widehat{p}_1, \widehat{p}_2) \leq \sqrt{ \frac {2\log(4|\Languages|/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\]
\end{lemma}

\begin{proof}
Let $\delta_\ell=\delta/2|\Languages|$.
Hoeffding's inequality states that for each $\Language\in\Languages$ and each $i\in\{1,2\}$, with probability at least $1-\delta_\ell$ it holds that
\[
\abs{ \widehat{p}_i(\Language) - p_i(\Language) } \leq \sqrt{ \frac {\log(2/\delta_\ell)} {2|\Multiset_i|} }.
\]
We can now upper bound the language metric as
\begin{align*}
L_\Languages(\widehat{p}_1, \widehat{p}_2) &= \max_{\Language \in \Languages} \abs{\widehat{p}_1(\Language) - \widehat{p}_2(\Language)}\\
 &\leq \max_{\Language \in \Languages} ( \abs{\widehat{p}_1(\Language) - p_1(\Language)} + \abs{p_1(\Language) - p_2(\Language)} + \abs{p_2(\Language) - \widehat{p}_2(\Language)} )\\
 &\leq \sqrt{ \frac {\log(2/\delta_\ell)} {2|\Multiset_1|} } + 0 + \sqrt{ \frac {\log(2/\delta_\ell)} {2|\Multiset_2|} } \leq \sqrt{ \frac {2\log(2/\delta_\ell)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\end{align*}
Taking a union bound implies that this bound holds with probability at least $1-2|\Languages|\delta_\ell=1-\delta$.
\end{proof}

\begin{lemma}
For $t\in[0,H]$, let $\Multiset_1$ and $\Multiset_2$ be multisets sampled from distributions $p_1$ and $p_2$ on $\Delta(\Episodes_{H-t})$, and let $\widehat{p}_1$ and $\widehat{p}_2$ be empirical estimates of $p_1$ and $p_2$ due to $\Multiset_1$ and $\Multiset_2$, respectively.
If $p_1\neq p_2$ and $\min(|\Multiset_1|,|\Multiset_2|)\geq 8\log(4|\Languages|/\delta)/\mu_0^2$, with probability at least $1-\delta$ the statistical test satisfies
\[
L_\Languages(\widehat{p}_1, \widehat{p}_2) \geq \sqrt{ \frac {2\log(4|\Languages|/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\]
\end{lemma}

\begin{proof}
We can lower bound the language metric as
\begin{align*}
L_\Languages(\widehat{p}_1, \widehat{p}_2) &= \max_{\Language \in \Languages} \abs{\widehat{p}_1(\Language) - \widehat{p}_2(\Language)}\\
 &\geq \max_{\Language \in \Languages} ( \abs{p_1(\Language) - p_2(\Language)} - \abs{\widehat{p}_1(\Language) - p_1(\Language)} - \abs{p_2(\Language) - \widehat{p}_2(\Language)} )\\
 &\geq \mu_0 - \sqrt{ \frac {\log(2/\delta_\ell)} {2|\Multiset_1|} } - \sqrt{ \frac {\log(2/\delta_\ell)} {2|\Multiset_2|} } \geq \mu_0 - \sqrt{ \frac {2\log(4|\Languages|/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }\\
 &\geq \mu_0 - \frac {\mu_2} 2 \geq \frac {\mu_0} 2 \geq \sqrt{ \frac {2\log(4|\Languages|/\delta)} {\min(|\Multiset_1|,|\Multiset_2|)} }.
\end{align*}
Taking a union bound implies that this bound holds with probability at least $1-2|\Languages|\delta_\ell=1-\delta$.
\end{proof}
The remainder of the proof of Theorem~\ref{thm:lang} is analogous to that of Theorem~\ref{thm:cms}.
However, we no longer get a term $\sqrt{H}$ from $\sqrt{\log((AOR)^H)}$ unless the number of languages in $\Languages$ is exponential in $H$.

\section{Details of the experiments}
\label{app:exps}

In this appendix we describe each domain in detail and include examples of RDPs learned by \textsc{AdaCT-H}.

\subsection{Corridor}
This RDP example was introduced in  \citet{ronca_2021_EfficientPACa}. The environment consists of a $2\times m$ grid, with only two actions $a_0$ and $a_1$ which moves the agent to states $(0,i+1)$ and $(1,i+1)$ respectively from state $(\cdot, i)$. The goal of the agent is to avoid an enemy which is present in position $(0,i)$ with probability $p_i^0$, and at $(1,i)$ with probability $p_i^1$. The agent receives a reward of $+1$ for avoiding the enemy at a particular column, and the probabilities $p_i^0$ and $p_i^i$ are switched every time it encounters the enemy. When the agent reaches the last column, its position is reset to the first column. The observation space is given by $(i,j,e)$, where $i,j$ is the cell position of the agent and $e \in \{\textit{enemy}, \textit{clear} \}$ denotes the presence of the guard in the current cell. Fig \ref{fig:corridor} shows the minimal automaton obtained by all three algorithms for $H=5$.
\begin{figure}[h!]
  \centering
  \includegraphics[scale=0.28]{figures/prison-guard_1.3.png}
  \caption{Automaton obtained from the corridor environment. The edges are labelled as [$\textit{action}$, $\textit{observation}$, $\textit{enemy}$].}
  \label{fig:corridor}
\end{figure}


\subsection{T-maze}
The T-maze environment was introduced by Bakker~\cite{bakker2001rlandlstm} to capture long term dependencies with RL-LSTMs. As shown in Figure \ref{fig:tmaze}, at the initial position $S$, the agent receives an observation $X$, depending on the position of the goal state $G$ in the last column. The agent can take four actions, $\textit{North}$, $\textit{South}$, $\textit{East}$ and $\textit{West}$. The agent receives a reward of $+4$ on taking the correct action at the T-junction, and $-1$ otherwise, terminating the episode. The agent also recieves a $-1$ reward for standing still. At the initial state the agent receives observation $011$ or $110$, $101$ throughout the corridor and $010$ at the T-junction. Fig \ref{fig:tmaze} shows the optimal automaton obtained when the available actions in the corridor are restricted to only $East$ (the automaton obtained without this restriction is shown in~Fig.~\ref{fig:tmaze_unres}). Table~\ref{table:1} shows our results with the unrestricted action space. Both our approaches find the optimal policy in this case, unlike Flex-Fringe which fails to capture this long term dependency. 
