\begin{define}[Information-Constrained Simple Binary Hypothesis Testing]\label{dfn:info_hyp}
Let $P$ and $Q$ be a pair of distributions on a discrete set $\cX$. Let $\pi\in(0,0.5]$ and $\Theta \sim \Ber(\pi)$. When $\Theta = 0$ (resp.\ $\Theta = 1$) we have $X_i\overset{i.i.d.}{\sim}Q$ (respectively $X_i\overset{i.i.d.}{\sim}P$). Let $\delta\in(0,1)$ and $\cT$ a convex set of channels with input space $\cX$ and output space $\cY$. Consider the channel and estimator pair $(T,\hat{\theta})$ where $\mathbf{T}=(T^1,T^2,\dots,T^n)$ is a sequence of $n$ channels where all channels have the same output space $\cY$, 
% from $\cT$
% \anote{This does not seem to capture the third category below (sequential interactivity), where $T_i$ is a channel that also takes $Y_{1:i-1}$. I think we need to make this definition clearer,} 
and $\hat{\theta}:\cY^n\rightarrow\{0,1\}$ is the tester. %\anote{What about public versus private randomness? Does that affect anything? we should definitely add a remark for it. Varun: Agreed. I want to say that public randomness is useless since you can simply condition on one particular realisation of the public random variable and arrive at a good private protocol, be it sequential, non-id, or id. But I want to think about it a bit. \new{TODO}}
\begin{enumerate}

   \item 
    (Unconstrained) We denote the problem of simple binary hypothesis testing without constraints between two distributions $P$ and $Q$, with prior $\pi$ and error probability $\delta$ as $\cB_B(P,Q,\pi,\delta)$. The sample complexity of simple binary hypothesis testing, denoted by $n^*(P,Q,\pi,\delta)$, is the smallest number of samples $n$ for which there exists a test $\hat \theta$ satisfying 
    \begin{equation}\label{eq:hp_def_1}
        \pi \cdot \prob_{X\sim P^{\otimes n}}[\hat{\theta}(X)\neq 1]+\alb \cdot \prob_{X\sim Q^{\otimes n}}[\hat{\theta}(X)\neq 0]\leq \delta,
    \end{equation}
    where we use the shorthand $X = (X_1, \dots, X_n)$.
    \item (Identical) 
    $\mathbf{T}=(T,T,\dots,T)$ where $T\in\cT$. We say that the pair $(T,\hat{\theta})$ solves the information constraint hypothesis testing problem in identical channel setting with $n$ samples with prior $\pi$ and error probability $\delta$ if 
    \begin{equation}\label{eq:hp_def}
        \pi \cdot \prob_{X\sim P^{\otimes n}}[\hat{\theta}(Y)\neq 1]+\alb \cdot \prob_{X\sim Q^{\otimes n}}[\hat{\theta}(Y)\neq 0]\leq \delta\,.
    \end{equation}
    In the above, we denote $(X_1,X_2,\dots,X_n)$ by $X$ and $(Y_1,Y_2,\dots,Y_n)$ by $Y$. Also, we assume that we have $Y_i=T(X_i)$. The sample complexity $\nsid(P,Q,\pi,\delta,\cT)$ of information-constrained hypothesis testing with identical channels is the smallest $n$ for which there exists a pair of channel and tester $(T,\hat{\theta})$ that solves the problem with $n$ samples. 
        \item (Non-identical and non-interactive)
        $\mathbf{T}=(T^1,T^2,\dots,T^n)$ where $T^i\in\cT$. We say that the pair $(\mathbf{T},\hat{\theta})$ solves the information-constrained hypothesis testing with non-identical (and non-interactive) channels if they satisfy \cref{eq:hp_def} where $Y_i=T^i(X_i)$. The sample complexity is denoted by $\nsnid(P,Q,\pi,\delta,\cT)$.
    \item (Sequentially interactive) 
    $\mathbf{T}=(T^1,T^2,\dots,T^n)$ and each $T^i$ is a channel from $\cX\times\cY^{i-1}$ to $\cY$, such that for any fixed $(y_1,y_2,\dots,y_{i-1})$, the stochastic map $(X_i,y_1,y_2,\dots,y_{i-1}) \mapsto Y_i$ is in $\cT$.  
    % $T^i: (X_i,y_1,y_2,\dots,y_{i-1}) \to Y_i$ is in $\cT$. 
    We say that the pair $(\mathbf{T},\hat{\theta})$ solves this problem if they satisfy \cref{eq:hp_def} where $Y_i=T^i(X_i,Y_1,Y_2,\dots,Y_{i-1})$. We denote the sample complexity of this problem by $\nsseq(P,Q,\pi,\delta,\cT)$.
\end{enumerate}
