To answer these two questions, we develop two main technical results that might be of independent interest: (i) a one-shot lower bound on the error probability of simple binary hypothesis testing (\Cref{thm:one-shot}); and (ii) and a sharp reverse data-processing inequality for the Hellinger-$\lambda$ divergences (\Cref{revdatainf}). A notable application of (i) is that it yields a short and neat proof of the formula for $n^*(P, Q, \pi, \delta)$, whose discovery was the primary contribution in \cite{PenEtal24b}; see \Cref{samplecomplxsimplecor}.


\subsection{Preliminaries}
We provide some basic definitions and facts about hypothesis testing and $f$-divergences that are needed to discuss our results.
\begin{define}[$f$-divergence \cite{powu2025}]\label{dfn: f-div}
    Let $f:[0,\infty]\rightarrow\real\cup\{\infty\}$ be a convex function with $f(1)=0$. For two distributions $P$ and $Q$ we define $D_f(\mu\parallel\nu)$ to be
    \begin{equation}
        D_f(P\parallel Q)=\E_{Q}\left[f\left(\frac{dP}{dQ}(Z)\right)\mathbbm{1}_{\{\frac{dP}{dQ}(Z)<\infty\}}\right]+f'(\infty)P\left(\frac{dP}{dQ}(Z)=\infty\right).
    \end{equation}
\end{define}
\begin{fact}[Convexity of $f$-divergences]\label{fact:fdiv-cvx}
    All f-divergences are jointly convex in both inputs.
\end{fact}
\begin{define}[Hellinger-$\lambda$ divergence]
    For any $\lambda\in(0,1)$ we define the Hellinger-$\lambda$ divergence between two distributions $P$ and $Q$ as $H_{\lambda}(P,Q)=1-\E_Q\left[\left(\frac{dP}{dQ}\right)^\lambda\right]$. We also define $\betl(P,Q)=\E_Q\left[\left(\frac{dP}{dQ}\right)^\lambda\right]=1-H_{\lambda}(P,Q)$ to be the Hellinger-$\lambda$ affinity. Hellinger-$\lambda$ is an $f$-divergence with $f(x)=1-x^\lambda$.
\end{define}

\begin{fact}[Tensorisation of Hellinger affinity]
 Hellinger affinity tensorises; i.e., for every $\lambda\in(0,1)$ and any $P$, $Q$ any $n\in\mathbb{N}$ we have
 %   \begin{equation*}
        $\betl(P^{\otimes n},Q^{\otimes n})=\left(\betl(P,Q)\right)^n.$
%    \end{equation*}
\end{fact}
%The next fact gives a relation between different Hellinger-$\lambda$ divergences. %For a proof, see Proposition 2.48 of \cite{bar2002complexity}.
\begin{fact}[Inequality between Hellinger-$\lambda$ divergences \cite{bar2002complexity}]\label{Hlambdaupper}
    For any pair of distributions $\mu$ and $\nu$ and
    $\forall\ 0<\alpha<\beta<1$, we have
    %\begin{equation*}
       $ \frac{\alpha}{\beta}H_{\beta}(\mu,\nu)
        \leq
        H_{\alpha}(\mu,\nu)
        \leq
        \frac{1-\alpha}{1-\beta}H_{\beta}(\mu,\nu)$.
    %\end{equation*}
\end{fact}
%In the next fact we define the optimal Bayes error and state a classical upper bound for it.

\begin{fact}[Optimal Bayes error]\label{fact: bayes}
Consider $\cB_B(P,Q,\pi,\delta)$ as in Definition~\ref{dfn:info_hyp}. Let $e_\pi(P,Q)$ denote the minimum error probability over all estimators $\hat{\theta}:\cX\rightarrow\{0,1\}$ based on a single sample $X$. The following facts are folklore~\cite{HelRav70}:

\begin{enumerate}
\item
The error of the optimal estimation is
    %\begin{equation}
       $e_\pi(P,Q)=\sum_{x\in \cX}\min\{\pi P(x),\alb Q(x)\}.$
    %\end{equation}

\item
For any $\lambda\in [0,1]$ we have
  %  \begin{equation}\label{eq: classical_ub}
       $e_\pi(P,Q)\leq \pi^\lambda {\alb}^{\lamb}\betl(P,Q).$
  %  \end{equation}
\end{enumerate}
\end{fact}
\paragraph{Notation:}
