\section{Distributed Simple Hypothesis Testing Under Communication Constraint}\label{disthyp}
In light of \cref{id-nonid-channels}, it is evident that to study the sample complexity of distributed simple hypothesis testing with sequential interaction and constraints given by a set of channels $\cT$, it is enough to study $\inf_{T\in\cT}\betls(TP,TQ)$. %we have seen that the sample complexity of the distributed simple binary hypothesis testing under constraints, when we are free to use interaction between sensors to design channels, is within a constant factor of the sample complexity when we are obliged to use the same channel for all sensors. Also, from \cref{samplecomplxsimplecor}, we know that when all channels are the same, say $T\in\cT$, the sample complexity is equal to $\frac{\log(\frac{\pi}{\delta})}{\log\frac{1}{\betls(TP,TQ)}}$ (up to constant factors, under mild regularity conditions). Hence, to determine the sample complexity of distributed simple hypothesis testing with sequential interaction and constraints given by a set of channels $\cT$, it is enough to study $\inf_{T\in\cT}\betls(TP,TQ)$. 
In this section, we consider communication (or quantisation) constraints. We define $\cT_D$ as the set of all channels from $\cX$ to $\cY$ where $|\cY|=D$, i.e., each $X_i$ must be quantised to one of $D$ values before transmitting it to the central server. Without loss of generality, we assume $\cY = \{1, 2, \dots, D\}$. In \cite{PenEtal24a}, it was shown that the set $\cT_D$ is a convex polytope whose extreme points are \emph{threshold channels}, defined as follows.


\begin{define}[Threshold channels]\label{def: threshold}
We say $T\in\cT_D$ is a threshold channel if $T$ is characterised by disjoint intervals $\{I_1,I_2,\dots,I_D\}$ covering $\real$, where $T(x)=i$ if and only if $\frac{dP}{dQ}(x)\in I_i$. 
\end{define}

Observe that minimising the Hellinger affinity is equivalent to maximising the Hellinger divergence. % the problem of finding a channel that minimises the Hellinger-$\ls$ affinity between $TP$ and $TQ$ is identical to that of finding a channel that maximises the Hellinger-$\ls$ divergence, since $\betls(TP,TQ)=1-H_{\ls}(TP,TQ)$.
 Standard data-processing results imply that 
%\begin{align*}
$H_{\ls}(TP, TQ) \le H_{\ls}(P,Q).$
%\end{align*}
We require lower bounds on $\sup_{T \in \cT_D}H_{\ls}(TP, TQ)$ in terms of $H_{\ls}(P,Q)$; i.e., a ``reverse'' data-processing inequality. Such an inequality was shown in \cite{PenEtal23} for the Hellinger-$1/2$ divergence. Our main technical result of this section is a reverse data-processing inequality for a large class of $f$-divergences that we call \emph{TV-like} $f$-divergences. These are defined as follows: 
\begin{define}[TV-like $f$-divergence]\label{def: tv_f}
We say $D_{f}(P\parallel Q)\triangleq \E_Q[f(\frac{dP}{dQ})]$ is a \textbf{TV-like f-divergence} if $f(x)$ is a non-negative, convex function on $\real_+\cup\{+\infty\}$ with $f(1)=0$ which satisfies
\begin{enumerate}
    \item There exist $b,B\in \real_+$ such that $f$ is bounded by $B$ in $[0,b]$; i.e., for all $x\in[0,b]$, $f(x)\le B$.
    \item There exist $C_1,C_2\geq 0$ such that $f$ is almost linear on $(b, \infty)$; i.e., for all $x\in(b,\infty]$,  $C_1 x\leq f(x)\leq C_2 x$.
\end{enumerate}
\end{define}


%We state and prove a reverse data-processing inequality for a wide range of $f$-divergences. Specifically, this result holds for the divergences $D_f(.\parallel.)$ where $f(x)$ is bounded in the interval between zero and some positive number $b>0$, and exhibits linear behavior for $x\geq b$. We provide the following definition for this type of f-divergences which we call \textbf{TV-like f-divergence}.

%\begin{rem}
    Some notable f-divergences that satisfy the definition above are $TV$, Hellinger-$1/2$, and indeed, all Hellinger-$\lambda$ divergences (c.f.\ \cref{Hlamnice}). Kullback--Leibler and $\chi^2$ divergences are not TV-like (because $f(x) = x\log x$ and $f(x) = x^2-1$ are superlinear). %Finally, the convexity of $f$ is largely irrelevant: A ``divergence'' defined using any $f$ that is monotonically decreasing on $[0,b]$ and increasing on $(b, \infty)$ satisfies a reverse data-processing inequality (although it may not satisfy the usual data-processing inequality).
%\end{rem}

%The following theorem states our main result of this section.
\setcounter{thr}{3}
\begin{thr}[Reverse data-processing inequality for TV-like divergences]\label{revdata}
    Let $P$ and $Q$ be two discrete distributions, and let $D_f$ be a TV-like f-divergence with parameters $b,B,C_1,C_2$. Then for any $D\geq 2$ there exists a threshold quantizer $T^*\in \cT_D$ such that the following inequality holds \begin{equation}
        D_f(T^*P\parallel T^*Q)
        \geq
        \frac{1}{52}\min\left\{1,\frac{26C_1}{C_2},\frac{D}{R}\right\}D_f(P\parallel Q), 
    \end{equation}
    where $R=1+\log(\frac{2B}{D_f(P\parallel Q)})$ and in the special case where $P$ and $Q$ are supported on points $k$, we can put $R=\min\{k,1+\log(\frac{2B}{D_f(P\parallel Q)})\}$. 
\setcounter{thr}{6}
    %\textcolor{red}{Where does the bound proved in Case 1 appear? It should be max of two terms shown in Case 1 and Case 2, right}\textcolor{blue}{You are right, I ignored the constant factor $\frac{C_1}{2C_2}$ I put this in the min.}
\end{thr}

\begin{proof}[Proof of \cref{revdata}]
    We can write $D_f(P\parallel Q)$ as the sum of two terms 
    \begin{equation}
    D_f(P\parallel Q)
    =
    \underbrace{\E_Q\left[f\left(\frac{dP}{dQ}\right)\mathbbm{1}_{\{\frac{dP}{dQ}\leq b\}}\right]}_{S_1}
    +\underbrace{\E_Q\left[f\left(\frac{dP}{dQ}\right)\mathbbm{1}_{\{\frac{dP}{dQ}> b\}}\right]}_{S_2}
    \end{equation}
    Now either $S_1\geq\frac{1}{2}D_f(P\parallel Q)$ or $S_2\geq\frac{1}{2}D_f(P\parallel Q)$. We analyse these cases separately.\vspace{0.2cm}\\
    \textbf{Case 1.} Suppose $S_2\geq\frac{1}{2}D_f(P\parallel Q)$. Then we have
    \begin{equation}
        \frac{1}{2}D_f(P\parallel Q)
        \leq 
        \E_Q\left[f\left(\frac{dP}{dQ}\right)\mathbbm{1}_{\{\frac{dP}{dQ}> b\}}\right]
        \leq
        C_2 P\left[\frac{dP}{dQ}>b\right],
    \end{equation}
    where we used the fact that $f(x)\leq C_2 x$ for $x>b$.
    Now consider the two-level quantiser $T^*$ that maps any input $x\in\cX$ with $\frac{dP}{dQ}(x)>b$ to $a_1$ and maps the input to $a_2$ otherwise. For this quantiser,
    \begin{equation}
        D_f\left(T^*P\parallel T^*Q\right)
        \geq
        Q\left[\frac{dP}{dQ}>b\right]f\left(\frac{P\left[\frac{dP}{dQ}>b\right]}{Q\left[\frac{dP}{dQ}>b\right]}\right)
        \geq
        C_1 P\left[\frac{dP}{dQ}>b\right].
    \end{equation}
    For the last inequality, we used the fact that $f(x)\geq C_1 x$ for $x>b$. Combining the two bounds above, we obtain
    \begin{equation}
        D_f(T^*P\parallel T^*Q)
        \geq
        \frac{C_1}{2C_2}D_f(P\parallel Q).
    \end{equation}
%    Thus, we can preserve a constant fraction of the $f$-divergence in this case.

    \textbf{Case 2.} Suppose $S_1\geq\frac{1}{2}D_f(P\parallel Q)$. Define the random variable $Z$ as $Z=f\left(\frac{dP}{dQ}(X)\right)\mathbbm{1}_{\{\frac{dP}{dQ}(X)\leq b\}}$ where $X \sim Q$. Note that $\E[Z]=S_1\geq\frac{1}{2}D_f(P\parallel Q)$. We now recall a reverse Markov inequality originally proved in \cite[Lemma 3.10]{PenEtal23}. 
        \begin{lem}[Reverse Markov inequality \cite{PenEtal23}]
    \label{lem:revMarkovD}
    Let $Z$ be a random variable over $[0, B)$ with expectation $\E[Z] > 0$. Let $R = 1 +  \log(B/\E [Y])$. Then
    \begin{align}
    \label{revMarkov}
    \sup_{0 \le \eta_1 \le  \cdots \le \eta_D = B} \sum_{j=1}^{D-1} \eta_{j} \prob\left( Z \in [\eta_{j}, \eta_{j+1}) \right) \geq \frac{1}{13} \E[Z] \min \left\{1, \frac{D}{R}  \right\}.
    \end{align}
    For the special case where $Z$ is supported on $k$ points, we may set $R = \min\{k,1 +  \log(B/\E [Y])\}$, and there is a $\poly(k,D)$ algorithm to find $\nu_j$'s that achieve the bound~\eqref{revMarkov}.
    \end{lem}

    Because $Z\in[0,B)$ we can use \cref{lem:revMarkovD} to get the following inequality
    \begin{align}
    \sup_{0\leq\eta_1\leq\dots\leq\eta_D=B}\sum_{i=1}^{D-1}\eta_i\prob[Z\in[\eta_i,\eta_{i+1})]
    \geq &
    \frac{1}{13}\min\left\{1,\frac{D}{1+\log(\frac{B}{\E[Z]})}\right\}\E[Z]
    \geq \nonumber\\&
    \frac{1}{26}\min\left\{1,\frac{D}{1+\log(\frac{2B}{D_f(P\parallel Q)})}\right\}D_f(P\parallel Q). \label{revmarkz}
    \end{align} 
    Consider any partition 
    $\{0\leq\eta_1\leq\dots\leq\eta_D=B\}$.    %\begin{equation}\label{lastineqdata}
%        D_f(T^*P\parallel T^*Q)
%        \geq 
%        \sum_{i=1}^{D-1}\eta_i\prob[Z\in[\eta_i,\eta_{i+1})].
%    \end{equation}
    For each $[\eta_i,\eta_{i+1})$ define $\{I_i^j\}_{j=1}^t$ to be the preimage of $[\eta_i,\eta_{i+1})$ under the function $f$ i.e. $f^{-1}([\eta_i,\eta_{i+1}))$.  Note that $I_i^j$ is always an interval and $t \le 2$ can be at most equal to 2, so, here we make the assumption that if $t=1$ we set $I_i^2=\emptyset$. For $T^*$ that maps $x\rightarrow w^j_i$ when $\frac{dP}{dQ}(x)\in I^j_i$, we have
    \begin{align}
    \sum_{i=1}^{D-1}\eta_i\prob[Z\in[\eta_i,\eta_{i+1})]
    =&
    \sum_{i=1}^{D-1}\sum_{j=1}^{2} \eta_i Q\left[\frac{dP}{dQ}\in I_i^j\right]
    \leq \nonumber \\&
    \sum_{i=1}^{D-1}\sum_{j=1}^{2} Q\left[\frac{dP}{dQ}\in I_i^j\right]f\left(\frac{P[\frac{dP}{dQ}\in I_i^j]}{Q[\frac{dP}{dQ}\in I_i^j]}\right)
    =
    D_f(T^*P\parallel T^*Q). \label{lastineqdata}
    \end{align}
    Where the inequality follows from the fact that $\frac{P[\frac{dP}{dQ}\in I_i^j]}{Q[\frac{dP}{dQ}\in I_i^j]}\in I_i^j$, 
    so we have $f\left(\frac{P[\frac{dP}{dQ}\in I_i^j]}{Q[\frac{dP}{dQ}\in I_i^j]}\right)\geq \eta_i$. Without loss of generality we can assume that $D$ is even and then we get the final result from the combination of \cref{lastineqdata} and \cref{revmarkz}.
\end{proof}

In the following theorem we state our main result about the sample complexity of simple binary hypothesis testing under communication constraints.

