\begin{proof}[Proof of \cref{thm: sc_D}]
    We start with the proof of the upper bound. Our first lemma states that  $H_\lambda$ are TV-like divergences. The proof is a routine calculation and is deferred to \Cref{app:Hlamnice}.
    \begin{restatable}[Hellinger-$\lambda$ divergence is TV-like]{lem}{Hlamnice}\label{Hlamnice}
        For any $\lambda\in(0,1)$, $H_\lambda(P,Q)=1-\E[(\frac{dP}{dQ})^\lambda]$ is a TV-like f-divergence.
    \end{restatable}
    Now set $H_*\triangleq\sup_{T\in\cT_D}H_{\ls}(TP,TQ)$ for $\ls$ chosen as \cref{thm: e_alpha_lb} and let $\beta_*=1-H_*$. From the argument in \Cref{subsec:compare} we know that $\nsseq(P,Q,\pi,\delta,\cT_D)\asymp \frac{\log(\frac{\pi}{\delta})}{\log(\frac{1}{\beta_*})}$ and because for $x\in(0,0.5)$ we have $e^{-2x}\leq 1-x\leq e^{-x}$ we conclude that $\nsseq(P,Q,\pi,\delta,\cT_D)\asymp \frac{\log(\frac{\pi}{\delta})}{H_*}$. We use the fact from \cref{Hlamnice} and \cref{revdata} to conclude that we have $H_*\gtrsim \frac{D}{\log\left(\frac{1}{H_{\ls}(P,Q)}\right)}H_{\ls}(P,Q)$ and we have
    \begin{align}
        \nsseq(P,Q,\pi,\delta,\cT_D)
        \asymp
        \frac{\log(\frac{\pi}{\delta})}{H_*}
        \lesssim
        \log\left(\frac{1}{H_{\ls}(P,Q)}\right)\frac{\log(\frac{\pi}{\delta})}{H_{\ls}(P,Q)}\frac{1}{D}
        \lesssim
