\subsection{Proof of  \Cref{techupbound}}\label{app: affinity-upperbound}

In this part, we prove \Cref{techupbound}, remember that we denote $\betl(\Ber(p),\Ber(q))$ by $\betl(p,q)$ in this lemma. also remember that we had
\begin{equation}
    \ls=\frac{\log(\frac{\alb}{\delta})}{\log(\frac{\alb}{\delta})+\log(\frac{\pi}{\delta})}
        \in[0.5,1).
\end{equation}
\techupbound*
\begin{proof}
    Suppose $e_\pi(p,q)=\delta \in (0,\pi)$. First, let us compute an explicit formula for $e_\pi(p,q)$.
    \begin{equation*}
    e_\pi(p,q)=\min\{\pi p,\alb q\} + \min\{\pi\pb,\alb\qb\}
    \end{equation*}
    Now if both minimums occur in the first argument of minimum or both occur in the second argument we will either have $\delta=\pi$ or $\delta=\alb$ which is not acceptable because both $\pi$ and $\alb$ are greater than $\delta$. So we have one of the following settings
    \begin{equation}\label{lines}
    \textbf{Line1:}\ \delta=\pi p +\alb(1-q)\quad\text{or}\quad \textbf{Line2:}\ \delta=\alb q+\pi(1-p).
    \end{equation}
    We define the set $L_1$(resp.\ $L_2$) to be all acceptable pairs $(p,q)$ on \textbf{Line1} (resp.\ \textbf{Line2}). One can see that we have the following forms for these two sets
    \begin{align}
        & L_1=\left\{(p,q)|\ q=\frac{\pi}{\alb}p+(1-\frac{\delta}{\alb})\ for\ p\in\left[0,\frac{\delta}{\pi}\right]\right\}\\
        &L_2=\left\{(p,q)|\ q=\frac{\pi}{\alb}p+\frac{\delta-\pi}{\alb}\ for\ p\in\left[1-\frac{\delta}{\pi},1\right]\right\}
    \end{align}
    It is also true that we can obtain $L_2$ from $L_1$ by substituting $(p,q)$ by $(\pb,\qb)$, essentially we have 
    $L_2=\{(\pb,\qb)\ s.t.\ (p,q)\in L_1\}$. Now the goal is to maximize $\betl(p,q)$ on $L_1\cup L_2$ but note that $\betl(p,q)=\betl(\pb,\qb)$, so without loss of generality we can do this maximization only on $L_1$. For points in $L_1$ it is easy to see that $p\in[0,\frac{\delta}{\pi}]$ and $q\in[1-\frac{\delta}{\alb},1]$. So we know that $\pb,q\neq 0$, and hence we can write 
    \begin{align}
        \max_{(p,q)\in L_1}\betl(p,q)
        &=
        \max_{(p,q)\in L_1} \left\{q\left(\frac{p}{q}\right)^{\lambda}+\Bar{p}\left(\frac{\Bar{q}}{\Bar{p}}\right)^{\lamb}\right\}
        \nonumber\\
        &\leq
        \max_{\substack{(p_0,q_0)\in L_1\\(p_1,q_1)\in L_1\\(p_2,q_2)\in L_1}}\left\{q_0\left(\frac{p_1}{q_1}\right)^{\lambda}+\Bar{p_0}\left(\frac{\Bar{q_2}}{\Bar{p_2}}\right)^{\lamb}\right\}
        \nonumber\\
        &=\label{maxbetl}
        \max_{(p_0,q_0)\in L_1}\left\{q_0 \left(\max_{(p_1,q_1)\in L_1}\frac{p_1}{q_1}\right)^{\lambda}+\Bar{p_0}\left(\max_{(p_2,q_2)\in L_1}\frac{\Bar{q_2}}{\Bar{p_2}}\right)^{\lamb}\right\}\,.
    \end{align}
    We can calculate the interior maximums explicitly as below
    \begin{align}
        \label{max1}
        & \max_{(p_1,q_1)\in L_1}\frac{p_1}{q_1}
        = 
        \max_{p_1\in [0,\frac{\delta}{\pi}]}\frac{p_1}{\frac{\pi}{\alb}p_1+1-\frac{\delta}{\alb}}
        = 
        \max_{p_1\in (0,\frac{\delta}{\pi}]}\frac{1}{\frac{\pi}{\alb}+(1-\frac{\delta}{\alb})\frac{1}{p_1}}
        =
        \frac{\delta}{\pi} \\&\label{max2}
        \max_{(p_2,q_2)\in L_1}\frac{\Bar{q_2}}{\Bar{p_2}}
        = 
        \max_{p_2\in[0,\frac{\delta}{\pi}]}\frac{\frac{\delta}{\alb}-\frac{\pi}{\alb}p_2}{\Bar{p_2}} 
        = 
        \max_{p_2\in[0,\frac{\delta}{\pi}]}\frac{\pi}{\alb}-\frac{\pi-\delta}{\alb}\frac{1}{\Bar{p_2}}
        =
        \frac{\delta}{\alb}
    \end{align}
    Here we choose $\lambda$ such that $(\frac{\delta}{\pi})^\lambda=(\frac{\delta}{\alb})^{\lamb}$ and it is easy to check that we should choose $\lambda=\ls=\frac{\log(\frac{\alb}{\delta})}{\log(\frac{\alb}{\delta})+\log(\frac{\pi}{\delta})}$. Now we just need to optimize on $(p_0,q_0)$. By substituting the values from \cref{max1} and \cref{max2} in \cref{maxbetl} we have
    \begin{align}
        \max_{(p,q)\in L_1}\betls(p,q) 
        \leq& 
        \left(\frac{\delta}{\pi}\right)^{\ls}\max_{(p_0,q_0))\in L_1}\{q_0+\Bar{p_0}\}\nonumber\\ 
        =&
        \left(\frac{\delta}{\pi}\right)^{\ls}\max_{p_0\in [0,\frac{\delta}{\pi}]}\left\{\left(2-\frac{\delta}{\alb}\right)-\left(1-\frac{\pi}{\alb}\right)p_0\right\} 
        \nonumber\\=& 
        \left(\frac{\delta}{\pi}\right)^{\ls}\left(2-\frac{\delta}{\alb}\right)\,,
    \end{align}
    which is stronger than the claimed bound.
\end{proof}
