\subsection{Proof of \cref{idchannels}}\label{lem2proof}
Remember that we denoted $\beta_*\triangleq\inf_{T\in\cT}\betls(TP,TQ)$ and assumed that the channels $(T^1,T^2,\dots,T^n)$ are chosen in a sequentially interactive way, which means that channel $T^j$ can get as input $X_j$ and $Y_1^{j-1}=(Y_1,Y_2,\dots,Y_{j-1})$ but for any fixed choice of $y_1^{j-1}=(y_1,y_2,\dots,y_{j-1})$ the channel from $X_j$ is in the family of channels $\cT$. In this lemma, we denote the output probability of this sequence of channels with respect to the input probability $P^{\otimes n}$ (respectively, $Q^{\otimes n}$) by $P_{Y_1^n}$ (respectively, $Q_{Y_1^n}$). Here we state the proof of the following lemma.   
\idchannels*
\begin{proof}[Proof of  \cref{idchannels}]
    We prove this lemma by induction on $n$. For $n=1$, the inequality follows from the definition of $\beta_*$. So, suppose the statement is true for all $k\leq n-1$, we prove it for $n$. We can write the Hellinger affinity as below
    \begin{align}
    \betl(P_{Y_1^n},Q_{Y_1^n})
    =&
    \E_{Q_{Y_1^n}}\left[\left(\frac{P_{Y_1^n}}{Q_{Y_1^n}}\right)^\lambda\right]
    \nonumber\\
    &=
    \E_{Q_{Y^{n-1}_1}}\E_{Q_{Y_n|Y_1^{n-1}}}\left[\left(\frac{P_{Y_1^{n-1}}}{Q_{Y_1^{n-1}}}\right)^\lambda\left(\frac{P_{Y_n|Y_1^{n-1}}}{Q_{Y_n|Y_1^{n-1}}}\right)^\lambda\right]
    \nonumber\\&=
    \sum_{y_1^{n-1}\in\cY^{n-1}}Q_{Y_1^{n-1}}(y_1^{n-1})\left(\frac{P_{Y_1^{n-1}}(y_1^{n-1})}{Q_{Y_1^{n-1}}(y_1^{n-1})}\right)^\lambda\E_{Q_{Y_n|Y^{n-1}_1=y_1^{n-1}}}\left[\left(\frac{P_{Y_n|Y^{n-1}_1=y_1^{n-1}}}{Q_{Y_n|Y_1^{n-1}=y_1^{n-1}}}\right)^\lambda\right]\,.\label{betlexpansion}
    \end{align}
    Now for some $\epsilon>0$, let $\bar{y}_1^{n-1}\in\cY^{n-1}$ be such that 
    \begin{equation}\label{eq:inf-affinity}
    (1-\epsilon)\E_{Q_{Y_n|Y_1^{n-1}=\bar{y}_1^{n-1}}}\left[\left(\frac{P_{Y_n|Y_1^{n-1}=\bar{y}_1^{n-1}}}{Q_{Y_n|Y^{n-1}_1=\bar{y}_1^{n-1}}}\right)^\lambda\right]
    \leq
    \inf_{y^{n-1}_1\in\mathcal{Y}^{n-1}}\E_{Q_{Y_n|Y_1^{n-1}=y_1^{n-1}}}\left[\left(\frac{P_{Y_n|Y_1^{n-1}=y_1^{n-1}}}{Q_{Y_n|Y_1^{n-1}=y_1^{n-1}}}\right)^\lambda\right]\,.
    \end{equation}
    Then by using the induction assumption and \cref{eq:inf-affinity} we can lower bound  \cref{betlexpansion} 
    \begin{align}
        \betl(P_{Y_1^n},Q_{Y_1^n})
        &=
        \sum_{y_1^{n-1}\in\cY^{n-1}}Q_{Y_1^{n-1}}(y_1^{n-1})\left(\frac{P_{Y_1^{n-1}}(y_1^{n-1})}{Q_{Y_1^{n-1}}(y_1^{n-1})}\right)^\lambda\E_{Q_{Y_n|Y^{n-1}_1=y_1^{n-1}}}\left[\left(\frac{P_{Y_n|Y^{n-1}_1=y_1^{n-1}}}{Q_{Y_n|Y_1^{n-1}=y_1^{n-1}}}\right)^\lambda\right]\nonumber
        \\&\geq
        (1-\epsilon)\E_{Q_{Y_n|Y_1^{n-1}=\bar{y}_1^{n-1}}}\left[\left(\frac{P_{Y_n|Y_1^{n-1}=\bar{y}_1^{n-1}}}{Q_{Y_n|Y^{n-1}_1=\bar{y}_1^{n-1}}}\right)^\lambda\right]\beta_*^{n-1}
\nonumber        \\&\geq
        (1-\epsilon)\beta_*^{n},
    \end{align}
    where we used the assumption of induction, \cref{eq:inf-affinity} for the first inequality, and the definition of $\beta_*$ for the last inequality. Now, it is enough to let $\epsilon\downarrow 0$ to complete the proof.
\end{proof}




\section{Proofs for  \Cref{disthyp}}
\subsection{Proof of \cref{Hlamnice}}\label{app:Hlamnice}
\Hlamnice*
\begin{proof}[Proof of \cref{Hlamnice}]
Let $f_\lambda(x) = \lamb + \lambda x - x^\lambda$. One can verify that $H_{\lambda}(P,Q)=\E[f(\frac{dP}{dQ})]$. We prove the following properties for $f_{\lambda}(x)$.
    \begin{enumerate}[label=\roman*.]

\item \emph{Non-negativity}: $f_\lambda(x) \ge 0$ for all $x \in [0, \infty)$, and $f_\lambda(1) = 0$. This fact follows from the AM-GM inequality.

\item \emph{Monotonicity}: $f_\lambda(\cdot)$ is  decreasing on $[0,1]$ and increasing on $[1, \infty)$. This is easily seen by computing the derivative, \begin{align*}
f_\lambda'(x) = \lambda - \lambda x^{\lambda - 1},
\end{align*}
and checking its sign.

\item \emph{Boundedness over an interval}: $f_\lambda(x) \le 1$ for $x \in [0, 1/\lambda]$. As $f_\lambda(0) = \bar \lambda < 1$, the monotonicity property implies it is enough to check $f_\lambda(1/\lambda) \le 1$. Plugging in the value of $x$ to be $1/\lambda$,
\begin{align*}
f_\lambda(1/\lambda) &= \bar \lambda + 1 - (1/\lambda^\lambda).
\end{align*}
Differentiating with respect to $\lambda$,
\begin{align*}
\frac{d}{d\lambda} f_\lambda(1/\lambda) &= -1 + \lambda^{-\lambda}(1+\log \lambda) \le 0,
\end{align*}
where the final inequality uses $\lambda^\lambda \ge \lambda \ge 1 + \log \lambda$. Thus, $f_\lambda(1/\lambda)$ is maximized in the limit as $\lambda \to 0$. As $\lambda \to 0$, it can easily be verified that $f_\lambda(1/\lambda)$ tends to 1. Hence, we conclude that $f_\lambda(1/\lambda) \le 1$. 

\item \emph{Eventual linearity}: For $x \ge 1/\lambda$, we claim that $f_\lambda(x) \asymp \lambda x$. Specifically,  
\begin{align*}
c_1 \lambda x \le f_\lambda(x) \le c_2 \lambda x,
\end{align*}
where $c_1 = (1-\sqrt{2/3})/4$ and $c_2 = 2$. The upper bound is almost immediate:
\begin{align*} 
f_\lambda(x) \le \bar \lambda + \lambda x \le 2\lambda x,
\end{align*}
where we used $\bar \lambda < 1 \le x\lambda$ when $x \ge 1/\lambda$.

To prove the lower bound, we use the convexity of $f_\lambda(\cdot)$ to write
\begin{align*}
f_\lambda(x) &\ge (x - 3/(4\lambda))f_\lambda'(3/(4\lambda)) \ge x f_\lambda'(3/(4\lambda))/4.
\end{align*}
Above, we used that since $x \ge 1/\lambda$, $(x - 3/(4\lambda)) \ge x - 3x/4 = x/4.$ Evaluating $f_\lambda'(3/(4\lambda))$,
\begin{align*}
f_\lambda'(3/(4\lambda)) &= \lambda \left( 1 - (4\lambda/3)^{\bar \lambda}\right).
\end{align*}
It is not hard to check that $\left( 1 - (4\lambda/3)^{\bar \lambda}\right)$ is a decreasing function of $\lambda$ over $[0,1/2]$, and hence
\begin{align*}
f_\lambda'(3/(4\lambda) \ge \lambda (1-\sqrt{2/3}).
\end{align*}
Plugging in, we conclude the result.
\end{enumerate}
\end{proof}
