\also Order type realizability~\ourref{p:ordertype}, linear hypergraph realizability~\ourref[Linear Hypergraph Realizability]{p:linhypreal}.
%\tags 
\end{problemL}


\begin{problemL}{$\mathcal{LR}$-Calculus}
\label{p:LRCalculus}
\mindex{LR Calculus@$\mathcal{LR}$-Calculus}
\given A conjunctive logical formula using relations $\operatorname{left}(p,q,r)$ and $\operatorname{right}(p,q,r)$ for points in the Euclidean plane. 
\question Are there points in the plane satisfying the constraints of the formula? We say $\operatorname{left}(p,q,r)$ if $p$ and $q$ are distinct, and $r$ lies strictly to the left of the line from $p$ to $q$, and similarly for $\operatorname{right}(p,q,r)$.
\complexity \ER-complete by Mn\"{e}v~\cite{M88} since it is equivalent to simple order type realizability~\ourref[Simple Order Type Realizability]{p:ordertype}. Later, Lee~\cite{L13,L14} proved \ER-completeness for general logical formulas (not necessarily conjunctive) via a reduction from oriented matroid realizability~\ourref[Matroid!Oriented Matroid Realizability]{p:ordertype}, which is a slightly weaker result than Mn\"{e}v's. 
\comments The full $\mathcal{LR}$-calculus allows nine relations (e.g.\ see~\cite{SL15b}. For further \ER-completeness results on spatial calculi, see~\cite{L13,L14}.
\universality Mn\"{e}v~\cite{M88}.
%\openq 
\also  Order type realizability~\ourref{p:ordertype}.
%\tags 
\end{problemL}




\begin{problemL}{Cross-Product Expression Satisfiability}
\label{p:CrossProductExpr}
\mindex{Cross-Product Expression Satisfiability@Cross-Product Expression Satisfiability}
\given A cross-product term $t(x_1, \ldots, x_n)$; that is, a term that is either one of the variables, or of the form $(r \times s)$, where $r$ and $s$ are cross-product terms.
\question Are there vectors $v_1, \ldots, v_n \in \R^3$ such that $t(v_1, \ldots, v_n) = v_1$, where $\times$ is the cross-product over $\R^3$?
\complexity \ER-complete by Herrmann,  Sokoli, and Ziegler~\cite{HSZ13} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. 
\comments Herrmann,  Sokoli, and Ziegler show that the problem is equivalent to the existential theory of $F$ for any field $F \subseteq \R$, and that the problem remains \ER-complete over the real projective plane~\cite{HSZ13}. They also consider various variants that turn out to be equivalent to polynomial identity testing.
%\universality 
%\openq 
%\also 
\end{problemL}

\begin{problemL}{Realizability of Euclidean Embeddings of Rankings (REER)}
\label{p:REER}
\mindex{Realizability of Euclidean Embeddings of Rankings}
\given A conjunctive logical formula of the forms $x_i \preceq_{\ell} x_j$ and $x_i \prec_{\ell} x_j$, 
where $i,j \in [n]$ and $\ell \in [d]$.
\question Are there points $x_i \in \R^d$, $i \in [n]$ and vectors $v_{\ell} \in \R^d$ such that all conditions are satisfied? Here $x_i \preceq_{\ell} x_j$  means that $v_{\ell}^T (x_i-x_j) \geq 0$, and  $x_i \prec_{\ell} x_j$  means that $v_{\ell}^T (x_i-x_j) > 0$.
\complexity \ER-complete by Schockaert and Lee~\cite{SL15b} for any fixed dimension $d \geq 2$ via a reduction from $\mathcal{LR}$-calculus.
%\comments 
%\universality 
%\openq 
\also $\mathcal{LR}$-calculus~\ourref{p:LRCalculus}
%\tags 
\end{problemL}

\begin{problemL}{Topological Inference in RCC8 with Convexity}
\label{p:RCC8con}
\mindex{Topological Inference in RCC8 with Convexity}
\given A {\em constraint network}, that is, a conjunctive logical formula using the predicate ``convex'', and the eight binary relations of the region-connection calculus (RCC8): DC (disconnected), EC (externally connected), EQ (equal), PO (partially overlapping), TPP (tangential proper part), TPPi (tangential proper part inverse), non-tangential proper part (NTTP), and non-tangential proper part inverse (NTTPi), see~\cite{DGC99} for definitions.
\question Are there regular regions in the plane satisfying the logical condition?  A region is {\em regular} if it is the closure of its interior. It does not have to be connected.
\complexity \ER-complete by Davis, Gotts, Cohn~\cite{DGC99} via a reduction from collinearity logic~\ourref[Collinearity Logic]{p:CollLogic}. The problem remains \ER-complete if relations are restricted to EC, PP and ``convex'''~\cite{DGC99}, even in (fixed) higher dimension~\cite[Appendix A]{SL15}. It also remains complete if the set of relations is PO, DC and ``convex'' and the relation between any two regions has to be specified (a {\em fully specified contraint network})~\cite{S10}; this result is obtained via a reduction from intersection graphs of convex sets~\ourref[Convex Set(s)!Intersection Graph]{p:convintersect}.
\comments Membership in \ER\ is not trivial, since regions only have to be regular. 
%\universality 
\openq Does the topological inference problem in RCC8 with convexity remain in \ER, if we added the predicate ``connected''~\cite[Remark 4]{S10}?
\also Convex set intersection graph~\ourref{p:convintersect}.
\end{problemL}


\begin{problemL}{Quantum Logic Strong Satisfiability}
\label{p:QuantumStrong}
\mindex{Quantum Logic Strong Satisfiability}
\given A propositional formula $\phi(x)$, with $x=(x_1,x_2,\ldots ,x_n)$.
\question Is the formula $\phi(x)$ {\em strongly satisfiable} over the modular ortholattice $L(\R^d)$ for some constant $d\geq 3$, i.e., does there exist an assignment of values $a_i\in L(\R^d)$ to the $x_i$ such that $\phi (a)=\mathbf{1}$ when interpreted in $L(\R^d)$?
\complexity \ER-complete by \cite{HZ16}.
\comments The lattice $L(\R^d)$ is the lattice of \emph{linear subspaces of $\R^d$}, with the following three operations, where $U$ and $V$ are two such linear subspaces:
\begin{description}
\item[meet:] $U\wedge V = U\cap V$,
\item[complement:] $\neg U = \{x\in\R^d : \langle x, u\rangle = 0\ \forall u\in U \}$, the orthogonal subspace,
\item[join:] $U\vee V = U + V$, where $+$ denotes the Minkowski sum. Hence the join $U\vee V$ is simply the linear subspace spanned by $U$ and $V$.
\end{description}
In addition, we define the constants $\mathbf{0} = \{ (0,0,\ldots ,0) \}$ (the origin) and $\mathbf{1} = \R^d$ (the whole space).
The lattices $L(\R^d)$ are \emph{modular ortholattices}. They form the basis of the so-called \emph{quantum logic} proposed by Birkhoff and von Neumann in 1936~\cite{BvN36}. The problem studied by Hermann and Ziegler~\cite{HZ16} should not be confused with another quantum satisfiability problem referred to as QSAT. For $d=2$, the problem is \NP-complete. 
\also Quantum Logic Weak Satisfiability~\ourref{p:QuantumWeak}.
\end{problemL}


\begin{problemL}{Quantum Logic Weak Satisfiability}
\label{p:QuantumWeak}
\mindex{Quantum Logic Weak Satisfiability}
\given A propositional formula $\phi(x)$, with $x=(x_1,x_2,\ldots ,x_n)$.
\question Is the formula $\phi(x)$ {\em weakly satisfiable} over $L(\R^d)$ for some fixed constant $d\geq 3$, i.e., does there exist an assignment of values $a_i\in L(\R^d)$ to the $x_i$ such that $\phi (a)\not= \mathbf{0}$ when interpreted in $L(\R^d)$?
\complexity \ER-complete by \cite{HZ16}.
\comments See quantum logic strong satisfiability~\ourref{p:QuantumStrong} for definitions. For $d=2$, the problem is \NP-complete. 
\also Quantum Logic Strong Satisfiability~\ourref{p:QuantumStrong}.
\end{problemL}


\begin{problemL}{Arithmetic Data Exchange Realizability}
\label{p:arithdataex}
\mindex{Arithmetic Data Exchange Realizability}
\given Two {\em (database) schemas}, $S$ and $T$ (finite relational signatures over real arithmetic), an {\em arithmetic schema mapping}, $(S,T, \Sigma_{st}, \Sigma_{t})$, where $\Sigma_{st}$ and $\Sigma_{t}$ are finite sets of sentences over $S\cup T$ and $T$, respectively (with $\Sigma_{st}$ encoding translation constraints, and $\Sigma_{t}$ encoding target constraints), and an {\em instance} $I$ of $S$. The target constraints $\Sigma_t$ are assumed to be {\em weakly acyclic}. (For detailed definitions, see~\cite{tCKO13}.)
\question Is there an instance $J$ of $T$ such that $(I,J)$ satisfies both $\Sigma_{st}$ and $\Sigma_{t}$?
\complexity \ER-complete by ten Cate, Kolaitis, and Othman~\cite[Theorem 4.10]{tCKO13} via a reduction from rectilinear crossing number~\ourref[Graph(s)!Rectilinear Crossing Number]{p:rectcross}.
\comments Ten Cate, Kolaitis, and Othman also show that the {\em certain answer variant} of the data exchange problem is \VR-complete for conjunctive queries. 
%\universality 
%\openq 
\also Rectilinear crossing number~\ourref{p:rectcross}.

\end{problemL}

\section{Algebra}\label{sec:A}

\begin{quote}
Polynomials in this section are {\em multivariate} unless explicitly stated. Polynomials can be represented in various different ways; our default representation is the {\em explicit (or sparse)} representation as a sum of monomial terms with integer coefficients. A denser representation of polynomials can be achieved through an {\em arithmetic (or algebraic) circuit}, which is a directed graph with vertices ({\em gates}) that represent variables or the mathematical operators $+,-,\cdot$. The difference between the explicit and the circuit representation corresponds to the difference between Boolean formulas and Boolean circuits in logic: circuits can reuse already computed values. Circuits can be extended with additional operators, such as the sign-function or division, which allows them to represent non-polynomial functions~\cite{BC09}. 

In this section we will occasionally encounter \EC, the existential theory of the complex numbers. 
\end{quote}

\subsection{Polynomials and Arithmetical circuits}
% Polynomials

\begin{problemA}{Feasibility}  %\FEASLabel}
\label{p:feasibility}
\mindex{Polynomial(s)!feasibility}
\index{feasibility|see {Polynomial(s)}}
\given  A family $f = (f_1, \ldots, f_k): \R^n \rightarrow \R^k$ of polynomials $f_i \in \Z[x_1, \ldots, x_n]$. 
\question Is there an $x \in \R^n$ such that $f_i(x) = 0$ for all $i \in [k]$? 
\complexity \ER-complete, even if the total degree of all polynomials is at most $2$ or if $k = 1$ and the single polynomial is non-negative and has total degree at most $4$~\cite{BSS89, BFS99, BCSS98,SS17}. 
Reductions are from \ETR~\ourref[Existential Theory of the Reals]{p:ETR}. Also remains \ER-complete if the domain is a compact set like the unit ball or $[-1,1]^n$ and each polynomial has total degree at most $2$~\cite[Lemma 3.9]{S13}. For a fixed number $n$ of variables, the feasibility problem can be decided in polynomial time (using quantifier elimination). 
If $k = 1$ and the degree is at most $3$, the problem is solvable in polynomial time by Triesch~\cite{T90}.
\comments In the BSS-model this result traces back to~\cite{BSS89,BCSS98}. Buss, Frandsen, and Shallit~\cite{BFS99} define the existential theory $ETh(F)$ of a field $F$ (as a decision problem), and show that the feasibility problem over $F$ is complete for $ETh(F)$. 
In the real case this is true even for $k = 1$. 
Arguably, the \ER-completeness result is implicit in the normal forms devised by Mn\"{e}v~\cite{M88} and Shor~\cite{S91}. 
Triesch's result was proved in the BSS-model~\cite{T90}, but carries over. 
%\universality 
\openq Does the problem remain \ER-complete for $n = 1$ and $k=1$ if the polynomial is represented by a straight-line program? See the candidate problem feasibility of a univariate polynomial. 
\also \ETR~\ourref{p:ETR}, feasibility of univariate polynomial~\ourref[Polynomial(s)!Feasibility of Univariate Polynomial (Open)]{p:UniFEAS}, existential theory of invertible matrices~\ourref{p:ETInvMat}.
%\tags 
\end{problemA}


\begin{problemA}{(Strict) Local Positivity}  %\LocPosLabel}
\label{p:LocalPos}
\mindex{Polynomial(s)!Positivity!Local}\mindex{Polynomial(s)!Strict Positivity!Local}
\given A family $f = (f_1, \ldots, f_k): \R^n \rightarrow \R^k$ of polynomials $f_i \in \Z[x_1, \ldots, x_n]$. We say that $f$ is {\em (strictly) locally positive} if $f(x) \geq 0$ ($f(x) > 0$) for some $x \in \R^n$. 
\question Is $f$ (strictly) locally positive?
\complexity \ER-complete for family of polynomials of degree $2$, by Schaefer, \v{S}tefankovi\v{c}~\cite{SS17}, or a single polynomial of degree $8$ by Ouaknine and Worrell~\cite[Theorem 7]{OW17} via a reduction 
from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. The reductions work for both strict and non-strict versions. 
The result also remains true for bounded domains~\cite{OW17,SS23}. (Ouaknine and Worrell only prove the bounded case and write that it is ``straightforward'' to adapt to the case $\R^n$; a proof of that case can be found in~\cite{SS23} which also lowers the degree to $4$.)
Kiefer and Tang~\cite{KT24} give an independent proof for a single multivariate polynomial of degree $6$ on a bounded domain.
\comments The reductions do not (and cannot) maintain strong forms of universality (such as stable equivalence), since feasibility describes closed sets and positivity describes open sets. Strict local positivity is called \SINEQ\index{SINEQ@\SINEQ} by Kratochv\'{\i}l and Matou\v{s}ek~\cite{KM94}.
Cucker and Rossell\'{o}~\cite{CR92} discuss this problem under the name $SPOS_d$.
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}, global positivity~\ourref{p:GlobalPos}, positivity of linear recurrence~\ourref{p:poslinrecur}.
%\tags 
\end{problemA}


\begin{problemA}{(Strict) Global Positivity}   %\GloPosLabel}
\label{p:GlobalPos}
\mindex{Polynomial(s)!Positivity!Global}\mindex{Polynomial(s)!Strict Positivity!Global}
\index{Positivity|see {Polynomial(s)}}
\given  A polynomial $f: \R^n \rightarrow \R$ in $\Z[x_1, \ldots, x_n]$. If $f(x) \geq 0$ ($f(x) > 0$) for all $x \in \R^n$ we say that $f$ is {\em (strictly) globally positive}. 
\question Is $f$ (strictly) globally positive?
\complexity \VR-complete by Ouaknine and Worrell~\cite[Theorem 7]{OW17} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. Remains hard for bounded domain and total degree at most $8$.
\comments Strict global positivity is what is typically meant by a function being positive. Since $f$ is strictly globally positive (globally positive) if and only if $-f$ is not locally positive (not strictly locally positive), \VR-completeness follows from Ouaknine and Worrell~\cite[Theorem 7]{OW17} showing that (strict) local positivity is \ER-complete. In the BSS-model, Cucker and Rossell\'{o}~\cite{CR92} called global positivity {\em Hilbert's 17th problem}\index{Hilbert's 17th problem}, and classified its complement using the exotic quantifier $\exists^*$ later introduced by Koiran~\cite{K99,K00}. 
\also Feasibility~\ourref{p:feasibility}, local positivity~\ourref{p:LocalPos}.
%\tags 
\end{problemA}


\begin{problemA}{Fixed Point}   %\FixPoLabel}
\label{p:FixedPoint}
\mindex{Polynomial(s)!Fixed Point}
\index{Fixed Point|see {Polynomials(s)}}
\given A family $f = (f_1, \ldots, f_n): \R^n \rightarrow \R^n$ of polynomials $f_i \in \Z[x_1, \ldots, x_n]$. 
\question Does $f$ have a {\em fixed point}, that is an $x \in \R^n$ with $f(x) = x$?
\complexity \ER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS17} via a (trivial) reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. For fixed dimension $n$, the problem can be decided in polynomial time (using quantifier elimination).
\comments The reduction is trivial. 
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}, Brouwer Fixed Point~\ourref{p:BrouwerFixedPoint}.
%\tags 
\end{problemA}


\begin{problemA}{Brouwer Fixed Point}    
\label{p:BrouwerFixedPoint}
\mindex{Polynomial(s)!Brouwer Fixed Point}
\index{Brouwer Fixed Point|see {Polynomial(s)}}
\given A family $f = (f_1, \ldots, f_n): [-1,1]^n \rightarrow [-1,1]^n$ of polynomials in $\Z[x_1, \ldots, x_n]$, $q \in \Q^n$, $\delta \in \Q_{\geq 0}$.
\question Is there a {\em fixed point} of $f$ within distance $\delta$ of $q$, that is an $x \in [-1,1]^n$ with $f(x) = x$ and $\norm{x-q}_{\infty}< \delta$?
\complexity \ER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS17} via a reduction from Fixed Point~\ourref[Polynomial(s)!Fixed Point]{p:FixedPoint}. The problem remains \ER-complete for other natural compact domains and norms. For fixed dimension $n$, the problem can be decided in polynomial time (using quantifier elimination). 
\comments Without the restriction $\norm{x-q}_{\infty}< \delta$, there always is a fixed point, by Brouwer's fixed-point theorem. Ettessami and Yannakakis~\cite{EY10} introduced the complexity class \FIXP\ to capture the complexity of these types of problems. 
%\universality 
%\openq 
\also Fixed point~\ourref{p:FixedPoint}.
%\tags 
\end{problemA}




\begin{problemA}{Nontrivial Homogeneous Zero (\HTN)}
\label{p:HTN}
\mindex{Polynomial(s)!Nontrivial Homogenous Zero}
\index{HTN@\HTN|see {Polynomial(s),Nontrivial Homogenous Zero}}
\given A family $f = (f_1, \ldots, f_k): \R^n \rightarrow \R^k$ of homogeneous polynomials $f_i \in \Z[x_1, \ldots, x_n]$. 
\question Is there a {\em non-trivial zero}, that is, an $x \in \R^k$ with $f(x) = 0$ and $x\neq 0$?
\complexity \ER-complete by Schaefer~\cite[Corollary 3.10]{S13} from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} with compact domain. Remains \ER-complete even if the total degree of each polynomial is $2$.
\comments This problem was introduced as \HTN, abbreviating Hilbert's Homogeneous Nullstellensatz\index{Hilbert's Homogenous Nullstellensatz}, by Koiran and shown \NP-hard~\cite[Theorem 6]{K00}. The proof in~\cite{S13} yields polynomials of degree $4$, but that is unnecessary: the term $\sum_{i=1}^n x_i^2$ in the proof does not need to be square, which implies that $y_0^4$ and $x_0^4$ can be replaced by $y_0^2$ and $x_0^2$, yielding quadratic polynomials. This problem is equivalent to a $3$-dimensional tensor having eigenvalue $0$. The problem is called Quadratic Feasibility in~\cite{HL13} which also contains a sketch of a hardness proof which has issues~\cite[Example 2.5]{SS18}.
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}, \ISO~\ourref{p:ISO}, 
tensor with eigenvalue $0$~\ourref{p:tensorzero}.  
%\tags 
\end{problemA}


\begin{problemA}{Isolated Zero (\ISO)}
\label{p:ISO}
\mindex{Polynomial(s)!Isolated Zero}
\index{Isolated Zero|see {Polynomial(s)}}
\index{ISO@\ISO}
\given A family $f = (f_1, \ldots, f_k): \R^n \rightarrow \R^k$ of polynomials $f_i \in \Z[x_1, \ldots, x_n]$. 
\question Does $f$ have an {\em isolated zero}, that is, an $x \in \R^k$ such that $f(x) = 0$ and $f(x') \neq 0$ in an open neighborhood of $x$?
\complexity \VR-complete, by Koiran~\cite{K00}, Schaefer~\cite{S13}  via a reduction from \HTN~\ourref[Polynomial(s)!Nontrivial Homogenous Zero]{p:HTN} due to Koiran. 
Membership is shown in Schaefer,  \v{S}tefankovi\v{c}~\cite{SS17}. 
Remains \ER-complete even if the total degree of each polynomial is $4$.
\comments Koiran~\cite{K00} introduced the problem \ISO\ as the question whether the algebraic variety
$\{x\in \R^n: f(x) = 0\}$ contains an isolated point, and observed that \HTN~\ourref[Polynomial(s)!Nontrivial Homogenous Zero]{p:HTN} reduces to the complement of \ISO; since he also showed that \HTN~\ourref[Polynomial(s)!Nontrivial Homogenous Zero]{p:HTN} is \NP-hard, this implied \coNP-hardness for \ISO. 
%\universality 
%\openq 
\also \HTN~\ourref{p:HTN}, isolated point~\ourref{p:isopoint}, semialgebraic set with isolated point~\ourref{p:semiisolated}.
%\tags 
\end{problemA}

\begin{problemA}{Injectivity (polynomial)}
\label{p:injectivity}
\mindex{Polynomial(s)!Injectivity}
\index{Injectivity|see {Polynomial(s)}}
\given A family $f = (f_1, \ldots, f_n): \R^n \rightarrow \R^n$ of polynomials $f_i \in \Z[x_1, \ldots, x_n]$.
\question Is $f$ injective on $\R^n$?
\complexity \VR-complete (unpublished, see comments). 
 For functions represented by arithmetic circuits, this was shown by B\"{u}rgisser, Cucker~\cite[Corollary 9.4]{BC09}.
\comments Start with the feasibility problem for a polynomial $g \in \Z[x_1, \ldots, x_{n-1}]$. 
Then $g$ is feasible if and only if $f(x_1, \ldots, x_n) := (x_1, \ldots, x_{n-1}, x_n g(x_1, \ldots, x_{n-1}))$ is not injective. 
Starting with feasibility on a bounded or open domain implies hardness for testing injectivity on these domains as well. 
%\universality 
%\openq 
\also Surjectivity (second level)~\ourref{p:surjectivity}.  
%\tags 
\end{problemA}

\begin{problemA}{Regularity (polynomial)}
\label{p:regularity}
\mindex{Polynomial(s)!Regularity}
\index{Regularity|see {Polynomial(s)}}
\given A polynomial $f \in \Z[x_1, \ldots, x_n]$. 
\question Is $f$ {\em regular}? That is, there is no common real zero of $f$ and its partial derivatives. 
\complexity \VR-complete by Cucker, Rossell\'{o}~\cite{CR92} via a reduction from (non)-feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments A polynomial $g \in \Z[x_1, \ldots, x_{n}]$ is feasible if and only if $f = g^2$ is not regular. 
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}.  
%\tags 
\end{problemA}

\begin{problemA}{Totality (arithmetic circuit)}
\label{p:totality}
\mindex{Arithmetic Circuit!Totality}
\given An arithmetic circuit with division defining a (partial) function $f: \R^n \rightarrow \R$. The value of the circuit is not {\em defined} if it requires division by zero. 
\question Is $f$ total on $\R^n$, that is, is $f$ defined for every $x \in \R^n$? 
\complexity \VR-complete by B\"{u}rgisser, Cucker~\cite[Proposition 4.1, Corollary 9.4]{BC09} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. 
\comments The problem is hard for a single division gate, since we can let $f = 1/g$, where $g$ is a polynomial. Then $f$ is total if and only if $g$ is not feasible. Without division gate, the problem is trivial. 
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}, injectivity~\ourref[Polynomial(s)!Injectivity]{p:injectivity}, surjectivity (second level)~\ourref{p:surjectivity}.  
%\tags 
\end{problemA}

\begin{problemA}{Continuity (arithmetic circuit)}
\label{p:ContinuityAC}
\mindex{Arithmetic Circuit!Continuity}
\given An arithmetic circuit, division-free but with sign function $\sgn$, defining a function $f: \R^n \rightarrow \R$. 
\question Is $f$ continuous on $\R^n$?
\complexity \VR-complete by B\"{u}rgisser, Cucker~\cite[Corollary 9.4]{BC09} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. 
\comments A polynomial $g$ is feasible if and only if $f = \sgn(g^2)$ is not continuous, showing hardness of continuity. The trickier part is showing membership in \VR, since expressing continuity seems to require a quantifier alternation; B\"{u}rgisser and Cucker solve this problem via exotic quantifiers, which can be eliminated in this case. 
%\universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}, continuity at a point (arithmetic circuit)~\ourref[Arithmetic Circuit!Continuity at a Point]{p:ContinuityatPointAC}.  
\end{problemA}

\begin{problemA}{Continuity at a Point (arithmetic circuit)}
\label{p:ContinuityatPointAC}
\mindex{Arithmetic Circuit!Continuity at a Point}
\given An arithmetic circuit, division-free but with sign function $\sgn$, defining a function $f: \R^n \rightarrow \R$, a point $x \in Q^n$. 
\question Is $f$ continuous at $x$?
\complexity \VR-complete by B\"{u}rgisser, Cucker~\cite[Corollary 9.4]{BC09} via a reduction from unboundedness of a semialgebraic set~\ourref[Semialgebraic Set(s)!unboundedness]{p:unbounded}. 
\comments A polynomial $g$ is feasible if and only if $f = \sgn(g^2)$ is not continuous, showing hardness of continuity. The trickier part is showing membership in \VR, since expressing continuity seems to require a quantifier alternation; B\"{u}rgisser and Cucker solve this problem via exotic quantifiers, which can be eliminated in this case. 
%\universality 
%\openq 
\also Continuity (arithmetic circuit)~\ourref[Arithmetic Circuit!Continuity]{p:ContinuityAC}, unboundedness of semialgebraic set~\ourref{p:unbounded}.  
%\tags 
\end{problemA}

\begin{problemA}{Domain Density (arithmetic circuit)}
\label{p:DomainDensityAC}
\mindex{Arithmetic Circuit!Domain density}
\given An arithmetic circuit (with division gate and sign function), defining a (partial) function $f: \R^n \rightarrow \R$.
\question Is the domain of $f$ dense in $\R^n$?
\complexity \VR-complete, by B\"{u}rgisser, Cucker~\cite[Proposition 5.7, Corollary 9.4]{BC09}.
\comments  In the Zariski topology, B\"{u}rgisser, Cucker~\cite[Proposition 5.7, Corollary 9.4]{BC09} show that the problem is \ER-complete. 
%\universality 
%\openq 
\also Image density (second level)~\ourref{p:imagedensity}, density of semialgebraic set~\ourref{p:radiussemi}.  
\end{problemA}



\begin{problemA}{Polynomial Projection (Linear)}
\label{p:PolyProj}
\mindex{Polynomial(s)!Projection (Linear)}
\given Two polynomials $f,g:\R^n\to\R$ in $\Z[x_1,x_2,\ldots,x_n]$.
\question Is there a matrix $A$ such that $f(x)=g(Ax)$?
\complexity \ER-complete by Bl\"{a}ser, Rao, and Sarma~\cite{BRS17} via a reduction from the symmetric tensor rank problem~\ourref[Tensor!Rank]{p:tensorrank} .
\comments Over an arbitrary integral domain, the problem is complete for the existential theory of that domain~\cite{BRS17}. If $A$ is a diagonal, invertible matrix, then the polynomial projection problem can be solved in randomized polynomial time~\cite{BRS17}. The general (affine) polynomial projection problem asks whether there is a matrix $A$ and a vector $b$ such that $f(x) = g(Ax+b)$. The special case $A = I$ is known as polynomial equivalence under shifts~\ourref[Polynomial Equivalence under Shifts (Open)]{p:polyshifts}. 
%\universality 
\openq Is the affine polynomial projection problem \ER-hard? This version is known to be \NP-hard by Kayal~\cite{K12}.
\also Polynomial equivalence under shifts~\ourref{p:polyshifts}.    
%\tags 
\end{problemA}


\subsection{Matrices and Tensors}\label{sec:MatandTen}

\begin{quote}
A $d$-dimension (real) tensor $T$ is an element in $\R^{n_1\times \cdots \times n_d}$. The tensor has rank at most $k$ if it can be written as $\sum_{i=1}^k v_1 \otimes \cdots \otimes v_k$, where $v_i \in \R^{n_i}$ for $1 \leq i \leq d$, and $\otimes$ is the outer product of two vectors. Matrices are then the special case of $2$-dimensional tensors. There are other notions of tensor- and matrix-rank, some of which we discuss below.
\end{quote}

\begin{problemA}{Matrix Singularity}
\label{p:MatSing}
\mindex{Matrix!Singularity}
\given A square matrix $M(x_1, \ldots, x_k)$ with variable entries $x_1, \ldots, x_k$ and entries in $\Q$. 
\question Is $M(x_1, \ldots, x_k)$ singular, that is, does $M(x_1, \ldots, x_k)$ have determinant $0$ for some $(x_1, \ldots, x_k) \in~\R^k$?
\complexity \ER-complete by Buss, Frandsen, Shallit~\cite{BFS99} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments Buss, Frandsen, Shallit~\cite{BFS99} show that the singularity problem over any commutative ring $R$ is complete for the existential theory of $R$. The reduction is based on Valiant's universality proof for the determinant~\cite{V79}. Non-singularity, that is, testing whether $M(x_1, \ldots, x_k)$ is non-singular for some $x_1, \ldots, x_k$ lies in randomized polynomial time, so is unlikely to be \ER-complete~\cite{BFS99}. Brijder, Geerts, and Van den Bussche~\cite{BGvdBW19b} introduce a formal matrix language (MATLANG) in which matrix singularity is expressible, implying that expression evaluation in that language is \ER-complete.
%\universality 
%\openq 
\also Existential theory of invertible matrices~\ourref{p:ETInvMat}, constrained matrix invertibility problem~\ourref{p:constmatinv}, feasibility~\ourref{p:feasibility}.
%\tags 
\end{problemA}



\begin{problemA}{Minimum/Maximum Matrix Rank}
\label{p:minmaxmatrank}
%minimium/maximum matrix rank~\ourref[Matrix!Rank]{p:minmaxmatrank}
%minimium/maximum matrix rank~\ourref{p:minmaxmatrank}
\mindex{Matrix!Rank}
\given A square matrix $M(x_1, \ldots, x_k)$ variable entries $x_1, \ldots, x_k$ and entries in $\Q$, integer $k$. 
\question Is the rank of $M(x_1, \ldots, x_k)$ at most/at least $k$ for some $(x_1, \ldots, x_k) \in \R^k$?
\complexity \ER-complete by Buss, Frandsen, Shallit~\cite{BFS99} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments Buss, Frandsen, Shallit~\cite{BFS99} show that the minimum and maximum matrix rank problems over any field $F$ is complete for the existential theory of $F$, even if the matrix entries lie in $\{0,1\}$. A minimum rank problem for matrices with affine entries can be used to prove \ER-completeness of tensor rank~\ourref{p:tensorrank}, see~\cite{SS18}.
%\universality 
\openq Buss, Frandsen, Shallit~\cite{BFS99} show that approximating the minimum rank of a matrix to within a factor of $1+\varepsilon$ is \NP-hard for sufficiently small $\varepsilon$, is it also \ER-hard? \sep\ How hard is the minimum matrix rank problem if each variable occurs only once in the matrix? This is the well-known minimum rank matrix completion problem, the maximum rank version of this problem can be solved in randomized polynomial time~\cite{BFS99}. Related to this is the problem of computing the minimum rank of a sign pattern matrix~\ourref[Sign Pattern Matrix!Minimum Rank]{p:minranksignpatmat}.  \sep\ Is the problem hard for constant $k$, say $k = 4$? 
\also Feasibility~\ourref{p:feasibility}, tensor rank~\ourref{p:tensorrank}, minimum rank of sign pattern matrix~\ourref{p:minranksignpatmat}, minimum graph rank~\ourref{p:mingraphrank}, low rank approximation (matrix)~\ourref{p:lowrankapp}.
%\tags 
\end{problemA}



\begin{problemA}{Minimum Rank of Linear Combination of Matrices}
\label{p:minrankspanmat}
\mindex{Matrix!Minimum Rank of Linear Combination}
\given A family of matrices $M_1, M_2,\ldots ,M_k \in \Q^{m\times n}$ and an integer $r$.
\question Is the rank of $\sum_i \lambda_iM_i$ at most $r$ for some nonzero combination $(\lambda_1, \ldots, \lambda_k) \in \R^k$?
\complexity \ER-complete by Bl\"{a}ser, Ikenmeyer, Lysikov, Pandey, and Schreyer~\cite[Theorem 2.3]{BILPS21} via a reduction from \HTN~\ourref[Polynomial(s)!Nontrivial Homogenous Zero]{p:HTN} even for $r = 1$.
\comments There are interesting connections to various notions of tensor rank, including slice rank and border rank, see~\cite{BILPS21}. The result is used to prove \ER-hardness of the orbit closure containment problem~\ourref[Tensor!Orbit Closure Containment]{p:orbitcontain}.
\openq There is an affine version of this problem, in which we require that $\lambda_1 = 1$; this version is known to be \NP-hard~\cite{BIJL18}, but is it \ER-complete? 
\also Minimum matrix rank~\ourref{p:minmaxmatrank}, tensor rank~\ourref{p:tensorrank}, orbit closure containment~\ourref{p:orbitcontain}.
\end{problemA}


\begin{problemA}{Minimum Rank of Sign Pattern Matrix}
\label{p:minranksignpatmat}
%minimum rank of sign pattern matrix~\ourref[Sign Pattern Matrix!Minimum Rank]{p:minranksignpatmat}
%minimum rank of sign pattern matrix~\ourref{p:minranksignpatmat}
\mindex{Sign Pattern Matrix!Minimum Rank}
\given A {\em generalized sign pattern matrix}, that is, $M \in \{+,-,0\}^{n \times n}$, integer $k$.
\question Is there a matrix $A \in \R^{n\times n}$ of rank at most $k$ so that $\sgn(A) = M$, where $\sgn$ is the sign function applied to each entry?
\complexity \ER-complete by Bhangale, Kopparte~\cite{BK15} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}, even for $k = 3$.
\comments For $k = 2$ the problem is solvable in polynomial time~\cite{BK15}. The maximum rank variant is equivalent to a matching problem and can be solved in polynomial time~\cite{BK15}.
%\universality 
\openq Generalized in the name refers to allowing the entry $0$; in a {\em sign pattern matrix} zero entries are not allowed; in this case Bhangale, Kopparte~\cite{BK15} can still show that the problem is \NP-hard, but \ER-completeness is open.
\also Minimum/maximum matrix rank~\ourref{p:minmaxmatrank}, feasibility~\ourref{p:feasibility}.
%\tags 
\end{problemA}

\begin{problemA}{Monotone Matrix Rank}
\label{p:monmatrank}
\mindex{Matrix!Monotone Rank}
\given A matrix $M \in \Q^{m \times n}$, integer $k$. 
\question Is the {\em monotone rank} of $M$ at most $k$, that is, is there a matrix $A$ of rank at most $k$, and monotone functions $f_1, \ldots, f_n$ such that $M_{ij} = f_j(A_{ij})$, where $i \in [m], j \in [n]$?
\complexity \ER-complete for $k = 2$ by Lienkaemper~\cite{L23b} via a reduction from simple allowable sequence~\ourref[Simple Allowable Sequence]{p:allowableseq}.
%\comments 
%\universality 
%\openq 
\also Minimum/maximum matrix rank~\ourref{p:minmaxmatrank}, minimum rank of sign pattern matrix~\ourref{p:minranksignpatmat}, (simple) allowable sequence~\ourref{p:allowableseq}.
%\tags 
\end{problemA}

\begin{problemA}{Minimum Graph Rank}
\label{p:mingraphrank}
\mindex{Minimum Graph Rank}
\given A graph $G$ on $n$ vertices, an integer $k\geq 0$.
\question Is there a real symmetric matrix $A \in \R^{n \times n}$ of rank at most $k$ so that $v_iv_j \in E(G)$ if and only if $A_{i,j} \neq 0$, for $1 \leq i \neq j \leq n$?
\complexity \ER-complete even for $k = 3$ by Grace, Hall, Jensen and Lawrence~\cite[Section 4]{L23} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. 
\comments It is also claimed that over an arbitrary infinite field instead of $\R$, the problem (with $A$ being Hermitian instead of symmetric) is equivalent to the existential theory of the field.
%\universality 
%\openq 
\also Minimum matrix rank~\ourref{p:minmaxmatrank}. 
%\tags 
\end{problemA}


\begin{problemA}{Non-negative Matrix Factorization (NMF)}
\label{p:nonnegmatfac}
\mindex{Matrix!Non-negative Factorization}
\given A square matrix $M \in \Q^{n \times n}$ with all entries non-negative and a natural number $k\in \N$. 
\question Are there $n\times k$ and $k\times n$ matrices $A,B$ such that $M = AB$ and all entries of $A$ and $B$ are non-negative?
\complexity \ER-complete by Shitov~\cite{S16} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments Vavasis had earlier shown NP-hardness~\cite{V09}. The smallest $k$ for which $M$ has a non-negative factorization equals the non-negative rank of $M$, that is the smallest number of rank-$1$ matrices with non-negative entries, whose sum is $M$~\cite[Lemma 2.1]{CR93}, so the non-negative matrix rank problem\mindex{Matrix!Non-negative Rank}\index{Non-negative matrix rank|see {Matrix}} is also \ER-complete.
Rank problems for matrices with affine entries can be used to prove \ER-completeness of tensor rank~\ourref[Tensor!Rank]{p:tensorrank}, see~\cite{SS18}. 
\universality Shitov~\cite{S16} also shows universality.
\openq Is the problem already hard for some fixed $k$, say four?
\also Nested polytopes~\ourref{p:nestpolytopes}, Hadamard decomposition~\ourref{p:Hadamard}.
%\tags 
\end{problemA}





\begin{problemA}{(Real) PSD Rank}
\label{p:PSDrank}
\mindex{Matrix!(Real) PSD Rank}
\given A matrix $A \in \Q^{m\times n}$, a natural number $r\in \N$.
\question Is $\operatorname{psd-rank}(A)\leq r$? That is, are there Hermitian
positive semidefinite $r \times r$ matrices $(B_1,  \ldots , B_m)$ and $(C_1, \ldots ,C_n)$ with $A(i,j) = \trace(B_iC_j )$, for all $i , j$? If the $B_i$ and $C_j$ are restricted to be real, we obtain the \textit{real psd rank} of $A$. 
\complexity Shitov established \ER-completeness~\cite[Theorem 3.4]{S23PSD} of the (complex) PSD rank.
He also established \ER-completeness~\cite{shitov2017complexity} of the real PSD rank. The problem remains hard in case the nominator and denominator of each entry are given in unary. 
\comments The abbreviation psd stands for positive semi-definite. 
The literature often does not distinguish between real and complex psd rank. 
PSD Rank can be solved in polynomial time for any fixed value of $r$.
%\universality open
% \openq 
\also CPSD Rank~\ourref{p:CPSDrank}
\end{problemA}


\begin{problemA}{(Real) CPSD Rank}
\label{p:CPSDrank}
\mindex{Matrix!CPSD Rank}
\given A matrix $A \in \Q^{n\times n}$, a natural number $r\in \N$
\question Is $\operatorname{cpsd-rank}(A) \leq r$? That is, are there Hermitian psd matrices $(P_1, \ldots , P_n)$ of size $r \times r$ such that $A(i,j) = \trace P_i P_j$ for all $i,j$? We say $A$ is \textit{completely positive semi-definite}. If the $P_i$ are restricted to be real matrices, we obtain the \textit{real CPSD rank} of $A$. 
\complexity Shitov established \ER-completeness~\cite[Theorem 3.10]{S23PSD} of both the cpsd and the real cpsd rank.
\comments The problem is even hard in case the nominator and denominator of each entry are given in unary. 
For any fixed integer $r$, there is a polynomial time algorithm to determine
whether the cpsd rank or real cpsd rank of a given matrix are at most $r$~\cite[Theorem 3.14]{S23PSD}.
%\universality open
% \openq 
\also PSD Rank~\ourref{p:PSDrank}.
% \tags 
\end{problemA}


\begin{problemA}{Phaseless Rank}
\label{p:phaselessrank}
\mindex{Matrix!Phaseless Rank}
\given A matrix $A \in \Q^{m\times n}$, a natural number $r\in \N$
\question Does $A$ have {\em phaseless rank} at most $r$, that is, is there a matrix $\varepsilon \in \C^{m \times n}$ with $|\varepsilon_{ij}| = 1$ such that $A \odot \varepsilon$ has rank at most $r$, where $\odot$ denotes the element-wise matrix product?
\complexity Shitov established \ER-completeness~\cite[Theorem 3.7]{S23PSD}.
%\Year 2023
\comments The problem is hard even if the numerator and denominator of each entry are given in unary. 
%\universality open
% \openq 
% \also 
% \tags 
\end{problemA}

\begin{problemA}{Rank-Constrained Optimization}
\label{p:rankconrtainedopti}
\mindex{Matrix!Rank-Constrained Optimization}
\given Two matrices $A,B\in\R^{\ell\times n}$, a natural number $k$.
\question Is there an $n\times n$ matrix $X$ in the positive semidefinite cone $S^n_+$ such that $AX=B$ and $\operatorname{rank}(X)\leq k$?
\complexity \ER-complete by Bertsimas, Cory-Wright, and Pauphilet~\cite{BCWP22} via a reduction from
linkage realizability~\ourref[Linkage!Linkage Realizability]{p:linkagereal}. 
\comments  In Bertsimas et al.~\cite{BCWP22}, the general problem of minimizing an expression of the form $\langle C,X\rangle + \lambda\cdot\operatorname{rank}(X)$ subject to $AX=B$, $\operatorname{rank}(X)\leq k$ and $X\in\mathcal{K}$ for some proper cone $\mathcal{K}$ is considered.
This problem is already \ER-hard for $\mathcal{K}=S^n_+$, $k=2$, $\lambda = 1$ and $C=\mathbf{0}$ by reduction from unit linkage realizability.
\also Linkage realizability~\ourref{p:linkagereal}. 
\end{problemA}

\begin{problemA}{Tensor Rank}
\label{p:tensorrank}
\mindex{Tensor!Rank}
\given A $3$-dimensional tensor $T = (t_{ijk}) \in \Q^{d_1\times d_2\times d_3}$, a natural number $k$.
\question Is the {\em (tensor) rank} of $T$ at most $k$; that is, are there at most $k$ rank-$1$ tensors $T_1, \ldots, T_k$ such 
that $T = \sum_{i \in [k]} T_i$? A tensor has {\em rank-$1$} if it can be written as $u \otimes v \otimes w$ for real vectors $u,v,w$, where $\otimes$ is the outer (Kronecker) product of two vectors.
\complexity \ER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS18} via a reduction from a restricted version of the minimum matrix rank problem~\ourref{p:minmaxmatrank}, and Shitov~\cite{S16b} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. 
The problem remains hard for symmetric tensors~\cite{S16b}.
\comments Tensor rank was famously shown \NP-hard by {H\r{a}stad}~\cite{H90}. 
Shitov~\cite{S16b} showed that over an integral domain, the (symmetric) tensor rank problem is as hard as the existential theory of that domain. 
For a related notion, called {\em border rank}, whose complexity is still open, see~\cite{BIJL18}.
\universality There is a universality result~\cite{SS24} (which fixes the version in~\cite{SS18}).
\openq Does the problem remain hard for fixed $k$?
\also Minimum matrix rank~\ourref{p:minmaxmatrank}.
%\tags 
\end{problemA}

\begin{problemA}{Tensor with Eigenvalue $0$}
\label{p:tensorzero}
\mindex{Tensor!Eigenvalue 0}
\given A $3$-dimensional tensor $T = (t_{ijk}) \in \Q^{n\times n\times n}$.
\question Does $T$ have $0$ as an {\em eigenvalue}; that is, is there a non-zero vector $v \in R^n$ for which $\sum_{i,j=1}^{n} t_{i,j,k}v_iv_j = 0$ for all $k\in [n]$?
\complexity \ER-complete by Schaefer~\cite[Corollary 3.10]{S13}, also see Schaefer, \v{S}tefankovi\v{c}~\cite[Example 2.5]{SS18}. 
\comments There also is a proof by Hillar and Lim~\cite{HL13}, but it appears to have a gap, see the discussion in~\cite[Example 2.5]{SS18}. The problem is equivalent to the nontrivial homogenous zero problem (\HTN)~\ourref[Polynomial(s)!Nontrivial Homogenous Zero]{p:HTN}. 
We should note that there are other, non-equivalent, definitions of tensor eigenvalues.  
%\universality 
\openq Is the eigenvalue problem \ER-complete for symmetric tensors (with eigenvalues in $\Q[d]$)? Hillar and Lam~\cite[Theorem 9.3]{HL13} show that this problem is \NP-hard. 
\also Tensor rank~\ourref{p:tensorrank} , \HTN~\ourref{p:HTN}, tensor eigenvector approximation~\ourref{p:tensoreigenapp}, tensor singular value~\ourref{p:tensorsingular}.
%\tags 
\end{problemA}

\begin{problemA}{Orbit Closure Containment}
\label{p:orbitcontain}
\mindex{Tensor!Orbit Closure Containment}
\given Two $3$-dimensional tensors $T, T' \in \Q^{n\times n\times n}$.
\question Is the orbit closure of $T$ contained in the orbit closure of $T'$ under the $\mathsf{GL}_n\times \mathsf{GL}_n\times \mathsf{GL}_n$ action in $\R$?
\complexity \ER-complete by Bl\"{a}ser, Ikenmeyer, Lysikov, Pandey, and Schreyer~\cite{BILPS21} via a reduction from minimum rank of linear combination of matrices~\ourref[Matrix!Minimum Rank of Linear Combination]{p:minrankspanmat}.
\comments The orbit of $T$ under $\mathsf{G}_n$ is the set $\{ gT : g\in \mathsf{G}_n\}$, and we consider the closure of these orbits in the Zariski topology. We refer to Bl\"{a}ser et al.~\cite{BILPS21} for detailed definitions and motivations.
\also Minimum rank of linear combination of matrices~\ourref{p:minrankspanmat}, tensor rank~\ourref{p:tensorrank}, minimum matrix rank~\ourref{p:minmaxmatrank}.
\end{problemA}

