\subsection{Semialgebraic and Algebraic Sets}\label{sec:SAS}

\begin{quote}
For polynomials and their representations, see Section~\ref{sec:A}.
%
An {\em algebraic set} is the zero-set of a family of polynomials: $S = \{x\in R^n: f_i(x) = 0$ for all $i \in [k]\}$ and is specified  by its defining polynomials, $f_i$, $i \in [k]$. A {\em basic semialgebraic set} is a set of the form $S = \{x: \in \R^n: f_i(x) = 0$ for all $i \in [k], g_i(x) > 0$ for all $i \in [m]\}$. A {\em semialgebraic set} is the finite union of basic semialgebraic sets. 
We will see two ways of specifying a semialgebraic set: via a formula $\varphi$ as
$S = \{x \in \R^n: \varphi(x)\}$, where $\varphi$ is a quantifier-free formula in the theory of the reals with free variables $x$; and via an arithmetic circuit $C$, where $S = \{x: \in \R^n: C(x) = 1\}$, where $x$ are the variables of the circuit $C$. Unless we say otherwise, we assume a semialgebraic set is specified using the formula $\varphi$.
\end{quote}

\begin{problemA}{Cardinality of Semialgebraic Set}
\label{p:cardinality}
\mindex{Semialgebraic Set(s)!cardinality}
\given A semialgebraic set $S \subseteq \R^n$, a natural number $k\geq 1$ or $k = \infty$.
\question Does $S$ contain fewer than $k$ elements? 
\complexity \VR-complete by Cucker and Rossell\'{o}~\cite{CR92} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} for any fixed $k$, including $k = \infty$. 
\comments Special (named) cases are $k = 1$, the {\em emptiness}\mindex{Semialgebraic Set(s)!emptiness} and $k = \infty$, the {\em finiteness}\mindex{Finiteness of Semialgebraic Set} problem. Cucker and Rossell\'{o}~\cite{CR92} work in the BSS-model, but their proof carries over to \VR. If $k$ is not fixed, the problem is complete for the counting version of \ER, see~\cite[Proposition 8.5(ii)]{BC06}.
%\universality 
%\openq 
\also Dimension of semialgebraic set~\ourref{p:dimension}, feasibility~\ourref{p:feasibility}. 
\end{problemA}

\begin{problemA}{Dimension of Semialgebraic Set}
\label{p:dimension}
\mindex{Semialgebraic Set(s)!dimension}
\given A semialgebraic set $S \subseteq \R^n$, an integer $d\geq 0$.
\question Does $S$ have (real) dimension at least $d$; that is, is there a projection $\pi: \R^n\rightarrow \R^d$ (dropping $n-d$ coordinates), such that $\pi(S)$ contains a non-empty interior? 
\complexity \ER-complete by Koiran~\cite{K99} via reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}, even for any fixed $d \geq 0$. 
\comments For $d = 0$ the problem degenerates to the non-emptiness problem of a semialgebraic set~\ourref{p:cardinality}.
Cucker and Rossell\'{o}~\cite{CR92} looked at the cases $d = n-1$, which they call the hypersurface problem\index{Hypersurface|see {Semialgebraic Set(s),dimension}}, and $d = n$, which they call the NEI (nonempty interior) problem\index{Nonempty Interior|see {Semialgebraic Set(s),dimension}}. They showed that both problems can be described using the exotic quantifier $\exists^*$ (not formally introduced until Koiran's papers~\cite{K99,K00}).

The \ER-hardness reduction is straight-forward, the non-trivial part is showing that the problem lies in \ER. Koiran~\cite{K99} first shows this for the BSS-model, but also explains how to translate the result into the discrete setting, corresponding to \ER. Koiran had earlier shown that the {\em complex} dimension of a semialgebraic set is \EC-complete (again for the BSS-model)~\cite{K97}. For his result Koiran introduces the exotic quantifier $\exists^*$ and shows how to eliminate it. 
%\universality 
%\openq 
\also Local dimension of semialgebraic set~\ourref{p:locdimension}, feasibility~\ourref{p:feasibility}. 
\end{problemA}




\begin{problemA}{Local Dimension of Semialgebraic Set}
\label{p:locdimension}
\mindex{Semialgebraic Set(s)!local dimension}
\given A semialgebraic set $S \subseteq \R^n$, $x \in \Q^n$, an integer $d\geq 0$.
\question Does $S$ have local dimension at least $d$ at $x$; that is, is there a sufficiently small neighborhood $U$ of $x$ such that the dimension of $S \cap U$ is at least $d$? 
\complexity \ER-complete by B\"{u}rgisser and Cucker~\cite[Corollary 6.6,Corollary 9.4]{BC09} even for $d = 1$ via a reduction from testing whether $0$ lies in the closure of a semialgebraic set~\ourref[Semialgebraic Set(s)!Zero in closure]{p:ZeroinClosure}.
\comments \ER-membership uses the exotic quantifier \HQ{}, which can be eliminated.
%\universality 
%\openq 
\also Dimension of semialgebraic set~\ourref{p:dimension}. 
%\tags semialgebraic sets 
\end{problemA}




\begin{problemA}{Convexity of Semialgebraic Set}
\label{p:convexity}
\mindex{Semialgebraic Set(s)!convexity}
\given A semialgebraic set $S \subseteq \R^n$, a natural number $n \geq 2$.
\question Is $S$ {\em convex}, that is, does the line segment $st$ belong to $S$ for every two points $s, t \in S$? 
\complexity \VR-complete by Cucker and Rossell\'{o}~\cite{CR92}. Also, see Schaefer, \v{S}tefankovi\v{c}~\cite{SS23}.
\comments The proof by Cucker and Rossell\'{o}~\cite{CR92} is phrased in the BSS-model, but translates easily to the \VR-completeness setting, as shown in~\cite{SS23}.
%\universality 
%\openq 
\also Star-shapedness of semialgebraic set~\ourref{p:starshaped}, convexity through translation~\ourref{p:convtrans}.
\end{problemA}


\begin{problemA}{Unboundedness of Semialgebraic Set}
\label{p:unbounded}
\mindex{Semialgebraic Set(s)!unboundedness}
\given A semialgebraic set $S \subseteq \R^n$.
\question Is $S$ {\em unbounded}, that is, is it true that for every $r > 0$ there is an $x \in S$ with $\norm{x} > r$?
\complexity \ER-complete by Cucker, Rossell\'{o}~\cite{CR92}, also see
B\"{u}rgisser, Cucker~\cite[Proposition 6.4,Corollary 9.4]{BC09}, and Schaefer, \v{S}tefankovi\v{c}~\cite{SS23}.
\comments Membership in \ER\ is the non-trivial part here, since the definition uses a universal quantifier. Cucker, Rossell\'{o}~\cite{CR92} work in the BSS-model, but consider a restricted variant which corresponds to \ER, and obtain membership using an upper bound from real algebraic geometry. B\"{u}rgisser and Cucker~\cite{BC09} work with an exotic quantifier and show how to eliminate it; Schaefer and \v{S}tefankovi\v{c}~\cite{SS23} give a reduction from  feasibility over a bounded domain. 
%\universality 
%\openq 
%\also 
%\tags semialgebraic sets 
\end{problemA}


\begin{problemA}{Radius of Semialgebraic Set}
\label{p:radiussemi}
%radius of semialgebraic set~\ourref[Semialgebraic Set(s)!radius]{p:radiussemi}
%radius of semialgebraic set~\ourref{p:radiussemi}
\mindex{Semialgebraic Set(s)!radius}
\index{Radius|see {Semialgebraic Set(s)}}
\given A semialgebraic set $S \subseteq \R^n$, $d\in \Q_{\geq 0}$.
\question Does $S$ have radius at most $d$; that is, is there a point $c \in \R^n$ such that $\norm{c-s}\leq d$ for every $s \in S$?
\complexity \VR-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} via reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} over a bounded domain.
\comments The \ER-hardness reduction is straight-forward, 
the difficulty lies in showing that the problem lies in \VR\ by eliminating the quantification over the center. 
%\universality 
%\openq 
\also Diameter of semialgebraic set~\ourref{p:diamsemi}.
%\tags semialgebraic sets 
\end{problemA}


\begin{problemA}{Diameter of Semialgebraic Set}
\label{p:diamsemi}
%diameter of semialgebraic set~\ourref[Semialgebraic Set(s)!diameter]{p:diamsemi}
%diameter of semialgebraic set~\ourref{p:diamsemi}
\mindex{Semialgebraic Set(s)!diameter}
\index{Diameter|see {Semialgebraic Set(s)}}
\given A semialgebraic set $S \subseteq \R^n$, $d\in \Q_{\geq 0}$.
\question Does $S$ have diameter at most $d$; that is, do every two points in $S$ have distance at most $d$ from each other?
\complexity \VR-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} via reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} over a bounded domain.
\comments The strict version, in which we require the diameter to be strictly less than $d$ is also \VR-complete; the only issue is \VR-membership, but that can be handled using the exotic \HQ-quantifier as we saw in Section~\ref{sec:repexotic}. 
%\universality 
%\openq 
\also Radius of semialgebraic set~\ourref{p:radiussemi}.
%\tags semialgebraic sets 
\end{problemA}


\begin{problemA}{Density of Semialgebraic Set}
\label{p:densitysemi}
%density of semialgebraic set~\ourref[Semialgebraic Set(s)!density]{p:densitysemi}
%density of semialgebraic set~\ourref{p:radiussemi}
\mindex{Semialgebraic Set(s)!density}
\given A semialgebraic set $S \subseteq \R^n$.
\question Is $S$ dense in $\R^n$? A set $S \subseteq T$ is {\em dense} in $T$ if for every $t \in T$ and every $\varepsilon > 0$ there is an $s \in S$ such that $\norm{s-t} < \varepsilon$. 
\complexity In \VR\ by Koiran~\cite{K99}. \VR-complete by B\"{u}rgisser, Cucker~\cite[Proposition 5.2,Corollary 9.3]{BC09}, and Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} via reduction from strict positivity over a bounded domain.
\comments The tricky part here is membership in \VR, that follows using Koiran's method~\cite{K99}.  B\"{u}rgisser, Cucker~\cite{BC09} showed the problem complete for semialgebraic sets defined by arithmetic circuits, Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} strengthened the result to semialgebraic sets defined by formulas. 

The directed Hausdorff distance of $S$ and $T$~\ourref[Semialgebraic Set(s)!Hausdorff distance]{p:Hausdorffdist} is $0$ if and only if $S \cap T$ is dense in $T$, so replacing $\R^n$ with another semialgebraic set leads to a \VER-complete problem.  
%\universality 
\openq Does the problem remain hard for algebraic sets?
\also Distance of semialgebraic sets~\ourref{p:distancesemi}, (directed) Hausdorff distance of semialgebraic sets (second level)~\ourref{p:Hausdorffdist}, zero in closure of semialgebraic set~\ourref{p:ZeroinClosure}, Image density (second level)~\ourref{p:imagedensity}, Domain density (arithmetic circuit)~\ourref{p:DomainDensityAC}.
%\tags semialgebraic sets 
\end{problemA}


\begin{problemA}{Zero in Closure of Semialgebraic Set}
\label{p:ZeroinClosure}
%zero in closure of semialgebraic set~\ourref[Semialgebraic Set(s)!Zero in closure]{p:ZeroinClosure}
%zero in closure of semialgebraic set~\ourref{p:ZeroinClosure}
\mindex{Semialgebraic Set(s)!Zero in closure}
\given A semialgebraic set $S \subseteq \R^n$.
\question Does $0$ belong to the closure of $S$? That is, are there $s_n \in S$ such that $\norm{s_i}\rightarrow 0$ for $n \rightarrow \infty$?
\complexity \ER-complete by Cucker, Rossell\'{o}~\cite{CR92}.
\comments Membership is the interesting result here, it requires an upper bound from real algebraic geometry. Cucker and Rossell\'{o}~\cite{CR92} call this the {\em (Euclidean) adherence}\mindex{Semialgebraic Set(s)!Adherence} problem.  B\"{u}rgisser, Cucker~\cite[Proposition 5.1,Corollary 9.4]{BC09} study both the Euclidean and Zariski adherence problem.
%\universality 
\openq How hard is this problem in the Zariski topology~\cite[Table 2]{BC09}?
\also Distance of semialgebraic sets~\ourref{p:distancesemi}.
%\tags 
\end{problemA}


\begin{problemA}{Isolated Point of Semialgebraic Set}
\label{p:isopoint}
%isolated point~\ourref[Semialgebraic Set(s)!isolated point]{p:isopoint}
%isolated point~\ourref{p:isopoint}
\mindex{Semialgebraic Set(s)!isolated point}
\given A semialgebraic set $S \subseteq \R^n$.
\question Is $0$ an isolated point in $S$, that is, does $S$ not contain other points arbitrarily close to $0$?
\complexity \VR-complete by B\"{u}rgisser, Cucker~\cite[Corollary 6.7, Corollary 9.4]{BC09} via a reduction from  testing whether $0$ lies in the closure of a semialgebraic set~\ourref[Semialgebraic Set(s)!Zero in closure]{p:ZeroinClosure}. 
\comments The problem remains hard for algebraic sets, see the isolated zero problem~\ourref[Polynomial(s)!Isolated Zero]{p:ISO}. The complexity of testing whether a semialgebraic set contains an isolated point is open~\ourref[Semialgebraic Set(s)!isolated point existence (Open)]{p:semiisolated}. 
%\universality 
%\openq 
\also Isolated zero~\ourref{p:ISO}, semialgebraic set with isolated point~\ourref{p:semiisolated}, zero in closure of semialgebraic set~\ourref{p:ZeroinClosure}. 
%\tags 
\end{problemA}


\begin{problemA}{Closedness of Basic Semialgebraic Set}
\label{p:closedness}
%closedness of basic semialgebraic set~\ourref[Basic Semialgebraic Set!closedness]{p:closedness}
%closedness of basic semialgebraic set~\ourref{p:closedness}
\mindex{Basic Semialgebraic Set!closedness}
\index{Closedness|see {Basic Semialgebraic Set}}
\given Basic Semialgebraic set $B \subseteq \R^n$, a natural number $n \geq 2$.
\question Is $B$ {\em closed}, that is, does it contain all its limit points? 
\complexity \VR-complete by B\"{u}rgisser, Cucker~\cite[Lemma 6.20,Corollary 9.4]{BC09} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments Hardness is easy: let $B = \{(x,y) \in R^{n+1}: f(x) = 0, y > 0\}$, then $f$ is not feasible if and only if the basic semialgebraic set $B$ is closed; membership in \VR\ is much trickier, and is open for semialgebraic sets in general\index{Semialgebraic Set(s)!closedness (Open)}.
The problem remains \VR-hard for compactness instead of closedness\index{Semialgebraic Set(s)!compactness (Open)}. 
%\universality 
\openq Does the problem lie in \VR\ for semialgebraic sets? 
\also Zero in Closure of semialgebraic sets~\ourref{p:ZeroinClosure}. 
%\tags 
\end{problemA}


\begin{problemA}{Distance of Semialgebraic Sets}
\label{p:distancesemi}
%distance of semialgebraic sets~\ourref[Semialgebraic Set(s)!distance]{p:distancesemi}
%distance of semialgebraic sets~\ourref{p:distancesemi}
\mindex{Semialgebraic Set(s)!distance}
\given Two semialgebraic sets $S, T \subseteq \R^n$.
\question Do $S$ and $T$ have distance $0$, that is, are there $s_n \in S$ and $t_n \in T$ such that $\norm{s_i-t_t}\rightarrow 0$ for $n \rightarrow \infty$?
\complexity \ER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS17} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments \ER-hardness is easy, more interesting is membership in \ER, since there is a universal quantifier which has to be eliminated. The special case in which $T$ consists of a single point amounts to determining whether a point lies in the closure of a semialgebraic set~\ourref[Semialgebraic Set(s)!Zero in closure]{p:ZeroinClosure}.
%\universality 
%\openq 
\also Zero in closure of semialgebraic set~\ourref{p:ZeroinClosure}, Hausdorff distance~\ourref{p:Hausdorffdist}.
%\tags 
\end{problemA}


\begin{problemA}{Hyperplane Local Support of Semialgebraic Set}
\label{p:LocSupp}
%locally supporting hyperplane~\ourref[Semialgebraic Set(s)!local support by hyperplane]{p:LocSupp}
%locally supporting hyperplane~\ourref{p:LocSupp}
\mindex{Semialgebraic Set(s)!local support by hyperplane}
\given A semialgebraic set $S \subseteq \R^n$, hyperplane $H$.
\question Does $H$ locally support $S$; that is, some open subset of $H$ belongs to $S$ and, close to that subset, all of $S$ lies on the same side of $H$?
\complexity \ER-complete by B\"{u}rgisser, Cucker~\cite{BC09} and Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
\comments Hardness was shown by B\"{u}rgisser and Cucker~\cite{BC09} for arithmetic circuits for a (potentially) larger class. Schaefer and \v{S}tefankovi\v{c}~\cite{SS23} consider semialgebraic sets defined by formulas. 
%\universality 
%\openq 
\also Distance of semialgebraic sets~\ourref{p:distancesemi}.
%\tags 
\end{problemA}

