\section{Computational Geometry}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Realizability of Configurations}

\begin{quote}
A rank-$d$ \emph{chirotope} is a function $\chi: \{1,2,\ldots ,n\}^d: \rightarrow \{-1,0,1\}$ with the following properties:
(i) exchanging two components $i$ and $j$ changes the sign: $\chi (\tau_{ij}(\lambda)) = -\chi(\lambda)$ , hence it is an \emph{alternating sign map}; (ii) the function $|\chi|$ is the characteristic function of independent sets of a \emph{matroid}; (iii) the following \emph{Grassmann-Pl\"ucker relation} holds:
for every $\lambda\in [n]^{d-2}$ and $a,b,c,d\in [n]\setminus\lambda$, the set 
\[
\{ 
\chi(\lambda , a,b)\cdot \chi(\lambda ,c,d), -\chi(\lambda ,a,c)\cdot \chi(\lambda ,b,d), \chi(\lambda ,a,d)\cdot \chi(\lambda ,b,c)
\}
\]
either contains $\{ -1,+1\}$ or equals $\{ 0\}$.
We usually identify a chirotope $\chi$ with it opposite $-\chi$.
A chirotope defines an oriented matroid of rank $d$. In rank three, chirotopes are often referred to as \emph{order types}. 
it can be checked that for a given set of $n$ vectors $\{ v_1,v_2,\ldots ,v_n\}$ in $\R^d$, the function $\chi$ that returns 
$\sgn (\det (v_{\lambda_1}, v_{\lambda_2}, \ldots , v_{\lambda_d}))$ satisfies the above properties. This function indicates
the orientation of the simplex formed by any $d$-tuple of vectors. In the plane, we can associate to every point $p\in\R^2$ the vector $(p_1,p_2,1)$. Then the rank-three chirotope given by the determinant indicates whether a given ordered triple of points
forms a clockwise, counter-clockwise, or flat triangle. 
It is not true that every rank-three chirotope corresponds to a set of points in the plane, in that sense. Deciding this is one of the fundamental \ER-complete problem.
\end{quote}


\begin{problemCG}{(Simple) Order Type Realizability}
\label{p:ordertype}
\mindex{Order Type Realizability}\mindex{Simple Order Type Realizability}
\given An order type $\chi: [n]^3: \rightarrow \{-1,0,1\}$.
\question Are there points $p_1, \ldots, p_n$ in the plane realizing this order type, hence such that $p_k$ lies to the left of $p_ip_j$ if $\chi(p_i,p_j,p_k) = -1$, to the right if $\chi(p_i,p_j,p_k) = 1$, and the three points are collinear otherwise?
\complexity \ER-complete by Mn\"{e}v~\cite{M88, S91} even if the order type is {\em simple} (aka {\em uniform}), that is, does not take on value $0$.
\comments This is one of the original \ER-complete problems, dual to simple stretchability~\ourref[Simple Stretchability]{p:Stretch}, and a special case of (rank-$3$) oriented matroid realizability\index{Matroid!Oriented Matroid Realizability}. For a detailed proof of \ER-completeness, see Matou\v{s}ek~\cite{M14}. In spatial reasoning, the order type is captured by the $\mathcal{LR}$-calculus (left/right calculus,~\ourref[LR Calculus@$\mathcal{LR}$-Calculus]{p:LRCalculus}), which is therefore \ER-complete~\cite{WL10}. There is a partial variant, in which $\chi$ is only required to be defined on subsets of $[n]$ of fixed size and fixed overlap; that version remains \ER-complete~\cite{S21b}, which is useful in establishing results for problems with fixed parameters, such as segment intersection graphs of bounded degree~\ourref[Segment Intersection Graph]{p:SEG}, pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}, and the rectilinear local crossing number~\ourref[Graph(s)!Rectilinear Local Crossing Number]{p:rectloccross}. 
\universality Mn\"{e}v~\cite{M88}, also see Shor~\cite{S91}. 
%\openq 
\also Directional walk~\ourref{p:directwalk}, collinearity logic~\ourref{p:CollLogic}, $\mathcal{LR}$-calculus~\ourref{p:LRCalculus}, pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}, rectilinear local crossing number~\ourref{p:rectloccross}.
%\tags 
\end{problemCG}


\begin{problemCG}{Oriented Matroid Realizability Over the Reals}
\label{p:ormatroidreal}
\mindex{Matroid!Real Realizability}
\given A rank-$d$ oriented matroid, for some fixed $d$, given for example as a chirotope $\chi:[n]^d\to \{-1,0,1\}$. 
\question Can this oriented matroid be realized over the reals, hence are there vectors $v_1,\ldots,v_n \in \R^d$ such that $\chi (\lambda) = \sgn(\det(v_{\lambda_1}, v_{\lambda_2}, \ldots, v_{\lambda_d}))$?
\complexity \ER-complete from order type realizability~\ourref[Order Type Realizability]{p:ordertype}.
%\universality 
% \openq 
\also Order type realizability~\ourref{p:ordertype}. 
\end{problemCG}



\begin{problemCG}{Matroid Realizability Over the Reals}
\label{p:matroidreal}
\mindex{Matroid!Real Realizability}
\given A family $F\subset 2^{[n]}$ and a dimension $d\in \N$. 
\question Are there vectors $v_1,\ldots,v_n \in \R^d$ such that for every set $s\in 2^{[n]}$, we have $s\in F$ if and only if the vectors $\{v_i : i \in S \}$ are linearly independent?
\complexity \ER-complete by Kim, Mesmay, and Miltzow~\cite{KdMM23}; the paper contains two reductions: one from order type realizability~\ourref[Order Type Realizability]{p:ordertype}, the other from distinct \ETR~\ourref[Distinct ETR@Distinct \ETR]{p:DistETR}.  
\comments The proof follows from a careful reading of the \ER-completeness proofs of order type realizability~\ourref[Order Type Realizability]{p:ordertype}~\cite{M14}, but
the result was first explicitly stated by Kim, Mesmay, and Miltzow~\cite{KdMM23}
in an arguably simpler and self-contained way.
Matroids can be represented in various ways, affecting the complexity status of the realizability problem.
Typically matroids are given by a circuit or black-box model. Compared to that,
the explicit representation via independent sets may appear wasteful. However,
representing the problem explicitly an only make it easier, but it is still \ER-hard. Moreover,
matroid realizability is \ER-complete for every fixed $d\geq 3$, so at most $O(n^d)$ sets have to be specified.

Sturmfels also studied the problem of matroid realizability over the rational numbers and showed similar equivalences with finding rational solutions to Diophantine equations~\cite{S87}.
However Sturmfels' reduction is not polynomial time, so does not establish an \EQ-completeness result.
%\universality 
% \openq 
\also Order type realizability~\ourref{p:ordertype}, distinct \ETR~\ourref{p:DistETR}. 
%\tags 
\end{problemCG}


\begin{problemCG}{(Simple) Allowable Sequence}
\label{p:allowableseq}
%simple allowable sequence~\ourref[Simple Allowable Sequence]{p:allowableseq}
%allowable sequence~\ourref[Allowable Sequence]{p:allowableseq}
%simple allowable sequence~\ourref{p:allowableseq}
%allowable sequence~\ourref{p:allowableseq}
\mindex{Allowable Sequence}
\mindex{Simple Allowable Sequence}
\given A sequence $\pi_1, \ldots, \pi_k$ of permutations of $[n]$.  
\question Is the given sequence {\em allowable}, that is, is there a set of $n$ points in the plane so that the permutations $\pi_1, \ldots, \pi_k$ are obtained, in that order, by projecting the points onto a line rotating by a half turn around some point of the plane?
\complexity \ER-complete by Hoffmann and Merckx~\cite{HM18} even if the sequence is {\em simple}, that is, every two consecutive permutations differ by transposition of two adjacent elements via a reduction from order type realizability~\ourref[Order Type Realizability]{p:ordertype}. 
\comments Allowable sequences are one of the oldest tools in the computational geometers tool set, first introduced in the 19th century, see~\cite{GP80}.
\universality Hoffmann and Merckx~\cite{HM18}.
%\openq 
\also Order type realizability~\ourref{p:ordertype}, visibility graph of polygon with holes~\ourref{p:polygonholesvisibility}.
%\tags 
\end{problemCG}


\begin{problemCG}{Radial System Realizability}
\label{p:radialsystem}
%radial system realizability~\ourref[Radial System!Realizability]{p:radialsystem}
%radial system realizability~\ourref{p:radialsystem}
\mindex{Radial System!Realizability}
\given An (abstract) radial system, that is a family $(\pi_i)_{i \in [n]}$ such that $\pi_i$ is a permutation of $[n]-\{i\}$, for each $i$.
\question Are there points $p_1, \ldots, p_n$ in the plane so that for each $i$, the points seen from $p_i$ occur in radial clockwise order as described by $\pi_i$?
\complexity \ER-complete by Cardinal and Kusters~\cite{CK15} via a reduction from order type realizability~\ourref[Order Type Realizability]{p:ordertype}.
\comments There is a partial variant, in which the radial system only needs to be specified for point sets of bounded size and overlap, see~\cite{S21b}; the partial variant can be used to establish hardness for problems with fixed parameters, such as existence of simultaneous geometric embeddings for a fixed number of graphs, and straight-line realizability of bounded-degree graphs with rotation system~\ourref[Graph(s)!Straight-line Realizability of Graph with Rotation System]{p:straightrotation}.
%\universality 
%\openq 
\also Order type realizability~\ourref{p:ordertype}, straight-line realizability of graph with rotation system~\ourref{p:straightrotation}, simultaneous geometric embedding~\ourref{p:SGE}.
%\tags 
\end{problemCG}


\begin{problemCG}{Directional Walk}
\label{p:directwalk}
%directional walk~\ourref[Directional Walk]{p:directwalk}
%directional walk~\ourref{p:directwalk}
\mindex{Directional Walk}
\given A walk $W$ on $n$ vertices, and a direction left/right for every triple of consecutive points along $W$. 
\question Are there $n$ points in the plane so that for all triples $(p,q,r)$ of consecutive points along the walk, $r$ lies to the left or right or $pq$ as specified and distinct vertices are mapped to distinct locations?
\complexity \ER-complete~\cite{S21b} via a reduction from a partial version of order type realizability~\ourref[Order Type Realizability]{p:ordertype}. Remains \ER-complete even if each edge occurs at most once on the walk~\cite{KR23}.  
\comments The directional walk problem can be viewed as a sparsified version of order type realizability, or a special case of the left/right calculus~\cite{WL10}. 
%\universality 
\openq Does the problem remain \ER-complete if the realizing walk has to be crossing-free? 
\sep\ The proof in~\cite{S21b} implies that the problem remains \ER-complete even if each vertex occurs only a finite number of times along the walk. Is the directional walk problem \ER-complete even if each vertex occurs at most twice (once being trivial)?
\also Order type realizability~\ourref{p:ordertype}.
%\tags 
\end{problemCG}



\begin{problemCG}{Finite Convex Geometry Realizability}
\label{p:convexgeoreal}
%finite convex geometry realizability~\ourref[Finite Convex Geometry Realizability]{p:convexgeoreal}
%finite convex geometry realizability~\ourref{p:convexgeoreal}
\mindex{Finite Convex Geometry Realizability}
\given A {\em finite convex geometry} $(V, \mathcal{C})$, that is a set $\mathcal{C}\subseteq 2^{V}$ that contains $\emptyset$, $V$, is closed under intersection, and for every $C \in \mathcal{C}\setminus \{V\}$ there is an $v \in V$ such that $C \cup \{v\} \in \mathcal{C}$. 
\question Are there $n$ points in $\R^d$ which realize the given finite convex geometry? Letting $\conv(C)$ denote the convex hull of the points in $C$, a point set $P$ {\em realizes} the finite convex geometry $(P, \{C \subseteq P: \conv(C) \cap P = C\})$.   
\complexity \ER-complete by Adaricheva and Wild~\cite{AW10,HM18} for $d = 2$, via a reduction from order type realizability~\ourref[Order Type Realizability]{p:ordertype}, and by Hoffmann and Merckx~\cite{HM18} for $d \geq 2$ via a reduction from allowable sequence~\ourref[Allowable Sequence]{p:allowableseq}.  
%\comments 
%\universality 
%\openq 
\also Allowable sequence~\ourref{p:allowableseq}, order type realizability~\ourref{p:ordertype}, 
convex neural codes~\ourref{p:convneuralcode}. 
%\tags 
\end{problemCG}


\begin{problemCG}{Free Space Matrix Realizability}
\label{p:freespacemat}
%free space matrix realizability~\ourref[Free Space Matrix!Realizability]{p:freespacemat}
%free space matrix realizability~\ourref{p:freespacemat}
\mindex{Free Space Matrix!Realizability}
\given A matrix $M_{\varepsilon} \in \{0,1\}^{n \times n}$, $\varepsilon \in \Q_{>0}$. $M_{\varepsilon}$ is the {\em free space matrix} for two polygonal curves $P = (p_1, \ldots, p_n)$ and $Q = (q_1, \ldots, q_m)$ in $\R^d$, if $M_{\varepsilon}$ has a $1$ in cell $(i,j)$ if and only if $\norm{p_i-q_j} < \varepsilon$.
\question Are there two polygonal curves $P$ and $Q$ so that $M_{\varepsilon}$ is the free space matrix for $P$ and $Q$?
\complexity \ER-complete for every $d \geq 2$ by Akitaya, Buchin, Mirzanezhad, Ryvkin, and Wenk~\cite[Theorem 14]{ABMRW23} via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}.
\comments In $\R^1$, the problem can be decided in polynomial time~\cite[Theorem 16]{ABMRW23}.
%\universality 
%\openq 
\also Free space diagram realizability~\ourref{p:freespacediag}, oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}.
%\tags computational geometry, Fr\'{e}chet distance 
\end{problemCG}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Arrangements and Stretchability}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\begin{quote}
Arrangements of vectors or points can be dualized into arrangements of hyperplanes. From the topological representation theorem~\cite{FL78,BKMS05}, oriented matroids can always be realized as arrangements of pseudo-hyperplanes. In the planar case, we obtain \emph{pseudoline arrangements}. In a projective setting, a pseudoline arrangement is defined on a two-sphere, but a pseudoline arrangement can also be defined in the plane as a collection of $x$-monotone curves that pairwise intersect exactly once. 
For our purpose, the only relevant information about a pseudoline arrangement is the underlying combinatorics, or equivalence class under homeomorphisms of the plane. A convenient way to specify this information is in the form of a \emph{wiring diagram}, or by specifying, for each pseudoline, the left-to-right order of its intersection points with the other pseudolines.
\end{quote}

\begin{problemCG}{(Pseudoline) Stretchability}  %\StretchLabel}
\label{p:Stretch}
%stretchability~\ourref[Stretchability]{p:Stretch}
%simple stretchability~\ourref[Simple Stretchability]{p:Stretch}
%hyperbolic simple stretchability~\ourref[Hyperbolic Simple Stretchability]{p:Stretch}
%stretchability~\ourref{p:Stretch}
%Simple stretchability~\ourref{p:Stretch}
%Hyperbolic simple stretchability~\ourref{p:Stretch}
\mindex{Stretchability!Pseudolines}\mindex{Stretchability}
\mindex{Simple Stretchability}
\mindex{Hyperbolic Simple Stretchability}
\given A pseudoline arrangement.
\question Is the arrangement {\em stretchable}, that is, is it isomorphic to a straight-line arrangement? 
\complexity \ER-complete, by Mn\"{e}v~\cite{M88}, and Shor~\cite{S91} via a reduction from the existential theory of totally ordered real variables~\ourref[Existential Theory of Totally Ordered Real Variables]{p:ETRORV}. The problem remains \ER-complete if the given arrangement is {\em simple}, that is, at most two pseudolines intersect in each point~\cite{SS17}. Since simple stretchability in the plane is equivalent to simple stretchability in the hyperbolic plane, hyperbolic simple stretchability is also \ER-complete~\cite{B22,BBDJ23}.
\comments Stretchability is the original \ER-complete problem in the Mn\"{e}v/Shor tradition. Mn\"{e}v~\cite{M88} showed that pseudoline stretchability is universal, and Shor~\cite{S91} recast the result from a computer scientists point of view. A nice introductory presentation of the result is due to Matou\v{s}ek~\cite{M14}. Shor~\cite{S91} also explicitly shows that pseudo-line stretchability is \NP-hard.
\universality Both pseudoline stretchability and simple pseudoline stretchability are universal, as shown by Mn\"{e}v~\cite{M88}, also see Shor~\cite{S91}. 
%\openq 
\also Existential theory of totally ordered real variables~\ourref[Existential Theory of Totally Ordered Real Variables]{p:ETRORV}, pseudo-segment stretchability~\ourref{p:SegStretch}.
%\tags 
\end{problemCG}


\begin{problemCG}{Pseudo-segment Stretchability}  %\SegStretchLabel}
\label{p:SegStretch}
%pseudo-segment stretchability~\ourref{p:SegStretch}
%pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}
\mindex{Stretchability!Pseudo-segments}
\given An arrangement of \emph{pseudo-segments}: $x$-monotone curves such that each pair intersects exactly once.
\question Is the arrangement {\em stretchable}, that is, is it isomorphic to an arrangement of straight-line segments? 
\complexity \ER-complete by Mn\"{e}v~\cite{M88}, and Shor~\cite{S91}, since pseudoline stretchability~\ourref[Stretchability]{p:Stretch} can be viewed as a special case. The problem remains \ER-complete if each pseudo-segment is involved in at most $72$ crossings and the arrangement is simple, by Schaefer~\cite{S21b} via a reduction from a partial version of order type realizability~\ourref[Order Type Realizability]{p:ordertype}. F{\"{o}}rster, Kindermann, Miltzow, Parada, Terziadis, and Vogtenhuber~\cite{FKMPTV24} show that the problem remains \ER-hard even if the intersection graph of the arrangement has chromatic number at most $30$.
\comments This result can be used to show that segment intersection graphs~\ourref{p:SEG} of degree at most $216$ are \ER-complete to recognize~\cite{S21b} and that the geometric thickness of multigraphs~\ourref[Graph(s)!Geometric Thickness of Multigraph]{p:geothickmulti} is \ER-complete~\cite{FKMPTV24}.
%\universality 
\openq What is the smallest number of crossings on a pseudo-segment for which the pseudo-segment stretchability remains \ER-complete? \sep\ Does the problem remain \ER-complete if the intersection graph of the arrangement has chromatic number at most $2$?~\cite{FKMPTV24}.
\also  Order type realizability~\ourref{p:ordertype}, geometric thickness of multigraphs~\ourref{p:geothickmulti}, segment intersection graph~\ourref{p:SEG}.
%\tags 
\end{problemCG}




\begin{problemCG}{Arrangement Graph}
\label{p:arrangegraph}
\mindex{Arrangement Graph}
\given A graph $G$.
\question Is $G$ an arrangement graph? The vertices of an {\em arrangement graph} are intersection points of an arrangement $L$ of lines in the plane, and two vertices are adjacent if and only if they lie on the same line of $L$ and the line segment between them does not intersect any of the lines in $L$.
\complexity \ER-complete, by Bose, Everett, Wismath~\cite{BEW03} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}.
\also Segment number~\ourref{p:segnumber}.
\end{problemCG}

\begin{problemCG}{(Pseudocircle) Circularizability}
\label{p:pseudocirccirc}
\mindex{Pseudocircle Circularizability}
\given An \emph{arrangement} of \emph{pseudocircles}, that is, a collection of closed curves, any two of which are either disjoint or intersect exactly twice.
\question Is the arrangement {\em circularizable}, that is, is there a homeomorphism of the plane taking it to an arrangement of circles? 
\complexity \ER-complete by Kang and M\"uller~\cite{KM14} (see also Felsner and Scheucher~\cite{FS20}) via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. The problem remains \ER-hard when restricted to arrangements of great pseudocircles~\cite{FS20}. 
%\comments 
%\universality
%\openq 
\also Simple stretchability~\ourref{p:Stretch}.
\end{problemCG}


\begin{problemCG}{Oriented Hyperplane Realizability in $\R^d$}
\label{p:orientedhyperplanereal}
\mindex{Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$}
\given A set $S \subseteq \{-,+\}^n$ with $\{(-,\ldots,-), (+,\ldots,+)\}\subseteq S$.
\question Are there $n$ oriented hyperplanes in $\R^d$ such that for every vector $s \in S$ there is a point in $\R^d$ whose characteristic vector with respect to the hyperplane arrangement is $s$? 
\complexity \ER-complete  by Tanenbaum, Goodrich, and Scheinerman~\cite{TGS95}, Basri, Felzenszwalb, Girshick, Jacobs, and Klivans~\cite{BFGJK09}, and Kang and M\"uller~\cite{KM12} for every $d \geq 2$ via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
\comments Tanenbaum, Goodrich, and Scheinerman~\cite{TGS95} cast the problem slightly differently, as that of recognizing point-halfspace orders~\ourref[Point half space orders in Rd@Point-halfspace orders in $\R^d$]{p:pointhalfspaceorders}. For $d = 2$ this is very close to the simple stretchability problem~\ourref[Simple Stretchability]{p:Stretch}, but with the additional condition that $\{(-,\ldots,-), (+,\ldots,+)\}\subseteq S$. Kang and M\"uller~\cite{KM12} also show that specifying a realizing hyperplane arrangement may require $2^{\Theta(n)}$ bits. Basri, Felzenszwalb, Girshick, Jacobs, and Klivans~\cite{BFGJK09} introduce oriented hyperplane realizability under the name matrix visibility\index{Matrix Visibility} problem and show it is \ER-hard (they only claim \NP-hardness, but reduce from oriented matroid realizability~\ourref[Matroid!Oriented Matroid Realizability]{p:ordertype}). For $d = 2$, McDiarmid and M\"{u}ller study this as the oriented line arrangement problem\index{Oriented Line arrangement}.
%order type realizability~\ourref{p:ordertype}). 
%\universality 
%\openq 
\also Point-halfspace orders~\ourref{p:pointhalfspaceorders}, dot-product graph~\ourref{p:dotprodgraph}, unit ball graph~\ourref{p:unitballgraph}, Euclidean preference~\ourref{p:Euclideanpref}, oriented matroid realizability~\ourref{p:ordertype}. 
\end{problemCG}


\begin{problemCG}{Point-halfspace orders in $\R^d$}
\label{p:pointhalfspaceorders}
\mindex{Point half space orders in Rd@Point-halfspace orders in $\R^d$}
\given A bipartite poset $(B,T,\leq)$.
\question Are there injective maps $f$ from $B$ to $\R^2$ and $g$ from $T$ to the set of halfplanes in $\R^2$ such that $f(x)\in g(y)$ if and only if $x\leq y$? 
\complexity \ER-complete  by Tanenbaum, Goodrich, and Scheinerman~\cite{TGS95} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. Also \ER-complete in any fixed higher dimension $d$.
\comments This is a different but essentially equivalent encoding of the oriented hyperplane realizability problem~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. 
%\universality 
%\openq 
\also Oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}. 
\end{problemCG}


\begin{problemCG}{Circle Orders}
\label{p:circleorders}
\mindex{Circles orders}
\given A poset $P = (S,\leq)$.
\question Is $P$ the containment order of a set of closed disks in the plane, hence does there exist an injective map $f$ from $S$ to the set of closed disks in $\R^2$ such that $f(x)\subseteq f(y)$ if and only if $x\leq y$? 
\complexity \ER-complete by Cardinal~\cite{C24} via a reduction from pseudocircle circularizability~\ourref[Pseudocircle Circularizability]{p:pseudocirccirc}. Also \ER-complete if $P$ is a bipartite poset.
%\universality 
%\openq 
\also Point-halfspace orders~\ourref{p:pointhalfspaceorders}.
\end{problemCG}

\subsection{Covering and Packing}

\begin{problemCG}{Art Gallery Problem}
\label{p:ArtGallery}
\mindex{Art Gallery Problem}
\given A simple polygon $P$ with corners in $\Q^2$ and a number $k \in \N$.
\question Does there exist a set $G\subset P$ of $k$ guards such that every point inside the polygon is visible from~$G$? Two points $a$, $b$ are said to be visible to each other in case that the line segment $ab$ is completely contained in the polygon~$P$. The polygon is considered to be closed.
\complexity \ER-complete, by Abrahamsen, Adamaszek, Miltzow~\cite{AAM18,AAM22}, and Stade~\cite{S23c}
\comments  Also known as the minimum star cover problem~\cite{OR87}\index{Minimum Star Cover}. The original \ER-completeness proof in~\cite{AAM22} is fairly involved, but Stade found a shorter proof in 2022~\cite{S23}.
It is known that irrational coordinates can already be necessary for two and three guardable galleries~\cite{AAM17, MM22}. 
There is a series of papers that try to find practical algorithms for the art gallery problem.
Interestingly some of them come with provable performance guarantees under some mild assumptions~\cite{HM21}.
\universality The art gallery problem admits topological universality~\cite{BEMMSW22,BEMMSW23,ST22}.
\openq Does the problem lie in \ER\ for semialgebraic art galleries, even in $\R^2$?
\also Polygon convex cover~\ourref{p:polygonconvcov}, star-shapedness of semialgebraic set~\ourref{p:starshaped}. 
%\tags 
\end{problemCG}

\begin{problemCG}{Boundary-Guarding}
\label{p:boundaryguard}
\mindex{Boundary Guarding@Boundary-Guarding}
\given A simple polygon $P$ with corners in $\Q^2$ and a number $k \in \N$.
\question Does there exist a set $G\subset \partial P$ of $k$ guards such that every point inside the polygon is visible by at least one guard in~$G$?
\complexity \ER-complete, by Stade~\cite{S23c} via a reduction from \RGETRINV~\ourref[Range ETRINV@\RGETRINV]{p:RGETRINV}.
\comments The boundary guarding problems differs from the art gallery problem~\ourref[Art Gallery Problem]{p:ArtGallery} in that the guards must be on the boundary.
%\universality 
\openq It is open if boundary-boundary guarding is \ER-complete; in the boundary-boundary variant, all guards must be placed on the boundary, and only the boundary has to be guarded~\cite{S23c}. This is similar to the terrain guarding problem, which turns out to be \NP-complete~\cite{KK11,FHK16}.
\also Art gallery problem~\ourref{p:ArtGallery}, \ETRINV~\ourref{p:ETRINV}.
\end{problemCG}


\begin{problemCG}{Geometric Packing}
\label{p:geopack}
\mindex{Geometric Packing}
\given A simple polygon $C$, the {\em container}, and polygonal pieces $p_1,\ldots,p_m$, all polygons have corners in $\Q^2$.
\question Is it possible to move (translate and rotate) all the pieces so they lie in the container without overlapping?
\complexity This problem is \ER-complete, by Abrahamsen, Miltzow, and Seiferth~\cite{AMS20}, even
if the container is a square and all pieces are convex. The reduction is from \ETRINV~\ourref[ETRINV@\ETRINV]{p:ETRINV}. 
\comments The problem is in \NP\ in case that only translations are allowed. 
The proof from~\cite{AMS20} required that either the pieces or the container had a partially curved boundary. This condition was removed in a paper by Miltzow and Schmiermann~\cite{MS24} about continuous constraint satisfaction problems~\ourref[Continuous Constraint Satisfaction Problem]{p:CSSP}, which implies that geometric packing remains \ER-complete even if all the pieces are convex and polygonal, a simplified proof of that result can also be found in~\cite{AMS24}.
%\universality 
\openq Does the problem remain \ER-hard if the pieces are restricted to a fixed number of shapes (one, for example)~\cite{S21b}? 
\sep\
Is the problem fixed-parameter tractable in the number $m$ of pieces?
\sep\ How hard is the packing problem if the pieces to be packed are unit disks? Hardness may be easier to show for polygons with holes~\cite{A24b}.
%\also 
\end{problemCG}

\begin{problemCG}{Polygon Convex Cover}
\label{p:polygonconvcov}
\mindex{Polygon!Convex Cover}
\given A simple polygon, a natural number $k \in \N$.
\question Can the polygon be written as the union of at most $k$ convex polygons?
\complexity \ER-complete by Abrahamsen~\cite{A22} via a reduction from \RGETRINV~\ourref[Range ETRINV@\RGETRINV]{p:RGETRINV}. The problem remains \ER-complete even if all the convex polygons have to be triangles.
\comments Also known as the {\em minimum convex cover problem}\index{Minimum Convex Cover}, it was previously known to be \NP-hard~\cite{CR94} and to lie in \ER~\cite{OR82}. Replacing convex sets with star-shaped sets one obtains the art gallery problem~\ourref[Art Gallery Problem]{p:ArtGallery}. 
%\universality 
\openq Abrahamsen~\cite{A24b} asks whether the polygon cover problem remains \ER-hard if a set of convex polygons is given and the original polygon has to be covered by rotated and translated copies of the convex polygons.   
\also \ETRINV~\ourref{p:ETRINV}, \RGETRINV~\ourref{p:RGETRINV}, art gallery problem~\ourref{p:ArtGallery}.
%\tags 
\end{problemCG}

\subsection{Geometric Representations of Graphs and Hypergraphs}


\begin{problemCG}{Unit Disk Graph}
\label{p:unitdiskgraph}
%unit disk graph~\ourref[Disk Graph!Unit Disk Graph]{p:unitdiskgraph}
%unit disk graph~\ourref{p:unitdiskgraph}
\mindex{Disk Graph!Unit Disk Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of unit disks in the plane?
\complexity \ER-complete, by McDiarmid, M\"{u}ller~\cite{McDM10,McDM13} via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. The problem remains \ER-complete for unit balls in $d$-dimensional space~\cite{KM12} again via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}.
\comments This problem was earlier shown to be \NP-hard in~\cite{BK98}.
%\universality 
\openq Does the problem remain hard for graphs of bounded degree~\cite{S21b}? 
\also Disk graph~\ourref{p:diskgraph}, hyperbolic unit disk graph~\ourref{p:hypunitdiskgraph}, unit ball graph~\ourref{p:unitballgraph}, unit disk contact graph~\ourref{p:unitdiskcontact}, oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}.
%\tags geometric intersection graphs
\end{problemCG}


\begin{problemCG}{Disk Graph}
\label{p:diskgraph}
%disk graph~\ourref[Disk Graph]{p:diskgraph}
%disk graph~\ourref{p:diskgraph}
\mindex{Disk Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of disks in the plane?
\complexity \ER-complete, by McDiarmid, M\"{u}ller~\cite{McDM13} via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. 
%\comments  
%\universality 
\openq Does the problem remain \ER-complete for balls in $d$-dimensional space~\cite{McDM13}? \sep\ Does the problem remain hard for graphs of bounded degree?
\also Unit disk graph~\ourref{p:unitdiskgraph}, unit ball graph~\ourref{p:unitballgraph}.
%\tags geometric intersection graphs
\end{problemCG}


\begin{problemCG}{Hyperbolic Unit Disk Graph}
\label{p:hypunitdiskgraph}
%hyperbolic unit disk graph~\ourref[Disk Graph!Hyperbolic Unit Disk Graph]{p:hypunitdiskgraph}
%hyperbolic unit disk graph~\ourref{p:hypunitdiskgraph}
\mindex{Disk Graph!Hyperbolic Unit Disk Graph}
\given A graph $G$. 
\question Is $G$ the intersection graph of unit disks in the hyperbolic plane?
\complexity \ER-complete, by Bieker, Bl{\"{a}}sius, Dohse, and Jungeblut~\cite{BBDJ23} via a reduction from hyperbolic simple stretchability~\ourref[Hyperbolic Simple Stretchability]{p:Stretch}.
\comments The proof uses the result that every unit disk graph is also a hyperbolic unit disk graph~\cite{BFKS23}.  
%\universality 
%\openq 
\also Unit disk graph~\ourref{p:unitdiskgraph}, hyperbolic simple stretchability (under Stretchability~\ourref{p:Stretch}).
%\tags geometric intersection graphs
\end{problemCG}


\begin{problemCG}{Unit Ball Graph in $\R^d$}
\label{p:unitballgraph}
%unit ball graph~\ourref[Unit Ball Graph in Rd@Unit Ball Graph in $\R^d$]{p:unitballgraph}
%unit ball graph~\ourref{p:unitballgraph}
\mindex{Unit Ball Graph in Rd@Unit Ball Graph in $\R^d$}
\given A graph $G$.
\question Is $G$ the intersection graph of unit balls in $\R^d$?
\complexity \ER-complete for every fixed $d \geq 2$ by Kang, M\"{u}ller~\cite{KM12} via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. This generalizes the result for unit disk graphs~\ourref{p:unitdiskgraph}, the case $d = 2$, by McDiarmid and M\"{u}ller~\cite{McDM10}. 
\comments Kang and  M\"{u}ller~\cite{KM12} call this the {\em $d$-sphericity} problem\index{sphericity@$d$-sphericity}, and they establish exponential lower and upper bounds on the centers of a family of balls representing $G$. Fiduccia, Scheinerman, Trenk and Zito~\cite{FSTZ98} asked whether the problem lies in \NP. For $d = 1$ we get the {\em unit interval problem}, which is solvable in linear time~\cite{LO93}.
%\universality 
\openq Does recognizing unit ball graphs remain \ER-complete in $d$-dimensional hyperbolic space~\cite{BBDJ23}?
\also Unit disk graph~\ourref{p:unitdiskgraph}, oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}, dot-product graph~\ourref{p:dotprodgraph}.
%\tags geometric intersection graphs
\end{problemCG}



\begin{problemCG}{Dot-Product Graph in $\R^d$}
\label{p:dotprodgraph}
%dot-product graph~\ourref[Dot Product Graph in Rd@Dot-Product Graph in $\R^d$]{p:dotprodgraph}
%dot-product graph~\ourref{p:dotprodgraph}
\mindex{Dot Product Graph in Rd@Dot-Product Graph in $\R^d$}
\given A graph $G = (V,E)$.
\question Are there vectors $v_1, \ldots, v_n \in \R^d$ such that $ij \in E$ if and only if $v_i^Tv_j \geq 1$ for all $ 1\leq i,j \leq n$?
\complexity \ER-complete, by Kang, M\"{u}ller~\cite{KM12} for every fixed $d \geq 2$ via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. This generalizes the result for unit disk graphs~\ourref{p:unitdiskgraph}, the case $d = 2$, by McDiarmid and M\"{u}ller~\cite{McDM10}. 
\comments The problem was introduced by Fiduccia, Scheinerman, Trenk and Zito~\cite{FSTZ98}. The smallest $d$ for which $G$ has a dot-product representation is the {\em dot-product dimension} of the graph. Kang and M\"uller~\cite{KM12} also establish exponential upper and lower bounds on the precision of the vectors~$v_i$. 
%\universality 
%\openq 
\also Oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}, unit ball graph~\ourref{p:unitballgraph}, unit disk graph~\ourref{p:unitdiskgraph}, representing graph with ortogonal vectors~\ourref{p:graphorthogonalvectorsR3}. 
%\tags 
\end{problemCG}


\begin{problemCG}{Segment Intersection Graph (\SEG)}
\label{p:SEG}
\mindex{Segment Intersection Graph}
\index{SEG@\SEG|see {Segment Intersection Graph}}
\given A graph $G$.
\question Is $G$ the intersection graph of line segments in the plane?
\complexity \ER-complete, by Kratochv{\'\i}l and Matou{\v{s}}ek~\cite{KM94}, reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
The problem remains \ER-hard for graphs of bounded degree~\cite{S21b} via a reduction from pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}.
\comments A slightly simplified \ER-hardness proof can be found in~\cite{S10} and, in full detail, in~\cite{M14}. Kratochv{\'\i}l and Matou{\v{s}}ek~\cite{KM94} show that there are graphs on $n$ vertices which require segment representations of size $2^{2^{\Omega(n^{0.5})}}$, and that there are always representations of size at most $2^{2^{O(n)}}$.
%\universality 
\openq The problem is known to be \NP-hard for graphs of girth at least $k$~\cite{KP07}, does it remain \ER-hard?
\also Unit segment intersection graph~\ourref{p:uniSEG}, 3D segment intersection graph~\ourref{p:3dSEG}, planar slope number~\ourref{p:planarslopenumb}, pseudo-segment stretchability~\ourref{p:SegStretch}, $k$-polyline intersection graph~\ourref{p:kpolySEG}, incidence graph of geometric $3$-configuration~\ourref{p:geoconfig}, linear hypergraph realizability~\ourref[Linear Hypergraph Realizability]{p:linhypreal}.
%\tags geometric intersection graphs
\end{problemCG}



\begin{problemCG}{Unit Segment Intersection Graph}
\label{p:uniSEG}
\mindex{Segment Intersection Graph!Unit Segment Intersection Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of unit line segments in the plane?
\complexity \ER-complete, by Hoffmann, Miltzow, Weber, and Wulf~\cite{HMWW24}, reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
\also Segment intersection graph~\ourref{p:SEG}.
\end{problemCG}

\begin{problemCG}{$k$-Polyline Intersection Graph}
\label{p:kpolySEG}
\mindex{Segment Intersection Graph!$k$-Polyline Intersection Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of $k$-polylines in the plane? A {\em $k$-polyline} is a polygonal chain consisting of $k-1$ line segments.
\complexity \ER-complete, by Hoffmann, Miltzow, Weber, and Wulf~\cite{HMWW24} for any fixed $k$ via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
\also Segment intersection graph~\ourref{p:SEG}.
\end{problemCG}


\begin{problemCG}{(Downward) Ray Intersection Graph}
\label{p:rayintersect}
\mindex{Ray Intersection Graph}
\mindex{Ray Intersection Graph!Downward Ray Intersection Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of (downward) rays in the plane?
\complexity The recognition of both ray and downward ray intersection graphs is \ER-complete by Cardinal, Felsner, Miltzow, Tompkins and Vogtenhuber~\cite{CFMTV18} via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}.
\comments Downward ray intersection graphs are equivalent to grounded segment graphs~\cite{CFMTV18}. The paper~\cite{CFMTV18} also shows \ER-completeness of outer segment graph recognition. Outer segments have one endpoint on a common circle and the other endpoint in the interior of the circle.
%\universality 
\also Segment intersection graph~\ourref{p:SEG}.
\end{problemCG}

\begin{problemCG}{3D Segment Intersection Graph}
\label{p:3dSEG}
\mindex{Segment Intersection Graph!3D Segment Intersection Graph}
\index{3D Segment Intersection Graph|see {Segment Intersection Graph}}
\given A graph $G$.
\question Is $G$ the intersection graph of line segments in $\R^3$?
\complexity \ER-complete, by Evans, Rz\c{a}\.{z}ewski, Saeedi, Shin, and Wolff~\cite{ERSSW19} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}.
\comments The authors remark that the problem remains \ER-hard in any fixed dimension.
\also Segment intersection graph~\ourref{p:SEG}.
\end{problemCG}

\begin{problemCG}{3D Line Intersection Graph}
\label{p:LIG}
\mindex{Line Intersection Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of lines in $\R^3$?
\complexity \ER-complete, by Cardinal~\cite{C24} via a reduction from matroid realizability over the reals~\ourref{p:matroidreal}.
%\universality 
\also Segment intersection graph~\ourref{p:SEG}, 3D segment intersection graph~\ourref{p:3dSEG}.
\end{problemCG}


\begin{problemCG}{Convex Set Intersection Graph}
\label{p:convintersect}
\mindex{Convex Set Intersection Graph, see {Convex Set(s)}}
\mindex{Convex Set(s)!Intersection Graph}
\given A graph $G$.
\question Is $G$ the intersection graph of a family of convex sets in the plane?
\complexity \ER-complete, by Schaefer~\cite{S10} by a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. Remains \ER-complete if the graph has bounded degree~\cite{S21b}.
\comments While not explicitly claimed in~\cite{S10}, \ER-hardness also holds for any family of convex sets that can arbitrarily closely approximate any line segment; this includes ellipses\index{Ellipses Intersection Graph}, triangles and convex polygons. It was shown by M\"{u}ller, van Leeuwen, van Leeuwen~\cite{MvLvL13} that the intersection graph recognition
problem for translates (or homothets) of any fixed convex polygon can be solved on an exponential-size grid.
This implies that the corresponding recognition problems lie in \NP.
%\universality 
\openq Bieker, Bl{\"{a}}sius, Dohse, and Jungeblut~\cite{BBDJ23} ask whether the problem remains \ER-complete in the hyperbolic plane.
\also Segment intersection graph~\ourref{p:SEG}, topological inference in RCC8 with convexity~\ourref{p:RCC8con}.
%\tags geometric intersection graphs
\end{problemCG}


\begin{problemCG}{Nerves of Convex Set}
\label{p:nervesconv}
\mindex{Convex Set(s)!Nerves}
\given A simplicial complex $S$ of dimension $k$.
\question Is $S$ the $k$-skeleton of the nerve of $c$-dimensional convex sets in $\R^d$?
\complexity \ER-complete for many parameter combinations with $k\geq 2$, in particular
$k \geq d$ and $c = d-1$ or $c=d$, by Schnider and Weber~\cite{SW23}.
\comments This defines a family of problems. This family is parameterized by
 the dimension of the convex sets $c$,
the ambient dimension $d$ containing the convex sets
and the dimension $k$ of the dimension of the input simplicial complex.
Note that for $k=1$, this is a question about graphs.
For example, $(k,c,d)=(1,1,1)$ asks if the underlying graph is an interval graph, 
which is known to be polynomial time solvable~\cite{BL76}.
Another illustrative example is $(k,c,d)=(1,1,2)$. Here, we ask if the underlying graph is the intersection graph
of segments, which is known to be \ER-complete~\cite{KM94}.
The hardness results stem from the hardness results of graphs
combined with a lifting lemma due to Tancer~\cite{Tan10}. 
Some other parameter combinations are always possible to realize (specifically $d,c\geq 2k+1$~\cite{W67})
and thus the computational problem becomes trivial.
%\universality 

Given a family $A$ of sets, we say the nerve of $A$ is a simplicial complex that has one vertex for each member of $A$, and any subset  $B\subseteq A$ forms a simplex if their intersection is non-empty.

\openq All remaining parameter combinations are still open.
\also Segment intersection graph~\ourref{p:SEG}, convex set intersection graph~\ourref{p:convintersect}, 
convex neural codes~\ourref{p:convneuralcode},
finite convex geometry realizability~\ourref{p:convexgeoreal}.
\end{problemCG}



\begin{problemCG}{Hypergraph Induced by Halfspaces and Points}
\label{p:inducedhyp}
\mindex{Hypergraph Induced by Halfspaces and Points}
\given A hypergraph $H=(V,E)$, an integer $d \geq 0$.
\question Is there a set of halfspaces and points in $\R^d$ such that the induced hypergraph equals $H$? The hypergraph has one vertex per point, and a hyperedge consists of all points belonging to the same halfspace. 
\complexity \ER-complete by Tanenbaum, Goodrich, Scheinerman~\cite{TGS95} via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch} for every fixed $d \geq 2$. The problem remains \ER-complete if halfspaces are replaced by balls\index{Hypergraphs Induced by Balls and Points}, ellipsoids\index{Hypergraphs Induced by Ellipsoids and Points} and, so-called, bi-curved, difference-separable, and computable convex sets as shown by Bertschinger, El Maalouly, Kleist, Miltzow,
and Weber~\cite{BEMKMW23b}.
%\comments 
% test
% %\universality 
\openq Does the problem remain \ER-complete for any other natural geometric objects? The authors of~\cite{BEMKMW23b} note that they are not aware of any such examples.
\also Stretchability~\ourref[Stretchability]{p:Stretch}, point-halfspace orders~\ourref{p:pointhalfspaceorders}, oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}.
\end{problemCG}


\begin{problemCG}{Linear Hypergraph Realizability}
\label{p:linhypreal}
%linear hypergraph realizability~\ourref[Linear Hypergraph Realizability]{p:linhypreal}
%linear hypergraph realizability~\ourref{p:linhypreal}
\mindex{Linear Hypergraph Realizability}
\given A {\em linear hypergraph} $H$, that is, a hypergraph in which every two edges share at most one point. 
\question Is there a {\em straight-line realization} of $H$; that is, can every hyperedge be drawn as a straight-line segment containing all vertices of the hyperedge and no other vertices of $H$? The segments are allowed to cross. 
\complexity \ER-complete, by Dobler, Kobourov, Lenhart, Mchedlidze, N\"{o}llenburg, and Symvonis~\cite{DKLMNS24} via a reduction from matroid realizability over the reals~\ourref[Matroid!Real Realizability]{p:matroidreal}
\comments Linear hypergraphs of degree at most $2$ are always realizable in the sense defined above. The {\em rank} of a hypergraph is the maximum size of a hyperedge. The straight-line realizability problem becomes non-trivial already for hypergraphs of rank and degree at most $3$~\cite{DKLMNS24}; this corresponds to incidence graphs of geometric $3$-configurations~\ourref[Incidence Graph of Geometric 3 Configuration@Incidence Graph of Geometric $3$-Configuration]{p:geoconfig}
%\universality 
\openq Dobler, Kobourov, Lenhart, Mchedlidze, N\"{o}llenburg, and Symvonis ask whether the problem remains \ER-hard if the hypergraph has bounded rank, of even rank $3$. The answer for bounded rank is likely yes, see the comments on a bounded version of collinearity logic~\ourref[Collinearity Logic]{p:CollLogic}.
\also Matroid realizability over the reals~\ourref{p:matroidreal}, collinearity logic~\ourref[Collinearity Logic]{p:CollLogic}, segment intersection graph~\ourref{p:SEG}, incidence graph of geometric $3$-configuration~\ourref{p:geoconfig}.
\end{problemCG}


\begin{problemCG}{(Point) Visibility Graph}
\label{p:visibilitygraph}
\mindex{Visibility Graph!Points}
\index{Point Visibility Graph|see {Visibility Graph}}
\given A graph $G$.
\question Is $G$ the visibility graph of a set of points in the plane? The visibility graph of a set of points in the plane has one vertex per point, and two vertices are adjacent if and only if the line segment between the two points does not contain any other point of the set.
\complexity \ER-complete, by Cardinal and Hoffmann~\cite{CH17}.
\comments If the points in the realization have to lie on a grid, the problem becomes \EQ-complete~\cite{CH17}. 
\openq The complexity of recognizing visibility graphs of polygons is open. In the visibility graph of a polygon, two vertices of the polygon are adjacent if and only if the line segment between them is contained in the polygon.
\also Visibility graph of polygon with holes~\ourref{p:polygonholesvisibility}, unit spanning ratio~\ourref{p:unitspanratio}, segment visibility graph~\ourref{p:segvisibilitygraph}, obstacle number~\ourref{p:obstaclenumb}, hidden set in polygon~\ourref{p:hiddenpoly}.
\end{problemCG}


\begin{problemCG}{Visibility Graph of Polygon with Holes}
\label{p:polygonholesvisibility}
\mindex{Visibility Graph!Polygon with Holes}
\index{Polygon!Visibility Graph of Polygon with Holes|see {Visibility Graph}}
\index{Visibility Graph of Polygon with Holes|see {Visibility Graph}}
\given A graph $G$.
\question Is there a polygon with holes such that $G$ is the visibility graph of the vertices of $G$; that is, the vertices of $G$ are the corners of the polygon and its holes, and there is an edge between two vertices if the segment connecting the two vertices lies inside the polygon?
\complexity \ER-complete by Hoffmann and Merckx~\cite{HM18} via a reduction from allowable sequence~\ourref[Allowable Sequence]{p:allowableseq} and Boomari, Ostovari, and Zarei~\cite{BOZ18} from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
%\Year
\comments For convex polygons with a single hole the visibility graphs are circular arc graphs and therefore recognizable in polynomial time~\cite{CE95}.
%\universality 
\openq What is the complexity of recognizing visibility graphs of polygons without holes\index{Visibility Graph!Polygon (Open)}? Boomari, Ostovari, and Zarei~\cite{BOZ18} conjecture that the problem remains \ER-complete. 
\also Allowable sequence~\ourref{p:allowableseq}, point visibility graph~\ourref{p:visibilitygraph}, internal/external polygon visibility graph~\ourref{p:intextvisibility}. 
\end{problemCG}




\begin{problemCG}{Internal/External Polygon Visibility Graph}
\label{p:intextvisibility}
\mindex{Visibility Graph!Internal/External Polygon}
\index{Internal/External Polygon Visibility Graph|see {Visibility Graph}}
\given A graph $G = G_{\mathit{int}} \cup G_{\mathit{ext}}$.
\question Is there a simple polygon such that $G_{\mathit{int}}$ is the visibility graph of the vertices of $G$ inside the polygon, and $G_{\mathit{ext}}$ is the visibility graph of the vertices of $G$ outside the polygon? Two vertices can see each other if the line segment connecting them does not cut through the side of the polygon.
\complexity \ER-complete by Boomari, Ostovari, and Zarei~\cite{BOZ18} from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. The problem remains \ER-complete even if the blocking vertex for each pair of vertices which cannot see each other is specified (see~\cite{BOZ18} for definition of blocking vertex).  
%\comments 
%\universality 
\openq What is the complexity of recognizing polygon visibility graphs\index{Visibility Graph!Polygon (Open)}, that is, if just $G_{\mathit{int}}$ is given? 
\also Visibility graph of polygon with holes~\ourref{p:polygonholesvisibility}, point visibility graph~\ourref{p:visibilitygraph}. 
\end{problemCG}




\begin{problemCG}{Triangulated Irregular Network Visibility Graph}
\label{p:tiangulatedirregular}
%triangulated irregular network visibility graph~\ourref[Visibility Graph!Triangulated Irregular Network]{p:tiangulatedirregular}
%triangulated irregular network visibility graph~\ourref{p:tiangulatedirregular}
\mindex{Visibility Graph!Triangulated Irregular Network}
\index{Triangulated Irregular Network Visibility Graph| see {Visibility Graph}}
\given A graph $G$, a plane triangulation $T$. 
\question Is there a triangulated irregular network (TIN) with visibility graph $G$ and $xy$-projection isomorphic to $T$? The {\em triangulated irregular network (TIN)} assigns coordinates in $\R^3$ to the vertices of $T$. Two vertices in the TIN can {\em see} each other if the straight-line segment connecting them lies above the TIN. 
\complexity \ER-complete by Boomari, Ostovari, and Zarei~\cite{BOZ21} from triangulation stretchability~\ourref[Stretchability!Triangulation]{p:TriStretch}. 
%\comments 
