\begin{problemCG}{Generalized Transmission Graph}
\label{p:transgraph}
%generalized transmission graph~\ourref[Graph(s)!Generalized Transmission Graph]{p:transgraph}
%generalized transmission graph~\ourref{p:transgraph}
\index{Generalized Transmission Graph, see {Graph(s)}}
\mindex{Graph(s)!Generalized Transmission Graph}
\given A directed graph $G = (V,E)$, a family $\mathcal{C}$ of geometric objects (e.g.\ lines in $\R^2$).
\question Are there objects $C(v) \in \mathcal{C}$ and points $p(v) \in C(v)$ for every vertex $v \in V$, such that $p(u) \in C(v)$ if and only if $uv \in E$ for all $u,v \in V$?
\complexity \ER-complete for $\mathcal{C}$ being lines in $\R^2$ by Klost and Mulzer~\cite{KM18} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. The problem is also \ER-complete for $\mathcal{C}$ being a restricted type of circular sectors instead of lines~\cite{KM18}.  
%\comments  
%\universality 
\openq For \ER-completeness of circular sectors, Klost and Mulzer~\cite{KM18} require a somewhat technical condition (they call wide-spread); they conjecture that that condition can be removed.
\sep\ What about other natural families of geometric objects? Are there general conditions on $\mathcal{C}$ that would guarantee $\ER$-hardness?
\also Segment intersection graph~\ourref{p:SEG}.
%\tags 
\end{problemCG}







\subsection{Graph Drawing}

\begin{quote}
Graphs in this section are simple (no multiple edges, no loops) and undirected, unless we say otherwise. A {\em (topological) drawing} of a graph assigns a different location to each vertex of the graph, typically in $\R^2$, and connects the endpoints of each edge by a (Jordan) curve. We assume that there are no vertices in the interior of edges, edges intersect finitely often, and no more than two edges cross in a point. In a {\em geometric/straight-line} drawing, all edges are represented by straight-line segments. We refer to crossing-free drawings as {\em embeddings} or {\em planar}.

A {\em rotation} at a vertex is a cyclic permutation of the edges incident on the vertex (meant to represent the order in which the edges leave the vertex in a drawing or embedding). A {\em rotation system} assigns a rotation to each vertex of a graph. 

We will occasionally encounter \EQ\, the existential theory of the rationals.
\end{quote}



\begin{problemCG}{Planar Slope Number}
\label{p:planarslopenumb}
%planar slope number~\ourref[Graph(s)!Planar Slope Number]{p:planarslopenumb}
%planar slope number~\ourref{p:planarslopenumb}
\mindex{Graph(s)!Planar Slope Number}
\index{Planar Slope Number|see {Graph(s)}}
\given A graph $G$, an integer $k \geq 0$.
\question Is there a crossing-free straight-line drawing of $G$ in which the edges are drawn using at most $k$ different slopes?
\complexity \ER-complete, by Hoffmann~\cite{H17}, reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}. For fixed $k$, the problem lies in \NP~\cite{H17} using a result from~\cite{KM94} which shows that intersection graphs of segments with a fixed number of slopes can be recognized in \NP. 
\comments A drawing realizing the planar slope number of the graph may not be possible on a grid, and it is\EQ-complete to decide whether a grid realization exists, and there is a $2^{2^{\Omega(n^{1/3})}}$ lower bound on the grid size~\cite{H17}.  
%\universality 
\openq How hard is it to determine the (non-planar) slope number\index{Graph(s)!Slope Number (Open)} of a graph~\cite{H17}? 
\also Upward planar slope number~\ourref{p:upplanarslopenumb}, upward outerplanar slope number~\ourref[Graph(s)!Upward Outerplanar Slope Number]{p:upouterplanarslopenumb}, segment intersection graph~\ourref{p:SEG}, line cover number~\ourref{p:linecovernumb}, segment number~\ourref{p:segnumber}, faithful drawability of edge-colored graph~\ourref{p:faithfullcolor}. 
%\tags planar, \GraphDrawing
\end{problemCG}


\begin{problemCG}{Upward Planar Slope Number}
\label{p:upplanarslopenumb}
%upward planar slope number~\ourref[Graph(s)!Upward Planar Slope Number]{p:upplanarslopenumb}
%upward planar slope number~\ourref{p:upplanarslopenumb}
\mindex{Graph(s)!Upward Planar Slope Number}
\index{Upward Planar Slope Number|see {Graph(s)}}
\given A directed graph $G$, an integer $k \geq 0$. A (straight-line) drawing of $G$ is {\em upward} if $u$ lies below $v$ for every directed edge $uv \in E(G)$.
\question Is there an upward planar straight-line drawing of $G$ in which the edges are drawn using at most $k$ different slopes?
\complexity \ER-complete, by Quapil~\cite{Q21}, reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}. 
\comments A drawing realizing the planar slope number of the graph may not be possible on a grid, and it is\EQ-complete to decide whether a grid realization exists, and there is a $2^{2^{\Omega(n^{1/3})}}$ lower bound on the grid size~\cite{H17}.  
%\universality 
\openq Does the problem turn \NP-complete for fixed $k$, as is the case for planar slope number~\ourref[Graph(s)!Planar Slope Number]{p:planarslopenumb}? It is known to be \NP-hard in that case~\cite{KZ23}. \sep\ Is the problem \EQ-complete if the vertices have to lie on a grid?
\also Planar slope number~\ourref[Graph(s)!Planar Slope Number]{p:planarslopenumb}, upward outerplanar slope number~\ourref[Graph(s)!Upward Outerplanar Slope Number]{p:upouterplanarslopenumb}. 
\end{problemCG}


\begin{problemCG}{Line Cover Number in $\R^d$}
\label{p:linecovernumb}
%line cover number~\ourref[Graph(s)!Line Cover Number in Rd@Line Cover Number in $\R^d$]{p:linecovernumb}
%line cover number~\ourref{p:linecovernumb}
\mindex{Graph(s)!Line Cover Number in Rd@Line Cover Number in $\R^d$}
\index{Line Cover Number|see {Graph(s)}}
\given A graph $G$, an integer $k \geq 0$
\question Are there $k$ lines in $\R^d$ whose union contains a crossing-free straight-line drawing of $G$? We say the lines {\em cover} $G$.
\complexity \ER-complete by Chaplick, Fleszar, Lipp, Ravsky, Verbitsky, and Wolff~\cite{CFLRVW23} for $d \in \{2,3\}$.
\comments Chaplick \textit{et al.}~\cite{CFLRVW23} define the {\em affine cover number}\index{Graph(s)!Affine Cover Number in Rd@Affine Cover Number in $\R^d$}
as the smallest number of $\ell$-dimensional planes in $\R^d$ that cover a straight-line drawing of $G$. Since the affine cover number of a graph is the same for $d > 3$ and $d = 3$, it is sufficient to study line cover numbers in $\R^2$ and line and plane cover numbers in $\R^3$. 
%\universality 
\openq Chaplick \textit{et al.}~\cite{CFLRVW23} show that the plane cover number is \NP-hard in $\R^3$. Is it \ER-complete? Is it \ER-complete for other values of $(\ell,d)$? 
\also Planar slope number~\ourref{p:planarslopenumb}, circle cover number under spherical cover number~\ourref{p:sphericalcovernumb}, minimum line number~\ourref{p:minlinenumb}, planar stick number of drawing~\ourref{p:planarsticknumb}.
%\tags 
\end{problemCG}



\begin{problemCG}{Segment Number}
\label{p:segnumber}
%segment number~\ourref[Graph(s)!Segment Number]{p:segnumber}
%segment number~\ourref{p:segnumber}
\mindex{Graph(s)!Segment Number}
\given A graph $G$, an integer $k \geq 0$.
\question Is there a crossing-free straight-line drawing of $G$ which is the union of $k$ straight-line segments? The smallest such $k$ is known as the {\em (planar) segment number}.
\complexity \ER-complete by Okamoto, Ravsky, and Wolff~\cite{ORW19} via a reduction from arrangement graph recognition~\ourref[Arrangement Graph]{p:arrangegraph} even if the maximum degree of the graph is $4$ and by Erickson~\cite{E19} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch} if the graph is $4$-regular and given with a fixed embedding which has to be realized. Several variants are \ER-complete as well, including the case that polyline drawings are allowed ({\em bend segment number}\index{Graph(s)!bend segment number}), that crossings are allowed ({\em crossing segment number}\index{Graph(s)!crossing segment number}), or that the straight-line drawing lies in $\R^3$ ({\em 3D segment number}\index{Graph(s)!3D segment number})~\cite{ORW19}.
\comments Erickson's result is phrased as straightening a closed curve, see the isotopic polygon problem~\ourref[Polygon!Isotopic]{p:isopolygon}. The arc number~\ourref[Graph(s)!Arc Number (Open)]{p:arcnumb} was introduced by Schulz~\cite{S15} as a variation of the segment number. 
%\universality 
%\openq 
\also Arrangement graph~\ourref{p:arrangegraph}, arc number~\ourref{p:arcnumb}, minimum line number~\ourref{p:minlinenumb}, isotopic polygon~\ourref{p:isopolygon}, planar stick number of drawing~\ourref{p:planarsticknumb}.
%\tags 
\end{problemCG}


\begin{problemCG}{Isotopic Polygon}
\label{p:isopolygon}
%isotopic polygon~\ourref[Polygon!Isotopic]{p:isopolygon}
%isotopic polygon~\ourref{p:isopolygon}
\mindex{Polygon!Isotopic}
\index{Isotopic Polygon|see {Polygon}}
\given A closed curve $\gamma$, that is, a $4$-regular plane graph, an integer $k \geq 0$.
\question Is there a polygon with $k$ vertices isotopic to $\gamma$?
\complexity \ER-complete by Erickson~\cite{E19} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}.
\comments The isotopic polygon problem is a special case of the
planar stick number of drawing~\ourref[Graph(s)!Planar Stick Number of Drawing (Open)]{p:planarsticknumb}, and can be viewed as the fixed embedding variant of the segment number~\ourref[Graph(s)!Segment Number]{p:segnumber}, and the 
\universality Universal~\cite{E19}.
%\openq 
\also Segment number~\ourref{p:segnumber}, planar stick number of drawing~\ourref{p:planarsticknumb}.
%\tags 
\end{problemCG}

\begin{problemCG}{Planar Stick Number of Drawing}
\label{p:planarsticknumb}
%planar stick number of drawing~\ourref[Graph(s)!Planar Stick Number of Drawing (Open)]{p:planarsticknumb}
%planar stick number of drawing~\ourref{p:planarsticknumb}
\mindex{Graph(s)!Planar Stick Number of Drawing}
\index{Planar Stick Number of Drawing (Open)|see {Graph(s)}}
\given A graph $G$ with topological drawing $D$ (not necessarily crossing-free), an integer $k \geq 0$.
\question Is there a poly-line drawing of $G$ isomorphic to $D$ with at most $k$ segments in total? 
\complexity \ER-complete via a reduction from isotopic polygon~\ourref[Polygon!Isotopic]{p:isopolygon}.
\comments This problem was suggested by the work of Khandhawit, Pongtanapaisan, and Wasun~\cite{KPW23} who introduce the stick number of a spatial diagram of a graph; since this notion requires knot equivalence, there is currently no chance to relate it to \ER, but the simplified version presented here should still be of interest, as the underlying computational problem. Erickson~\cite{E24} observed that hardness follows from the isotopic polygon problem~\ourref[Polygon!Isotopic]{p:isopolygon}, even if $G = K_3$: start with the closed curve $\gamma$ from that problem and view it as a topological drawing of $K_3$.
%\universality 
%\openq 
\also Segment number~\ourref{p:segnumber}, isotopic polygon~\ourref{p:isopolygon}, line cover number~\ourref{p:linecovernumb}, minimum line number~\ourref{p:minlinenumb}. 
%\tags 
\end{problemCG}


\begin{problemCG}{Triangulation Stretchability}  %\TriStretchLabel}
\label{p:TriStretch}
%triangulation stretchability~\ourref[Stretchability!Triangulation]{p:TriStretch}
%triangulation stretchability~\ourref{p:TriStretch}
\mindex{Stretchability!Triangulation}
\index{Triangulation Stretchability|see {Stretchability}}
\given A plane triangulation $T$, and a collection of paths in $T$.
\question Is there a straight-line drawing of $T$ in which each path in the collection lies on a line?
\complexity \ER-complete by Boomari, Ostovari, and Zarei~\cite{BOZ21} from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. 
