\begin{problemCG}{Graph in a Polygonal Domain}
\label{p:GraphinPD}
\mindex{Graph(s)!Graph in a Polygonal Domain}
\index{Graph in a Polygonal Domain|see {Graph(s)}}
\given A graph $G$ and a polygon $P$, the {\em domain}.
Some of the vertices of $G$ are specified to be vertices of~$P$.
\question Does there exists a straight line drawing $D$ of $G$ such that
$D$ lies inside the domain $P$? 
\complexity \ER-complete~\cite{LMM22} via a reduction from \PETRINV~\ourref[Planar ETRINV@\PETRINV]{p:PlanarETRINV}.
\comments The problem is closely related to partial drawing extensibility (PDE)~\ourref[Graph(s)!Partial Drawing Extensibility (Open)]{p:partialdrawingext}.
In the PDE problem, we are given a partial straight-line drawing of a 
graph, and we are asked whether this drawing can be extended to a straight-line drawing of the full graph~\cite{P06}.
This differs from the graph in a polygonal domain problem in that in PDE we are 
not allowed to place vertices on existing edges, whereas in the current problem we are allowed to place vertices on the already existing polygon.
%\universality is open.
\openq Patrignani~\cite{P06} showed that the partial drawing extensibility problem~\ourref[Graph(s)!Partial Drawing Extensibility (Open)]{p:partialdrawingext} is \NP-hard, is it \ER-complete? 
\also Partial drawing extensibility~\ourref{p:partialdrawingext}.
\end{problemCG}

\begin{problemCG}{Drawing Graph on Segments with Obstacles}
\label{p:drawgraphsegobstacles}
\mindex{Graph(s)!Drawing Graph on Segments with Obstacles}
\index{Drawing Graph on Segments with Obstacles|see {Graph(s)}}
\given A plane graph $G$, a line-segment $\ell_v$ (open or closed) for every $v \in V(G)$, and a set $S$ of line-segments, all in the plane. 
\question Is there a straight-line drawing of $G$, isomorphic to the given embedding, in which every vertex $v$ lies on $\ell_v$, and edges do not cross the line-segments in $S$?
\complexity \ER-complete by Bieker~\cite{B20} via a reduction from a variant of \PETRINV~\ourref[Planar ETRINV@\PETRINV]{p:PlanarETRINV}.
\comments Since open line segments can be points, this problem can be turned into a restricted version of the partial drawing extensibility problem~\ourref[Graph(s)!Partial Drawing Extensibility (Open)]{p:partialdrawingext}, whose complexity is open.  
%\universality 
\openq Segments are allowed to be both open and closed. Does the problem remain \ER-hard if all segments are open, or all segments are closed? \sep\ The proof requires segments with four different slopes, does the problem become easier with fewer slopes? \sep\ Does the problem remain \ER-hard if $S$ is empty? \sep\ Does the problem remain \ER-hard if the embedding of the graph is not fixed?
\also Graph in a polygonal domain~\ourref{p:GraphinPD}, partial drawing extensibility~\ourref{p:partialdrawingext}, pseudo-segment stretchability~\ourref{p:SegStretch}.
%\tags 
\end{problemCG}


\begin{problemCG}{Rectilinear Crossing Number}
\label{p:rectcross}
%rectilinear crossing number~\ourref[Graph(s)!Rectilinear Crossing Number]{p:rectcross}
%rectilinear crossing number~\ourref{p:rectcross}
\mindex{Graph(s)!Rectilinear Crossing Number}
\index{Rectilinear Crossing Number|see {Graph(s)}}
\given A graph $G$, an integer $k \geq 0$.
\question Does $G$ have a straight-line drawing with at most $k$ crossings? The smallest such $k$ is the {\em rectilinear crossing number} of $G$.
\complexity \ER-complete. \ER-hardness was shown by Bienstock~\cite{B91} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch} and Dean~\cite{D02} showed that the problem lies in \ER. 
\comments For $k \leq 2$ it is known that the rectilinear crossing number equals the standard crossing number~\cite{BD93}, so the problem can be decided in polynomial time for those values. (The case $k = 3$ is also claimed, but only sketched, in the paper.)
\universality Bienstock's reduction yields algebraic universality~\cite{B91}.
\openq Does the problem remain \ER-complete for graphs of bounded degree?
\sep\ Does the problem remain \ER-complete for fixed $k$? What is the complexity of the problem for $k = 4$?
\sep\ Does the problem remain \ER-complete if each edge consists of $t$ segments, for some fixed $t$. What about $t = 2$? This question is based on Bienstock~\cite{B91} who named the corresponding crossing number the {\em $t$-polygonal crossing number}, and pointed out that realizing an optimal $t$-polygonal crossing number drawing may require exponential precision for every fixed $t$.
\also Rectilinear local crossing number~\ourref{p:rectloccross}, pseudolinear vs rectilinear crossing number~\ourref{p:pseudorectcross}, segment intersection graph~\ourref{p:SEG}, maximum rectilinear crossing number~\ourref{p:maxrectcross}.
%\tags \ComputationalGeometry, \GraphDrawing
\end{problemCG}


\begin{problemCG}{Pseudolinear vs Rectilinear Crossing Number}
\label{p:pseudorectcross}
%pseudolinear vs rectilinear crossing number~\ourref[Graph(s)!Pseudolinear vs Rectilinear Crossing Number]{p:pseudorectcross}
%pseudolinear vs rectilinear crossing number~\ourref{p:pseudorectcross}
\mindex{Graph(s)!Pseudolinear vs Rectilinear Crossing Number}
\index{Pseudolinear vs Rectilinear Crossing Number|see {Graph(s)}}
\given A graph $G$.
\question If $G$ has a pseudolinear drawing with at most $k$ crossings, does $G$ have a straight-line drawing with $k$ crossings, for every $k$? In other words, does the pseudolinear crossing number of $G$ equal its rectilinear crossing number~\ourref[Graph(s)!Rectilinear Crossing Number]{p:rectcross}? A {\em pseudolinear drawing} of a graph is a pseudoline arrangement in which every edge is drawn as part of a pseudoline.
\complexity \ER-complete by Hern\'{a}ndez-V\'{e}lez, Lea\~{n}os, and Salazar via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}.
%\comments
%\universality 
%\openq 
\also Rectilinear crossing number~\ourref{p:rectcross}, stretchability~\ourref[Stretchability]{p:Stretch}.
%\tags \ComputationalGeometry, \GraphDrawing
\end{problemCG}


\begin{problemCG}{Rectilinear Local Crossing Number}
\label{p:rectloccross}
%rectilinear local crossing number~\ourref[Graph(s)!Rectilinear Local Crossing Number]{p:rectloccross}
%rectilinear local crossing number~\ourref{p:rectloccross}
\mindex{Graph(s)!Rectilinear Local Crossing Number}
\index{Rectilinear Local Crossing Number|see {Graph(s)}}
\given A graph $G$, an integer $k \geq 0$.
\question Does $G$ have a straight-line drawing with at most $k$ crossings {\em per edge}? The smallest such $k$ is the {\em rectilinear local crossing number} of $G$.
\complexity \ER-complete~\cite{S21}. Remains \ER-complete for fixed $k \geq 867$~\cite{S21}.
\comments \ER-complete~\cite{S21} via a reduction from simple pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}. \NP-complete for $k = 1$~\cite{S14}, and \NP-hard for every fixed $k \geq 2$~\cite{S21}.
\universality Reduction yields algebraic universality~\cite{S21}.
\openq Does the problem remain \ER-complete for graphs of bounded degree? \sep\ What is the largest $k$ for which the problem lies in \NP? What is the smallest $k$ for which the problem is \ER-complete?
\also Rectilinear crossing number~\ourref{p:rectcross}, segment intersection graph~\ourref{p:SEG}, pseudo-segment stretchability~\ourref{p:SegStretch}.
\end{problemCG}


\begin{problemCG}{Geometric Partial $1$-Planarity}
\label{p:geopartial1planarity}
%geometric partial $1$-planarity~\ourref[Graph(s)!Geometric Partial 1 Planarity@Geometric Partial $1$-Planarity]{p:geopartial1planarity}
%geometric partial $1$-planarity~\ourref{p:geopartial1planarity}
\mindex{Graph(s)!Geometric Partial 1 Planarity@Geometric Partial $1$-Planarity}
\index{Geometric Partial 1 Planarity@Geometric Partial $1$-Planarity|see {Graph(s)}}
\given A graph $G = (V,E)$, a subset of edges $F \subseteq E$.
\question Is there a straight-line drawing of $G$ in which every edge of $F$ has at most one crossing?
\complexity \ER-complete by Schaefer~\cite{S14} via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}. 
\comments The special case of geometric $1$-planarity in which $F = E$ is only \NP-complete, a folklore result~\cite{S14}. 
%\universality 
\openq What is the complexity of geometric partial planarity~\ourref[Graph(s)!Geometric Partial Planarity]{p:geopartialplanarity}, the variant of the problem in which edges in $F$ have to be crossing-free? 
\also Geometric partial planarity~\ourref{p:geopartialplanarity}, rectilinear local crossing number~\ourref{p:rectloccross}. 
%\tags Crossings.
\end{problemCG}

\begin{problemCG}{Weak Rectilinear Realizability}
\label{p:rectilinearreal}
%weak rectilinear realizability~\ourref[Graph(s)!Weak Rectilinear Realizability]{p:rectilinearreal}
%weak rectilinear realizability~\ourref{p:rectilinearreal}
%strict rectilinear realizability~\ourref[Graph(s)!Strict Rectilinear Realizability]{p:rectilinearreal}
%strict rectilinear realizability~\ourref{p:rectilinearreal}
\mindex{Graph(s)!Weak Rectilinear Realizability}
\mindex{Graph(s)!Strict Rectilinear Realizability}
\given A graph $G = (V,E)$, a set $R \subseteq \binom{E}{2}$.
\question Is there a straight-line drawing of $G$ such that $\{e,f\} \in R$ for every two edges $e$ and $f$ that cross in the drawing?
\complexity \ER-complete, even for complete graphs by Kyn\v{c}l~\cite{K11} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}. Remains \ER-complete in the {\em strict} case, in which $R$ contains exactly the pairs of edges that cross in the drawing, even if $G$ is the complete graph.
\comments The strict case for a matching is the segment intersection graph problem~\ourref[Segment Intersection Graph]{p:SEG}, which was known to be \ER-complete~\cite{KM94}; the fact that the problem remains hard for complete graphs is novel here~\cite{K11}. For topological drawings, the problem in \NP-complete~\cite{K91b,SSS03}.
%\universality 
%\openq 
\also segment intersection graph~\ourref{p:SEG}, straight-line realizability of graph with rotation system~\ourref{p:straightrotation}.
%\tags topological graphs, crossings.
\end{problemCG}


\begin{problemCG}{Straight-line Realizability of Graph with Rotation System}
\label{p:straightrotation}
%straight-line realizability of graph with rotation system~\ourref[Graph(s)!Straight-line Realizability of Graph with Rotation System]{p:straightrotation}
%straight-line realizability of graph with rotation system~\ourref{p:straightrotation}
\mindex{Graph(s)!Straight-line Realizability of Graph with Rotation System}
\given A graph $G = (V,E)$ with {\em rotation system} $\pi$, that is, a function that assigns to every vertex $v \in V$ a cyclic permutation of the edges incident on $v$.
\question Is there a straight-line drawing of $G$ such that the cyclic permutation of the edges incident to each vertex $v$ agrees with $\pi(v)$? 
\complexity \ER-complete for complete graphs~\cite{K11} via a reduction from strict rectilinear realizability~\ourref[Graph(s)!Strict Rectilinear Realizability]{p:rectilinearreal}. Remains \ER-complete for graphs of bounded degree~\cite{S21b} via a reduction from the partial version of radial system realizability~\ourref[Radial System!Realizability]{p:radialsystem}~\cite{S21b}.
\comments For complete graphs, the pairs of intersecting edges completely determine the rotation system of a straight-line drawing and vice versa; this implies that for complete graphs, the problem is equivalent to the strict rectilinear realizability problem. 
%\universality 
\openq How hard is the problem for cubic graphs? \sep\ Is it \NP-complete to test whether a graph with rotation system has a good (topological) drawing? For complete graphs, this can be decided in polynomial time~\cite{K20}. 
\also Weak rectilinear realizability~\ourref{p:rectilinearreal}, simultaneous geometric embedding~\ourref{p:SEG}, radial system realizability (partial version)~\ourref{p:radialsystem}.
%\tags topological graphs, rotation system, crossings.
\end{problemCG}



\begin{problemCG}{Simultaneous Geometric Embedding (\SGE)}
\label{p:SGE}
%simultaneous geometric embedding~\ourref[Graph(s)!Simultaneous Geometric Embedding]{p:SGE}
%simultaneous geometric embedding~\ourref{p:SGE}
\mindex{Simultaneous Geometric Embedding, see {Graph(s)}}
\mindex{Graph(s)!Simultaneous Geometric Embedding}
\index{SGE@\SGE|see {Graph(s), Simultaneous Geometric Embedding}}
\given A family $(G_i)_{i \in [k]}$ of graphs on a shared vertex set.
\question Is there a straight-line drawing of $G = \bigcup_{i \in [k]} G_i$ in which each $G_i$ by itself is planar?
\complexity \ER-complete by Cardinal and Kusters~\cite{CK15}. Remains \ER-complete even if $k$ is fixed and all graphs are paths~\cite{S21b} and in the case that there are no {\em public} edges (edges belonging to more than one graph), the {\em empty sunflower case}~\cite{KR23} even for fixed $k=31$~\cite{FKMPTV24}. 
A weak hardness result for \SGE\ was first presented in~\cite{EBGJPSS08}.
\comments Explicitly shown \ER-complete in~\cite{CK15} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}; the result can also be proved by reduction from strict rectilinear realizability of complete graphs~\ourref[Graph(s)!Strict Rectilinear Realizability]{p:rectilinearreal}~\cite{K11}, but the reduction from simple stretchability leads to stronger precision bounds: a simultaneous geometric embedding may require a grid of size $2^{2^{\Omega(n)}}$, where $n = V(G)$. The reductions for fixed $k$ start with pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}. 
%\universality 
\openq Does the empty sunflower case remain \ER-hard if all graphs are trees? \sep\ Does the problem remain \ER-complete for $k = 2$~\cite{C15}?
\also Strict rectilinear realizability~\ourref{p:rectilinearreal}, geometric thickness of multigraphs~\ourref{p:geothickmulti}, geometric thickness~\ourref{p:geothick}, pseudo-segment stretchability~\ourref{p:SegStretch}.
%\tags topological graphs, crossings, simultaneous drawing.
\end{problemCG}


\begin{problemCG}{Geometric Thickness of Multigraph}
\label{p:geothickmulti}
%geometric thickness of multigraphs~\ourref[Graph(s)!Geometric Thickness of Multigraph]{p:geothickmulti}
%geometric thickness of multigraphs~\ourref{p:geothickmulti}
\mindex{Graph(s)!Geometric Thickness of Multigraph}
\given A multigraph $G$, a natural number $k \in \N$.
\question Does $G$ have a straight-line drawing in which the edges can be colored with $k$ colors in such a way that no crossing in the drawing involves two edges of the same color?
\complexity \ER-complete by F{\"{o}}rster, Kindermann, Miltzow, Parada, Terziadis, and Vogtenhuber~\cite{FKMPTV24} for every fixed $k \geq 57$ via a reduction from pseudo-segment stretchability~\ourref[Stretchability!Pseudo-segments]{p:SegStretch}. The problem remains \ER-complete even if $G$ has fixed local crossing number~\cite{FKMPTV24}.
\comments Geometric thickness was introduced by Kainen~\cite{K73}. It has similarities to the simultaneous geometric embedding problem~\ourref[Graph(s)!Simultaneous Geometric Embedding]{p:SGE}, which is \ER-complete. For a brief discussion, see~\cite[Remark 7]{S21b}. The complexity of the geometric thickness of (simple) graphs~\ourref[Graph(s)!Geometric Thickness (Open)]{p:geothick} remains open. 
%\universality 
%\openq 
\also Geometric thickness~\ourref{p:geothick}, simultaneous geometric embedding~\ourref{p:SGE}.
%\tags graph drawing, straight-line drawing. 
\end{problemCG}


\begin{problemCG}{Right-Angle Crossing Drawability}
\label{p:racdraw}
%right-angle crossing drawability~\ourref[Graph(s)!Right Angle Crossing Drawability@Right-Angle Crossing Drawability]{p:racdraw}
%right-angle crossing drawability~\ourref{p:racdraw}
\mindex{Graph(s)!Right Angle Crossing Drawability@Right-Angle Crossing Drawability}
\index{Right-Angle Crossing Drawability|see {Graph(s)}}
\index{RAC Drawability|see {Graph(s),Right-Angle Crossing Drawability}}
\given A graph $G$.
\question Does $G$ have a straight-line drawing in which all crossings are right-angle crossings? Such drawings are known as right-angle crossing drawings, or {\em RAC-drawings}, for short. 
\complexity \ER-complete by Schaefer~\cite{S23b} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} (using straight-line drawability with junctions as an intermediate problem). Remains \ER-complete even if the topological embedding of the graph is given and each edge is involved in at most eleven crossings, and crossing angles are doubly exponentially close to being right-angle~\cite{S23b}.
\comments Determining whether $G$ has a RAC-drawing on the integer grid is \EQ-complete~\cite{S23b}. The {\em resolution} at a crossing is the smaller of the two angles incident to a crossing; the {\em crossing resolution} of a straight-line drawing is the largest resolution at any crossing, so RAC-drawings have maximal crossing resolution. The maximal resolution at vertices is known as the angular resolution~\ourref[Graph(s)!Angular Resolution]{p:angularres}.
%\universality 
\openq In a RAC$_k$ drawing each edge is allowed to have up to $k$ bends. Are RAC$_1$- and RAC$_2$-drawability \ER-hard? \sep\ Does RAC-drawbility remain \ER-hard for graphs of bounded degree? \sep\ Does RAC-drawability remain \ER-hard for $1$-planar drawing, that is, drawings with at most one crossing per edge? See geometric partial $1$-planarity~\ourref[Graph(s)!Geometric Partial 1 Planarity@Geometric Partial $1$-Planarity]{p:geopartial1planarity}. 
\sep\ Does RAC-drawability remain \ER-complete if all right-angle crossings have to occur between axis-parallel edges? This variant is introduced as apRAC-drawability in~\cite{ABKKPU23} who showed that the problem is \NP-hard.
\also Angular resolution~\ourref{p:angularres}, geometric partial $1$-planarity~\ourref{p:geopartial1planarity}. 
%\tags graph drawing, crossings 
\end{problemCG}



\begin{problemCG}{Lombardi-Drawability With Rotation System}
\label{p:lombardidraw}
%Lombardi-drawability with rotation system~\ourref[Graph(s)!Lombardi Drawability with Rotation System@Lombardi-Drawability with Rotation System]{p:lombardidraw}
%Lombardi-drawability with rotation system~\ourref{p:lombardidraw}
\mindex{Graph(s)!Lombardi Drawability with Rotation System@Lombardi-Drawability with Rotation System}
\index{Lombardi drawability (Open)|see {Graph(s)!Lombardi-Drawability with Rotation System}}
\index{Lombardi drawability with Rotation System|see {Graph(s)}}
\given A graph $G=(V,E)$ with {\em rotation system} $\pi$, that is, a function that assigns to every vertex $v \in V$ a cyclic permutation of the edges incident on $v$.
\question Does $G$ have a Lombardi drawing in the plane respecting $\pi$? In a {\em Lombardi drawing} all edges must be drawn as circular arcs (crossings are allowed), and every vertex must have {\em perfect angular resolution}, that is, all angles between consecutive ends at the vertex must be the same. The drawing {\em respects} the rotation system if the cyclic permutation of the edges incident to each vertex $v$ agrees with $\pi(v)$? 
\complexity \ER-complete by Jungeblut~\cite{J24} via a reduction from simple stretchability~\ourref[Simple Stretchability]{p:Stretch}.
\comments 
%\universality 
\openq How hard is Lombardi drawability if no rotation system is given~\cite[Open Problem 1]{J24}? \sep\
How hard is Lombardi drawability if we require the drawing to be crossing-free (with or without rotation system)n~\cite[Open Problem 2]{J24}?
\sep\ Does Lombardi drawability remain hard for graphs of bounded degree?
\also Straight-line realizability of graph with rotation system~\ourref{p:straightrotation}, angular resolution~\ourref[Graph(s)!Angular Resolution]{p:angularres}, arc number~\ourref{p:arcnumb}.
%\tags 
\end{problemCG}



\begin{problemCG}{Angular Resolution}
\label{p:angularres}
%angular resolution~\ourref[Graph(s)!Angular Resolution]{p:angularres}
%angular resolution~\ourref{p:angularres}
\mindex{Graph(s)!Angular Resolution}
\index{Angular Resolution|see {Graph(s)}}
\given A graph $G$, a natural number $k \geq 2$.
\question Does $G$ have a straight-line drawing with {\em angular resolution} at least $\pi/(2k)$, that is, a drawing in which all angles between incident edges are at least $\pi/(2k)$? The {\em angular resolution} of $G$ is the supremum of the angular resolution of all straight-line drawings of $G$. 
\complexity \ER-complete by Schaefer~\cite{S23} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} (using straight-line drawability with junctions as an intermediate problem). Remains \ER-complete even if a crossing-free topological embedding of the graph is given~\cite{S23}.
\comments There is a subtle difference between a graph having angular resolution at least $\alpha$ and there being a drawing of the graph with angular resolution at least $\alpha$, since angular resolution of a graph is defined as a supremum, as observed in~\cite{FHHKLSWW93}. Both versions are \ER-complete.  
%\universality 
\openq Testing for angular resolution at least $\pi/4$ is \NP-complete. Is the angular resolution problem \ER-complete for $\pi/3$~\cite{S23}? \sep\ Does the problem remain \ER-complete if $G$ is planar, but the angular-resolution drawing does not have to be~\cite{S23}?
\also RAC-drawability~\ourref{p:racdraw}.
%\tags graph drawing
\end{problemCG}



\begin{problemCG}{Prescribed Area Extension}
\label{p:preareaext}
%prescribed area extension~\ourref[Graph(s)!Prescribed Area Extension]{p:preareaext}
%prescribed area extension~\ourref{p:preareaext}
\mindex{Graph(s)!Prescribed Area Extension}
\index{Prescribed Area Extension|see {Graph(s)}}
\given A plane graph $G$, an area assignment for $G$, where an {\em area assignment} for $G$ assigns a positive real number to every face of $G$; locations for some of the vertices of $G$ are fixed in the plane. 
\question Does $G$ have a straight-line drawing realizing the area assignment, that is, each face having the area prescribed by the area assignment, with the fixed vertices at their prescribed location? 
\complexity \ER-complete by Dobbins, Kleist, Miltzow and Rz\polhk a\.{z}ewski~\cite{DKMR23} via a reduction from \PETRINV~\ourref[Planar ETRINV@\PETRINV]{p:PlanarETRINV}.
%\comments  
%\universality 
\openq Does the problem remain \ER-hard without fixing vertex locations?  
\also Prescribed area~\ourref{p:prearea}, area universality~\ourref{p:areauniversal}, area universality for triples with partial area assignment~\ourref{p:areauniversaltriples}.  
%\tags 
\end{problemCG}




\begin{problemCG}{Straight-line Realizability with Unit Spanning Ratio}
\label{p:unitspanratio}
\mindex{Graph(s)!Straight line Realizability with Unit Spanning Ratio}
\index{Straight-line Realizability with Unit Spanning Ratio, see {Graph(s)}}
\given A graph $G$.
\question Is there a {\em proper} straight-line drawing of $G$ in the plane with spanning ratio one? Here proper means that no two vertices are drawn on the same point, and no point corresponding to a vertex lies on a segment representing an edge, apart from the two endpoints. The {\em spanning ratio} of a drawing is the maximum ratio, over all pairs of vertices, of the length of a shortest path in the drawing and the Euclidean distance. 
\complexity \ER-complete, by Aichholzer, Borrazzo, Bose, Cardinal, Frati, Morin, Vogtenhuber~\cite{ABBCFMV22} via a reduction from the point visibility graph problem~\ourref[Visibility Graph!Points]{p:visibilitygraph}.
\comments Aichholzer et al.~\cite{ABBCFMV22} show that a graph has a proper drawing with spanning ratio $1$ if and only if it is the visibility graph of a set of points in the plane~\ourref[Visibility Graph!Points]{p:visibilitygraph}. They also show that the problem becomes linear-time solvable if the drawing has to be planar (crossing-free). 
\also Point visibility graph~\ourref{p:visibilitygraph}.
\end{problemCG}


\begin{problemCG}{Graph Realizability}
\label{p:graphreal}
\mindex{Graph(s)!Graph Realizability}
\index{Graph Realizability|see {Graph(s)}}
\given A graph $G$ with weight function $\ell: E(G) \rightarrow \Q_{\geq 0}$.
\question Is there a straight-line drawing of $G$ in which every edge $e$ of $G$ has length $\ell(e)$?  
\complexity \ER-complete by Schaefer~\cite{S13} via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}. The problem remains \ER-complete even if $\ell(e) = 1$ for all $e \in E(G)$.
\comments Graph drawings are assumed to be non-degenerate in that vertices do not overlap with other vertices or edges; relaxing that condition leads to the linkage realizability problem~\ourref{p:linkagereal}. 
The problem was first shown \NP-hard by Saxe~\cite{S79} and Yemini~\cite{Y79}; Eades and Wormald~\cite{EW90} showed \NP-hardness if the drawing has to be crossing-free (and all edges have the same length), and that result was strengthened by Cabello, Demaine, and Rote~\cite{CDR07}. The problem is known under different names to different communities, e.g.\ as the Euclidean distance matrix completion problem\index{Euclidean Distance Matrix Completion}~\cite{L09}, and it has many variants and applications~\cite{LLMM14}. A related problem is the reconstruction problem: given a multiset of distances (of the form $\sqrt{q}$ for $q \in \Q$) are there $n$ points in $\R^d$ such that the multiset contains exactly their pairwise distances. This problem turns out to be \NP-complete~\cite{LSS03}.
%\universality 
\openq It is open whether the problem remains \ER-complete for embedded graphs.
(A claimed \ER-hardness proof~\cite{ADDELS16} may not be complete. We were informed by one of the authors
that the PhD thesis of Abel~\cite{PhDAbel2016} contains more details, `` but is still lacking some detail and edits''.) 
% 
\also Unit distance graph~\ourref{p:unitdist}, linkage realizability~\ourref{p:linkagereal}, graph flattenability~\ourref{p:graphflatten}. 
\end{problemCG}


\begin{problemCG}{Graph with Long and Short Edges}
\label{p:graphlongshort}
\mindex{Graph(s)!Graph with long and short edges}
\index{Graph with long and short edges|see {Graph(s)}}
\index{Dichotomous ordinal graph|see {Graph(s)}}
\given A graph $G = (V,E)$ with a partition of the edges $E = E_s \cup E_{\ell}$ into {\em short} and {\em long} edges. 
\question Is there a straight-line drawing of $G$ in which exactly the short edges have length at most $1$?   
\complexity \ER-complete by Angelini, Cornelsen, Haase, Katsanou, Montecchiani, Symvonis~\cite{ACHKMS24} via a unit disk graph~\ourref[Disk Graph!Unit Disk Graph]{p:unitdiskgraph}.
\comments Graphs with long and short edges were introduced in~\cite{ACHKMS24} under the name {\em dichotomous ordinal graphs}. The same paper suggests a reduction from Euclidean preference~\ourref[Euclidean Preference]{p:Euclideanpref}, but there also is a direct reduction from unit disk graphs~\ourref[Disk Graph!Unit Disk Graph]{p:unitdiskgraph}: $G = (V,E)$ is a unit disk graph if and only if the graph $H$ on vertex set $V$ can be realized with short edges $E$ and long edges $\binom{V}{2}-E$. 
%\universality 
\openq Does the problem remain \ER-complete if the realization has to be crossing-free? If the short edges have to induce a plane graph, then, as~\cite{ACHKMS24} point out, the problem is \NP-hard~\cite{AKPT16}. 
\sep\ Does the problem remain \ER-complete if the underlying graph is a complete bipartite graph? That is the case of most interest in~\cite{ACHKMS24}.
\also Unit disk graph~\ourref{p:unitdiskgraph}, Euclidean preference~\ourref{p:Euclideanpref}, graph realizability~\ourref{p:graphreal}. 
%\tags 
\end{problemCG}


\begin{problemCG}{(Strict) Unit Distance Graph}
\label{p:unitdist}
%unit distance graphs~\ourref[Graph(s)!Unit Distance Graph]{p:unitdist}
%strict unit distance graphs~\ourref[Graph(s)!Strict Unit Distance Graph]{p:unitdist}
%unit distance graphs~\ourref{p:unitdist}
%strict unit distance graphs~\ourref{p:unitdist}
\mindex{Graph(s)!Unit Distance Graph}\mindex{Graph(s)!Strict Unit Distance Graph}
\given A graph $G$.
\question Is $G$ a (strict) subgraph of $E_2 = (\R^2, \{uv \in (\R^2)^2: |u-v| = 1\})$?
\complexity Recognition of both unit distance graphs and strict unit distance graphs is \ER-complete by Schaefer~\cite{S13} via a reduction from graph realizability~\ourref[Graph(s)!Graph Realizability]{p:graphreal}.
\comments By definition, different vertices of $G$ correspond to distinct points in $E_2$; if we relax this condition, we get the degenerate unit distance graph problem~\cite{HKP11}, which we discuss as part of the linkage realizability problem~\ourref{p:linkagereal}. Erd\"{o}s, Haray and Tutte~\cite{EHT65} introduced the {\em Euclidean dimension}\index{Graph(s)!Euclidean Dimension}\index{Euclidean dimension|see {Graph(s)}} of a graph, which is the smallest $d$ for which $G$ is a subgraph of $E_d = (\R^d, \{uv \in (\R^d)^2: |u-v| = 1\})$; so testing whether a graph has dimension at most $2$ is already \ER-complete.
\universality Maehara~\cite{M91} showed that the distances that occur in rigid unit distance graphs are exactly the algebraic numbers. 
\openq Is the Euclidean dimension \ER-complete for every fixed $d$?
\also Linkage realizability~\ourref{p:linkagereal}, unit disk contact graph~\ourref{p:unitdiskcontact}, graph realizability~\ourref{p:graphreal}. 

\end{problemCG}




\begin{problemCG}{Linkage Realizability}
\label{p:linkagereal}
%linkage realizability~\ourref[Linkage!Linkage Realizability]{p:linkagereal}
%linkage realizability~\ourref{p:linkagereal}
\mindex{Linkage!Linkage Realizability}
\given A graph $G$ with a function $\ell: E(G) \rightarrow \Q_{\geq 0}$.
\question Can we assign a point $p_u \in \R^d$ to every $u \in V(G)$ such that $|f(u)-f(v)| = \ell(uv)$ for every edge $uv$?
\complexity \ER-complete by Abbott~\cite{A08} via a reduction from Feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} for every $d\geq 2$, The problem remains \ER-complete even for unit linkages , that is if $\ell(e) = 1$ for all $e \in E(G)$, in $\R^2$ by Schaefer~\cite{S13} via a reduction from pseudoline stretchability~\ourref[Stretchability]{p:Stretch}. 
\comments The main difference to graph realizability~\ourref[Graph(s)!Graph Realizability]{p:graphreal} is that vertices can overlap with other vertices and edges. In some definitions, linkages also come with points with pre-assigned locations. Unit linkages are called {\em degenerate unit distance graphs} by Horvat, Kratochv\'{\i}l, and Pisanski~\cite{HKP11} who showed that the problem is \NP-hard.
\universality The universality of linkage realizability is Kempe's universality theorem~\cite{KM02, A08}.
\openq Is realizability of unit linkages \ER-complete in arbitrary dimension? There is a gadget, due to Saxe~\cite{S79}, that increases the dimension by one, but it is not a unit linkage.
\also Unit distance graph~\ourref{p:unitdist}, graph realizability~\ourref{p:graphreal}, linkage rigidity~\ourref{p:linkagerigid}. 
\end{problemCG}



\begin{problemCG}{Linkage Rigidity}
\label{p:linkagerigid}
\mindex{Linkage!Linkage Rigidity}
\given A graph $G$ with a function $\ell: E(G) \rightarrow \Q_{\geq 0}$, and a {\em configuration}, that is, $p_u \in \Q^d$ for every $u \in V(G)$ such that $|p_u-p_v| = \ell(uv)$ for every edge $uv$.
\question Is the configuration rigid, that is, do small changes to all $p_u$ so that the length conditions are still satisfied lead to the same configuration modulo rigid motions of the plane?
\complexity \VR-complete by Abbott~\cite{A08}, Schaefer~\cite{S13} for $d \geq 2$ via a reduction from \ISO~\ourref[Polynomial(s)!Isolated Zero]{p:ISO}. Abbott~\cite{A08} shows that \ISO\ reduces to linkage rigidity for $d = 2$, and $d-1$-dimensional linkage rigidity reduces to $d$-dimensional linkage rigidity. Together with the \ER-completeness of \ISO, this implies \ER-completeness of $d$-dimensional linkage rigidity for every fixed $d \geq 2$. Membership of linkage rigidity in \VR\ is shown in~\cite{S13}.
\comments The main difference to graph realizability~\ourref[Graph(s)!Graph Realizability]{p:graphreal} is that vertices can overlap with other vertices and edges. 
%\universality 
%\openq 
\also Unit distance graph~\ourref{p:unitdist}, linkage realizability~\ourref{p:linkagereal}, graph realizability~\ourref{p:graphreal}. 
\end{problemCG}




