\subsection{Polytopes and Simplicial Complexes}

\begin{quote}
A polytope is the convex hull of a finite point set in $\R^d$.
The {\em face lattice} of a polytope is the lattice of its faces: the {\em join}
of two faces is the smallest face containing both faces, and the {\em meet}
is the intersection of the faces. Given a lattice, that is, a partial order with
join and meet operations, one can ask whether it is {\em polytopal}, namely
whether it is the face lattice of a polytope. 
We refer to the face lattice of $P$ as its \emph{combinatorial type}, and to $P$ itself as a
\emph{realization} of this combinatorial type. 
The realizability question is known as the {\em algorithmic Steinitz problem}, due to a famous theorem of Steinitz.
Let the {\em graph of a polytope} be the graph formed by the vertices and edges of the
polytope. The graph is also referred to as the \emph{$1$-skeleton}, and the $k$-skeleton for $k\geq 1$ is the 
complex of all faces of dimension up to $k$.
Steinitz theorem characterizes the graphs of $3$-dimensional polytopes:
they are precisely the simple, planar, $3$-connected graphs~\cite[Section 4]{Z95}, hence easy to
recognize. For $3$-polytopes the facial lattice is determined by the graph of the polytope,
so the algorithmic Steinitz problem for $3$-polytopes is tractable. 


Note that the complete combinatorial type of a polytope can be deduced from its set of $(n-1)$-dimensional faces, or \emph{facets}: the lower-dimensional faces are simply obtained by intersecting subsets of facets. The input to the problems can therefore be restricted to be a list of facets.

We obtain an interesting variant if we restrict the problem to \emph{simple} polytopes, the skeletons of which are regular graphs. In that case the facial lattice is determined by the graph of the polytope 
(Blind and Mani with an easy proof by Kalai, see~\cite[Section~3.4]{Z95} and~\cite[Problem 15]{KP03}).

A polytope is said to be \emph{simplicial} if all its facets are simplices. 

\emph{Subdivisions} are closely related to polytopes. Given a set of points, a
subdivision is a covering of their convex hull by polytopes, or \emph{cells}, the vertices of which are
points of the set, such that any two intersect in a common face.
If all cells are simplices, then the subdivision is called a \emph{triangulation}.
A \emph{Delaunay subdivision} is such that the cells are defined by an empty sphere condition:
A cell $C$ is part of the Delaunay subdivision of a set of points in $\R^d$ if and only if there exists a
$(d-1)$-sphere passing through the vertices of $C$ but containing no other point of the set in its interior.
For generic point sets, such cells are always simplices, and we talk of \emph{Delaunay triangulations}.

An \emph{abstract simplicial $k$-complex} is a collection of sets of size at most $k$ that is closed under taking subsets. More generally, an \emph{(abstract) polyhedral complex} is a collection of (combinatorial types of) polytopes, such that every face of every polytope is also part of the collection, and any two polytopes in the collection intersect in a common face. 
\end{quote}

\begin{problemCG}{Polytope Realizability}
%polytope 
\label{p:Polytope}
%Polytope Realizability~\ourref[Polytope(s)!Polytope Realizability]{p:Polytope}
%Polytope Realizability~\ourref{p:Polytope}
\mindex{Polytope(s)!Polytope Realizability}
\index{Polytope Realizability|see {Polytope(s)}}
\given A combinatorial type, given as a list of facets. %A collection $F$ of subsets of $[n+4]$.
\question Does there exist a polytope of this combinatorial type? % an $n$-dimensional polytope on $n+4$ vertices whose facets are exactly the subsets in~$F$?
\complexity \ER-complete, by Mn\"{e}v~\cite{M88} via a reduction from existential theory of totally ordered real variables~\ourref[Existential Theory of Totally Ordered Real Variables]{p:ETRORV}.
\comments This problem is also known as the \emph{algorithmic Steinitz problem}. The problem is known to be hard in particular for $n$-dimensional polytopes with 
$n+4$ vertices. The input is then a collection of subsets of size at least $n$ of the $n+4$ vertices.
\universality Mn\"{e}v~\cite{M88}, also see Richter-Gebert~\cite{RG99}.
\also 4-dimensional Polytope Realizability~\ourref{p:4DPolytope}, Simplicial Polytope Realizability~\ourref{p:SPolytope}, Inscribed Simplicial Polytope Realizability~\ourref{p:ISPolytope}, treetope graph~\ourref{p:treetopegraph}, existential theory of totally ordered real variables~\ourref{p:ETRORV}.
%\tags 
\end{problemCG}

\begin{problemCG}{4-dimensional Polytope Realizability}
\label{p:4DPolytope}
\mindex{Polytope(s)!4-dimensional Polytope Realizability}
\index{4-dimensional Polytope Realizability|see {Polytope(s)}}
\given A combinatorial type, given as a list of facets. 
\question Does there exist a 4-dimensional polytope of this combinatorial type? 
\complexity \ER-complete, by Richer-Gebert and Ziegler~\cite{RGZ95} and Richter-Gebert~\cite{RG96} via a reduction from existential theory of totally ordered real variables~\ourref[Existential Theory of Totally Ordered Real Variables]{p:ETRORV}. 
\universality Richter-Gebert and Ziegler~\cite{RGZ95}, and Richter-Gebert~\cite{RG96,RG99}.
\openq The complexity of the problem for simplicial polytopes of constant dimension $d\geq 4$ is open, see Richter-Gebert~\cite{RG96}. The complexity of the related problem in dimension 4 in which we are only given the graph ($1$-skeleton) of the polytope is also open.
\also Polytope Realizability~\ourref{p:Polytope}.
\end{problemCG}

\begin{problemCG}{Simplicial Polytope Realizability}
\label{p:SPolytope}
\mindex{Polytope(s)!Simplicial Polytope Realizability}
\index{Simplicial Polytope Realizability|see {Polytope(s)}}
\given A combinatorial type, given as a list of facets. 
\question Does there exist simplicial polytope of this combinatorial type? 
\complexity \ER-complete, by Mn{\"e}v~\cite{M88}, and Adiprasito and Padrol~\cite{AP17} even in even dimension via a reduction from oriented matroid realizability~\ourref[Matroid!Oriented Matroid Realizability]{p:ormatroidreal}.
\universality Adiprasito and Padrol~\cite{AP17}.
\comments Universality of simplicial polytopes was announced by Mn{\"e}v~\cite{M88}, but with an incomplete proof. Adiprasito and Padrol prove the universality result for \emph{neighborly polytopes}, the $d$-dimensional polytopes whose $\lfloor d/2\rfloor$-skeleton is complete. Neighborly polytopes in even dimension are simplicial, so this implies the current result, but we can further assume neighborliness. 
The problem is known to be hard in particular for $n$-dimensional polytopes with 
$n+4$ vertices. 
\openq Encouraged by the results of Richter-Gebert~\cite{RG96} and Bokowski and Guedes de Oliveira~\cite{BG90}, Adiprasito and Padrol make the ``daring conjecture'' that the result holds in dimension $4$. 
\also Inscribed Simplicial Polytope Realizability~\ourref{p:ISPolytope}.
\end{problemCG}

\begin{problemCG}{Inscribed Simplicial Polytope Realizability}
\label{p:ISPolytope}
\mindex{Polytope(s)!Inscribed Simplicial Polytope Realizability}
\index{Inscribed Simplplical Polytope Realizability|see {Polytope(s)}}
\given A combinatorial type, given as a list of facets. 
\question Does there exist simplicial polytope of this combinatorial type, all vertices of which lie on a sphere? 
\complexity \ER-complete, by Adiprasito, Padrol, and Theran~\cite{APT15}.
\universality Adiprasito, Padrol, and Theran~\cite{APT15}.
\comments Delaunay subdivisions are obtained by stereographic projections of inscribed polytopes.
The problem is known to be hard in particular for $n$-dimensional polytopes with 
$n+4$ vertices. 
\openq The complexity of the problem for inscribed polytopes (not necessarily simplicial) of constant dimension $d\geq 4$ is open as well. In dimension $3$, a result by Rivin implies that inscribed polytopes can be recognized in polynomial time~\cite{R96}, although it is not clear how to efficiently produce a realization.
\also Delaunay Triangulation~\ourref{p:Delaunaytri}.
\end{problemCG}



\begin{problemCG}{Nested Polytopes}
\label{p:nestpolytopes}
\mindex{Polytope(s)!Nested Polytopes}
\index{Nested Polytopes|see {Polytope(s)}}
\given Two polytopes $A\subseteq B \subseteq \R^d$ and a number $k\in \N$. The polytope $A$ is described by vertices and the polytope $B$ is described by its facets.
\question Does there exist a polytope $X$ on at most $k$ vertices with $A\subseteq X \subseteq B$?
\complexity \ER-complete, by Dobbins, Holmsen and Miltzow~\cite{DHM19} via a direct reduction from \ETRINV~\ourref[ETRINV@\ETRINV]{p:ETRINV}.
\universality Universality follows from~\cite{DHM19}.
\comments  Vavasis~\cite{V09} 
showed that there is a reduction from non-negative matrix factorization~\ourref[Matrix!Non-negative Factorization]{p:nonnegmatfac} to nested polytope,
for the special case $k=d+1$.
(In the case $k=d-1$ the intermediate polytope is a simplex, and thus they call this problem the intermediate simplex problem.
\index{Intermediate Simplex Problem|see {Polytope(s)}})

Shitov showed in turn \ER-completeness and universality for non-negative matrix factorization and thus also implied the nested polytope result~\cite{S16}.
\also \ETRINV~\ourref{p:ETRINV}.
%\tags 
\end{problemCG}

\begin{problemCG}{Delaunay Triangulation}
\label{p:Delaunaytri}
\mindex{Pointset!Delaunay Triangulation}
\index{Delaunay Triangulation|see {Pointset}}
\given A collection $F$ of subsets of size $n-4$ of $[n]$.
\question Does there exist a $(n-5)$-dimensional Delaunay triangulation on $n$ vertices, such that the vertices of the cells of the triangulations are exactly the subsets in $F$?
\complexity \ER-complete, by Adiprasito, Padrol, and Theran~\cite{APT15} via a reduction from Inscribed Simplicial Polytope Realizability~\ourref[Inscribed Simplicial Polytope Realizability]{p:ISPolytope}.
\universality Adiprasito, Padrol, and Theran~\cite{APT15}.
\comments The result is directly reduced from the complexity of Inscribed Simplicial Polytope Realizability~\ourref[Inscribed Simplicial Polytope Realizability]{p:ISPolytope}: An inscribed polytope in dimension $d$ is mapped to a Delaunay subdivision in dimension $d-1$ via a stereographic projection.
\openq The complexity of the problem in constant dimension $d\geq 3$ is open. In dimension two, it is known from a result by Rivin that Delaunay triangulations can be recognized in polynomial time~\cite{R96}, although it is not clear how to efficiently produce a realization. Adiprasito, Padrol, and Theran conjecture that universality already holds for $3$-dimensional Delaunay subdivisions~\cite{APT15}. Padrol and Theran~\cite{PT14} give examples of Delaunay triangulations with disconnected realization spaces.
\also Inscribed Simplicial Polytope Realizability~\ourref{p:ISPolytope}, Gabriel graph~\ourref{p:Gabrielgraph}. 
%\tags 
\end{problemCG}


\begin{problemCG}{Simplicial Complex}
\label{p:simplicialcomplex}
\mindex{Simplicial Complex}
\given An abstract simplicial $k$-complex $C$ and a natural number $d \in \N$.
\question Does $C$ have a geometric embedding in $\R^d$?
\complexity \ER-complete for all $d\geq 3$ and $k\in\{d-1,d\}$, by Abrahamsen, Kleist, and Miltzow~\cite{AKM23} via a reduction from stretchability~\ourref[Stretchability]{p:Stretch}.
\comments For piecewise linear embedding, the problem has been shown to be \NP-hard even in dimension 3, see~\cite{MTW11, MRST20}.
\openq For which combinations of $k$ and $d$ is the problem \ER-complete?
An interesting case is when $k=2$ and $d=4$.
\also Polyhedral complex~\ourref{p:polyhedralcomplex}.
\end{problemCG}

\begin{problemCG}{Polyhedral Complex}
\label{p:polyhedralcomplex}
\mindex{Polyhedral Complex}
\given An abstract polyhedral complex $C$ composed of quadrangles and triangles.
\question Does $C$ have a geometric embedding in $\R^3$ in which the image of every polygon is a convex polygon, and their relative interiors are disjoint?
\complexity \ER-complete, by Brehm (unpublished), via a reduction from collinearity~\ourref[Collinearity Logic]{p:CollLogic}.
\comments The result has been announced and presented, but never published formally. It is hinted at by Ziegler~\cite{Z08}. Wilson~\cite{W12} also showed that the same result holds for polyhedral complexes composed of convex three-dimensional polyhedra.
\also Collinearity logic~\ourref{p:CollLogic}, simplicial complex~\ourref{p:simplicialcomplex}.
\end{problemCG}

