\section{Game Theory}

\subsection{Games in Strategic Form}

\begin{quote}
We briefly recall the definitions related to games given in \emph{strategic form}.
An $r$-player game $\Gamma$ in strategic form is a pair $\Gamma =(\Sigma_i, \mathsf{U}_i)$, for $i\in 1,2,\ldots ,r$, where $\Sigma_i$ is the set of strategies available to the $i$th player, and $\mathsf{U}_i$ is the payoff function of player $i$, of the form $\mathsf{U}_i:\Sigma_1\times\Sigma_2\times\ldots\times\Sigma_r\to\R$.

A \emph{mixed strategy} for the $i$th player, as opposed to a \emph{pure strategy} $s\in\Sigma_i$, is a probability distribution $\sigma_i$ on the pure strategies in $\Sigma_i$. Let $\mathbf{\sigma}=(\sigma_i)_{i=1,2,\ldots,r}$ be a collection of mixed strategies for each of the $r$ players. The expected payoff of the $i$th player under these probability distributions is:
\[
\mathsf{U}_i(\mathbf{\sigma}) = \sum_{s\in\prod_{i=1}^r \Sigma_i}
\mathsf{U}_i(s) \cdot
\prod_{i=1}^r \sigma_i(s_i)\cdot
\]

A Nash equilibrium is a collection of mixed strategies such that no player can improve her expected payoff by deviating from her current mixed strategy. Hence it consists of a collection of mixed strategies $\mathbf{\sigma}$ such that for every $i\in\{1,2,\ldots ,r\}$ and every $\mathbf{\sigma}'$ obtained by replacing $\sigma_i$ by another mixed strategy $\sigma'_i$, we have $\mathsf{U}_i(\mathbf{\sigma}) \geq \mathsf{U}_i(\mathbf{\sigma}')$. The classical result of Nash is that such an equilibrium exists for any game.
A Nash equilibrium is said to be \emph{pure} if it consists only of pure strategies. 
\end{quote}

\begin{problemGT}{Nash Equilibrium in a Ball}
\label{p:NashinBall}
\mindex{Nash Equilibrium!In a Ball}
\given A $3$-player game $\Gamma$ in strategic form, $u\in\Q$. 
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ such that $\sigma_i(s)\leq u$ for all $i=1,2,3$ and all $s\in\Sigma_i$?
\complexity \ER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS17} via a reduction from Brouwer Fixed Point~\ourref[Polynomial(s)!Brouwer Fixed Point]{p:BrouwerFixedPoint} due to Ettessami and Yannakakis~\cite{EY10}.
\comments The result holds for a fixed $u=1/2$~\cite{SS17}.
\also Brouwer Fixed Point~\ourref{p:BrouwerFixedPoint}.
\end{problemGT}


\begin{problemGT}{Nash Equilibrium with Bounded Payoffs}
\label{p:NashBoundedPayoff}
\mindex{Nash Equilibrium!Bounded Payoffs}
\given A $3$-player game $\Gamma$ in strategic form, $u\in\Q$. 
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ such that $\mathsf{U}_i(\mathbf{\sigma})\geq u$ for all $i\in\{ 1,2,3\}$?
\complexity \ER-complete by Garg, Mehta, Vazirani, Yazdanbod~\cite{GMVY18} via a reduction from Nash Equilibrium in a ball~\ourref{p:NashinBall}.
\comments The problem in which we require that $\mathsf{U}_i(\mathbf{\sigma})\leq u$ instead is also \ER-complete. Both results hold for symmetric win-lose games as well, as shown by Bil{\`o}, Hansen, Arnsfelt and Mavronicolas~\cite{BHM23}. Berthelsen and Hansen~\cite{BH22} also show that for zero-sum games, deciding the existence of a Nash equilibrium in which $\mathsf{U}_i(\mathbf{\sigma})=0$ for all $i\in\{ 1,2,3\}$  is \ER-complete. The proofs of the latter are related to those in Hansen~\cite{H19}.
\end{problemGT}

\begin{problemGT}{Nash Equilibrium with Restricted Support}
\label{p:NashRestrictedSupp}
\mindex{Nash Equilibrium!Restricted Support}
\given A $3$-player game $\Gamma$ in strategic form, a subset $T_i\subseteq\Sigma_i$ for each $i=1,2,3$. 
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ such that the set of strategies $s\in\Sigma_i$ such that $\sigma_i(s)>0$ is contained in $T_i$ for every $i\in\{1,2,3\}$?
\complexity \ER-complete by Garg, Mehta, Vazirani, Yazdanbod~\cite{GMVY18} via a reduction from Nash Equilibrium in a ball~\ourref{p:NashinBall}.
\comments The problem in which we require that the set contains $T_i$ instead is also \ER-complete~\cite{GMVY18,BM21}. The two problems are respectively called \textit{Superset} and \textit{Subset} in~\cite{GMVY18}.
Both results hold for win-lose games as well~\cite{BHM23}.
\end{problemGT}

\begin{problemGT}{Second Nash Equilibrium}
\label{p:NashSecond}
\mindex{Nash Equilibrium!Second}
\index{Second Nash Equilibrium|see {Nash Equilibrium}}
\given A $3$-player game $\Gamma$ in strategic form. 
\question Does $\Gamma$ have at least two distinct Nash equilibria? 
\complexity \ER-complete by Garg, Mehta, Vazirani, Yazdanbod~\cite{GMVY18} via a reduction from Nash Equilibrium with Bounded Payoffs~\ourref{p:NashBoundedPayoff}. The problem is referred to as \textit{NonUnique} in ~\cite{GMVY18}.
\end{problemGT}

\begin{problemGT}{Nash Equilibrium with Bounded Total Payoff}\mindex{Nash Equilibrium!Bounded Total Payoff}
\label{p:NashBoundedTotalPayoff}
\given A $3$-player game $\Gamma$ in strategic form, $u\in\Q$. 
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ such that $\sum_{i\in\{1,2,3\}}\mathsf{U}_i(\mathbf{\sigma})\geq u$?
\complexity \ER-complete by Bil{\`o}, Mavronicolas~\cite{BM21} via a reduction from Nash Equilibrium with Restricted Support~\ourref{p:NashRestrictedSupp}.
\comments The problem in which we require that $\sum_i\mathsf{U}_i(\mathbf{\sigma})\leq u$ instead is also \ER-complete.
An alternative hardness proof is also given by Berthelsen and Hansen~\cite{BH22}.
Both results hold for symmetric win-lose games as well~\cite{BHM23}. 
\end{problemGT}



\begin{problemGT}{Nash Equilibrium with Bounded Support}
\label{p:NashBoundedSupp}
\mindex{Nash Equilibrium!Bounded Support}
\given A $3$-player game $\Gamma$ in strategic form, a natural number $k\in\N$. 
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ such that the number of nonzero components of $\sigma_i$ is at least $k$, for every $i\in\{1,2,3\}$?
\complexity \ER-complete by Bil{\`o}, Mavronicolas~\cite{BM21} via a reduction from Nash Equilibrium with Restricted Support~\ourref{p:NashRestrictedSupp}.
\comments The problem in which we require that the support has size at most $k$ is also \ER-complete. Both results hold for symmetric win-lose games as well~\cite{BHM23}.
\end{problemGT}

\begin{problemGT}{Minmax Value}
\label{p:minmaxGame}
%minmax value~\ourref[Nash Equilibrium!Minmax Value]{p:minmaxGame}
%minmax value~\ourref{p:minmaxGame}
\mindex{Game in Strategic Form!Minmax Value}
\index{Minmax Value|see {Game in Strategic Form!}}
\given A 3-player game $\Gamma$ in strategic form.
\question Is the minmax value of player 1 at most 0? Here the minmax value of player $i$ is the minimum utility $\min_{\sigma} \max_{s_i} \mathsf{U}_i (\sigma \setminus s_i)$ of a best reply strategy, where $\sigma \setminus s_i$ is the collection of strategies obtained by replacing $\sigma_i$ by $s_i$ in $\sigma$.
\complexity \ER-complete by Hansen~\cite{H19} via a reduction from a variant of~\ourref{p:feasibility} similar to that of~\cite[Lemma 3.9]{S13}, where the solution of a system of quadratic equations is promised to lie in a polyhedron contained in the standard simplex.
\comments The problem remains \ER-complete under various promises, see Hansen~\cite{H19} for details.
\end{problemGT}

\begin{problemGT}{Trembling Hand Perfect Equilibrium}
\label{p:thpNash}
%Trembling Hand Perfect Equilibrium~\ourref[Nash Equilibrium!Trembling Hand Perfect]{p:thpNash}
%Trembling Hand Perfect Equilibrium~\ourref{p:thpNash}
\mindex{Nash Equilibrium!Trembling Hand Perfect}
\given A 3-player game $\Gamma$ in strategic form, and a pure Nash equilibrium $\mathbf{\sigma}$ of $\Gamma$.
\question Is $\mathbf{\sigma}$ a trembling hand perfect equilibrium? 
A collection of strategies $\sigma$ is a trembling hand perfect equilibrium if and only if it is the limit of a sequence of $\varepsilon$-perfect equilibria with $\varepsilon\to 0^+$, where an $\varepsilon$-perfect equilibrium is a Nash equilibrium that is fully mixed, and in which only pure strategies that are best replies get probability more than $\varepsilon$, see~\cite{S75,M78}.
\complexity \ER-complete by Hansen~\cite{H19} via a reduction from Minmax value~\ourref{p:minmaxGame}.
\end{problemGT}

\begin{problemGT}{Proper Equilibrium}
\label{p:pNash}
%Proper Equilibrium~\ourref[Nash Equilibrium!Proper]{p:pNash}
%Proper Equilibrium~\ourref{p:pNash}
\mindex{Nash Equilibrium!Proper}
\given A 3-player game $\Gamma$ in strategic form, and a pure Nash equilibrium $\mathbf{\sigma}$ of $\Gamma$.
\question Is $\mathbf{\sigma}$ a proper equilibrium? Here $\sigma$ is a proper equilibrium if it is the limit point of a sequence of $\varepsilon$-proper equilibria with $\varepsilon\to 0^+$, where an $\varepsilon$-proper equilibrium is a fully mixed equilibrium such that given two pure strategies $k$ and $\ell$ of the same player, if $k$ is a worse reply against $\sigma$ than $\ell$, then $\sigma$ must assign a probability to $k$ that is at most $\varepsilon$ times the probability it assigns to $\ell$, see~\cite{S75}.
\complexity \ER-complete by Hansen~\cite{H19} via a reduction from Minmax value~\ourref{p:minmaxGame}.
\end{problemGT}

\begin{problemGT}{Strategy Sets Closed under Rational Behavior}
\label{p:curbGame}
%Proper Equilibrium~\ourref[Game in Strategic Form!!Strategy Sets Closed under Rational Behavior]{p:curbGame}
%Strategy Sets Closed under Rational Behavior~\ourref{p:curbGame}
\mindex{Game in Strategic Form!Strategy Sets Closed under Rational Behavior}
\given A 3-player game $\Gamma$ in strategic form, and a collection of subsets $S_i\subseteq\Sigma_i$, $i=1,2,3$.
\question Is the collection $\{ S_i\}$ closed under rational behavior (CURB)? Here sets of pure strategies
$\{ S_i\}_{i=1}^m$ of an $m$-player game is CURB if and only if for all pure strategies $s$ of Player $i$ such that $s$ is a best reply to a distribution $S_1\times S_2 \times\ldots\times S_{i-1} \times S_{i+1} \times\ldots\times S_m$,
we have that $s\in S_i$.
\complexity \ER-complete by Hansen~\cite{H19} via a reduction from Minmax value~\ourref{p:minmaxGame}.
\end{problemGT}

% Pareto/strong NE

\begin{problemGT}{Pareto Optimal Nash Equilibrium}
\label{p:ParetoNash}
%Pareto optimal Nash Equilibrium~\ourref[Nash Equilibrium!Pareto Optimal]{p:ParetoNash}
%Pareto optimal Nash Equilibrium~\ourref{p:ParetoNash}
\mindex{Nash Equilibrium!Pareto Optimal}
\index{Pareto Optimal Nash Equilibrium|see {Nash Equilibrium}}
\given A $3$-player game $\Gamma$ in strategic form.
\question Does $\Gamma$ have a  Pareto optimal Nash equilibrium? A collection $\mathbf{\sigma}$ of mixed strategies is Pareto optimal if there does not exist any $\mathbf{\sigma}'$ such that $\mathsf{U}_i(\mathbf{\sigma}')\geq \mathsf{U}_i(\mathbf{\sigma})$ for all $i\in\{1,2,3\}$, and $\mathsf{U}_i(\mathbf{\sigma}')> \mathsf{U}_i(\mathbf{\sigma})$ for at least one $i\in\{1,2,3\}$. 
\complexity \ER-complete by Berthelsen, Hansen~\cite{BH22} via a reduction from the variant of Nash Equilibrium with Bounded Payoffs~\ourref{p:NashBoundedPayoff}, in which we require $\mathsf{U}_i(\mathbf{\sigma})=0$. 
\comments The result also holds for zero-sum games. The problem of deciding whether there exists a non-Pareto optimal Nash equilibrium is \ER-hard for symmetric win-lose games as well~\cite{BM21,BHM23}. 
\openq It is open whether the result also holds for win-lose games~\cite{BHM23}.
\end{problemGT}

\begin{problemGT}{Strong Nash Equilibrium}
\label{p:strongNash}
%strong Nash Equilibrium~\ourref[Nash Equilibrium!Strong]{p:strongNash}
%strong optimal Nash Equilibrium~\ourref{p:strongNash}
\mindex{Nash Equilibrium!Strong}
\index{Strong Nash Equilibrium|see {Nash Equilibrium}}
\given A $3$-player game $\Gamma$ in strategic form.
\question Does $\Gamma$ have a strong Nash equilibrium? A collection $\mathbf{\sigma}$ of mixed strategies is a strong Nash equilibrium if no coalition of players can together increase their payoff, hence if there is no nonempty subset $B\subseteq\{1,2,3\}$ such that all players in $B$ can increase their payoff by simultaneously deviating from their strategies in $\mathbf{\sigma}$. 
\complexity \ER-complete by Berthelsen, Hansen~\cite{BH22} via a reduction from the variant of Nash Equilibrium with Bounded Payoffs~\ourref{p:NashBoundedPayoff} in which we require $\mathsf{U}_i(\mathbf{\sigma})=0$.
\comments The result also holds for zero-sum games. The problem of deciding whether there exists a non-strong Nash equilibrium is \ER-hard for symmetric win-lose games as well~\cite{BHM23}.
\openq It is open whether the result also holds for win-lose games~\cite{BHM23}. 
\end{problemGT}

\begin{problemGT}{Nonsymmetric Nash Equilibrium}
\label{p:nonsymNash}
%Nonsymmetric Nash Equilibrium~\ourref[Nash Equilibrium!Strong]{p:nonsymNash}
%Nonsymmetric Nash Equilibrium~\ourref{p:nonsymNash}
\mindex{Nash Equilibrium!Nonsymmetric}
\index{Nonsymmetric Nash Equilibrium|see {Nash Equilibrium}}
\given A symmetric $3$-player game $\Gamma$ in strategic form.
\question Does $\Gamma$ have a nonsymmetric Nash equilibrium? 
\complexity \ER-complete by Berthelsen, Hansen~\cite{BH22} via a reduction from the variant of Nash Equilibrium with Bounded Payoffs~\ourref{p:NashBoundedPayoff} in which we require $\mathsf{U}_i(\mathbf{\sigma})=0$.
\end{problemGT}

\begin{problemGT}{Irrational Nash Equilibrium}
\label{p:irrationalNash}
%irrational Nash Equilibrium~\ourref[Nash Equilibrium!Irrational]{p:irrationalNash}
%irrational Nash Equilibrium~\ourref{p:irrationalNash}
\mindex{Nash Equilibrium!Irrational}
\index{Irrational Nash Equilibrium|see {Nash Equilibrium}}
\given A $3$-player game $\Gamma$ in strategic form.
\question Does $\Gamma$ have a Nash equilibrium $\mathbf{\sigma}$ in which $\sigma_i(s)\not\in\Q$ for some $i\in\{1,2,3\}$ and some $s\in\Sigma_i$?
\complexity \ER-hard by Berthelsen, Hansen~\cite{BH22} via a reduction from the variant of Nash Equilibrium with Bounded Payoffs~\ourref{p:NashBoundedPayoff} in which we require $\mathsf{U}_i(\mathbf{\sigma})=0$.
\comments The result also holds for zero-sum games~\cite{BH22}, and for win-lose games~\cite{BHM23}.
The problem of deciding whether there exists a rational Nash equilibrium, in which $\sigma_i(s)\in\Q$ for all $i\in\{1,2,3\}$ and all $s\in\Sigma_i$ is shown to be \EQ-hard~\cite{BH22}. It is open whether the problem is even decidable.
\end{problemGT}

\subsection{Games in Extensive Form}

\begin{quote}
Games in \emph{extensive form} are defined by a rooted tree with utility vectors at the leaves. Nodes of the tree are controlled either by one of the player, or by a so-called chance player, in which case we associate a probability distribution to the outgoing edges. In games in extensive form with \emph{imperfect information}, strategies can only be based on partial information, or \emph{signals} regarding the moves of the opponent.
A behavioral strategy is a mixed strategy based only on the received signals.
In games with \emph{imperfect recall}, not only strategies can only be based on partial information, but players can forget about the sequence of signals or actions.
The definitions extend to games that are defined on directed acyclic graphs.
We refer to Hansen~\cite{H19} and Gimbert, Paul, Srivathsan~\cite{GPS20} for detailed definitions.
\end{quote}

\begin{problemGT}{Trembling Hand Perfect Equilibrium for Games in Extensive Form}
\label{p:NashTremblingExt}
%trembling hand perfect equilibrium for games in extensive form~\ourref[Nash Equilibrium!Game in Extensive form!Trembling Hand Perfect]{p:NashTremblingExt}
%trembling hand perfect equilibrium for game in extensive form~\ourref{p:NashTremblingExt}
\mindex{Nash Equilibrium!Game in Extensive Form!Trembling Hand Perfect}
\index{Trembling Hand Perfect Equilibrium for Game in Extensive Form|see {Nash Equilibrium, Game in Extensive Form}}
\mindex{Nash Equilibrium!Game in Extensive Form!Quasi Perfect}
\index{Quasi Perfect Equilibrium for Game in Extensive Form|see {Nash Equilibrium, Game in Extensive Form}}
\mindex{Nash Equilibrium!Game in Extensive Form!Sequential}
\index{Sequential Equilibrium for Game in Extensive Form|see {Nash Equilibrium, Game in Extensive Form}}
\given A 3-player game $\Gamma$ in extensive form, and a pure Nash equilibrium $\mathbf{\sigma}$ of $\Gamma$.
\question Is $\mathbf{\sigma}$ a trembling hand perfect equilibrium? 
\complexity \ER-complete by Hansen~\cite{H19} via a reduction from Minmax value~\ourref{p:minmaxGame}.
\comments We refer~\cite{S75,vD84} for the definition of trembling hand perfect equilibria for games in extensive form. Hansen~\cite{H19} also gives \ER-completeness results for other properties of pure Nash equilibria of games in extensive form, in particular that of belonging to a \emph{sequential equilibrium}~\cite{KW82} and being a \emph{quasi-perfect equilibrium}~\cite{vD84}. 
\also Trembling Hand Perfect Equilibrium~\ourref{p:thpNash}.
\end{problemGT}



\begin{problemGT}{Non-negative Expected Payoff for Games in Extensive Form}
\label{p:NonnegExt}
%Non-negative Expected Payoff for Games in Extensive form~\ourref[Game in Extensive form!Non-negative Expected Payoff]{p:NonnegExt}
%Non-negative Expected Payoff for Games in Extensive form~\ourref{p:NonnegExt}
\mindex{Game in Extensive Form!Non-negative Expected Payoff}
\index{Non-negative Expected Payoff for Games in Extensive Form|see {Game in Extensive Form}}
\given A one-player game in extensive form, with imperfect recall.
\question Is the maximum expected payoff, over all behavioral strategies, non-negative?
\complexity \ER-complete by Gimbert, Paul, Srivathsan~\cite{GPS20}, via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. The result also holds for deciding whether the maximum payoff is strictly positive.
\also Feasibility~\ourref{p:feasibility}.
\end{problemGT}

\begin{problemGT}{Nonnegative Maxmin Payoff for Games in Extensive Form}
\label{p:NonnegMaxminExt}
%Nonnegative Maxmin Payoff for Games in Extensive Form~\ourref[Game in Extensive form!Nonnegative Maxmin Payoff]{p:NonnegMaxminExt}
%Nonnegative Maxmin Payoff for Games in Extensive Form~\ourref{p:NashNonnegMaxminExt}
\mindex{Game in Extensive Form!Non-negative Maxmin Payoff}
\index{Non-negative Maxmin Payoff for Games in Extensive Form|see {Game in Extensive Form}}
\given A zero-sum two-player game in extensive form, with imperfect recall.
\question Is the maxmin payoff, over all behavioral strategies, non-negative?
\complexity Both \ER-hard and \VR-hard, and belongs to \EVR by Gimbert, Paul, Srivathsan~\cite{GPS20}. Reductions are from Non-negative Expected Payoff for Games in Extensive form~\ourref{p:NonnegExt}.
\also Non-negative Expected Payoff for Games in Extensive form~\ourref{p:NonnegExt}.
\end{problemGT}

\begin{problemGT}{Stationary Nash Equilibrium in Acyclic Games}
\label{p:SNashAcyclic}
%Stationary Nash Equilibrium in Acyclic Games~\ourref[Nash Equilibrium!Game in Extensive Form!Stationary Nash equilibrium in acyclic games]{p:SNashAcyclic}
%Stationary Nash Equilibrium in Acyclic Games~\ourref{p:SNashAcyclic}
\mindex{Nash Equilibrium!Game in Extensive Form!Stationary Nash Equilibrium in Acyclic Games}
\given An acyclic $m$-player recursive game with payoff demands $L\in\R^m$.
\question Does there exist a stationary Nash equilibrium satisfying all the demands? A stationary equilibrium is one involving stationary strategies, that only depend on the current node of the graph.
\complexity \ER-complete by Hansen and S\o lvsten~\cite{HS20}. The reduction is from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} with homogeneous quadratic polynomials over a simplex.
\comments \ER-completeness holds even for $7$-player games with non-negative rewards.
\end{problemGT}

\subsection{Fair Division Problems}


\begin{problemGT}{Square-Cut Pizza Sharing}
\label{p:pizzasquarecut}
\mindex{Pizza Sharing!Square-Cut}
\index{Square-Cut Pizza Sharing|see {Pizza Sharing}}
\given A collection of $n$ pizzas, where a {\em pizza} is a mass distribution (measure) on $[0,1]^2$ that can be computed for polygonal subsets using arithmetic circuits. 
\question Can all pizzas be halved simultaneously by a {\em square cut}, that is, a single cut which is a polygonal arc consisting of horizontal and vertical segments, and such that the square cut makes at most $n-2$ turns? 
\complexity \ER-complete by Deligkas, Fearnley, and Melissourgos~\cite{DFM20,DFM22} via a reduction from consensus halving~\ourref[Consensus Halving]{p:consensushalving}. Remains \ER-complete even if each pizza consists of at most $6$ square or triangular pieces of mass (not necessarily uniform), and each point belongs to at most $3$ pizzas~\cite{DFM20,DFM22}. 
\comments The \ER-hardness result is sharp in the sense that $n$ pizzas can always be halved simultaneously with a square-cut making at most $n-1$ turns~\cite{KRPS16}.
%\universality 
%\openq 
\also Line-cut pizza sharing~\ourref{p:pizzalinecut}, consensus halving~\ourref{p:consensushalving}. 
\end{problemGT}


\begin{problemGT}{Line-Cut Pizza Sharing}
\label{p:pizzalinecut}
\mindex{Pizza Sharing!Line-Cut}
\index{Line-Cut Pizza Sharing|see {Pizza Sharing}}
\given A collection of $2n$ pizzas, where a {\em pizza} is a mass distribution (measure) on $[0,1]^2$ that can be computed for polygonal subsets using arithmetic circuits. 
\question Can all pizzas be halved simultaneously by making $k$ line cuts (and assembling the resulting pieces appropriately)? 
\complexity \ER-complete by Schnider~\cite{S21d} via a reduction from consensus halving~\ourref[Consensus Halving]{p:consensushalving} with $k = n-1$  
%\Year
\comments The \ER-hardness result is sharp in the sense that $2n$ pizzas can always be halved simultaneously with at most $n$ line cuts~\cite{HK20}.
%\universality 
%\openq 
\also Square-cut pizza sharing~\ourref{p:pizzasquarecut}, consensus halving~\ourref{p:consensushalving}. 
\end{problemGT}

\begin{problemGT}{Consensus Halving}
\label{p:consensushalving}
\mindex{Consensus Halving}
\given A family of $n$ arithmetic circuits computing functions $F_i: [0,1] \rightarrow \R$, $i \in [n]$, a natural number $k \in \N$. The functions $F_i$ are used to valuate intervals and unions of intervals by defining $F_i([a,b]) = F_i(b)-F_i(a)$, and $F_i(A \cup B) = F_i(A) + F_i(B)$ for disjoint subsets $A$ and $B$ of $[0,1]$. 
\question Is there a {\em $k$-cut}, that is, $k$ points $0 \leq x_1 \leq \cdots \leq x_k \leq 1$, with the following property: if we split $[0,1]$ into
two sets $A_+ = \bigcup_{0 \leq 2i \leq k} [x_{2i}, x_{2i+1}]$ and $A_- = \bigcup_{0 \leq 2i+1 \leq k} [x_{2i+1}, x_{2i+2}]$, where we let $x_0 = 0$ and $x_{k+1} = 1$, then $F_i(A_+) = F_i(A_-)$ for all $i \in [n]$? That is all agents, the holders of the valuation functions, valuate the two ``halves'' $A_+$ and $A_-$ equally.
\complexity \ER-complete by Deligkas, Fearnley, Melissourgos, and Spirakis~\cite{DFMS22} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility} over a compact domain. The problem is hard for $k = n-1$ and always solvable (using the Borsuk-Ulam Theorem) for $k = n$.
%\Year
%\comments
%\universality 
\openq Does the problem remain hard if the $F_i$ are given as polynomials? 
\also Square-cut pizza sharing~\ourref{p:pizzasquarecut}, line-cut pizza sharing~\ourref{p:pizzalinecut}. 
\end{problemGT}

\subsection{Markets}

\begin{problemGT}{Equilibrium in Exchange Markets}
\label{p:Market}
%Equilibrium in Exchange Markets~\ourref[Equilibrium in Exchange Markets]{p:Market}
%Equilibrium in Exchange Markets~\ourref{p:Market}
\mindex{Equilibrium in Exchange Markets}
\given An Arrow-Debreu exchange market, consisting of a set $\mathcal{G}$ of $g$ divisible goods, a set $\mathcal{A}$ of agents, a matrix $W$ such that $W_{ij}$ is the amount of good $j$ with agent $i$, and a non-negative piecewise-linear concave utility function $U_i:\R^g_+\to\R_+$.
\question Is there an equilibrium in the market, that is, $p\in\R_+^g$ and $x_i\in\R^g$ for all $i\in\mathcal{A}$, such that
\begin{eqnarray*}
   \forall i\in\mathcal{A}: x_i & = & \mathrm{arg}\max_y \{U_i(y) : \sum_j y_jp_j\leq\sum_j W_{ij}p_j \} \\
\forall j\in\mathcal{G}: \sum_i x_{ij} & = & \sum_i W_{ij}?
\end{eqnarray*}
\complexity \ER-complete by Garg, Mehta, Vazirani, and Yazdanbod~\cite{GMVY17} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}.
The result holds even under the assumption that the utility functions are Leontief utility functions, a special subclass of piecewise-linear concave functions, see~\cite{GMVY17} for definitions.
%\universality 
%\openq 
%\also 
\end{problemGT}

