\section{Machine Learning and Probabilistic Reasoning}

\begin{quote}
Artificial neural networks come in  many variants. For the purpose of this section,
we only define fully-connected, feed-forward, ReLU networks.
Such a network realizes a parameterized function $N_p: \R^{n} \rightarrow \R^m$ which maps an input $x\in \R^n$ to some output $N_p(x) \in \R^m$ given some parameters $p$ (weights and biases).
Given a set of data points $(x,y)$, the goal is to find the right $p$ such that $N_p$ predicts the $y$-values of the data points to within a given threshold.
The function $N_p$ is the composition of two types of functions.
The first type is a simple affine transformation $x \mapsto Ax + b$.
The second type is an activation function; examples include the identity function and the rectified linear unit activation function \ReLU. 
(The name is more complicated than the function itself.)
\ReLU maps $x \in \R^n$ to $y \in \R^n$, where  $y_i = \max(x_i,0)$.
An artificial neural network can be described as a repeated composition
of affine functions and \ReLU's.
We refer the interested reader to the comprehensive book by Goodfellow, Bengio and Aaron on  Deep learning~\cite{goodfellow2016deep}, for an in-depth introduction of the great variety neural network architectures and training methods.


\bigskip

When we want to reason about probabilities in a formal sense, we can define 
formal languages $\mathcal{L}$ which can express probabilities of events,
where events can again be combined using elementary variables, conditional probabilities and conjunction of events, comparison of probabilities, independence statements, confirmation statements and potentially many more. 
There is an illustrative example that shows us that irrational numbers might be needed to find a solution.
We try to find probabilities such that $ \Pr(A \cap B ) = 1 - \Pr(A \cap B)$ and 
$\Pr(A \cap B ) = \Pr(B) \cdot \Pr(B)$ 
implies that $\Pr(B) = \sqrt{1/2}$.
\end{quote}



\begin{problemML}{Training Neural Networks}
\label{p:neuralnettrain}
%training neural network~\ourref[Neural Networks!Training]{p:neuralnettrain}
%training neural network~\ourref{p:neuralnettrain}
\mindex{Neural Networks!Training}
\index{Training Neural Network|see {Neural Networks}}
\given A set of data points, a neural network architecture, a cost function, a threshold
\question Do there exist biases and weights such that the total error is below the threshold?
\complexity First Abrahamsen, Kleist and Miltzow~\cite{AKM21} showed \ER-completeness for arbitrary network architectures, two layers, and the identity activation function.
Bertschinger, Hertrich, Jungeblut, Miltzow, and Weber~\cite{BHJMW22} strengthened the result to fully-connected neural networks with only two input, two output neurons and the ReLU activation function.
In case that we allow that some weights are given in the input than the problem was shown to be \ER-complete already in 1992 by Zhang~\cite{Z92}.
\comments The \ER-hardness results were extended in part to other activation functions involving non-algebraic functions~\cite{HHKV23}.
In that case the problems might not be even decidable.
To make the problems with non-algebraic activation functions easier, the neural network problem was studied in a regime where incorrect answers are allowed~\cite{BDC23}.
%\universality 
%\openq 
\also Reachability in neural network~\ourref{p:neuralnetreach}.
\end{problemML}

\begin{problemML}{Reachability in Neural Networks}
\label{p:neuralnetreach}
\mindex{Neural Networks!Reachability}
\index{Reachability in Neural Network|see {Neural Networks}}
\given A feedforward neural network $N$ with weights and biases, seen as a function from $N:\R^n\to\R^m$, and two convex polytopes $A\subseteq \R^n$ and $B\subseteq \R^m$, described by linear inequalities. 
\question Do there exist points $x \in A$ and $y \in B$ such that $N(x) = y$?
\complexity The complexity of the problem depends on the type of activation functions that are allowed, see Wurm~\cite{W23b}. 
The problem becomes \ER-hard for many common non-linear activation functions.
\comments Wurm~\cite{W23b} shows a close relation to constraint satisfaction problems (CSPs).
Different computational complexities of CSPs translate directly to the corresponding complexity of the neural network reachability problem.
% \universality 
%\openq 
\also Training neural network~\ourref{p:neuralnettrain}.
%\tags 
\end{problemML}

\begin{problemML}{Satisfiability of Probabilistic Languages \L{}}
\label{p:satprobL}
\mindex{Satisfiability of Probabilistic Languages}
\given A formula $\varphi$ in the probabilistic language \L .
\question Does there exists an assignment of probabilities that makes $\varphi$ true?
\complexity Moss\'{e}, Ibeling, and Icard~\cite{MII22} showed that the problem is \ER-complete for the languages
$\L^{\textrm{cond}}_{\textrm{prob}}$, $\L^{\textrm{poly}}_{\textrm{prob}}$, $\L^{\textrm{cond}}_{\textrm{causal}}$, and $\L^{\textrm{poly}}_{\textrm{causal}}$.
% 
Ibeling, Icard, Mierzewski, and Mossé~\cite{IIMM23} showed \ER-completeness
for the languages 
$\L^{\textrm{ind}}$, $\L^{\textrm{confirm}}$, $\L^{\textrm{cond}}$, and 
$\L^{\textrm{poly}}$
% 
The problem is known to be \NP-complete for the languages 
$\L^{\textrm{comb}}_{\textrm{prob}}$, 
$\L^{\textrm{lin}}_{\textrm{prob}}$, 
$\L^{\textrm{comp}}_{\textrm{causal}}$, and
or $\L^{\textrm{lin}}_{\textrm{causal}}$, see also Fagin~\cite{F86}.
The reductions are from \ETRINV~\ourref[ETRINV@\ETRINV]{p:ETRINV}.
\comments The results indicate that the difference between 
\NP-completeness and \ER-completeness is caused by 
allowing conditional probability statements 
or the multiplication of probabilities.
The satisfiability problem for probabilistic languages that are allowed to contain summation symbols, e.g.\ abbreviating a sum like $1+2+3 +...+ n$ as $\sum_{i=1}^{n}i$, is complete for the class \succER, a real version of \NEXP~\cite{vdZBL23}.
% \universality 
%\openq 
\also \ETRINV~\ourref{p:ETRINV}.
\end{problemML}


\begin{problemML}{Gaussian Conditional Independence Inference Problem}
\label{p:gaussianindependence}
\mindex{Gaussian Conditional Independence Inference Problem}
\given A Conditional Independence Inference Rule $\varphi$. See~\cite{studeny2006probabilistic} for definitions.
\question Is the rule $\varphi$ valid for all regular Gaussians?
\complexity Boege (see~\cite[Theorem 5.38]{B22b} and \cite[Theorem 11]{B22c}) showed that the problem is \VR-complete.
\comments The proof is via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}, using Shor's normal and an encdoing via geometric von Staudt gadgets.
% \universality 
%\openq 
\also Feasibility~\ourref{p:feasibility}.
%\tags 
\end{problemML}

