\section{Markov Chains and Decision Processes}

\begin{quote}
We recommend the book by Sutton and Barto on reinforcement learning~\cite{sutton2018reinforcement} for the definition of Markov Decision Processes (MDPs) and their variants, to which a full chapter is dedicated, and which does an excellent job of illustrating the notion in-depth.
\end{quote}

\begin{problemMDP}{Realizability of polynomial parametric Markov Decision Processes}
\label{p:realpolyMC}
\mindex{Markov Decision Process!Realizability of polynomial parametric MDP}
\index{Realizability of polynomial parametric MDP|see {Markov Decision Process}}
\given A polynomial, parametric Markov Decision Process with at least two states.
\question Is the polynomial parametric Markov Decision Process realizable?
\complexity The problem is first claimed to be \ER-complete by Junges, Katoen, P\'{e}rez, and Winkler~\cite{JKPW21} via a reduction from local positivity over a bounded domain~\ourref[Polynomial(s)!Positivity!Local]{p:LocalPos}.
They in turn attribute this to earlier work by
Lanotte, Maggiolo{-}Schettini, Troina~\cite{LMT07}.
\comments Polynomial and parametric in the context of Markov Decision Processes mean that the transition probabilities are polynomial functions $f(x)$ instead of real numbers.
The question is whether there exists some $x$ such that $f$ describes a well-defined Markov Decision Process.
%\universality 
%\openq 
%\also 
%\tags 
\end{problemMDP}

\begin{problemMDP}{Never Worse States in Graph Parametric MDP}
\label{p:neverworseMDP}
\mindex{Markov Decision Process!Never Worse States in Graph Parametric MDP}
\index{Never Worse States in Graph Parametric MDP|see {Markov Decision Process}}
\given A (non-weighted) parametric Markov Decision Process $\mathcal{M}$ with graph $G(\mathcal{M}) = (V,E)$, together with $v\in V$ and $W\subseteq V$.
\question Is $v$ never worse than $W$?
\complexity Engelen, P\'{e}rez, and Rao showed that the problem is \VR-complete~\cite{EPR23} via a reduction from (the complement of) strict local positivity~\ourref[Polynomial(s)!Strict Positivity!Local]{p:LocalPos}.
% \comments 
% \universality 
%\openq 
\also Equally bad states in graph parameteric MDP~\ourref{p:equallybadMDP}, strict local positivity~\ourref{p:LocalPos}.
%\tags 
\end{problemMDP}

\begin{problemMDP}{Equally Bad States in Graph Parametric MDP}
\label{p:equallybadMDP}
%equally bad states in graph parameteric MDP~\ourref[Markov Decision Process!Equally Bad States in Graph Parametric MDP]{p:equallybadMDP}
%equally bad states in graph parameteric MDP~\ourref{p:equallybadMDP}
\mindex{Markov Decision Process!Equally Bad States in Graph Parametric MDP}
\index{Equally Bad States in Graph Parametric MDP|see {Markov Decision Process}}
\given A (non-weighted) parametric Markov Decision Process $\mathcal{M}$ with graph $G(\mathcal{M}) = (V,E)$, together with $v,w\in V$.
\question Is $v$ never worse than $w$ and vice versa?
\complexity Engelen, P\'{e}rez, and Rao showed that the problem is \VR-complete~\cite{EPR23} via a reduction from~\ourref[Markov Decision Process!Never Worse States in Graph Parametric MDP]{p:neverworseMDP}.
% \comments 
% \universality 
%\openq 
\also Never worse states in graph parameteric MDP~\ourref{p:neverworseMDP}.
%\tags 
\end{problemMDP}

\begin{problemMDP}{Total Variation Distance in MDP}
\label{p:totvardistMDP}
%total variation distance in MDP~\ourref[Markov Decision Process!Total Variation Distance]{p:totvardistMDP}
%total variation distance in MDP~\ourref{p:totvardistMDP}
\mindex{Markov Decision Process!Total Variation Distance}
\index{Total Variation Distance in MDP|see {Markov Decision Process}}
\given A (labeled) Markov Decision Process and two initial distributions $\mu$ and $\nu$.
\question Is there a (memoryless) strategy such that total variation distance in the induced Markov~Chain equals $0$?
\complexity Kiefer and Tang showed that the problem is \ER-complete~\cite{KT20} via a reduction from non-negative matrix factorization~\ourref[Matrix!Non-negative Factorization]{p:nonnegmatfac}. Remains \ER-complete for total variation distance less than~$1$~\cite{KT20}.
\comments The problem is polynomial time decidable if we ask if the total variation distance can be made larger than $0$.
For the related notion of probabilistic bisimilarity all studied cases are either \NP-complete or in \P~\cite{KT20}.
% \universality 
\openq If we ask for total variation distance equal to one then it is known that the problem is \NP-hard and in \ER~\cite{KT20}. 
So it remains to settle this case.
\also Non-negative matrix factorization~\ourref{p:nonnegmatfac}.
%\tags 
\end{problemMDP}

\begin{problemMDP}{Reachability for Augmented Interval Markov Chain}
\label{p:reachMC}
%reachabilty for augmented interval Markov chain~\ourref[Markov Chain!Reachability for Augmented Interval MC]{p:reachMC}
%reachabilty for augmented interval Markov chain~\ourref{p:reachMC}
\mindex{Markov Chain!Reachability for Augmented Interval MC}
\index{Reachability for Augmented Interval MC|see {Markov Chain}}
\given An augmented interval Markov Chain $\mathcal{M}$, an initial vertex $s$, a target vertex $t$, and a threshold $\tau\in [0,1]$.
\question Does there exists an Markov Chain $M\in [\mathcal{M}]$ refining $\mathcal{M}$ such that 
the probability to go from $s$ to $t$ is at least/most $\tau$?
\complexity Chonev showed that the problem is \ER-complete~\cite{C19}. 
\comments The problem is also \ER-complete, if we consider the approximate version.
% \universality 
%\openq 
\also Quantitative reachabilty for parametric acyclic Markov chain~\ourref{p:quantreachMC}.
%\tags 
\end{problemMDP}


\begin{problemMDP}{Model Checking for Interval Markov Chains w.r.t.\ Unambiguous Automata} \label{p:MCforMCwrtUA}
\mindex{Markov Decision Process!{Model Checking for Interval Markov Chains with respect to Unambiguous Automata}}
\index{Model Checking for Interval Markov Chains with respect to Unambiguous Automata|see {Markov Chain}}
\given An interval Markov chain and a regular language $E$.
\question Does there exists values for the undetermined transitions of the Markov chain such that $E$ is satisfied?
\complexity The problem was shown to be $\NP_\R$-complete by Benedikt, Lenhardt, and  Worrell~\cite{BLW13b}. 
The same proof easily also shows \ER-completeness.
\comments 
They reduce from Local Positivity~\ourref{p:LocalPos} on a bounded domain with a single multivariate polynomial of a specific form.
% \universality 
%\openq 
% \also 
%\tags 
\end{problemMDP}


\begin{problemMDP}{Quantitative Reachability for Parametric Acyclic Markov Chains}
\label{p:quantreachMC}
%quantitative reachabilty for parametric acyclic Markov chain~\ourref[Markov Chain!Reachability for Augmented Interval MC]{p:quantreachMC}
%quantitative reachabilty for parametric acyclic Markov chain~\ourref{p:quantreachMC}
\mindex{Markov Chain!Quantitative Reachability for Parametric Acyclic MC}
\index{Quantitative Reachability for Parametric Acyclic MC|see {Markov Chain}}
\given A parametric \textit{acyclic} Markov Chain and a target state $T$.
\question Does there exists a well-defined and graph preserving valuation of the probability transitions such that the probability to reach $T$ is at least/most $1/2$?
\complexity The problem was shown to be \ER-complete by Junges, Katoen, P\'{e}rez, and Winkler~\cite{JKPW21}.
\comments The problem is very reminiscent to the Reachability problem for Augmented Interval Markov Chains. 
Clearly, the \ER-completeness also carries over to Markov Decision Processes.
The authors also use the term \textit{parameter synthesis} in this context to describe the question of finding parameters for some property to hold.
% \universality 
%\openq 
\also Reachabilty for augmented interval Markov chain~\ourref{p:reachMC}.
%\tags 
\end{problemMDP}


\begin{problemMDP}{Memoryless Distance Minimisation Problem for Markov Decision Processes}
\label{p:memorylessDMPforMDPs}
%
\mindex{Markov Chain!Memoryless Distance Minimisation Problem for MDP}
\index{Memoryless Distance Minimisation Problem for Markov Decision Processes|see {Markov Decision Process}}
\given A Markov Decision Process with two initial states, and a threshold.
\question Does there exists a memoryless strategy such that the distance between the two initial states is at most the threshold?
\complexity The problem was shown to be \ER-complete by Kiefer and Tang~\cite{KT24}.
\comments They reduce from strict local Positivity \ourref{p:LocalPos}, with bounded domain and a single polynomial of degree $6$.
% \universality 
%\openq 
% \also 
%\tags 
\end{problemMDP}

