\begin{problemMisc}{Euclidean Preference}
\label{p:Euclideanpref}
\mindex{Euclidean Preference}
\given A finite set $A$, and a {\em profile} $V$, a collection of strict orders $\succ_v$ over $A$, that is, each $\succ_v$ is total, irreflexive, antisymmetric and transitive. The orders are also called {\em preference relations} or {\em votes}. 
\question Is there a function $x: V\cup A \rightarrow \R^d$ such that $a \succ b$ implies that $\norm{x(v)-x(a)}_2 < \norm{x(v)-x(b)}_2$
for all $v \in V$ and $a,b \in A$? In that case the profile $V$ is known as {\em $d$-Euclidean}.
\complexity \ER-complete for any fixed $d \geq 2$ by Peters~\cite{P17} via a reduction from oriented hyperplane realizability~\ourref[Oriented Hyperplane Realizability in Rd@Oriented Hyperplane Realizability in $\R^d$]{p:orientedhyperplanereal}. Remains \ER-complete if all orders are {\em dichotomous}, that is, there is no triple $a,b,c$ with $a \succ_v b \succ_v c$ for any $v \in V$~\cite{P16,P17}.
%\Year
\comments For the Manhattan and maximum metrics the problem lies in \NP, so it is unlikely to be \ER-hard in those cases~\cite{P17}; \NP-hardness seems to be open for those metrics. 
%\universality 
%\openq 
\also Oriented hyperplane realizability~\ourref{p:orientedhyperplanereal}.
\end{problemMisc}


\begin{problemMisc}{(Ultimate) Positivity of Linear Recurrence}
\label{p:poslinrecur}
\mindex{Linear Recurrence!Positivity}\index{Positivity of Linear Recurrence|see {Linear Recurrence}}
\mindex{Linear Recurrence!Ultimate Positivity}\index{Ultimate Positivity of Linear Recurrence|see {Linear Recurrence}}
\given Coefficients $a_1, \ldots, a_k \in \Q^k$ and initial values $u_0, \ldots, u_{k-1} \in \Q^k$. 
With these numbers we define the sequence $u_n = \sum_{i=1}^k a_i u_{n-i}$ for $n \geq k$.
\question Is the sequence $(u_n)_{n \geq 0}$ {\em (ultimately) positive}; that is, is $u_n > 0$ for (almost) all $n$?
\complexity Both positivity and ultimate positivity are \VR-hard by Ouaknine and Worrell~\cite{OW17} via a reduction from strict local positivity (of a polynomial)~\ourref[Polynomial(s)!Strict Positivity!Local]{p:LocalPos}. For simple recurrences (the characteristic polynomial has no multiple roots), the problems can be decided in $\coNP^{\ER}$~\cite{OW14,OW17}. 
\comments These problems are related to Skolem's problem which asks whether $u_n = 0$ for some $n$. Decidability of Skolem's problem is a famously open question. 
%\universality 
\openq Does positivity (or ultimate positivity) lie in \VR? \sep\ What is the complexity of the robust version of the problem (in which each $a_i$ is given with a small neighborhood), as studied in~\cite{V23}?
\also Strict local positivity~\ourref{p:LocalPos}, zeroness of convolution recursive sequence~\ourref{p:zerconvolution}. 
\end{problemMisc}


\begin{problemMisc}{Linear Update Loop Termination}
\label{p:linearloop}
\mindex{Linear Update Loop Termination}
\given Boolean formula $\varphi(x)$ over polynomial inequalities in $x \in \R^n$, matrix $A \in \R^{n\times n}$, vector $b \in \R^n$.
\question Does the program $\mathrm{\mathbf{while}}\ \varphi(x)\ \mathrm{\mathbf{do}}\ x = Ax+b$ terminate for every initial value $x \in \R^n$?
\complexity \VR-complete by Frohn, Hark, Giesl~\cite[Theorem 7.5]{FHG23} via a reduction from feasibility~\ourref[Polynomial(s)!feasibility]{p:feasibility}. Remains \VR-complete if $b = 0$, but becomes \coNP-complete if $\varphi$ consists of linear polynomial conditions only~\cite[Theorem 7.3]{FHG23}. 
\comments The non-trivial part in this result is \VR-membership, the \VR-hardness is immediate with program $\mathrm{\mathbf{while}}\ \varphi(x)\ \mathrm{\mathbf{do}}\ x = x$. For earlier work on related problems, see~\cite{COW15}.
%\universality 
\openq What is the complexity of the problem if instead we ask whether the program terminates for a specific initial value $x \in \Q^n$? For specific types of conditions $\varphi(x)$ this was called the Extended Orbit Problem\index{Extended Orbit Problem (Open)} in~\cite{COW15} and shown to lie in \ER. Another problem that has similarities is the compact escape problem~\ourref[Compact Escape Problem]{p:compactescape}.
\also (Ultimate) positivity of linear recurrence~\ourref{p:poslinrecur}, compact escape problem~\ourref{p:compactescape}, feasibility~\ourref{p:feasibility}.
%\tags 
\end{problemMisc}



