\begin{problemL}{$Q_1\cdots Q_k$-Fragment of the Theory of the Reals}
\label{p:quantifiedR}
\mindex{Q1Qk fragment of the theory of the reals@$Q_1\cdots Q_k$-Fragment of the Theory of the Reals}
\given A sentence over the signature $(0,1,+,\cdot)$ with alternating quantifier blocks $Q_1, \ldots, Q_k$, with $Q_i \in \{\exists,\forall\}$ comparison operators $\{=, < \leq, \geq, >\}$ and logic connectives $\vee, \wedge$ and $\neg$. 
\question Is the sentence true if interpreted over the reals?
\complexity Complete for $Q_1\cdots Q_k \R$ by B\"{u}rgisser and Cucker~\cite{BC09}. The problem remains complete for
$Q_1\cdots Q_k \R$ even if the matrix is of the form $f(x) > 0$ or $f(x) \geq 0$, for a polynomial $f$, and, under certain conditions, for $f(x) = 0$, and if the quantifiers are restricted to $(-1,1)$ or $[-1,1]$, as shown by Schaefer and \v{S}tefankovi\v{c}~\cite[Tables 1 and 2]{SS23}. There are also some robustness results, mostly on the first and second level, that allow the use of exotic quantifiers, $\exists^*, \forall^*$  and \HQ, see~\cite{BC09,JJ23}.
%\comments 
%\universality 
%\openq 
\also \ETR~\ourref{p:ETR}. 
\end{problemL}

\subsection{Algebra}


\begin{problemA}{Compact Escape Problem}
\label{p:compactescape}
%compact escape problem~\ourref[Compact Escape Problem]{p:compactescape}
%compact escape problem~\ourref{p:compactescape}
\mindex{Compact Escape Problem}
\given A compact semialgebraic set $K \subseteq \R^n$, a matrix $A \in \Q^{n\times n}$.
\question For all $x \in K$ is there a $k$ such that $A^kx \not\in K$? 
\complexity \VER-complete by D'Costa, Lefaucheux, Neumann, Ouaknine, and Worrell~\cite{DCLNOW21} via a reduction from the $\forall\exists$-fragment of the theory of the reals~\ourref[Q1Qk fragment of the theory of the reals@$Q_1\cdots Q_k$-Fragment of the Theory of the Reals]{p:quantifiedR}.
\comments  D'Costa, Lefaucheux, Neumann, Ouaknine, and Worrell~\cite{DCLNOW21} show that the problem is hard for $\forall\exists_{<}\R$, hardness then follows, since $\VER = \forall\exists_{<}\R$ by Schaefer, \v{S}tefankovi\v{c}~\cite{SS23}.
%\universality 
%\openq 
\also $Q_1\cdots Q_k$-fragment of the theory of the reals~\ourref{p:quantifiedR}, linear update loop termination~\ourref{p:linearloop}.
%\tags 
\end{problemA}

\begin{problemA}{Hausdorff Distance}
\label{p:Hausdorffdist}
%Hausdorff distance~\ourref[Semialgebraic Set(s)!Hausdorff distance]{p:Hausdorffdist}
%Hausdorff distance~\ourref{p:Hausdorffdist}
\mindex{Hausdorff distance|see {Semialgebraic Set(s)}}
\mindex{Semialgebraic Set(s)!Hausdorff distance}
\given Two semialgebraic sets $A, B \subseteq \R^n$, $d \in \Q$. The {\em Hausdorff distance} is defined as $d_H(A,B) := \max(\sup_{a \in A} \inf_{b \in B} \norm{a-b}, \sup_{b \in B} \inf_{a \in A} \norm{a-b})$. 
\question Do $A$ and $B$ have Hausdorff distance at most $d$, that is,
is $d_H(A,B) \leq d$? 
\complexity \VER-complete by Jungeblut, Kleist, Miltzow~\cite{JKM23} and Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} via reductions from the $\forall\exists$-fragment of the theory of the reals~\ourref[Q1Qk fragment of the theory of the reals@$Q_1\cdots Q_k$-Fragment of the Theory of the Reals]{p:quantifiedR}. The problem remains hard for $d = 0$~\cite{JKM23,SS23} or $d$ double-exponentially small~\cite{JKM23}. 
\comments  Jungeblut, Kleist, Miltzow~\cite{JKM23} show that the problem is complete for $\forall\exists_<\R$, Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} show the full result, based on B\"{u}rgisser, Cucker~\cite{BC09} who called the $d = 0$ case {\em Euclidean Relative Denseness}.\index{Euclidean Relative Denseness}. The directed Hausdorff distance, $\sup_{a \in A} \inf_{b \in B} \norm{a-b}$ is also \VER-complete~\cite{JKM23, SS23}. The proofs are 
%\universality 
\openq Jungeblut %in his not-yet published thesis
asks whether the problem becomes \EVER-complete if we ask whether there is a translation $t$ in $\R^n$ such that $d_H(t(A),B) \leq d$; this is a restricted case of the  Gromov-Hausdorff distance~\ourref[Semialgebraic Set(s)!Gromov-Hausdorff Distance (Open)]{p:Gromovdistance}.
\also Distance of semialgebraic sets~\ourref{p:distancesemi}, Gromov-Hausdorff distance~\ourref{p:Gromovdistance}, Fr\'{e}chet distance of surfaces~\ourref{p:frechetdist}. 
%\tags 
\end{problemA}

\begin{problemA}{Surjectivity}
\label{p:surjectivity}
\mindex{Polynomial(s)!Surjectivity}
\given A polynomial $f$ in $\Z[x_1, \ldots, x_n]$, domain $A$, codomain $B$. 
\question Is $f$ surjective as a function from $A$ to $B$?
\complexity \VER-complete by Schaefer, \v{S}tefankovi\v{c}~\cite{SS23} extending work by B\"{u}rgisser and Cucker~\cite[Proposition 4.1]{BC09}. Hardness can be obtained via a reduction from a constrained version of the $Q_1\cdots Q_k$-fragment of the theory of the reals~\ourref[Q1Qk fragment of the theory of the reals@$Q_1\cdots Q_k$-Fragment of the Theory of the Reals]{p:quantifiedR}. The problem remains \VER-complete if $A$ and $B$ are Cartesian products of $\R$ and $[-1,1]$ and the total degree of $f$ is bounded. 
\comments  B\"{u}rgisser and Cucker~\cite{BC09} showed that surjectivity of rational functions given by arithmetic circuits is \VER-complete, Schaefer and \v{S}tefankovi\v{c}~\cite{SS23} proved the result for polynomials.
%\universality 
\openq Does the problem remain \VER-complete if both $A$ and $B$ are of the form $\R^n$? 
\also Image density (arithmetic circuit)~\ourref{p:imagedensity}.
%\tags 
\end{problemA}


\begin{problemA}{Image Density (arithmetic circuit)}
\label{p:imagedensity}
%image density (arithmetic circuit)~\ourref[Arithmetic Circuit!Image density]{p:imagedensity}
%image density (arithmetic circuit)~\ourref{p:imagedensity}
\mindex{Arithmetic Circuit!Image density}
\given An arithmetic circuit (with sign function), defining a function $f: \R^n \rightarrow \R$.
\question Is the range of $f$ dense in $\R^n$?
\complexity \VER-complete, combining results from B\"{u}rgisser, Cucker~\cite[Proposition 5.7, Corollary 9.4]{BC09} and Junginger~\cite[Theorem 4.27]{JJ23}. 
\comments B\"{u}rgisser and Cucker show that this problem is hard for a complexity class involving exotic quantifiers; Junginger shows that that class equals \VER. In the Zariski topology, B\"{u}rgisser, Cucker~\cite[Proposition 5.7, Corollary 9.4]{BC09} show that the problem is \ER-complete. 
%\universality 
%\openq 
\also Surjectivity (second level)~\ourref{p:surjectivity}, domain density (arithmetic circuit)~\ourref[Arithmetic Circuit!Domain density]{p:DomainDensityAC}, density of semialgebraic set~\ourref{p:radiussemi}.  
%\tags 
\end{problemA}

