\begin{problemLO}{Universality of Unambiguous Context-Free Grammar (UUCFG)}
\label{p:universalunambig}
\mindex{Grammar!Universality of Unambiguous Context-Free Grammar (Open)}
\index{Universality of Unambiguous Context-Free Grammar (Open)|see {Grammar}}
\given A context-free grammar $G$ over alphabet $\Sigma$ which is {\em unambiguous}, that is, every word generated by the grammar has a unique derivation tree.
\question Is the grammar {\em universal}, that is, is $L(G) = \Sigma^*$?
\complexity This problem was shown to lie in \VR\ by Clemente~\cite{C20} using another interesting intermediate problem, zeroness of convolution recursive sequences~\ourref[Sequence!Zeroness of Convolution Recursive Sequence (Open)]{p:zerconvolution}, which also lies in \VR. Clemente also mentions a more direct proof of membership in Stanis{\l}aw Purga{\l}'s master's thesis. Finally, he shows that a slightly generalized problem, the coin-flip measure comparison problem\index{coin-flip measure comparison}, is as hard as \SSQR\ problem\index{sum of square roots}.
%\comments 
%\universality 
%\openq 
\also Positivity of linear recurrence~\ourref{p:poslinrecur}, zeroness of convolution recursive sequence~\ourref{p:zerconvolution}.
\end{problemLO}


\begin{problemLO}{Existential Theory of Invertible Matrices}
\label{p:ETInvMat}
\mindex{Matrix!Existential Theory of Invertible Matrices (Open)}
\index{Existential Theory of Invertible Matrices (Open)|see {Matrix}}
\given A conjunction of conditions of the form $AX_i = X_jB$, where the $X_k$ are (matrix) variables and $A,B \in \Q^{n \times n}$.
\question Are there invertible matrices $X_k \in \R^{n \times n}$ satisfying all conditions?
\complexity In \ER. 
\comments The problem was introduced by Dubut~\cite{D20} to upper-bound the complexity of the bisimilarity of diagrams (itself a possible candidate for \ER-completeness?). Without the invertibility contraints, the problem turns into a linear program becoming solvable in polynomial time. It may be easier to show the problem \ER-complete if one is given access to the inverses of the $X_i$, but that's not the case in the original problem.  
%\universality 
%\openq 
\also Matrix singularity~\ourref{p:MatSing}, constrained matrix invertibility problem~\ourref{p:constmatinv}, feasibility~\ourref{p:feasibility}.
\end{problemLO}




\subsection{Algebra}

\begin{problemAO}{Feasibility of Univariate Polynomial}  
\label{p:UniFEAS}
\mindex{Polynomial(s)!Feasibility of Univariate Polynomial (Open)}
\given A univariate polynomial $f \in \Z[x]$ defined by a straight-line program or arithmetic circuit.
\question Does $f$ have a root, that is, is there an $x$ such that $f(x) = 0$?
\complexity Known to be \NP-hard (for a history of proofs, see Perrucci, Sabia~\cite{PS07}), and in \ER. Is it \ER-complete?
\comments This candidate is a bit surprising; the known \NP-hardness proofs are quite intricate. Does the problem lie in \NP? 
If one asks whether $f$ has a {\em rational} root in a given interval, then the problem is decidable using Eisenstein's criterion, see for example~\cite[Lemma 5.22]{DGVvG99}; that makes it somewhat less likely that the rational version of the problem is \EQ-hard. See~\cite{BJ24} for complexity results on counting the number of real roots.
%\universality 
\openq What is the computational complexity of determining whether $f$ has a rational root in some given interval? 
\also Feasibility~\ourref{p:feasibility}.
%\tags 
\end{problemAO}

\begin{problemAO}{Polynomial Equivalence under Shifts}
\label{p:polyshifts}
\mindex{Polynomial Equivalence under Shifts (Open)|see {Polynomial(s)}}
\mindex{Polynomial(s)!Equivalence under Shifts (Open)}
\given Two polynomials $f,g:\R^n\to\R$ in $\Z[x_1,x_2,\ldots,x_n]$.
\question Is there a vector $b$ such that $f(x)=g(x+b)$?
\complexity In \ER.  
\comments This problem is discussed in Chillara, Grichener, and Shpilka~\cite{CGS23}, but the authors switch to a minimality version: given a polynomial $f$, is there a vector $b$ such that $f(x+b)$ has fewer monomials? For this version the authors show that over an integral domain which is not a field, the minimality version is as hard as the existential theory of the domain. Over $\Z$ this implies that the problem is undecidable, but the reduction does not apply to $\R$ (or $\Q$ or $\C$). 
%\universality 
%\openq 
\also Polynomial projection (linear)~\ourref{p:PolyProj}.    
%\tags 
\end{problemAO}

\begin{problemAO}{Semialgebraic Set with Isolated Point}
\label{p:semiisolated}
\mindex{Semialgebraic Set(s)!isolated point existence (Open)}
\given A semialgebraic set $S \subseteq \R^n$.
\question Does $S$ contain an isolated point; that is, is there an $x \in S$ such that $S$ contains no other points close to $x$?
\complexity In \EVR\ and known to be \VR-hard by B\"{u}rgisser, Cucker~\cite[Corollary 6.8, Corollary 9.4]{BC09}, but not known to be \EVR-complete.
\comments Testing whether a specific point belonging to $S$ is isolated, is \VR-complete, see the Isolated zero problem~\ourref[Polynomial(s)!Isolated Zero]{p:ISO}. 
%\universality 
%\openq 
\also Isolated point of semialgebraic set~\ourref{p:isopoint}, isolated zero~\ourref{p:ISO}. 
%\tags 
\end{problemAO}



\begin{problemAO}{Star-Shapedness of Semialgebraic Set}
\label{p:starshaped}
\mindex{Semialgebraic Set(s)!star-shapedness (Open)}
\given A semialgebraic set $S \subseteq \R^n$.
\question Is $S$ {\em star-shaped}? That is, is there a point in $S$ which can {\em see} all points in $S$ in the sense that the line segment connecting the points belongs to $S$?
\complexity In \EVR\ by definition.
\comments Suggested in Schaefer, \v{S}tefankovi\v{c}~\cite{SS23}.
%\universality 
%\openq 
\also Convexity of semialgebraic set~\ourref{p:convexity}. 
\end{problemAO}

\begin{problemAO}{Vapnik-\v{C}ervonenkis Dimension of Family of Semialgebraic Sets}
\label{p:semiVC}
\mindex{Semialgebraic Set(s)!Vapnik-\v{C}ervonenkis Dimension (Open)}
\given A family of semialgebraic sets ${\cal F} = \{\{x \in \R^n: \varphi(x,y)\}: y \in \R^m\}$, integer $k$.
\question Does ${\cal F}$ have Vapnik-\v{C}ervonenkis Dimension at least $k$, that is, are there $k$ points $P$ in $\R^n$ such that for every subset $P' \subseteq P$ of those points, there is an $S \in {\cal F}$ such that $P' = S \cap P$?
\complexity In \EVER; probably not complete for that class, since the universal quantifier is discrete, not real. 
\comments Suggested in Schaefer, \v{S}tefankovi\v{c}~\cite{SS23}. Over discrete sets this problem is complete for the third level of the polynomial-time hierarchy~\cite{S99}.
%\universality 
%\openq 
%\also 
\end{problemAO}


\begin{problemAO}{Gromov-Hausdorff Distance in Euclidean Space}
\label{p:Gromovdistance}
\mindex{Semialgebraic Set(s)!Gromov-Hausdorff Distance (Open)}
\given Two semialgebraic sets $A, B \subseteq \R^n$, $d \in \Q$. The {\em Hausdorff distance} of two sets $A$ and $B$ is $d_H(A,B) := \max(\sup_{a \in A} \inf_{b \in B} \norm{a-b}, \sup_{b \in B} \inf_{a \in A} \norm{a-b})$. The {\em Gromov-Hausdorff distance, $d_{GH}(A,B)$, of $A$ and $B$ in Euclidean space} is the infimum of $d_H(f(A),g(B))$ over all isometries (distance-preserving functions) $f,g$ from $\R^n$ to $\R^n$.
\question Do $A$ and $B$ have Gromov-Hausdorff distance at most $d$, that is,
is $d_{GH}(A,B) \leq d$? 
\complexity In \EVER\ by definition, and \VER-hardness follows from the \VER-hardness of the Hausdorff distance~\ourref[Semialgebraic Set(s)!Hausdorff distance]{p:Hausdorffdist}.
\comments The Gromov-Hausdorff distance has a more general definition than the one given here; the fact that for Euclidean spaces it is equivalent to the definition of $d_{GH}$ above, was shown by M{\'{e}}moli~\cite{M08}. To reduce the Hausdorff distance to the Gromov-Hausdorff distance, we can add a set of isolated points to the two sets that forces the isometries to be the identity.
%\universality 
%\openq 
\also Hausdorff distance~\ourref{p:Hausdorffdist}.
\end{problemAO}


\begin{problemAO}{Constrained Matrix Invertibility Problem}
\label{p:constmatinv}
\mindex{Matrix!Constrained Invertibility (Open)}
\given Two matrices $A,B \in \{0,*\}^{n \times n}$.
\question Can the $*$-entries in $A$ and $B$ be replaced by real entries so that $AB = I$, where $I$ is the $n$-dimensional identity matrix?
\complexity Over finite fields, the problem is known to be \NP-complete, by Bjerkevik, Botnan, and Kerber~\cite{BBK20}.
\comments This problem arises in the study of interleaving and stability of persistence modules~\cite{BBK20}, there may be further relevant open problems in that area.
%\universality 
%\openq 
\also Matrix singularity~\ourref{p:MatSing}, existential theory of invertible matrices~\ourref{p:ETInvMat}.
\end{problemAO}


\begin{problemAO}{Matrix $\ell^p$-Low Rank Approximation}
\label{p:lowrankapp}
\mindex{Matrix!$\ell^p$-Low Rank Approximation (Open)}
\given A matrix $A \in \Q^{m\times n}$, an integer $k \geq 0$, $\varepsilon \in \Q_{>0}$.
\question Is there a matrix $B \in \R^{m\times n}$ such that $\norm{A-B}_p < \varepsilon$ and $\operatorname{rank}(B) \leq k$? Here, $\norm{}_p$ denotes the {\em $\ell^p$-norm}, which is $(\sum_{i\in [m],j\in [n]} |A_{i,j}-B_{i,j}|^p)^{1/p}$ for $p \geq 1$, and $|\{(i,j) \in [m]\times [n]: A_{i,j} \neq B_{i,j}$ for $p = 0$.
\complexity In \ER, and known to be \NP-hard for $p \in \{0,1\}$ even for $k=1$~\cite{GV18}.
%\comments 
%\universality 
%\openq 
\also Maximum/minimum matrix rank~\ourref{p:minmaxmatrank}. 
\end{problemAO}

\begin{problemAO}{Hadamard Decomposition}
\label{p:Hadamard}
\mindex{Matrix!Hadamard Decomposition}
\given A matrix $M \in \Q^{m \times n}$, natural numbers $k_1, k_2 \in \N$. 
\question Are there matrices $M_1, M_2$ of rank $k_1$ and $k_2$ such that
$M = M_1 \odot M_2$, where $\odot$ is the component-wise product, known as the {\em Hadamard product}, of two matrices?
\complexity In \ER as observed by Ciaperoni, Gionis, and Mannila~\cite{CGM24} who asked the question. 
%\comments 
%\universality 
%\openq 
\also non-negative matrix factorization~\ourref{p:nonnegmatfac}.
\end{problemAO}


\begin{problemAO}{Tensor Eigenvector Approximation}
\label{p:tensoreigenapp}
\mindex{Tensor!Eigenvector approximation (Open)}
\given A $3$-dimensonal tensor $T = (t_{ijk}) \in \Q^{d\times d\times d}$, $\lambda \in \Q$, $\epsilon \in \Q_{>0}$.
\question Is there an $x \in \R^d$ within distance $\epsilon$ of an eigenvector $x'$ of $T$ for eigenvalue $\lambda$; that is, $\sum_{i,j} t_{i,j,k} x'_i x'_j = \lambda x'_k$, and $\norm{x-x'} < \epsilon$?
\complexity Known to be \NP-hard by Hillar, Lim~\cite{HL13} and in \ER\ by definition.  Is it \ER-complete?
%\comments 
%\universality 
%\openq 
\also Tensor with eigenvalue $0$~\ourref{p:tensorzero}, tensor rank~\ourref{p:tensorrank}.  
\end{problemAO}


\begin{problemAO}{Tensor Singular Value}
\label{p:tensorsingular}
\mindex{Tensor!Singular value (Open)}
\given A $3$-dimensional tensor $T = (t_{ijk}) \in \Q^{d\times d\times d}$, $\sigma \in \Q_{>0}$.
\question Is $\sigma$ a singular value of $T$? (See Hillar, Lim~\cite[Section 6]{HL13} for relevant definitions.)
\complexity Known to be \NP-hard even for $\sigma = 0$, by Hillar, Lim~\cite[Theorem 6.2]{HL13} and in \ER\ by definition.  Is it \ER-complete?
\comments It is also open whether testing if $\sigma$ is an upper bound on the spectral norm\index{Tensor!spectral norm} of $T$ is \ER-complete; it is known to be \NP-hard by Hillar, Lim~\cite[Theorem 1.10]{HL13}.
%\universality 
%\openq 
\also Tensor with eigenvalue $0$~\ourref{p:tensorzero}. 
\end{problemAO}

\begin{problemAO}{Zeroness of Convolution Recursive Sequence}
\label{p:zerconvolution}
\mindex{Sequence!Zeroness of Convolution Recursive Sequence (Open)}
\index{Zeroness of Convolution Recursive Sequence (Open)|see {Sequence}}
\given A convolution recursive sequence $f$. A sequence $f:\N\rightarrow \R$ is {\em convolution recursive} if there is a family $g = (g_1, \ldots, g_k): \R^k \rightarrow \R^k$ of polynomials $g_i \in \Q[x_1, \ldots, x_k]$ and $k$ sequences of real numbers $f_1 = f, f_2, \ldots, f_k$ such that $\sigma f_i = g_i(f_1, \ldots, f_k)$, where the polynomials $g_i$ are interpreted as follows: addition is addition of sequences and multiplication is convolution of sequences; the operator $\sigma$ shifts the sequence by one position. 
\question Is $f(n) = 0$ for all $n$?
\complexity This problem lies in \VR\ by Clemente~\cite{C20} who uses it to show that universality of an unambiguous context-free grammar~\ourref[Grammar!Universality of Unambiguous Context-Free Grammar (Open)]{p:universalunambig} lies in \VR. 
%\comments 
%\universality 
%\openq 
\also Universality of unambiguous context-free grammar~\ourref{p:universalunambig}, positivity of linear recurrence~\ourref{p:poslinrecur}.
\end{problemAO}



