\begin{problemCGO}{Colin de Verdi\`{e}re Invariant}
\label{p:ColindeVerdiere}
\mindex{Graph!Colin de Verdi\`{e}re invariant (Open)}
\index{Colin de Verdiere invariant open@Colin de Verdi\`{e}re invariant (Open)|see {Graph}}
\given A graph $G = (V,E)$ and a number $k\in \N$.
\question Is the Colin de Verdi\`{e}re invariant $\mu(G)$ at least $k$? For a definition see the comment section below.
\complexity Lies in \ER\ as shown by Kaluza and Tancer~\cite{KT19}.
\comments The graph parameter was introduced by Colin de Verdi\`{e}re~\cite[French]{de1990nouvel}
and is connected to well-studied graph classes. 
For example $\mu(G) \leq 2$ if and only if $G$ is an outerplanar graph and $\mu(G) \leq 3$ if and only if $G$ is a planar graph~\cite{van1999colin}.
The parameter $\mu(G)$ is the largest corank
of a symmetric matrix $M \in \R^{n\times n}$ such that
\begin{itemize}
    \item $ij\in E$ implies $M_{ij} <0$ and $M_{ij} =0$ otherwise;
    \item $M$ has exactly one negative eigenvalue, of multiplicity 1;
    \item There is a matrix $X$ such that $MX = 0$ and $X$ has only zero 
    entries on the diagonal and at the non-zero entries of $M$.
\end{itemize}
For fixed $k$ the invariant $\mu$ can be computed in polynomial-time, since it is minor-closed.
%\universality 
%\openq 
\also minimum graph rank~\ourref{p:mingraphrank}, minimium matrix rank~\ourref{p:minmaxmatrank}.
\end{problemCGO}

\begin{problemCGO}{Unit Disk Contact Graph}
\label{p:unitdiskcontact}
\mindex{Graph(s)!Unit Disk Contact Graph (Open)}
\given A graph $G$.
\question Is $G$ the {\em contact graph} of a collection of disjoint (open) unit disks in the plane, where two disks form a contact if they share exactly one point on their boundaries?
\complexity Known to be \NP-hard~\cite{BK96,KNP15} even if $G$ is outerplanar. 
%\Year
\comments Unit disk contact graphs are planar, and by Koebe's theorem all planar graphs are contact graphs of disks. There also is a weak version, which allows contacts between disks whose corresponding vertices are not adjacent; weak unit disk contact graphs thus are the subgraphs of unit disk contact graphs. 
%\universality 
%\openq 
\also Ply number~\ourref{p:plynumb}, kissing number~\ourref{p:kissingnumb}.  
\end{problemCGO}

\begin{problemCGO}{Ply Number}
\label{p:plynumb}
\mindex{Graph(s)!Ply number (Open)}
\given A graph $G$, an integer $k \geq 0$.
\question Is there a straight-line drawing of $G$ with the following property: If at each vertex we draw an open disk with radius half the length of the longest edge incident to the vertex, then no more than $k$ disks intersect at any point in the plane? The smallest such $k$ is the {\em ply number} of $G$.
\complexity The problem is \NP-hard, since having ply number at most $1$ is equivalent to being a unit disk contact graph~\ourref[Disk Graph!Unit Disk Contact Graph (Open)]{p:unitdiskcontact}, see~\cite{DGDHKKLMSY15}, and that problem is \NP-hard~\cite{KNP15}.
%\Year
\comments The ply number of a graph was introduced as a new metric for measuring the quality of graph drawings in~\cite{DGDHKKLMSY15}.
%\universality 
%\openq 
\also Unit distance graphs~\ourref{p:unitdist}, unit disk contact graphs~\ourref{p:unitdiskcontact}. 
\end{problemCGO}

\begin{problemCGO}{Free Space Diagram Realizability}
\label{p:freespacediag}
\mindex{Free Space Diagram Realizability (Open)}
\given A {\em free space diagram}, that is, a rectangle $[0,\ell_1]\times [0,\ell_2]$ in $\R^2$ which is subdivided into a grid of rectangular cells; each cell may be associated with an ellipse (which is cropped to the area of the cell), and a parameter $\varepsilon \in \Q_{\geq 0}$. 
\question Are there two polygonal curves $P_1,P_2$ of length $\ell_1$ and $\ell_2$ such that the union of the croppsed ellipses in the free space diagram corresponds to $\{(x,y): \norm{P_1(x)-P_2(y)}_2 \leq \varepsilon\}$? Here, $P(z)$ denotes the parameterization of polygon $P$ by length.
\complexity In \ER.
\comments The paper~\cite{ABMRW23} shows that planar linkage realizability~\ourref[Linkage!Linkage Realizability]{p:linkagereal} reduces to free space diagram realizability, but an earlier claim that planar linkage realizability is \ER-complete may have been erroneous, leaving the complexity of the free space diagram realizability problem in limbo as well.
%\universality 
%\openq 
\also Free space matrix realizability~\ourref{p:freespacemat}, linkage realizability~\ourref{p:linkagereal}, Fr\'{e}chet distance of surfaces~\ourref{p:frechetdist}.
\end{problemCGO}

