\begin{problemCGO}{Convex Neural Codes}
\label{p:convneuralcode}
\mindex{Convex Neural Codes|see {Convex Set(s)}}
\mindex{Convex Set(s)!Neural Codes}
\given A \emph{combinatorial neural code} $\mathcal{C}$: a set of subsets of $[n]$.
\question Does there exist a collection of convex sets $X_1,X_2,\ldots ,X_n$ in $R^d$, for some fixed constant $d\geq 2$, 
such that $\mathcal{C} = \{ I(x) : x\in\R^d \}$, where $I(x)=\{i\in [n] : x\in X_i\}$ is the \emph{intersection pattern} of $x$?
\complexity \ER-hard even for $d=2$, from~\cite{KLR23}, and decidable if $d=2$, from~\cite{BJ23}. 
