\begin{problemCGO}{Representing Graph with Orthogonal Vectors in $\R^3$}
\label{p:graphorthogonalvectorsR3}
\mindex{Graph(s)!Representing Graph with Orthogonal Vectors in $\R^3$ (Open)}
\index{Graph(s)!Representing Graph with Orthogonal Vectors in $\R^3$ (Open)|see {Graph(s)}}
\given A graph $G$ on $n$ vertices.
\question Can we assign $n$ distinct vectors in $\R^3$ to the vertices in $G$ so that any two vectors belonging to adjacent vertices are orthogonal to each other? (No restrictions on non-adjacent vertices.)  
\complexity Arends, Ouaknine, Jo\"{e}l and Wampler~\cite{AOW11} show that the problem lies in \ER. 
\comments Arends, Ouaknine, Jo\"{e}l and Wampler name this problem the ``embeddability problem''. They arrive at it in their search for small Kochen-Specker vector systems, which play a role in quantum computing. They consider additional restrictions on $G$ which are natural in this context, but which are all of an \NP\ nature, so the problem, as presented here seems to capture the computational core of the problem. 
%\openq 
\also Dot-product graph~\ourref{p:dotprodgraph},  unit ball graph~\ourref{p:unitballgraph}. 

\end{problemCGO}


\begin{problemCGO}{Graph Flattenability}
\label{p:graphflatten}
\mindex{Graph(s)!Flattenability (Open)}
\index{Flattenability|see {Graph(s)}}
\given A graph $G$, integer $d \geq 0$.
\question For every straight-line embedding of $G$ in $\R^{d'}$, with arbitrary $d' \geq d$, is there a straight-line embedding in $\R^d$ with the same distances between all pairs of vertices?
\complexity The problem lies in \VER~\cite{BC07} (the authors observe that it is equivalent to testing the equality of two semialgebraic sets\index{Semialgebraic Set(s)!equality}). For fixed $d$, graph flattenability is minor-closed and can therefore be solved in polynomial time; for hardness results it will therefore be essential that $d$ is part of the input. Lists of excluded minors are known for $d\leq 3$~\cite{BC07}.
\comments The problem was introduced under the name $d$-realizability by Belk and Connelly~\cite{BC07}, but it had been studied earlier. 
\openq Is the problem \NP- or \coNP-hard? 
\also Graph realizability~\ourref{p:graphreal}, area universality~\ourref{p:areauniversal}, unit distance graph~\ourref{p:unitdist}. 
\end{problemCGO}

\begin{problemCGO}{Faithful Drawability of Edge-Colored Graph}
\label{p:faithfullcolor}
\mindex{Graph(s)!Faithful Drawability of Edge-Colored Graph (Open)}
\index{Graph(s)!Faithful Drawability of Edge-Colored Graph (Open)|see {Graph(s)}}
\given A graph $G$ and a proper edge-coloring of $G$, that is, any two adjacent edges differ in color.
\question Is there a {\em faithful} drawing of $G$, that is, a drawing of $G$ in which all edges of the same color lie on concurrent lines, and no two edges lie on the same line?
\complexity In \ER, but otherwise open even for $4$-regular graphs.
\comments Richter shows that faithful drawability can be recognized in polynomial time for cubic graphs and conjectures that the problem is \ER-complete for $4$=regular graphs~\cite[Conjecture 9]{R11}. By moving the common points of the bundles of concurrent lines to infinity, we obtain a drawing in which all edges of the same color are parallel; this seems to suggest a connection to the planar slope number~\ourref[Graph(s)!Planar Slope Number]{p:planarslopenumb}.
%\universality 
%\openq 
\also Planar slope number~\ourref{p:planarslopenumb}.
\end{problemCGO}


