\label{p:hypercube}
%hypercube problem~\ourref[Pointset!Hypercube Problem (Open)]{p:hypercube}
%hypercube problem~\ourref{p:hypercube}
\mindex{Pointset!Hypercube Problem (Open)}
\index{Hypercube Problem (Open)|see {Pointset}}
\given Finite set of points $P \subseteq [0,1]^d$, a natural number $k\in \N$.
\question Is there a pointset $Q\subseteq [0,1]^d$  of
size $k$ such that $P \subset \conv(Q)$, where $\conv(Q)$ is the convex hull of $Q$?
\complexity The hypercube problem is \NP-hard via a reduction from 3SAT, and lies in \ER as shown by Kiefer and Wacther~\cite{KW14}. Kiefer and Wachter also observe that for fixed $d$, the problem lies in \P. 
\comments The problem remains \NP-hard if $P$ is required to contain the origin, the {\em restricted hypercube problem}. Kiefer and Wachter introduced this problem to isolate the geometric difficulty at the root of the
probabilitic automaton minimisation problem~\ourref[Automata!Probabilistic Automaton Minimisation]{p:probautomin}.
The hypercube problem is reminiscent of the nested polytope problem~\ourref[Polytope(s)!Nested Polytopes]{p:nestpolytopes} as defined by~\cite{DHM19}.
%\universality 
\openq Kiefer and Wachter~\cite{KW14} observe that for $d = 2$ the set $Q$ can always be assumed to be rational, and ask whether this remains true for higher dimensions.
\also Probabilitic automaton minimisation~\ourref{p:probautomin}, nested polytope problem~\ourref{p:nestpolytopes}.
%\tags 
\end{problemCGO}


\begin{problemCGO}{$k$-Median of Polygonal Curves}
\label{p:mediancurve}
%$k$-median of polygonal curves~\ourref[Median of Polygonal Curves (Open)@$k$-Median of Polygonal Curves (Open)]{p:mediancurve}
%$k$-median of polygonal curves~\ourref{p:mediancurve}
\mindex{Median of Polygonal Curves (Open)@$k$-Median of Polygonal Curves (Open)}
\given A family of polygonal curves $P_1, \ldots, P_n$ in $\R^d$, all of the same length, $c \in \Q$.
\question Is there a polygonal curve $P$ of length $k$ such that $\sum_{i \in [n]} d_F(P, P_i) \leq c$? Here, $d_F$ denotes the Fr\'{e}chet distance, see references for a definition.
\complexity In \ER, as shown by Rohde~\cite{R22}, and \NP-hard by Buchin, Driemel, and Struijs~\cite{BDS20}.
\comments The Fr\'{e}chet distance between two polygonal curves can be computed efficiently~\cite{AG95}.
%\universality 
%\openq 
\also Fr\'{e}chet distance of surfaces~\ourref{p:frechetdist}.
%\tags 
\end{problemCGO}


\begin{problemCGO}{Fr\'{e}chet Distance of Surfaces}
\label{p:frechetdist}
%Fr\'{e}chet distance of surfaces~\ourref[Fr\'{e}chet Distance of Surfaces (Open)]{p:frechetdist}
%Fr\'{e}chet distance of surfaces~\ourref{p:frechetdist}
\mindex{Fr\'{e}chet Distance of Surfaces (Open)}
\given Two homeomorphic surfaces $R$ and $S$ together with immersions $\varphi_R: R \rightarrow \R^3$, and $\varphi_S: S \Rightarrow \R^3$, $\delta \in \Q_{\geq 0}$.
\question Is the Fr\'{e}chet distance $\delta_F(R,S) \leq \delta$? Here $\delta_F(R,S)$ is the infimum over all homeomorphisms $f: R\rightarrow S$ of $\sup_{x \in R} \norm{\varphi_R(x) - \varphi_S(f(x))}_2$.
\complexity One has to assume that $R$, $S$, $\varphi_R$ and $\varphi_S$ have reasonable effective representations for this problem to fall into the domain of \ER. There are various relevant results, e.g.\ Godau's proof that the problem is \NP-hard~\cite{G99}, and Nayyeri and Xu's result that the problem lies in \ER\ if one of the surfaces is a triangle~\cite{NX18}.
%\comments 
%\universality 
%\openq 
\also Hausdorff distance~\ourref{p:Hausdorffdist}, $k$-Median of Polygonal Curves~\ourref{p:mediancurve}. 
%\tags 
\end{problemCGO}



\begin{problemCGO}{Compatible Triangulations of Polygons with Holes}
\label{p:comptriagpolygon}
%compatible triangulations of polygons with holes~\ourref[Polygon!Compatible Triangulations of Polygons with Holes (Open)]{p:comptriagpolygon}
%compatible triangulations of polygons with holes~\ourref{p:comptriagpolygon}
\mindex{Polygon!Compatible Triangulations of Polygons with Holes (Open)}
\index{Compatible Triangulations of Polygons with Holes (Open)|see {Polygon}}
\given Two vertex-labeled polygons $P$ and $Q$ with holes, an integer $k \geq 0$.
\question Can $P$ and $Q$ be extended to vertex-labeled triangulations which are compatible by adding at most $k$ points? Here two triangulations are {\em compatible} if they have the same rotation system, that is, the cyclic permutations of neighbors at each vertex is the same for both triangulations. 
\complexity In \ER\ and \NP-hard, as shown by Lubiw and Mondal~\cite{LM20}, who also ask whether the problem is \ER-hard.
\comments The additional points are known as {\em Steiner points}; the given polygons have to be compatible to start with for the problem to be solvable.
%\universality 
\openq Lubiw and Mondal~\cite{LM20} ask whether the problem remains \NP-hard for simple polygons (no holes). 
%\also 
%\tags 
\end{problemCGO}


\begin{problemCGO}{Convexity Through Translation}
\label{p:convtrans}
%convexity through translation~\ourref[Pointset!Convexity Through Translation (Open)]{p:convtrans}
%convexity through translation~\ourref{p:convtrans}
\mindex{Pointset!Convexity Through Translation (Open)}
\given A family of point sets in $\Q^2$.
\question Can the point sets be translated so that the resulting points are in convex position, that is, lie on the convex hull of the union of the translated point sets? 
\complexity In \ER\ and \NP-hard, as shown by Hoffmann, Kusters, Rote, Saumell, and Silveira~\cite{HKRSS13}.
%\Year
\comments If the point sets can be scaled as well as translated, the problem is not even known to be \NP-hard~\cite{HKRSS13}.
%\universality 
%\openq 
\also Convexity of semialgebraic set~\ourref{p:convexity}.
%\tags 
\end{problemCGO}


\begin{problemCGO}{Prescribed Area}
\label{p:prearea}
%prescribed area~\ourref[Graph(s)!Prescribed Area Extension (Open)]{p:prearea}
%prescribed area~\ourref{p:prearea}
\mindex{Graph(s)!Prescribed Area (Open)}
\index{Prescribed Area (Open)|see {Graph(s)}}
\given A plane graph $G$, an area assignment for $G$, where an {\em area assignment} for $G$ assigns a positive real number to every face of $G$. 
\question Does $G$ have a straight-line drawing realizing the area assignment, that is, each face having the area prescribed by the area assignment? 
\complexity In \ER. If some of the vertex locations can be fixed, the problem is \ER-complete, as shown by Dobbins, Kleist, Miltzow and Rz\polhk a\.{z}ewski~\cite{DKMR23}.
\comments Dobbins, Kleist, Miltzow and Rz\polhk a\.{z}ewski~\cite{DKMR23} conjecture that this problem is \ER-complete. 
%\universality 
%\openq 
\also Prescribed area extension~\ourref{p:preareaext}, area universality~\ourref{p:areauniversal}, area universality for triples with partial area assignment~\ourref{p:areauniversaltriples}.  
%\tags 
\end{problemCGO}


\begin{problemCGO}{Area Universality}
\label{p:areauniversal}
%area universality~\ourref[Graph(s)!Area Universality (Open)]{p:areauniversal}
%area universality~\ourref{p:areauniversal}
\mindex{Graph(s)!Area Universality (Open)}
\index{Area Universality (Open)|see {Graph(s)}}
\given A plane graph $G$.
\question An {\em area assignment} for $G$ assigns a positive real number to every face of $G$. Can every area assignment be realized by a straight-line embedding of $G$? In that realization, every face must have the area assigned to it. 
\complexity Dobbins,  Kleist, and Miltzow show that the problem lies in \VER\ and conjecture that it is \VER-complete. They can show that a more restricted version, area universality for triples with partial area assignments~\ourref[Graph(s)!Area Universality (Open)]{p:areauniversaltriples}, is \VER-complete. 
%\comments  
%\universality 
%\openq 
\also Area Universality for triples with partial area assignments~\ourref{p:areauniversaltriples}, prescribed area~\ourref{p:prearea}.
%\tags 
\end{problemCGO}


\begin{problemCGO}{Segment Visibility Graph}
\label{p:segvisibilitygraph}
%segment visibility graph~\ourref[Visibility Graph!Segment Visibility Graph (Open)]{p:segvisibilitygraph}
%segment visibility graph~\ourref{p:segvisibilitygraph}
\mindex{Visibility Graph!Segment Visibility Graph (Open)}
\index{Segment Visibility Graph (Open)|see {Visibility Graph}}
\index{Graph(s)!Visibility Graph|see {Visibility Graph}}
\given A graph $G$.
\question Is $G$ the visibility graph of a set of segments in the plane? The visibility graph of a set of segments represents each segment by a vertex, and there is an edge between two vertices if the corresponding segments can see each other, that is, if there is a line-segment connecting the two segments that does not intersect any other segment. 
\complexity In \ER. 
\comments There is also the endpoint segment visibility graph\index{Graph(s)!Endpoint Segment Visibility Graph (Open)}, which is the visibility graph of the endpoints of the segments, but the full segments are still the visibility obstacles.  
%\openq  
\also Point visibility graph~\ourref{p:visibilitygraph}, visibility graph of polygon with holes~\ourref{p:polygonholesvisibility},
internal/external polygon visibility graph~\ourref{p:intextvisibility}, obstacle number~\ourref{p:obstaclenumb}.
%\tags graph drawing, visibility 
\end{problemCGO}


\begin{problemCGO}{Obstacle Number}
\label{p:obstaclenumb}
%obstacle number~\ourref[Graph(s)!Obstacle Number (Open)]{p:obstaclenumb}
%obstacle number~\ourref{p:obstaclenumb}
\mindex{Graph(s)!Obstacle Number (Open)}
\given A graph $G$, an integer $k \geq 0$.
\question Is $G$ the visibility graph of a set of points (in general position) in the plane with at most $k$ polygonal obstacles? Here two points can {\em see} each other if the straight-line segment connecting them does not intersect any obstacles. 
\complexity In \ER. This problem is not known to be \NP-hard, though various variants and restrictions of it are, see the summary in~\cite{GdMV18}, and~\cite{BCGGHVW24}, which shows that the problem is \NP-hard for a single, fixed obstacle.
\comments Obstacle numbers were introduced by Alpert, Koch and Liason~\cite{AKL10}. There also is a variant known as the {\em planar obstacle number} in which the visibility segments may not cross each other~\cite{GdMV18}.  
%by Gimbel, de Mendoza and Valtr~\cite{GdMV18}.
%\openq  
\also (Point) visibility graph~\ourref{p:visibilitygraph}, segment visibility graph~\ourref{p:segvisibilitygraph}.  
%\tags graph drawing, visibility 
\end{problemCGO}

\begin{problemCGO}{Fiber Dimension}
\label{p:fiberdim}
%fiber dimension~\ourref[Graph(s)!Fiber Dimension (Open)]{p:fiberdim}
%fiber dimension~\ourref{p:fiberdim}
\mindex{Graph(s)!Fiber Dimension (Open)}
\index{Fiber Dimension (Open)|see {Graph(s)}}
\given A graph $G$, a natural number $d\in \N$. 
\question Does $G$ have fiber dimension at most $d$? That is, is there a polytope $P \subseteq \Q^d$ and a symmetric set $M \subseteq \Z^d$ such that $G$ is isomorphic to the graph on $V = P \cap \Z^d$ with an edge $uv$ if and only if $u-v \in M$.
\complexity We are not aware of any computational complexity results.
\comments The fiber dimension of a graph was defined by Windisch~\cite{W19}. Every graph has finite fiber dimension.
%\universality 
%\openq 
%\also 
%\tags 
\end{problemCGO}

\begin{problemCGO}{Treetope graph}
\label{p:treetopegraph}
\mindex{Graph(s)!Treetope graph (Open)}
\index{Treetope graph (Open)|see {Graph(s)}}
\given A graph $G$, an integer $k \geq 0$.
\question Is there a $k$-treetope polytope $P$ with $1$-skeleton $G$? A {\em $k$-treetope}
is a $k$-dimensional polytope with a special base facet $F$ that intersects every face of dimension at least two in at least two points. 
\complexity In dimension four Eppstein showed that the question is polynomial time solvable~\cite{E20}.
The complexity of this problem is open for dimension five and above.
\comments Eppstein states: ``\textit{Recognizing the graphs of pyramids over arbitrary 4-polytopes, and therefore also
recognizing the graphs of 5-treetopes, is as difficult as recognizing the graphs of
arbitrary 4-polytopes, which we expect to be complete for the existential theory of the
reals}~\cite{E20}.''
%\universality 
%\openq 
\also Polytope. 
% \tags 
\end{problemCGO}


