\title{Rejection-Sampled Linear Codes for Lossy Compression and Channel Simulation}
\author{Cheuk Ting Li and Jianguo Zhao \\
Department of Information Engineering, The Chinese University of Hong Kong, Hong Kong, China\\
Email: ctli@ie.cuhk.edu.hk, zhaojg@link.cuhk.edu.hk}
