\subsection{Proof of Lemma \ref{lem:gen_grs}\label{subsec:pf_gen_grs}}

Let $S_{L}(i):=\mathbb{P}(L\ge i)$, $S_{L|Y}(i|y):=\mathbb{P}(L\ge i|Y=y)$. By (\ref{eq:gen_grs_ineq}) and Bayes' rule,
\begin{align*}
 & \mathbb{P}(L=i)\\
 & \ge\theta S_{L}(i)\int_{\mathcal{Y}}\min\left\{ \frac{\mathrm{d}P_{Y|L\ge i}}{\mathrm{d}Q}(y),\,1\right\} Q(\mathrm{d}y)\\
 & =\theta\int_{\mathcal{Y}}\min\left\{ \frac{S_{L|Y}(i|y)}{S_{L}(i)}\frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y),\,1\right\} S_{L}(i)Q(\mathrm{d}y)\\
 & \ge\theta\int_{\mathcal{Y}}\min\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y),\,1\right\} S_{L}(i)S_{L|Y}(i|y)Q(\mathrm{d}y).
\end{align*}
Hence,
\begin{align*}
 & 1=\sum_{i=1}^{\infty}\mathbb{P}(L=i)\\
 & \ge\theta\sum_{i=1}^{\infty}\int_{\mathcal{Y}}\min\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y),\,1\right\} S_{L}(i)S_{L|Y}(i|y)Q(\mathrm{d}y)\\
 & \ge\theta\int_{\mathcal{Y}}\min\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y),\,1\right\} \\
 & \;\;\cdot\left(\sum_{i=1}^{\infty}\left(iS_{L}(i)-(i-1)S_{L}(i-1)\right)S_{L|Y}(i|y)\right)Q(\mathrm{d}y)\\
 & \ge\theta\int_{\mathcal{Y}}\min\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y),\,1\right\} \mathbb{E}\left[LS_{L}(L)\,\big|\,Y=y\right]Q(\mathrm{d}y)\\
 & =\theta\int_{\mathcal{Y}}\min\left\{ \bigg(\frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y)\bigg)^{-1},1\right\} \mathbb{E}\left[LS_{L}(L)\big|Y=y\right]P_{Y}(\mathrm{d}y)\\
 & =\theta\mathbb{E}\left[\min\left\{ \bigg(\frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y)\bigg)^{-1},\,1\right\} LS_{L}(L)\right]\\
 & =:\theta c.
\end{align*}
Define a probability measure $\tilde{Q}\ll P_{Y,L}$ over $\mathcal{Y}\times\mathbb{N}$, with
\[
\frac{\mathrm{d}\tilde{Q}}{\mathrm{d}P_{Y,L}}(y,i)=\frac{1}{c}\min\left\{ \bigg(\frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(y)\bigg)^{-1},1\right\} iS_{L}(i).
\]
Note that we also have $P_{Y,L}\ll\tilde{Q}$ since the above is positive $P_{Y,L}$-almost everywhere as $P_{Y}\ll Q$. Since $(Y,L)\sim P_{Y,L}$ and $c\le1/\theta$,
\begin{align*}
0 & \le D_{\mathrm{KL}}(P_{Y,L}\Vert\tilde{Q})\\
 & =\mathbb{E}\left[\log\frac{\mathrm{d}P_{Y,L}}{\mathrm{d}\tilde{Q}}(Y,L)\right]\\
 & \le\mathbb{E}\left[\log\max\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(Y),1\right\} \right]-\mathbb{E}[\log(\theta LS_{L}(L))].
\end{align*}
By \cite[proof of Claim IV.2]{harsha2010communication} (also see \cite[proof of Theorem 7]{li2024channel}), we have $\mathbb{E}[-\log S_{L}(L)]\le\log e$ for every random variable $L\in\mathbb{N}$. Also, by \cite[Appendix A]{harsha2007communication},
\[
\mathbb{E}\left[\log\max\left\{ \frac{\mathrm{d}P_{Y}}{\mathrm{d}Q}(Y),1\right\} \right]\le D_{\mathrm{KL}}(P_{Y}\Vert Q)+e^{-1}\log e.
\]
The result follows.

\subsection{Proof of Theorem \ref{thm:GRSSE_bound}\label{subsec:pf_GRSSE_bound}}

Let
\[
\mathbf{z}^{*}(\mathbf{s}):=\mathrm{argmin}_{\mathbf{z}\in\mathbb{F}_{q}^{n}:\,\mathbf{z}\mathbf{H}^{\top}=\mathbf{s}}\;\mathrm{wt}(\mathbf{z})
\]
be the coset leader.  Fix any $0\le\beta\le1$. Define a conditional distribution $\tilde{\kappa}(\mathbf{z}|\mathbf{s})$ for $\mathbf{z}\in\mathbb{F}_{q}^{n}$, $\mathbf{s}\in\mathbb{F}_{q}^{n-k}$ with 
\[
\tilde{\kappa}(\mathbf{z}|\mathbf{s})=\beta\mathbf{1}\{\mathbf{z}=\mathbf{z}^{*}(\mathbf{s})\}+(1-\beta)q^{-k}\mathbf{1}\{\mathbf{z}\mathbf{H}^{\top}=\mathbf{s}\},
\]
i.e., given the syndrome $\mathbf{s}$, we select the coset leader $\mathbf{z}^{*}(\mathbf{s})$ with probability $\beta$, or select an arbitrary $\mathbf{z}$ in the coset with probability $1-\beta$. Although $\tilde{\kappa}$ may not satisfy the constraint in (\ref{eq:grsse_argmin}), we can modify it to 
\[
\hat{\kappa}_{i}(\mathbf{z}|\mathbf{s})=\tilde{\kappa}(\mathbf{z}|\mathbf{s})\min\left\{ \frac{p_{\mathbf{Z}}^{(i)}(\mathbf{z})}{\mathbb{E}[\tilde{\kappa}(\mathbf{z}\boldsymbol{\Pi}_{i}\,|\,\mathbf{S}_{i})]},\,1\right\} ,
\]
$\hat{\kappa}_{i}(\mathrm{e}|\mathbf{s})=1-\sum_{\mathbf{z}}\hat{\kappa}_{i}(\mathbf{z}|\mathbf{s})$, which ensures that the constraint in (\ref{eq:grsse_argmin}) is satisfied. If GRSSE selects $\hat{\kappa}_{i}$, the proability of acceptance at iteration $i$ is
\begin{align*}
 & 1-\mathbb{E}[\hat{\kappa}_{i}(\mathrm{e}\,|\,\mathbf{S}_{i})]\\
 & =\mathbb{E}\bigg[\sum_{\mathbf{z}\in\mathbb{F}_{q}^{n}}\hat{\kappa}_{i}(\mathbf{z}\boldsymbol{\Pi}_{i}|\mathbf{S}_{i})\bigg]\\
 & =\mathbb{E}\bigg[\sum_{\mathbf{z}}\tilde{\kappa}(\mathbf{z}\boldsymbol{\Pi}_{i}|\mathbf{S}_{i})\min\bigg\{\frac{p_{\mathbf{Z}}^{(i)}(\mathbf{z})}{\mathbb{E}[\tilde{\kappa}(\mathbf{z}\boldsymbol{\Pi}_{i}\,|\,\mathbf{S}_{i})]},\,1\bigg\}\bigg]\\
 & =\sum_{\mathbf{z}}\min\left\{ p_{\mathbf{Z}}^{(i)}(\mathbf{z}),\,\mathbb{E}[\tilde{\kappa}(\mathbf{z}\boldsymbol{\Pi}_{i}\,|\,\mathbf{S}_{i})]\right\} \\
 & =\sum_{\mathbf{z}}\min\left\{ p_{\mathbf{Z}}^{(i)}(\mathbf{z}),\,\beta\mathbb{P}(\mathbf{z}\boldsymbol{\Pi}_{i}=\mathbf{z}^{*}(\mathbf{S}_{i}))+(1-\beta)q^{-n}\right\} \\
 & =:\sum_{\mathbf{z}}\min\left\{ p_{\mathbf{Z}}^{(i)}(\mathbf{z}),\,Q(\mathbf{z})\right\} .
\end{align*}
Since GRSSE selects the $\kappa_{i}$ with the maximum probability of acceptance, $\kappa_{i}$ is at least as good as the above. Hence, applying Lemma \ref{lem:gen_grs} on $(\mathbf{Z},L)$, $Q(\mathbf{z})$ and $\theta=1$ gives
\begin{align*}
 & \mathbb{E}\left[\log L\right]-\eta\\
 & \le D_{\mathrm{KL}}(p_{\mathbf{Z}}\Vert Q)\\
 & =-\mathbb{E}\left[\log Q(\mathbf{Z})\right]-H(\mathbf{Z})\\
 & =-\mathbb{E}\left[\log\left(\beta\mathbb{P}(\mathbf{Z}\boldsymbol{\Pi}_{i}=\mathbf{z}^{*}(\mathbf{S}_{i}))+(1-\beta)q^{-n}\right)\right]-H(\mathbf{Z})\\
 & \stackrel{(a)}{\le}-\mathbb{E}\!\left[\log\!\left(\!\beta\mathbf{1}\Big\{\mathrm{wt}(\mathbf{Z})\!<\!\frac{d}{2}\Big\} q^{k-n}+(1\!-\!\beta)q^{-n}\!\right)\!\right]-H(\mathbf{Z})\\
 & =\log\frac{1}{(1-\beta)q^{-n}}\\
 & \;\;\;+\mathbb{P}(\mathrm{wt}(\mathbf{Z})<d/2)\log\frac{(1-\beta)q^{-n}}{\beta q^{-(n-k)}+(1-\beta)q^{-n}}-H(\mathbf{Z})\\
 & \le\log q^{n}-H(\mathbf{Z})+\log\frac{1}{1-\beta}\\
 & \;\;\;+\mathbb{P}(\mathrm{wt}(\mathbf{Z})<d/2)\log\frac{(1-\beta)q^{-n}}{\beta q^{-(n-k)}}\\
 & =C-\mathbb{P}(\mathrm{wt}(\mathbf{Z})<d/2)\bigg(k\log q+\log\frac{\beta}{1-\beta}\bigg)+\log\frac{1}{1-\beta},
\end{align*}
where (a) is because if $\mathrm{wt}(\mathbf{z})<d/2$, then $\mathbf{z}\boldsymbol{\Pi}_{i}$ is the coset leader for one out of $q^{n-k}$ cosets. Therefore, we obtain (\ref{eq:grsse_logl}) by taking $\beta=1/2$. To obtain (\ref{eq:grsse_comm}), applying the inequality $H(L)\le\mathbb{E}[\log L]+\log(\mathbb{E}[\log L]+1)+1$ in \cite{sfrl_trans}, if we apply Huffman coding on $L$, the expected encoding length of $(L,\mathbf{M})$ is at most
\begin{align*}
 & H(L)+\log|\mathbb{F}_{q}^{k}|+1\\
 & \le C-\mathbb{P}(\mathrm{wt}(\mathbf{Z})<d/2)k\log q+\eta+3\\
 & \;\;+\log\left(C-\mathbb{P}(\mathrm{wt}(\mathbf{Z})<d/2)k\log q+\eta+2\right)+k\log q,
\end{align*}
which is the desired result.

