\>[15]{}(\Con{bin}\;(\Con{tip_s}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 cd\char34}\,\textbf\}_{\kern1pt\textbf{0}}})\;(\Con{bin}\;(\Con{tip_s}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 bd\char34}\,\textbf\}_{\kern1pt\textbf{1}}})\;(\Con{tip_z}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 bc\char34}\,\textbf\}_{\kern1pt\textbf{2}}})))\;{}\<[E]%
\\
\>[15]{}(\Con{bin}\;(\Con{bin}\;(\Con{tip_s}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 ad\char34}\,\textbf\}_{\kern1pt\textbf{3}}})\;(\Con{tip_z}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 ac\char34}\,\textbf\}_{\kern1pt\textbf{4}}}))\;(\Con{tip_z}\;\highlight{goal}{\textbf\{\,\Var p\;\text{\ttfamily \char34 ab\char34}\,\textbf\}_{\kern1pt\textbf{5}}})){}\<[E]%
