\\
\>[B]{}\Conid{ℕ-Induction-unary-parametricity}\;\Var f\;\mathrel{=}\;{}\<[E]%
\\
\>[B]{}\hsindent{3}{}\<[3]%
\>[3]{}\{\mskip1.5mu \Var p\;{}\<[8]%
\>[8]{}\mathbin{:}\;\Conid{ℕ}\;\Varid{→}\;\Conid{Set}\mskip1.5mu\}\;{}\<[36]%
