\>[41]{}\mathbin{:}\;\Varid{∀}\;\{\mskip1.5mu \Var m\mskip1.5mu\}\;\Varid{→}\;\Var p\;\Var m\;\Varid{→}\;\Conid{Set})\;{}\<[E]%
\\
\>[B]{}\hsindent{3}{}\<[3]%
