Each derivation in a context free-grammar may be associated with a tree, called a parse-tree, in the natural way (see Figure~\ref{fig:ambiguous}). We say that a {\CFG} is \emph{unambiguous} if every $w \in L(G)$ has a unique parse tree; equivalently this means that every word in $L(G)$ has a unique derivation in $G$. We call such a grammar a {\uCFG}. 

%

\begin{example}
    The grammar from Example~\ref{ex: ambig} is not unambiguous; see Figure~\ref{fig:ambiguous} for two different parse trees of the same word. So let us construct an unambiguous grammar for $L_n$.

    In a first step, it will be useful to generate all possible words of a given length $i$. To this end, we introduce non-terminals $C_1, \ldots, C_n$ and rules 
    \begin{align*}
        C_i &\to a C_{i-1} \mid b C_{i-1}& \text{ for } i \in [n], i>1 \\
        C_1 &\to a \mid b.
    \end{align*}
    Clearly, any derivation from any $C_i$ is unambiguous. Next, for every word $w\in \Sigma^{\le n}$, we introduce a non-terminal $A_w$ and a rule
    \begin{align*}
        A_w &\to w.
    \end{align*}
    One way to enforce unambiguity for $L_n$ is to ensure that 
    each derivation of a word $w$ in $L_n$ determines the first pair of positions containing $a$ at distance $n$ in $w$. To this end, we introduce for every $i\in [n]$ a way to generate words $u$ such that $i$ is the smallest integer for which the letters at position $i$ and $i+n$ in $u$ are both $a$. For every $i<n$, we thus introduce a non-terminal $A_i$ and for every $w\in \Sigma^{i-1}$ the rule
    \begin{align*}
        A_i &\to A_w a C_{n-i} A_{\bar{w}}a C_{n-i}, 
    \end{align*}
    where $\bar{w}$ is the word we get from $w$ by complementing all its letters, i.e., by flipping all occurrences of $a$ to $b$ and vice-versa. For $i=n$, we introduce $A_n$ and the rules
    \begin{align}\label{eq:uCFGexample}
        A_n &\to A_w a A_{\bar w} a
    \end{align} 
    for all $w\in \Sigma^{n-1}$.
    Clearly, all derivations from any $A_i$ are unambiguous. It only remains to add a starting symbol $S$ and the rules
    \begin{align*}
        S &\to A_1 \mid \ldots \mid A_n.
    \end{align*}
    Note that the grammar we have just constructed accepts $L_n$ but it has exponential size in $n$; in particular, there are exponentially many rules in (\ref{eq:uCFGexample}). So the unambiguous grammar here is of double exponential size with respect to the ambiguous one from Example~\ref{ex: ambig}. Our main result will show that this is unavoidable because every grammar for $L_n$ has exponential size in $n$.
\end{example}

We say that a {\CFG} is in \emph{Chomsky normal form} if all rules are of the form $A\rightarrow BC$ or $A\rightarrow a$ where $A,B,C$ are non-terminals and $a$ is a terminal \cite{DBLP:journals/iandc/Chomsky59a}. It is well-known that any {\CFG} $G$ can be transformed into an equivalent one $G'$ in Chomsky normal form, such that $|G'| \le |G|^2$. Therefore, from now on we always assume that {\CFG}s are in Chomsky normal form. Moreover, we assume that we don't have any redundant non-terminals, i.e. that every non-terminal $A$ appears in at least one parse tree generated by the grammar. If this is not the case, we get a smaller grammar accepting the same language by deleting all rules containing $A$. 




	\section{From Unambiguous CFGs to Rectangle Covers} \label{sec: rectangles}

	%
In this section, we show how one can prove lower bounds for unambiguous {\CFG}s by means of communication complexity. In fact, we focus on {\CFG}s whose languages are finite and, in particular, whose words are all of the same length. The following definition is crucial.

\begin{definition}[Rectangle] \label{def: rect} 
We say that a language $L$ with words of length $n$ is a \emph{rectangle} if there are numbers $n_1, n_2, n_3$ such that:
%
\begin{align*}L = \bigcup_{\substack{w_1\!w_3\in L_1: \\ |w_1| = n_1, |w_3| = n_3}} 
    \{w_1\}\times L_2 \times \{w_3\} \text{ where }L_1 \subseteq \Sigma^{n_1+n_3}, L_2 \subseteq \Sigma^{n_2}.
\end{align*}
%
We also say that $L$ is a rectangle with \emph{parameters} $(L_1, L_2,n_1, n_2, n_3)$. We say that a rectangle is \emph{balanced} if and only if $\frac{n}{3} \le n_2 \le \frac{2n}{3}$.
\end{definition} 
%
%
%

\begin{example}
Consider the language
\[
L_n^{\ast} := a^{n/2} (a+b)^{n} a^{n/2}
\]
of all words of length exactly $2n$ which begin and end with $n/2$ consecutive $a$ symbols. Then $L_n^{\ast}$ is a balanced rectangle. This follows by setting $n_1 = n_3 = n/2$, $n_2 = n$, $L_1 = \{a^n\}$ and $L_2 = (a+ b)^n$. 
\end{example}


It is easy to see that every language can be written as a union of balanced rectangles since any language containing a single word is a balanced rectangle. The aim of this section is to show that the number of rectangles needed to cover a language is closely related to the size of {\CFG}s accepting the language. This is formalised by the following proposition.

\begin{proposition}\label{prop:rectangles}
    Let $L$ be a language in which all words have length $n$ and which is accepted by a {\CFG}~$G$. Then $L$ can be written as
    \begin{align}\label{eq:rectangles}
        L:= \bigcup_{i\in [\ell]} L_i
    \end{align}
    where every $L_i$ is a balanced rectangle and $\ell \le n|G| 
    $. Moreover, if $G$ is unambiguous, then the union in (\ref{eq:rectangles}) is disjoint.
\end{proposition}

With Proposition~\ref{prop:rectangles} in hand, to prove that a language does not admit a small {\uCFG} it suffices to show that whenever $L$ is equal to a disjoint union of rectangles, the number of rectangles in the union must be big.  This gives a lower bound technique analogous to those which have been successfully deployed in \emph{knowledge compilation}, see for example \cite{BovaCMS16}.

\begin{example}
$L_n$ can be written as a union of $n$ balanced rectangles. To see this observe that for all fixed $0 \le k \le n-1$ the language
\[
L_n^k := (a+b)^k a (a+b)^{n-1} a (a+b)^{n-1-k}
\]
is a balanced rectangle, setting $n_1 = k$, $n_2 = n+1$, $n_3 = n-1-k$, $L_1 = (a+b)^{n-1}$ and $L_2 = a(a+b)^{n-1}a$. Moreover $L_n$ is by definition the union of all these languages. However, note that the $L_n^k$ languages are not disjoint. In fact, in Section~\ref{sec: lb} we will see that any union of balanced rectangles which equals $L$	must have size $2^{\Omega(n)}$, which by Proposition~\ref{prop:rectangles} proves our main lower bound.
\end{example}

In the remainder of this section, we will prove Proposition~\ref{prop:rectangles}. So fix a language $L$ in which all words have the same length $n$ and a context free grammar $G$ accepting $L$. We start with the following simple observation.

\begin{observation}\label{obs:samelength}
    For every non-terminal $A$ of $G$, the words that can be generated by a derivation in~$G$ starting from $A$ all have the same length.
\end{observation}
%

\begin{proof}
    By way of contradiction, assume that this were not the case, so there is some $A$ from which we can generate words of different lengths. Then, by assumption, we know that $A$ appears in~a parse tree of $G$. But in that parse tree we can substitute the derivation below $A$ by derivations for words of different lengths, and we get that $L$ contains words of different lengths, which contradicts the assumption on $L$.
\end{proof}

With the help of Observation~\ref{obs:samelength}, we can rewrite $G$ into an equivalent grammar in the following way: for every non-terminal $A$ of $G$ introduce new non-terminals $A_1, \ldots A_n$. For every rule $A\rightarrow BC$ let $\ell$ be the length of the words generated by $B$ and $i \in [n]$. Then if $i+\ell\le n$ the grammar $G'$ has rules $A_i\rightarrow B_i C_{i+\ell}$. Moreover, for every rule $A\rightarrow a$, the grammar $G'$ has the rules $A_i\rightarrow a$ for $i\in [n]$. Finally, the start symbol of $G'$ is $S_1$.

\begin{lemma} \label{lem:equiv}
    The grammars $G$ and $G'$ generate the same language and $|G'| \le n|G|$. Moreover, if $G$ is unambiguous then so is $G'$.
\end{lemma}    
\begin{proof}
    We build on the observation that in $G'$ the index $i$ of the non-terminals $A_i$ determines the position of the first letter of the word generated from $A_i$ in every word generated by $G$.     
    We use this to show that there is a bijection between the parse trees for the grammar $G$ and $G'$. So fix~a parse tree for a word $w$ in~$G$. Let $A$ be a non-terminal symbol in this parse tree and say that $A$ generates the word $w'$. Let $i$ be the position of the first letter of $w'$ in $w$. Then we substitute $A$ by~$A_i$ in the parse tree. Doing this for every non-terminal yields a new tree which is easily seen to be a parse tree of $G'$ for $w$. The inverse construction is simply deleting the indices that we introduced in the construction of $G'$. Overall, this shows that $G$ and $G'$ generate the same languages. Moreover, since we have a bijection of parse trees, if $G$ is unambiguous then so is $G'$.

    For the size bound, observe that for every $i\in [n]$ and every rule of $G$, we introduced a new rule of the same size. Thus, the size grows by a factor of $n$.
\end{proof}

We now make a connection between non-terminals of $G'$ and rectangles.

\begin{observation} \label{ob: rect}
    Let $A_i$ be a non-terminal of $G'$. Let $L'$ consist of all the words in the language of~$G'$ with a parse tree containing $A_i$. Then $L'$ is a rectangle for some parameters $(L_1, L_2, n_1, n_2, n_3)$ where the words in $L_2$ are exactly those generated by $A_i$.
\end{observation} 
%
%
\begin{proof}
    Consider any word $w$ in $L'$. Then $w= w_1 w_2 w_3$, where $w_2$ is generated from $A_i$. Then we can exchange $w_2$ by any other word $\bar w_2$ generated from  $A_i$ to get $\bar w = w_1\bar w_2w_3$ which is also in $L'$, so $\{w_1\}\times L(A_i)\times \{w_3\}\subseteq L'$ where $L(A_i)$ consists of all words generated from $A_i$.

    By Observation~\ref{obs:samelength}, we know that all words in $L(A_i)$ have the same length, that $|w_1|= i-1$ and $|w_3|= n - (i-1) - |w_2|$. Therefore, for all $w' = w_1'w_2'w_3'\in L'$ with $w_2'\in L(A_i)$ we have $|w_1| = |w_1'|$, $|w_2| = |w_2'|$  and $|w_3| = |w_3'|$. So we can write
    \begin{align*}
        L'= \bigcup_{\substack{w_1\!w_2\!w_3\in L': \\ w_2\in L(A_i)}} \{w_1\}\times L(A_i) \times \{w_3\}
   \end{align*}  
    which proves the observation.
\end{proof}

We can now construct the set of rectangles in Proposition~\ref{prop:rectangles} iteratively via the following process. While the language of $G'$ is not empty, choose a word $w$ in it and a parse tree for $w$. We claim that this parse tree must contain a non-terminal $A_i$ that generates words of length between $\frac{n}{3}$ and $\frac{2n}{3}$. To find this non-terminal, we use the following standard procedure: we descend in the parse tree from the root, iteratively always following the edge to the child whose subtree contains more leaves. We stop when the current node $v$ has less than $\frac{2n}{3}$ leaves in its subtree and claim that we have found the desired non-terminal which is the label of $v$. To see this, note that, since we have not stopped before, the subtree of the parent of $v$ contains more than $\frac{2n}{3}$ leaves, and since we go to the child with more children, $v$ must have at least $\frac{n}{3}$ leaves in its subtree. Observing that the number of leaves below $v$ is the same as the length of the generated word proves the claim. 

We put~$L'$, defined as in Observation~\ref{ob: rect}, into the set of rectangles we are constructing. Then we delete $A_i$ from~$G'$ as well as all other non-terminals that no longer appear in any parse tree and continue the iteration with the resulting language. 

This process terminates after at most $|G'| \le n|G|$ iterations and so produces some set of rectangles $\{R_i\}_{i \in [\ell]}$ with $\ell  \le n|G|$. Observe that, by construction, $\bigcup_{i \in [\ell]} R_i = L$. Moreover, if $G$ is unambiguous then, by Lemma~\ref{lem:equiv}, $G'$ is also unambiguous. This means that every word in $L$ appears in a unique parse tree in $G'$ and so the union $\bigcup_{i \in [\ell]} R_i$ is disjoint. Therefore, this process really does produce a set of rectangles witnessing Proposition~\ref{prop:rectangles}.


	\section{A Lower Bound for Disjoint Rectangle Covers} \label{sec: lb}	

	%

In this section, we show our lower bound for representations by {\uCFG}s via an exponential lower bound for the language $L_n$ from Example~\ref{ex: ambig}. This will provide the missing lower bound of Theorem~\ref{thm:main} and thus prove our main result.
Recall, that $L_n$ is defined as follows:
\[
L_n := \{ (a + b)^{k} a (a+b)^{n-1} a ( a + b)^{n-k-1} \, \mid \, k \le n-1\}.
\]

\noindent We will prove the following, confirming a conjecture from~\cite{DBLP:journals/corr/abs-2309-11663}.
\begin{theorem}\label{thm:lower}
For every $n\in \mathbb{N}$, every ${\uCFG}$ accepting $L$ has size $2^{\Omega(n)}$.
\end{theorem}

In the rest of this section, we prove Theorem~\ref{thm:lower}.
Observe that every word in $L_n$ has length $2n$ and that $L_n$ consists of all those words such that there are two $a$ symbols with distance exactly $n$ between them.  To prove Theorem~\ref{thm:lower}, we will use the rectangle based method presented in Section~\ref{sec: rectangles}.

Note that we may assume that $n$ is sufficiently big by choosing the constant hidden in the $\Omega$-notation to be sufficiently small. To simplify some of our arguments, for now we only consider~$L_n$ for values of $n$ which are divisible by $4$; it will be easy to remove this condition at the end of this section. 

\subsection{A Set Perspective}

Before diving into our proof we first introduce a change of perspective. It will be helpful to think of each word over $\{a,b\}$ of length $2n$ as defining a pair of subsets of~$[n]$. Formally, we define a bijection which maps each $w = w_1 \dots w_{2n}$, where $w_i \in \{a,b\}$ for each $i$ to a pair $(X_w, Y_w) \subseteq \{x_1, \dots, x_n\} \times \{y_1, \dots, y_n\}$  where $\{x_1, \dots, x_n\}$ and $\{y_1, \dots, y_n\}$ are both sets of elements and $X_w$ contains every $x_i$ such that $w_i = a$ and $Y_w$ contains every $y_i$ such that $w_{i+n} = a$. We write $X: =  \{x_1, \dots, x_n\}$ and $Y:= \{y_1, \dots, y_n\}$. 
%
Sometimes it will be useful to refer to the elements of $X \cup Y$ in a unified way, hence we define 
\[
z_i := \begin{cases}
x_i & i \in [n] \\
y_{i-n} & i \in [n+1, 2n].
\end{cases}
\]

\noindent We write $Z[i,j] : = \{z_{\ell} \, \mid \, i \le \ell \le j\}$ and $Z: = Z[1,2n]$. We similarly define $X[i,j]$ and $Y[i,j]$. Observe that each interval also induces a partition of~$Z$ as follows.

\begin{definition}[Ordered Partition]
We say that a partition $(\Pi_0, \Pi_1)$ of $Z$ is \emph{induced by the interval $[i,j]$} if for some $\ell \in \{0,1\}$, we have $\Pi_{\ell} = Z[i,j]$. We call a partition which is induced by some interval an \emph{ordered} partition. Moreover, we call an ordered partition $(\Pi_0, \Pi_1)$ \emph{balanced} if 
\[
\frac{2n}{3} \le |\Pi_0|, |\Pi_1| \le \frac{4n}{3}
\]
\end{definition}

Having these dual notions of intervals and the partitions they induce on $Z$ will be useful in our proofs. We next translate Definition~\ref{def: rect} to fit the set perspective.

\begin{definition}[Set Rectangle] \label{def: set_rect}
Let $(\Pi_0, \Pi_1)$ be an ordered partition of $Z$. We say that $R \subseteq \mathcal{P}(Z)$ is an ordered $(\Pi_0, \Pi_1)$-\emph{set rectangle} if there are sets $S \subseteq \mathcal{P}(\Pi_0)$ and $T \subseteq \mathcal{P}(\Pi_1)$ such that $R= S \times T$.\footnote{Remember that to simplify notation we read $S\times T$ as $\{U\cup V\mid U\in S, V\in T\}$.} We say that $R$ is a \emph{balanced set-rectangle} if $(\Pi_0, \Pi_1)$ is balanced. Moreover, if $(\Pi_0, \Pi_1)$ is induced by $[i,j]$ we also call~$R$ an $[i,j]$-set rectangle. 
\end{definition}

The following lemma justifies Definition~\ref{def: set_rect} and therefore our use of the set perspective in the rest of the proof.

\begin{lemma}
Let $L$ be a language over the alphabet $\{a,b\}$ with words of length $2n$, such that $L$ is~a rectangle in the sense of Definition~\ref{def: rect} with parameters $(L_1, L_2, n_1, n_2, n_3)$. Then $\{(X_w, Y_w) \, \mid \, w \in L\}$ is a $[n_1+1, n_1+n_2]$-set rectangle. 

Conversely, for any language $L$ over the alphabet $\{a,b\}$ with words of length $2n$ such that $\{(X_w, Y_w) \, \mid \, w \in L\}$ is an $[i,j]$-set rectangle, $L$ is a rectangle with $n_1 = i-1$, $n_2 = j-i+1$ and $n_3 = 2n-j$. 
\end{lemma}

\begin{proof}
Let 
\[L = \bigcup_{\substack{w_1\!w_3\in L_1: \\ |w_1| = n_1, |w_3| = n_3}} \{w_1\}\times L_2 \times \{w_3\}\text{ where }L_1 \subseteq \Sigma^{n_1+n_3}, L_2 \subseteq \Sigma^{n_2}.\]
be a rectangle with parameters $(L_1, L_2, n_1, n_2, n_3)$. Define 
\begin{align*}
S &:= \{(X_w, Y_w) \, \mid \, w = w_1 b^{n_2} w_3 \textit{ for some } w_1\!w_3 \in L_1\} \subseteq Z[1,n_1] \cup Z[n_1 + n_2 +1, 2n] \textit{ and}  \\
 T &:= \{(X_w, Y_w) \, \mid \, w = b^{n_1}w_2b^{n_3} \textit{ for some } w_2 \in L_2\} \subseteq Z[n_1+1, n_1 +n_2].
\end{align*} 
%
By construction $U \cap V = \emptyset$ for all $U \in S$, $V \in T$, so it is easy to verify that $S \times T = \{U \cup V \,\mid \, U \in S, V \in T\} = \{(X_w, Y_w) \, \mid \, w \in L\}$ and that this is a $[n_1+1, n_1 +n_2]$ rectangle. The converse direction is similar.
\end{proof}

Slightly abusing notation, we will from now on write $L_n$ to mean $\{(X_w, Y_w) \, \mid \, w \in L_n\}$. Also from now on we refer to ordered set-rectangles simply as ordered rectangles; that is, we will now completely switch to the set perspective. Seen this way, the language $L_n$ consists exactly of those pairs $(X_w, Y_w)$ of sets for which there is an $i$ such that $x_i\in X_w$ and $y_i\in Y_w$ are in the respective sets. Going one step further, if we identify the sets $X_w, Y_w$ with the corresponding index sets, $L_n$ consists of intersecting pairs of sets, so $L_n$ is essentially the complement of the famous set disjointness problem, which is widely regarded as the flagship problem of communication complexity, see e.g.~the survey~\cite{DBLP:conf/mfcs/Sherstov14}.

From the above discussion along with Proposition~\ref{prop:rectangles}, it follows that to prove Theorem~\ref{thm:lower} it suffices to prove the following proposition.

\begin{proposition} \label{prop: lb}
If $R_1, \dots, R_{\ell}$ is a set of ordered balanced rectangles such that $R_i$ and $R_j$ are disjoint for every $i \neq j$ and such that 
\begin{align*}
\bigcup_{i \in [\ell]} R_i = L_n,
\end{align*}
then $\ell = 2^{\Omega(n)}$.
\end{proposition}

We call a set of rectangles as in Proposition~\ref{prop: lb} a \emph{disjoint rectangle cover} for $L_n$. We will prove Proposition~\ref{prop: lb} in the next two subsections.

\subsection{A Lower Bound for Restricted Rectangles}

Before showing Proposition~\ref{prop: lb} in full generality, it will be useful to first consider a special case in which all rectangles share a particular partition.

\begin{theorem} \label{thm: base}
Any disjoint rectangle cover of $L_n$ by $[1,n]$-rectangles has size  $2^{\Omega(n)}$. 
\end{theorem}

Theorem~\ref{thm: base} is an immediate consequence of the so-called rank bound from communication complexity pioneered in~\cite{DBLP:conf/stoc/MehlhornS82}, see e.g.~\cite[Chapter~2]{RaoY2020} for a textbook introduction.
However, to prove Proposition~\ref{prop: lb} we need to generalise Theorem~\ref{thm: base}, which unfortunately cannot directly be done using known results from communication complexity: in contrast to most of the literature, Proposition~\ref{prop: lb} is not in the standard setting in which the partitions for all rectangles are fixed. Rather, different rectangles may use different partitions. This setting is called \emph{multi-partition communication complexity}~\cite{DBLP:journals/iandc/DurisHJSS04} and is far less studied. In particular, there is only one known lower bound that explicitly works for disjoint rectangle covers~\cite{DBLP:journals/tcs/Sauerhoff03}, which we cannot directly apply here. 

As a first step to proving Proposition~\ref{prop: lb} we thus give a new proof of Theorem~\ref{thm: base}. This proof will be more involved then the usual approach, but it has the advantage that we can later generalise it to Proposition~\ref{prop: lb}. We use a discrepancy argument in the spirit of that given by Sherstov in the context of multiparty communication complexity\footnote{We warn the reader that despite superficially similar names \emph{multiparty} and \emph{multipartition} communication complexity are very different concepts!}~\cite{DBLP:journals/siamcomp/Sherstov16}. The idea is to  define disjoint $A, B \subset L_n$, such that (1) any $[1,n]$-rectangle contains roughly the same number of sets from $A$ as from $B$ and (2) $L_n$ contains many more words from $A$ than $B$. Therefore, the size of any disjoint cover for~$L_n$ by $[1,n]$-rectangles must be large.

Informally, we split $X \cup Y$ into intervals of size four and then define $\Lset$ to be those sets $(U,V)$ containing exactly one element from each interval. Then $A$ is defined to be the set of $(U,V) \in \Lset$ such that the number of $i$ with $x_i \in U$ and $y_i \in V$ is odd and $B := \Lset \setminus A$. We next give the formal definition.

So set $m:= n/4$; note that $m$ is an integer since by assumption $n$ is divisible by four. Then for $i \in [m]$ we define:
%
\begin{align*}
 I_i^{X} :=& X[4(i-1)+1, 4i]\\
 \Lset_i^X :=& \{ U \subset I_i^X \, \mid \, |U|=1\} \\
 \Lset^X :=& \{ U \subset X \, \mid \, |U \cap I_i| = 1 \textit{ for every } i \in [m]\}.
 \end{align*}
%
We analogously define $I_i^Y$, $\Lset_i^Y$ and $\Lset^Y$ exactly as above but with $Y$ playing the role of~$X$. Then we set $\Lset := \Lset^X \times \Lset^Y$ and $\Lset_i = \Lset_i^{X} \times \Lset_i^Y$. Since we often want to take a unified perspective we define for $i \in [m]$, $I_i := I_i^X$ and $I_{i+m} = I_i^{Y}$. We call every $I_j$ an \emph{interval}.

We next show that $\Lset$ is big and that $L_n$ contains many more words from $A$ than from $B$. Recall, that $A \subset \Lset$ contains those $(U,V) \in \Lset$ such that the number of $i$ with $x_i \in U$ and $y_i \in V$ is odd and $B := \Lset \setminus A$.

\begin{lemma} \label{lem: sizes}
The following holds:
\begin{enumerate}
\item $|\Lset| = 2^{4m} $. \label{eq:lsize}
%
%
\item $|A \cap L_n| - | B \cap L_n| = |A| - |B \cap L_n| > 2^{\frac{7m}{2}}$. \label{eq:ABsize}
\end{enumerate}
\end{lemma}
\begin{proof}

For \eqref{eq:lsize} observe that in total there are $2m$ intervals each of length four and that for every such interval exactly one element is chosen for every $(U,V)\in \Lset$, so $|\Lset| = 4^{2m} = 2^{4m}$. 

The equality in \eqref{eq:ABsize} is trivial since $A \subset L_n$. To prove the inequality it suffices to show that $|B \setminus L_n| = 12^m$ and that $|B|- |A|= 2^{3m}$. To see this assume the aforementioned equalities, then
\begin{align*}
|A| - | B \cap L_n| &= |A| - (|B| - |B \setminus L_n|) \\ 
&= |B \setminus L_n| - (|B| - |A|) \\
&= 12^m - 2^{3m}  > 2^{\frac{7m}{2}},
\end{align*} 
where in the last step we use that $n$ (and thus $m$) is sufficiently big.

To show that $|B \setminus L_n| = 12^m$, consider for each $i\in [m]$ the $16$ sets $(U_i,V_i)\in \Lset_i$. By the definition of $\Lset_i$, the sets $U_i$ and $V_i$ contain a single element, respectively, so $U_i=\{x_j\}$, $V_i=\{y_k\}$, for some appropriate $j,k$. There are exactly four combinations such that $j=k$ and $12$ with $j\ne k$. Combining the latter for all $i\in [m]$ gives exactly $B \setminus L_n$, so $|B \setminus L_n| = 12^{m}$.

Finally, $|B|- |A|= 2^{3m}$ is true since
%
 \begin{align*}
2^{3m} &= (12 - 4)^{m} = \sum_{i=0}^m \binom{m}{i} 12^{m-i}(-4)^{i} \\
&= \sum_{i=0}^{\lfloor m/2 \rfloor}\left(\binom{m}{2i} 12^{m-2i} 4^{2i}\right ) - \sum_{i=1}^{\lceil m/2 \rceil}\left(\binom{m}{2i-1} 12^{m-(2i-1)} 4^{2i-1}\right ) \\
&= |B| - |A|. \qedhere
\end{align*} 
\end{proof}

The key to proving Theorem~\ref{thm: base} is the following: in Lemma~\ref{lem: sizes}, we have seen that there are many more sets in $A \cap L_n$ than in $B \cap L_n$. However, we will next show that each $[1,n]$-rectangle cannot contain many more sets of $A$ than $B$. Therefore, any disjoint cover of $L_n$ by $[1,n]$-rectangles must by big.

\begin{lemma} \label{lem: simple_des}
Let $R = S \times T$ be a $[1,n]$-rectangle. Then 
\[ \big||R \cap A| - |R \cap B|\big| \le 2^{3m}. \]
\end{lemma}

\begin{proof}
The key idea is to express $\big||R \cap A| - |R \cap B|\big|$ in terms of an appropriate expectation calculation. To set this up we need some definitions. 

Define for each $i\in [m]$ random variables $X_i, Y_i$ that take a value uniformly at random from $\Lset_i^{X}$ and $\Lset_i^{Y}$ respectively. We let all these random variables be independent and define new random variables $X := \bigcup_{i=1}^m X_i$, $Y = \bigcup_{i =1}^m Y_i$. Note that $X$ has the uniform distribution over $\Lset^{X}$ and $Y$ the uniform distribution on $\Lset^{Y}$. Moreover, $X$ and $Y$ are independent. Let $Y'$ be an independent copy of~$Y$.

For $L \subseteq \mathcal{P}(Z)$ we write $\chi_L$ for the indicator function of $L$, i.e. the function $\chi_L \colon \mathcal{P}(Z)\to \{0,1\}$ that evaluates to one exactly on inputs contained in $L$. For $U \in \Lset^X$ and $V \in \Lset^{Y}$ let $\Int(U,V) := 1$ if there is some $i$ such that $x_i \in U$ and $y_i \in V$, otherwise $\Int(U,V) :=0$. Note that if $U \in \Lset^X$ and $V \in \Lset^Y$ then $(-1)^{\chi_A(U,V)} = (-1)^{\sum_{i=1}^m \Int(U_i, V_i)}$, where $U_i := U \cap I_i^{X}$ and $V_i := V \cap I_i^{Y}$ for $i \in [m]$. 
The following calculation borrows heavily from \cite[Lemma 5.9]{RaoY2020} which in turn is inspired by an approach pioneered in~\cite{DBLP:journals/siamcomp/Sherstov16}.
%
%
%
\begin{align*}
\left(\frac{|R \cap A| - |R \cap B|}{ 2^{4m} }\right)^2 =& \left( \E_{X,Y} \left[\chi_R(X,Y) \cdot (-1)^{\chi_{A}(X,Y)}\right] \right)^2 \\
=& \left(\E_{X,Y } \left[ \chi_S(X) \cdot \chi_T(Y) \cdot (-1)^{\chi_{A}(X,Y)}\right] \right)^2 \\
\le& \E_{X} \left[ \chi_{S}(X)^2 \left( \E_{Y} \left[ \chi_T(Y) \cdot  (-1)^{\chi_{A}(X,Y)}\right] \right)^2 \right] \\
\le&  \E_{X, Y, Y'} \left[\chi_T(Y) \cdot \chi_T(Y') \cdot (-1)^{\chi_{A}(X,Y) +\chi_{A}(X,Y')}\right]\\
\le& \E_{Y, Y' }  \left[ \left| \E_{X} \left[(-1)^{\chi_{A}(X,Y) +\chi_{A}(X,Y')}\right] \right| \right] \\
=& \E_{Y, Y'} \left[ \left| \E_{X }\left[(-1)^{\sum_{i=1}^m \Int(X_i, Y_i) +\Int(X_i,Y'_i)}\right] \right | \right]
\end{align*}

Now fix $Y, Y'$. We claim that if $Y \neq Y'$ the inner expectation must evaluate to zero. First note that the probability that $Y = Y'$ is $1/|\Lset^{Y}| = 2^{-2m}$. Therefore, the claim implies the result via a simple calculation. We now prove the claim. 

So fix $Y \neq Y'$ while $X$ remains random as before. Let $C$ be the event that $\sum_{i=1}^m \Int(X_i, Y_i) +\Int(X_i,Y'_i)$ is even and $C_i$ be the event that $\Int(X_i, Y_i) +\Int(X_i,Y'_i) = 1$. Then $C$ is true if and only if the number of $i \in [m]$ such that $C_i$ is true is even. Note that if $Y_i = Y_i'$ then $C_i$ is false. So suppose $Y_i \neq Y_i'$. Since all intervals are of size four and $|X_i| = |Y_i| =|Y'_i| = 1$, we have $\mathbb{P}(C_i)= \frac{1}{2}$. Let $\mathcal{I} := \{i \in [m] \, \mid \, Y_i \neq Y_i'\}$ and $\alpha := |\mathcal{I}|$. Then
%
\begin{align*}
\mathbb{P}(C) = \sum_{i=0}^{\lfloor \frac{\alpha}{2} \rfloor} \binom{\alpha}{2i} 2^{-2i} 2^{-(\alpha- 2i)} = 2^{-\alpha} \sum_{i=0}^{\lfloor \frac{\alpha}{2} \rfloor} \binom{\alpha}{2i} = 2^{-\alpha} 2^{\alpha-1} = \frac{1}{2},
\end{align*}
%
%

%
%
%
\noindent where we use the fact that the sum of $\binom{\alpha}{i}$ over all even values of $i$ is $2^{\alpha-1}$. The claim and therefore the result follows.
\end{proof}

From Lemma~\ref{lem: simple_des}, we can deduce Theorem~\ref{thm: base}. In detail, let $R_1, \dots , R_\ell$ be a disjoint set of $[1,n]$-rectangles whose union is $L_n$. Then 
%
\begin{align*}
2^{\frac{7m}{2}} &< |A \cap L_n| - | B \cap L_n| \\
 &= \sum_{i=1}^\ell |A \cap R_i| - | B \cap R_i| \\ 
&\le  \ell \cdot 2^{3m},  
\end{align*}
where the first inequality is Lemma~\ref{lem: sizes}\eqref{eq:ABsize}, the equality uses the fact the rectangles form a cover and are disjoint, and the second inequality follows by Lemma~\ref{lem: simple_des}. It follows that $\ell = 2^{\Omega(m)} = 2^{\Omega(n)}$ which completes the proof of Theorem~\ref{thm: base}. 

\subsection{Proof of Theorem~\ref{thm:lower}}

To prove Proposition~\ref{prop: lb}, and therefore Theorem~\ref{thm:lower}, it suffices to prove an analogue of Lemma~\ref{lem: simple_des} that applies to all balanced ordered rectangles. In fact we have already done much of the work. The main point is that for every balanced ordered partition $(\Pi_0, \Pi_1)$ and `most' values of $\ell$, we have that $x_{\ell}$ and $y_{\ell}$ are on different sides of the partition. We now formalise the above idea, beginning with the nice case where the partition splits $x_{\ell}$ and $y_{\ell}$ for every $\ell$. Here using symmetry we may deduce the following corollary to the proof of Lemma~\ref{lem: simple_des}. 

\begin{corollary} \label{cor: disc}
Let $R = S \times T$ be an $[i,j]$-rectangle such that $j-i = n-1$. Then 
\[ \big||R \cap A| - |R \cap B|\big| \le 2^{3m} \]
\end{corollary}

To move from this to our more general case, we first elucidate some properties of balanced ordered partitions. So fix such a $(\Pi_0, \Pi_1)$. Let $G$ be the set containing those $i \in [n]$ such that $x_i$ and~$y_i$ are in different parts of the partition, i.e.~$G$ contains those $i \in [n]$ such that exactly one of~$x_i$ and~$y_i$ lies in $\Pi_0$. Let $V_G$ contain all those $x_i$ and $y_i$ such that $i\in G$. Moreover, let $I_G$ contain all intervals $I_i$ such that $I_i \subseteq V_G$.

It will be convenient to assume that $(\Pi_0, \Pi_1)$ is well-behaved with respect to the intervals $I_{\ell}$ in the following sense: we call $(\Pi_0, \Pi_1)$ \emph{neat} if for every interval $I_{\ell}$ we have that $I_{\ell} \subseteq \Pi_0$ or $I_{\ell} \subseteq \Pi_1$. In the remainder, we can largely restrict ourselves to neat partitions due to the following result.

\begin{lemma}\label{lem:makeneat}
  Let $R$ be an ordered balanced $(\Pi_0, \Pi_1)$-rectangle. Then there there is a neat ordered balanced partition $(\Gamma_0, \Gamma_1)$ and a set of disjoint $(\Gamma_0, \Gamma_1)$-rectangles $R_1, R_2, \ldots, R_k$ with $k \le 256$ such that $R = \bigcup_{\ell \in [k]}R_{\ell}$.
\end{lemma}

\begin{proof}
Suppose w.l.o.g.\! that $|\Pi_0| \le |\Pi_1|$. There are at most two intervals $I_i, I_j$ which violate neatness, i.e.\! that contain elements from $\Pi_0$ and $\Pi_1$. Let $(\Gamma_0, \Gamma_1)$ be the partition of $Z$ that we get by putting all elements from $I_i$ and $I_j$ into $\Pi_0$. Then, by construction, $(\Gamma_0, \Gamma_1)$ is neat and ordered. Moreover, it is balanced, since $\Gamma_0$ gained at most the $8$ elements from $I_i\cup I_j$, so $|\Gamma_0| \le |\Pi_0| + 8 \le n + 8\le \frac{2n}{3}$, where for the last inequality we use that $n$ is sufficiently big. 

Now consider $\alpha\subseteq I_i\cup I_j$. Then let $R_\alpha$ contain exactly those sets $U$ from $R$ for which $U\cap (I_i \cup I_j) =\alpha$. Then clearly $R_{\alpha} \cap R_{\alpha'} = \emptyset$ for $\alpha \neq \alpha'$. Note that $R_\alpha$ is both a $(\Pi_0, \Pi_1)$-rectangle and a $(\Gamma_0, \Gamma_1)$-rectangle since it is fully determined on $I_i\cup I_j$ and thus on the difference between the two partitions. Moreover, we have
    \begin{align*}
        R = \bigcup_{\alpha\subseteq I_i\cup I_j} R_\alpha.
    \end{align*}
    Since $|I_i\cup I_j| = 8$ and thus the disjoint union ranges over $2^8=256$ sets, the claim follows.
\end{proof}

Neat ordered partitions have the following useful properties.

\begin{lemma} \label{lem:ordered_par}
Let $(\Pi_0, \Pi_1)$ be a neat, ordered and balanced partition such that $|\Pi_0| \le |\Pi_1|$. Then
\begin{enumerate}
\item $\Pi_0 \subseteq V_G$ and
\item $|\Pi_0| = |G|$. 
%
\end{enumerate}
\end{lemma}

\begin{proof}
Let $[i,j]$ be the interval which induces the partition. First, suppose $\Pi_0 = Z[i,j]$. Since $|\Pi_0| \le n$ it follows that for every two elements $z_k, z_\ell$ of $\Pi_0$ the indices have distance at most $n-1$, i.e., if $z_k, z_{\ell} \in \Pi_0$ then $|\ell-k| \le n-1$. Since the distance between $x_{\ell}$ and $y_{\ell}$ is $n$ for every $\ell$, it follows that $\Pi_0$ cannot contain both $x_\ell$ and $y_\ell$ and thus $\Pi_0 \subseteq V_G$. 

If instead $\Pi_0 = Z \setminus Z[i,j]$, then 
\begin{align*}
\Pi_0 = \{z_{\ell} \in Z \, \mid \, \ell < i \} \cup \{z_{\ell} \in Z \, \mid \, \ell > j\}.
\end{align*}
So since $|Z[i,j]| \ge n$, we know that $j-i \ge n-1$ and it is easy to see that no two elements of $\Pi_0$ are at distance $n$. So again $\Pi_0 \subseteq V_G$; we have shown (1). 

For (2), observe that for every $\ell \in G$ we must have either $x_{\ell}$ or $y_{\ell}$ in $\Pi_0$, so $|G| \le |\Pi_0|$. Moreover, from (1) we get that for every $\ell \in G$ the set $\Pi_0$ cannot contain $x_{\ell}$ and $y_{\ell}$, so $|\Pi_0| \le |G|$ and thus $|\Pi_0| = |G|$. 
%
\end{proof}

We can now deploy Corollary~\ref{cor: disc} and Lemma~\ref{lem:ordered_par} to prove a generalisation of Lemma~\ref{lem: simple_des}. 

