\section*{Proof of Lemma 1}
Applying the coupled logarithm and expanding the expression using Eq. \eqref{11}

\begin{eqnarray}
  \ell_\kappa(\boldsymbol \th) & \equiv & \frac{1}{\alpha}\ln_\kappa\left(\exp_\kappa^{-\frac{1+d\kappa}{\alpha}}\left(\eta(\boldsymbol\theta) \cdot T(\boldsymbol{x}) \oplus_\kappa \ln_\kappa \left(\frac{h(\boldsymbol{x})}{Z_\kappa(\eta(\boldsymbol\theta))}
\right)^{-\frac{\alpha}{1+d\kappa}}\right)^{-\frac{\alpha}{1+d\kappa}}\right) \nonumber\\ 
\label{eq6} \\
& = & \frac{1}{\alpha}\left(\eta(\boldsymbol\theta) \cdot T(\boldsymbol{x}) \oplus_\kappa \ln_\kappa \left(\frac{h(\boldsymbol{x})}{Z_\kappa(\eta(\boldsymbol\theta))}
\right)^{-\frac{\alpha}{1+d\kappa}}
\right) \nonumber \\
%\ell_\kappa(\boldsymbol \th)
& = &\frac{1}{\alpha}\left(\eta(\boldsymbol\theta) \cdot T(\boldsymbol{x}) \oplus_\kappa \frac{1}{\kappa} \left( \left( \frac{h(\boldsymbol{x})}{Z_\kappa(\eta(\boldsymbol\theta))} \right)^{-\frac{\alpha\kappa}{1 + d\kappa}} - 1 \right)
\right)\\
& = & \frac{1}{\alpha}\left(\eta(\boldsymbol\theta) \cdot T(\boldsymbol{x}) \oplus_\kappa \frac{1}{\kappa} \left( R(\boldsymbol{\zeta} ) - 1 \right)
\right).
\end{eqnarray}

Let $\boldsymbol{\zeta} := (\boldsymbol{\theta}, \boldsymbol{x}, d, \alpha)$, and define
\begin{equation}
  R(\boldsymbol{\zeta} ) = \left( \frac{h(\boldsymbol{x})}{Z_\kappa(\eta(\boldsymbol{\theta}))} \right)^{-\frac{\alpha\kappa}{1 + d\kappa}}. 
\end{equation}

Then, the expression becomes
\begin{align*}
    \ell_\kappa(\boldsymbol \theta) =& \frac{1}{\alpha} \left[ \eta(\boldsymbol\theta) T(\boldsymbol{x}) + \frac{1}{\kappa} \left( R(\boldsymbol{\zeta}) - 1 \right) + \kappa \cdot \eta(\boldsymbol\theta) T(\boldsymbol{x}) \cdot \frac{1}{\kappa} (R(\boldsymbol{\zeta}) - 1) \right]\\
    =& \frac{1}{\alpha} \left[ \eta(\boldsymbol\theta) T(\boldsymbol{x})R(\boldsymbol{\zeta}) + \frac{1}{\kappa} (R(\boldsymbol{\zeta}) - 1) \right].
\end{align*}

Now, we obtain
\[
\frac{\partial \ell_\kappa(\boldsymbol \theta)}{\partial \boldsymbol\theta_i}
= \frac{1}{\alpha} \left[
\frac{\partial}{\partial \boldsymbol\theta_i} \left( \eta(\boldsymbol\theta) T(\boldsymbol{x})R(\boldsymbol{\zeta}) \right)
+ \frac{1}{\kappa} \cdot \frac{\partial (R(\boldsymbol{\zeta})-1)}{\partial \boldsymbol\theta_i}
\right],
\]
where the derivative of $\eta(\boldsymbol\theta) T(\boldsymbol{x})R(\boldsymbol{\zeta})$ is 
\begin{align}\label{eq.1}
    \frac{\partial}{\partial \boldsymbol\theta_i} \left( \eta(\boldsymbol\theta) T(\boldsymbol{x})R(\boldsymbol{\zeta}) \right)
    = \left( \frac{\partial \eta(\boldsymbol\theta)}{\partial \boldsymbol\theta_i} \right) \cdot T(\boldsymbol{x}) \cdot R(\boldsymbol{\zeta})
+ \eta(\boldsymbol\theta) \cdot T(\boldsymbol{x}) \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \boldsymbol\theta_i}
\end{align}
and the derivative of $( R(\boldsymbol{\zeta}) - 1)$ is
\[
\frac{1}{\kappa}\cdot\frac{\partial}{\partial \boldsymbol\theta_i}(R(\boldsymbol{\zeta}) - 1) = \frac{1}{\kappa}\cdot\frac{\partial R(\boldsymbol{\zeta})}{\partial \boldsymbol\theta_i}.
\]

Since
\[
R(\boldsymbol{\zeta}) = \left( \frac{h(\boldsymbol{x})}{Z_\kappa(\eta(\boldsymbol\theta))} \right)^{-r} = h(\boldsymbol{x})^{-r} \cdot Z_\kappa(\eta(\boldsymbol\theta))^{r},
\quad \text{where } r := \frac{\alpha\kappa}{1 + d\kappa},
\]
hence, 
\begin{eqnarray*} 
\frac{\partial R(\boldsymbol{\zeta})}{\partial \boldsymbol\theta}
& = &  h(\boldsymbol{x})^{-r} \cdot \frac{\partial}{\partial \boldsymbol\theta} \left( Z_\kappa(\eta(\boldsymbol\theta))^{r} \right)\\
& = & h(\boldsymbol{x})^{-r} \cdot r \cdot Z_\kappa(\eta(\boldsymbol\theta))^{r - 1} \cdot \frac{\partial Z_\kappa(\eta(\boldsymbol\theta))}{\partial \boldsymbol\theta}.
\end{eqnarray*}

By applying the chain rule on $( Z_\kappa(\eta(\boldsymbol\theta)))$, we can obtain
\begin{eqnarray}
\nonumber
\frac{\partial Z_\kappa(\eta(\boldsymbol\theta))}{\partial \boldsymbol\theta_i}
& = & \frac{\partial Z_\kappa}{\partial \eta} \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \boldsymbol\theta_i} \\
\label{eq.2}
\frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
 & = & r \cdot h(\boldsymbol{x})^{-r} \cdot Z_\kappa(\eta(\boldsymbol\theta))^{r - 1} \cdot \frac{\partial Z_\kappa(\eta)}{\partial \eta} \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i}.
\end{eqnarray}

From Eqs. \eqref{eq.1} and \eqref{eq.2}, we have 
\begin{align}\label{first}
    \frac{\partial \ell_\kappa(\boldsymbol \theta)}{\partial \theta_i} = \frac{1}{\alpha} \left[
T(\boldsymbol{x}) \cdot R(\boldsymbol{\zeta}) \cdot\frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i}
+ \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \eta (\boldsymbol\theta)\right) \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
\right],
\end{align}
where $R(\boldsymbol{\zeta}) = h(\boldsymbol{x})^{-r} \cdot Z_\kappa(\eta(\boldsymbol\theta))^{r}$, $r = \frac{\alpha\kappa}{1 + d\kappa}$, and
\begin{align*}
    \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
   = r \cdot h(\boldsymbol{x})^{-r} \cdot Z_\kappa(\eta(\boldsymbol\theta))^{r - 1} \cdot \frac{\partial Z_\kappa(\eta)}{\partial \eta} \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i}.
\end{align*}


For the second derivative, using the first derivative in Eq. \eqref{first}, we have
\begin{align}
\frac{\partial^2 \ell_\kappa (\boldsymbol\theta)}{\partial \theta_j \partial \theta_i} = \frac{1}{\alpha} \left( \frac{\partial A}{\partial \theta_j} + \frac{\partial B}{\partial \theta_j} \right), 
\end{align}
where
\begin{align*}
    A :=& T(\boldsymbol{x}) \cdot R(\boldsymbol{\zeta}) \cdot\frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i},\\
    B :=& \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \eta(\boldsymbol\theta) \right) \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}.
\end{align*}
Here, the derivative of $(A)$ can be obtained as 
\[
\frac{\partial A}{\partial \theta_j} = T(\boldsymbol{x}) \cdot \left[ \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_j} \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i}
+ R(\boldsymbol{\zeta}) \cdot \frac{\partial^2 \eta(\boldsymbol\theta)}{\partial \theta_j \partial \theta_i} \right]
\]
and the derivative of $(B)$ can be obtained as 
\begin{eqnarray*} \frac{\partial B}{\partial \theta_j} & = & \frac{\partial}{\partial \theta_j} \left( \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \eta(\boldsymbol\theta) \right) \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i} \right)\\
& = & T(\boldsymbol{x}) \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_j} \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
+ \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \eta(\boldsymbol\theta) \right) \cdot \frac{\partial^2 R(\boldsymbol{\zeta})}{\partial \theta_j \partial \theta_i}.
\end{eqnarray*} 

Substituting everything into the full Hessian expression, we can obtain
\begin{eqnarray*}
\frac{\partial^2 \ell_\kappa(\boldsymbol \th)}{\partial \theta_j \partial \theta_i} & = & \frac{1}{\alpha} \left[
T(\boldsymbol{x}) \cdot \left( \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_j} \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_i} 
+ R(\boldsymbol{\zeta}) \cdot \frac{\partial^2 \eta(\boldsymbol\theta)}{\partial \theta_j \partial \theta_i} \right)\right. 
\\
& & \left. 
+ T(\boldsymbol{x}) \cdot \frac{\partial \eta(\boldsymbol\theta)}{\partial \theta_j} \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
+ \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \eta(\boldsymbol\theta) \right) \cdot \frac{\partial^2 R(\boldsymbol{\zeta})}{\partial \theta_j \partial \theta_i}
\right].
\end{eqnarray*}
The results can be further simplified by considering the coupled exponential family (i.e., $\eta(\boldsymbol\theta)=\boldsymbol\theta$) instead of the curved coupled exponential family as follows:

\begin{eqnarray}
\label{eq12}
 \frac{\partial \ell_\kappa(\boldsymbol \theta)}{\partial \theta_i} & = & \frac{1}{\alpha} \left[
T(\boldsymbol{x}) \cdot R(\boldsymbol{\zeta}) 
+ \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \boldsymbol\theta\right) \cdot \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i}
\right] \\ 
\frac{\partial^2\ell_\kappa (\boldsymbol \th)}{\partial \theta_i \partial \theta_j} & = & \frac{1}{\alpha} \left[
T(\boldsymbol{x}) \left( \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_j} + \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i} \right)
+ \left( \frac{1}{\kappa} + T(\boldsymbol{x}) \cdot \boldsymbol\theta \right) \cdot \frac{\partial^2 R(\boldsymbol{\zeta})}{\partial \theta_j \partial \theta_i}
\right]. \nonumber \\ \label{eq13}
\end{eqnarray}

The geometrical quantities on the manifold $\mathcal{S}$ can be derived from Eqs. \eqref{eq12} and \eqref{eq13}, i.e., the Fisher metric tensors and the affine connection can be given by 
\begin{eqnarray*}
g_{ij} & = & -\mathbb{E}_{\boldsymbol{X}}\left[\frac{\pa^2\ell_\kappa(\boldsymbol \th)}{\pa\th_i\pa\th_j}\right]\\
& = & \frac{1}{\alpha} \left[
\mathbb{E}_{\boldsymbol{X}}\left[T(\boldsymbol{x})\right] \left( \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_j} + \frac{\partial R(\boldsymbol{\zeta})}{\partial \theta_i} \right)
+ \left( \frac{1}{\kappa} + \mathbb{E}_{\boldsymbol{X}}\left[T(\boldsymbol{x})\right] \cdot \boldsymbol\theta  \right) \cdot \frac{\partial^2 R(\boldsymbol{\zeta})}{\partial \theta_j \partial \theta_i}
\right].
\end{eqnarray*}
By substituting the first derivative in Eq. \eqref{eq12} and the  second derivative in Eq. \eqref{eq13}, we obtain the full expression for $\G_{ijk}$ as 
\begin{eqnarray*}
\G_{ijk} & = & \mathbb{E}_{\boldsymbol{X}}\left[\frac{\pa^2\ell_\kappa(\boldsymbol \th)}{\pa\th_i\pa\th_j}\frac{\pa\ell_\kappa(\boldsymbol \th)}{\pa\th_k}\right] \\
&=& \frac{1}{\alpha^2} \cdot \mathbb{E}_{\boldsymbol{X}}\left[ (A_1 + A_2) \cdot (B_1 + B_2) \right].
\end{eqnarray*}

