\section{Achievable Rate of RSMA Under Finite Constellations}
In this section, we present the mutual information of a linear system with finite alphabet input and utilize it to derive the rate expressions of RSMA.
\subsection{Prerequisites on Constellation-Constrained Rate}
Consider a linear system represented by\footnotemark
\begin{equation}
    y = \mathbf{h}^H\mathbf{P} \mathbf{s} + n.
\end{equation}
\footnotetext{The output is assumed to be a scalar because we focus on MISO systems in the paper. Extension to systems with vector output, such as MIMO systems, is straightforward.}where $n \sim \mathcal{CN}(0,\sigma^2)$, $\mathbf{h}^H\mathbf{P}$ is fixed and known, and $\mathbf{s}$ is an observation of a uniformly distributed random variable on finite support given by $\mathcal{X}$. Let $\mathbf{s}_m$ denote the $m$-th element in $\mathcal{X}$ in a certain order. The mutual information in bits between $\mathbf{s}$ and $y$ is given by
\begin{equation}   I(\mathbf{s};y|\mathbf{h}^H\mathbf{P}) = \log_2(|\mathcal{X}|) - H(\mathbf{s}|y,\mathbf{h}^H\mathbf{P}),
\end{equation}
where $H(\mathbf{s}|y,\mathbf{h}^H\mathbf{P})$ is the conditional entropy of $\mathbf{s}$ given $y$ and $\mathbf{h}^H\mathbf{P}$, and is expressed as \cite{Wu_BC_channel}
\begin{equation}\label{con_entropy}
\begin{split}
    &H(\mathbf{s}|y,\mathbf{h}^H\mathbf{P})\\
    %&= \frac{1}{\ln2} + \frac{1}{|\mathcal{X}|} \sum_{m=1}^{|\mathcal{X}|} \mathsf{E}_n \Big\{ \log_2 \sum_{l=1}^{|\mathcal{X}|} \exp \Big( -\frac{|\mathbf{h}^H\mathbf{P} (\mathbf{s}_m - \mathbf{s}_l) + n|^2}{\sigma^2} \Big) \Big\}.
    &= \frac{1}{\ln2} + \frac{1}{|\mathcal{X}|} \sum_{m=1}^{|\mathcal{X}|} \mathsf{E}_n \Big\{ \log_2 \sum_{l=1}^{|\mathcal{X}|} \exp \Big( -\frac{|\mathbf{h}^H\mathbf{P} \mathbf{d}_{m,l}(\mathcal{X}) + n|^2}{\sigma^2} \Big) \Big\},
\end{split}
\end{equation}
where $\mathbf{d}_{m,l}(\mathcal{X}) = \mathbf{s}_m - \mathbf{s}_l$. With Jensen's inequality and a constant shift, (\ref{con_entropy}) can be approximated by \cite{Zeng_CC_approx}
\begin{equation}\label{con_entropy_approx}
\begin{split}       &H(\mathbf{s}|y,\mathbf{h}^H\mathbf{P})^\text{approx.}\\
    &=\frac{1}{|\mathcal{X}|} \sum_{m=1}^{|\mathcal{X}|} \log_2 \sum_{l=1}^{|\mathcal{X}|} \exp \Big( -\frac{|\mathbf{h}^H\mathbf{P} \mathbf{d}_{m,l}(\mathcal{X})|^2}{2\sigma^2} \Big).
\end{split}
\end{equation}

\subsection{Achievable Rate of RSMA}
