Returning to the RSMA system model described in Section \ref{Section_system_model}, the achievable rate of the common stream at user-$k$, $k\in\mathcal{K}$, can be derived as \cite{Sibo2024}
\begin{equation}\label{CC_rate_common_1}
\begin{split}
    R_{\text{c},k}
    =& I(s_\text{c};y_k|\mathbf{h}_k^H\mathbf{P})\\
    =& I\Big(\{s_\text{c},s_1,...,s_K\} ; y_k \Big| \mathbf{h}_k^H\mathbf{P}\Big)\\
    &- I\Big(\{s_1,...,s_K\} ; y_k \Big| \mathbf{h}_k^H\mathbf{P},s_\text{c}\Big)\\
    =& H(s_\text{c},s_1,...,s_K) - H\Big(s_\text{c},s_1,...,s_K \Big| y_k,\mathbf{h}_k^H\mathbf{P}\Big)\\
    &- H(s_1,...,s_K) + H\Big(s_1,...,s_K \Big| y_k,\mathbf{h}_k^H\mathbf{P},s_\text{c}\Big),
\end{split}
\end{equation}
where the expansion is made from the chain rule of mutual information \cite{Cover}. To ensure that the common stream can be decoded by all the users, the common stream rate depends on the worst-cast user, i.e.
\begin{equation}\label{common_rate}
    R_\text{c} = \min_k R_{\text{c},k}.
\end{equation}
Similarly, for the private stream intended for user-$k$, if the receiver adopts SIC implementation, the achievable rate is expressed as
\begin{equation}\label{CC_rate_private_SIC}
\begin{split}
    &R_{\text{p},k}^{\text{SIC}}\\
    &= I \Big(s_k ; y_k \Big| \mathbf{h}_k^H\mathbf{P},s_\text{c} \Big)\\
    &= H(\{s_k|k\in\mathcal{K}\}) - H \Big(\{s_k|k\in\mathcal{K}\} \Big| y_k - \mathbf{h}_k^H\mathbf{p}_\text{c} s_\text{c},\mathbf{h}_k^H\mathbf{P} \Big)\\
    &\;\;\;\; -H(\{s_{k'}|k'\in\mathcal{K}/k\})\\
    &\;\;\;\; + H \Big(\{s_{k'}|k'\in\mathcal{K}/k\} \Big| y_k - \mathbf{h}_k^H\mathbf{p}_\text{c} s_\text{c}-\mathbf{h}_k^H\mathbf{p}_ks_k,\mathbf{h}_k^H\mathbf{P} \Big).
\end{split}
\end{equation}
With SIC-free receivers, the achievable rate is expressed as
\begin{equation}\label{CC_rate_private_no_SIC}
\begin{split}
    &R_{\text{p},k}^{\text{non-SIC}}\\
    &= I \Big(s_k ; y_k \Big| \mathbf{h}_k^H\mathbf{P} \Big)\\
    %&= I \Big(\{s_\text{c}, s_k\} ; y_k \Big| \mathbf{h}_k^H\mathbf{P} \Big) - I \Big(s_\text{c} ; y_k \Big| \mathbf{h}_k^H\mathbf{P}, s_k \Big)\\
    &= H(s_\text{c}, \{s_k|k\in\mathcal{K}\}) - H \Big(s_\text{c}, \{s_k|k\in\mathcal{K}\} \Big| y_k,\mathbf{h}_k^H\mathbf{P} \Big)\\
     &\;\;\;\;- H(s_\text{c},\{s_{k'}|k'\in\mathcal{K}/k\})\\
     &\;\;\;\; + H \Big(s_\text{c},\{s_{k'}|k'\in\mathcal{K}/k\} \Big| y_k-\mathbf{h}_k^H\mathbf{p}_ks_k,\mathbf{h}_k^H\mathbf{P} \Big).
\end{split}
\end{equation}
Note that the difference between (\ref{CC_rate_private_SIC}) and (\ref{CC_rate_private_no_SIC}) lies in the availability of knowledge on $s_\text{c}$.
The full expressions of $R_{\text{c},k}$,  $R_{\text{p},k}^{\text{SIC}}$ and $R_{\text{p},k}^{\text{non-SIC}}$ are given by (\ref{CC_rate_common_full})-(\ref{CC_rate_private_non_SIC_full}) respectively, where $\mathcal{X}_\text{c}$ is the constellation set used for the common stream, $\mathcal{X}_{\text{p},k}$ is the constellation set used for the private stream intended for the $k$-th user, and $\mathcal{X}_\mathcal{M} \triangleq \prod_{k\in\mathcal{M}}\mathcal{X}_{\text{p},k}$ for certain set $\mathcal{M}$. The approximations of $R_{\text{c},k}$, $R_{\text{p},k}^{\text{SIC}}$ and $R_{\text{p},k}^{\text{non-SIC}}$ are given by (\ref{CC_rate_common_approx})-(\ref{CC_rate_private_non_SIC_approx}) respectively.

