\section{Precoding Optimization}\label{Section_precoding_opt}
In this section, we consider WSR and MMF maximization problems for RSMA with SIC and non-SIC receivers, and propose precoding optimization algorithms to address them.
\subsection{Weighted sum-rate optimization}
The WSR problem can be expressed as
\begin{equation}\label{WSR}
\begin{split}
    \mathcal{P}_1: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \: \: & \sum_{k\in\mathcal{K}} u_k R_{k}^{\text{SIC/non-SIC}}\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}\\
    & \mathbf{c}^T \mathbf{1} = R_\text{c}\\
    & \mathbf{c} \succcurlyeq \mathbf{0},
\end{split}
\end{equation}
where $u_k$, $k\in\mathcal{K}$, denotes the weight assigned to user-$k$, $P_\text{T}$ denotes the transmit power budget, and $\mathbf{c} = [C_1,C_2,...,C_K]$.
\begin{proposition}\label{WSR_prop}
    Let $i \in \arg \max_{k \in \mathcal{K}} u_k$. If $(\mathbf{P}^\star, \mathbf{c}^\star)$ is a solution of $\mathcal{P}_1$, $(\mathbf{P}^\star, \mathbf{c}^{\star'})$ is another solution where $\mathbf{c}^{\star'} = [C_1^{\star'},C_2^{\star'},...,C_K^{\star'}]$ satisfies $C_i^{\star'} = R_\text{c}$ and $C_j^{\star'} = 0, \forall j \in \mathcal{K} \setminus i$.
\end{proposition}
\begin{IEEEproof}
    See Appendix \ref{proof of WSR_prop}.
\end{IEEEproof}

\begin{remark}
    The intuition behind Proposition \ref{WSR_prop} is of significant value for the practical implementation of RSMA, as it implies that when the objective is to maximize the WSR, only splitting the message of the most weighted users (or one of the most weighted users if multiple users are most weighted) is no worse than splitting multiple user messages. In practice, the splitting of messages requires additional implementation and control signaling, making splitting only one message a more favorable option.
\end{remark}

\begin{remark}
    The proof of Proposition \ref{WSR_prop} does not assume any input distribution, which means that Proposition \ref{WSR_prop} holds for arbitrary input distribution, including Gaussian input, and any other distribution for discrete or continuous space.
\end{remark}

As a direct consequence of Proposition \ref{WSR_prop}, one solution of $\mathbf{c}$ can already be determined given $u_k$, $k\in\mathcal{K}$. As a result, $\mathbf{c}$ can be removed from the design variables, and $\mathcal{P}_1$ is simplified into
\begin{equation}\label{WSR_2}
\begin{split}
    \mathcal{P}_2: \;\; \underset{\mathbf{P}}{\max} \: \: & u_{k'} R_\text{c} + \sum_{k\in\mathcal{K}} u_{k'} R_{\text{p},k}^{\text{SIC/non-SIC}}\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T},
\end{split}
\end{equation}
where $k' \in \arg \max_{k \in \mathcal{K}} u_k$.

One challenge in solving $\mathcal{P}_2$ lies in the fact that the expectation in (\ref{con_entropy}) cannot be reduced to an analytical form. One way to address it is to estimate (\ref{con_entropy}) empirically and optimize that estimate, but this can introduce a significant computational burden to algorithms. We adapt an alternative approach by using the approximation given by (\ref{CC_rate_common_approx})-(\ref{CC_rate_private_non_SIC_approx}) during the optimization process. The effectiveness of this approach has been illustrated, for example, in \cite{Zeng_CC_approx, Pei_MAC_channel, Sibo2024,Jin_GQMP}. To tackle the non-convexity and complicated structure of (\ref{con_entropy_approx}) and the discontinuity brought about by the point-wise minimum in (\ref{common_rate}), subgradient method \cite{Rockafellar} is chosen to solve $\mathcal{P}_2$. 

The gradient of (\ref{con_entropy_approx}) is given by
\begin{equation}\label{con_entropy_approx_gradient}
\begin{split}
    &\nabla_\mathbf{P} H(\mathbf{s}|y,\mathbf{h}^H\mathbf{P})^\text{approx.}\\
    &= \frac{\log_2 e}{|\mathcal{X}|}\sum_{m=1}^{|\mathcal{X}|} \frac{1}{\sum_{l=1}^{|\mathcal{X}|} u(\mathbf{P})}\sum_{l=1}^{|\mathcal{X}|} u(\mathbf{P}) \left( -\frac{\mathbf{hh}^H\mathbf{P}\mathbf{d}_{m,l}\mathbf{d}_{m,l}^H}{2\sigma^2} \right),
\end{split} 
\end{equation}
where 
\begin{equation}
    u(\mathbf{P}) = \sum_{l=1}^{|\mathcal{X}|} \exp \Big( -\frac{|\mathbf{h}^H\mathbf{P} \mathbf{d}_{m,l}|^2}{2\sigma^2} \Big).
\end{equation}
Based on (\ref{con_entropy_approx_gradient}), $\nabla_\mathbf{P}R_{\text{c},k}$, $\nabla_\mathbf{P}R_{k}^{\text{SIC}}$ and $\nabla_\mathbf{P}R_{k}^{\text{non-SIC}}$ can be obtained trivially. One subgradient of the weighted sum-rate can be obtained as
\begin{equation}\label{subgrad_WSR}
    g(R_{\text{WSR}}^{\text{SIC/non-SIC}}) =  \max_k u_k\nabla_\mathbf{P}R_{\text{c},k'} + \sum_{k\in\mathcal{K}} u_k\nabla_\mathbf{P}R_{k}^{\text{SIC/non-SIC}},
\end{equation}
where $k' = \arg \min_{k\in\mathcal{K}} R_{\text{c},k}$.

It is easy to see that any solution of $\mathcal{P}_2$, $\mathbf{P}^\star$, must satisfy $\|\mathbf{P}^\star\|_\text{F}^2 = P_\text{T}$. We therefore use the projection of $\mathbf{P}$ in $\{\mathbf{P} \big| \|\mathbf{P}\|_\text{F}^2 = P_\text{T}\}$ as the updated solution after every iteration. The proposed Projected SubGradient Ascent (PSGA) algorithm is summarized in Algorithm \ref{SR_opt_alg}\footnote{In Algorithm \ref{SR_opt_alg}, depending on the assumption about receivers, $R_\text{WSR} = R_{\text{WSR}}^{\text{SIC}} \text{ or } R_{\text{WSR}}^{\text{non-SIC}}$.}. For choosing step length, $t$, we use a modified backtracking line search specific for PSGA as described in Algorithm \ref{Modified_backtracking}. Compared to the classical backtracking for gradient descent/ascent, the proposed backtracking method incorporates projection when evaluating the predicted objective value after updating, ensuring a non-decreasing sequence of objectives. The convergence of general projected gradient methods is discussed in \cite{Luenberger}, although the convergence rate of PSGA for non-convex problems is generally difficult to prove. Note that Algorithm \ref{Modified_backtracking} leads to non-decreasing variation to the objective function, and the objective function of (\ref{WSR}) is upper bounded, therefore, Algorithm \ref{SR_opt_alg} is guaranteed to converge. The convergence is also numerically evaluated in Figure \ref{SR_Convergence}, where a monotonic increase in the objective function and the convergence can be observed.

\begin{algorithm}[!t]
    \caption{Projected Subgradient Ascent for Weight Sum-rate Maximization}
    \label{SR_opt_alg}
    \begin{algorithmic}[1]
        \REQUIRE $P_\text{T}$, $\mathcal{X}_\text{c}$, $\mathcal{X}_k$, $\mathbf{h}_k$, $k\in\mathcal{K}$, $\epsilon$, $v_\text{max}$.
        \ENSURE $\mathbf{P}^\star$
        \STATE Initialize $\mathbf{P}^0$.
        \STATE $v:=0$.
        \STATE Update. $R_{\text{WSR}}^{v} := R_{\text{WSR}}(\mathbf{P}^{v})$.
        \REPEAT
            \STATE $\Delta\mathbf{P} := g( R_{\text{WSR}})$ according to (\ref{subgrad_WSR}).
            \STATE Choose step size $t$ via Algorithm \ref{Modified_backtracking}.
            \STATE Update. $\mathbf{P}^{v+1} := \mathbf{P}^v + t \Delta\mathbf{P}$.
            \STATE Projection. $\mathbf{P}^{v+1} := \frac{\sqrt{P_\text{T}}}{\|\mathbf{P}^{v+1}\|_\text{F}}\mathbf{P}^{v+1}$.
            \STATE Update. $R_\text{WSR}^{v+1} := R_\text{WSR}(\mathbf{P}^{v+1})$.
            \STATE $v:=v+1$.
        \UNTIL $\mid R_\text{WSR}^{v} - R_\text{WSR}^{v-1} \mid\; < \epsilon$ or $v \geq v_\text{max}$.
        %\RETURN $\mathbf{P}^\star := \mathbf{P}^{v+1}$.
        \RETURN $\mathbf{P}^\star := \mathbf{P}^{v}$.
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[!t]
    \caption{Backtracking Line Search for PSGA}
    \label{Modified_backtracking}
    \begin{algorithmic}[1]
        \REQUIRE $\Delta\mathbf{P}$, $f(\cdot)$\footnotemark, $P_\text{T}$, $\alpha\in(0,0.5)$, $\beta\in(0,1)$ and $t_\text{min}$.
        \ENSURE $t$
        \STATE $t:=1$.
        \WHILE{$f(\frac{\sqrt{P_\text{T}}}{\|\mathbf{P}+t\Delta\mathbf{P}\|_\text{F}}(\mathbf{P}+t\Delta\mathbf{P})) \leq f(\mathbf{P}) + \alpha t\|\Delta\mathbf{P}\|^2_\text{F}$ \AND $t>t_\text{min}$,}
        \STATE{$t := \beta t$.}
        \ENDWHILE
        \IF{$t \leq t_\text{min}$,}
        \STATE {$t:=0$.}
        \ENDIF
        \RETURN $t$
    \end{algorithmic}   
\end{algorithm}

\footnotetext{$f(\cdot)$ refers to the objective function of interest. It is kept general here, as Algorithm \ref{Modified_backtracking} will be reused later to solve the MMF problem.}

\subsection{Max-min fairness optimization}
We now consider an MMF problem as follows:
\begin{equation}\label{Max_min}
\begin{split}
    \mathcal{P}_3: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \: \: & \min_{k\in\mathcal{K}}\: \: R_k^\text{SIC/non-SIC}\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}\\
    & \mathbf{c}^T \mathbf{1} = R_\text{c}\\
    & \mathbf{c} \succcurlyeq \mathbf{0}.
\end{split}
\end{equation}

Note that $\mathcal{P}_3$ is also a non-convex problem and hence is difficult to solve. To develop efficient algorithms for $\mathcal{P}_3$, we decouple it into the following two sub-problems,
\begin{equation}\label{Max_min_sub_c}
\begin{split}
    \mathcal{P}_4: \;\; \underset{\mathbf{c}}{\text{max}} \: \: & \min_{k\in\mathcal{K}}\: \: R_k(\mathbf{c};\mathbf{P})\\ 
    \text{s.t.} \: \: \: \;
    & \mathbf{c}^T \mathbf{1} = R_\text{c}\\
    & \mathbf{c} \succcurlyeq \mathbf{0},
\end{split}
\end{equation}
and
\begin{equation}\label{Max_min_sub_P}
\begin{split}
    \mathcal{P}_5: \;\; \underset{\mathbf{P}}{\text{max}} \: \: & \min_{k\in\mathcal{K}}\: \: R_k(\mathbf{P};\mathbf{c})\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T},
\end{split}
\end{equation}
where $R_k(\mathbf{c};\mathbf{P})$ indicates the case where 
$R_k^\text{SIC/non-SIC}$ is determined with 
$\mathbf{P}$ as a given parameter and 
$\mathbf{c}$ as a variable, whereas $R_k(\mathbf{P};\mathbf{c})$ indicates the case in which $\mathbf{c}$ is given and $\mathbf{P}$ is the variable. Hence, $\mathcal{P}_4$ optimizes $\mathbf{c}$ with a fixed $\mathbf{P}$ while $\mathcal{P}_5$ optimizes $\mathbf{P}$ with a given $\mathbf{c}$. 

Note that $\mathcal{P}_4$ is linear programming; therefore, its global optimal solution can be efficiently obtained. In particular, we developed a closed-form solution as in Proposition \ref{c_opt_prop}.

\begin{proposition}\label{c_opt_prop}
    The global optimal solution of $\mathcal{P}_4$ is given in closed form by Algorithm \ref{c_opt alg}.
\end{proposition}
\begin{IEEEproof}
    See Appendix \ref{proof of c_opt_prop}.
\end{IEEEproof}

\begin{algorithm}[!t]
    \caption{Global Optimal Common Stream Allocation}
    \label{c_opt alg}
    \begin{algorithmic}[1]
        \REQUIRE $R_\text{c}$, $R_{\text{p},k}$, $k\in\mathcal{K}$.
        \ENSURE $\mathbf{c}^\star$
        \STATE $k':=K+1$.
        \REPEAT 
            \STATE $k':=k'-1$.
            \STATE $\mathbf{d} :=[R_{\text{p},1},...,R_{\text{p},k'}]^T$.
            \STATE $\eta := \frac{R_\text{c}+\mathbf{1}^T\mathbf{d}}{k'}$.
            \STATE $\mathbf{c}' := \eta \mathbf{1} -\mathbf{d}$.
        \UNTIL $\mathbf{c}'\succcurlyeq 0$.
        \RETURN $\mathbf{c}^\star := [\mathbf{c}'^T,\; \mathbf{0}_{1\times (K-k'+1)}]^T$.
    \end{algorithmic}
\end{algorithm}

To remove the discontinuity caused by the point-wise minimum in $\mathcal{P}_5$, we apply a log-sum-exp approximation to its objective function and consider $\mathcal{P}_6$.
\begin{equation}\label{Max_min_LSE}
\begin{split}
    \mathcal{P}_6: \;\; \underset{\mathbf{P}}{\text{max}} \: \: & \frac{1}{\gamma}\log \sum_{k\in\mathcal{K}} \exp \big(\gamma R_k(\mathbf{P};\mathbf{c})\big)\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}.
\end{split}
\end{equation}
 The gap between point-wise minimum and its log-sum-exp approximation is characterized by the following \cite{Chen_2013},
 \begin{equation}
     0\leq \min_{1\leq i \leq L} f_i - \frac{1}{\gamma}\log\sum_i\exp(\gamma f_i) \leq \frac{1}{\gamma}\log L,\;\;\; \gamma < 0.
 \end{equation}

Let $R_\text{max-min}$ denotes the objective function in (\ref{Max_min_LSE}). One subgradient of $R_\text{max-min}$ w.r.t. $\mathbf{P}$ is derived to be
\begin{equation}\label{subgrad_MM_1}
    g(R_\text{max-min}) = \frac{1}{\gamma}\frac{\sum_{k\in\mathcal{K}} \gamma\exp \big(\gamma R_k(\mathbf{P};\mathbf{c})\big) g\big(R_k(\mathbf{P};\mathbf{c})\big)}{\sum_{k\in\mathcal{K}} \exp \big(\gamma R_k(\mathbf{P};\mathbf{c})\big)},
\end{equation}
where
\begin{equation}\label{subgrad_MM_2}
    g(R_k) = c_k\nabla_\mathbf{P} R_{\text{c},k'} + \nabla_\mathbf{P} R_{\text{p},k},
\end{equation}
and $k'= \arg \min_k R_{\text{c},k}$.
Similar to $\mathcal{P}_2$, $\mathcal{P}_6$ can also be solved using PSGA. The solution of (\ref{Max_min}) is obtained by updating the solution for $\mathcal{P}_4$ and $\mathcal{P}_6$ alternatively and the procedures are summarized in Algorithm \ref{GD for Max_min opt}. Note that updating $\mathcal{P}_6$ does not decrease the objective function due to Algorithm \ref{Modified_backtracking}, and updating $\mathcal{P}_4$ also does not decrease the objective function because Algorithm \ref{c_opt alg} leads to the global optimum. Hence, updating between $\mathcal{P}_4$ and $\mathcal{P}_6$ only leads to non-decreasing objective functions. It is trivial to see that the objective function of (\ref{Max_min}) is upper bounded and therefore Algorithm \ref{GD for Max_min opt} is guaranteed to converge.

\begin{algorithm}[!t]
    \caption{Subgradient Ascent with Projection for MMF Optimization}
    \label{GD for Max_min opt}
    \begin{algorithmic}[1]
        \REQUIRE $P_\text{T}$, $\mathcal{X}_\text{c}$, $\mathcal{X}_k$, $\mathbf{h}_k$, $k\in\mathcal{K}$, $\gamma$, $\epsilon$, $v_\text{max}$.
        \ENSURE $\mathbf{P}^\star$ and $\mathbf{c}^\star$
        \STATE Initialize $\mathbf{P}^0$.
            \STATE $v:=0$.
            \REPEAT
                \STATE Update $R_\text{c}$, $R_{\text{p},k}$ based on $\mathbf{P}^v$.
                \STATE Update $\mathbf{c}$ using Algorithm \ref{c_opt alg}.
                \STATE $\Delta\mathbf{P} := g( R_\text{max-min})$ according to (\ref{subgrad_MM_1}) and (\ref{subgrad_MM_2}).
                \STATE Choose step size $t$ via Algorithm \ref{Modified_backtracking}.
                \STATE Update. $\mathbf{P}^{v+1} := \mathbf{P}^v + t \Delta\mathbf{P}$.
                \STATE Projection. $\mathbf{P}^{v+1} := \frac{\sqrt{P_\text{T}}}{\|\mathbf{P}^{v+1}\|_\text{F}}\mathbf{P}^{v+1}$.
                \STATE Update. $R_\text{max-min}^{v+1} := R_\text{max-min}(\mathbf{P}^{v+1})$.
                \STATE $v:=v+1$.
            \UNTIL $\mid R_\text{max-min}^{v} - R_\text{max-min}^{v-1} \mid\; < \epsilon$ or $v \geq v_\text{max}$.
        \RETURN $\mathbf{P}^\star := \mathbf{P}^{v}$, $\mathbf{c}^\star = \mathbf{c}$.
    \end{algorithmic}
\end{algorithm}
