\section{Proof of Proposition \ref{WSR_prop}}\label{proof of WSR_prop}
If $\{u_1,...,u_K\}$ are all of the same value, it is trivial to see that $\mathbf{c}$ does not affect the objective function of $\mathcal{P}_1$. Hence, $C_i = R_\text{c}$ and $C_j = 0$, $\forall j \in \mathcal{K} \setminus i$, is one solution for $\mathbf{c}$ in $\mathcal{P}_1$.
If $\{u_1,...,u_K\}$ are of different values, we need the following lemma.

\begin{lemma}\label{WSR_lemma}
If $u_i > u_j$, $\forall j \in \mathcal{K}\setminus i$, for a given $\mathbf{P}$, one optimal $\mathbf{c}$ of $\mathcal{P}_1$ satisfies $C_i^\star = R_\text{c}$ and $C_j^\star = 0, \forall j \in \mathcal{K} \setminus \{i\}$.
\end{lemma}

\begin{IEEEproof}[Proof of Lemma \ref{WSR_lemma}]
Since $\mathbf{P}$ is given and the private rates, $R_{\text{p},k}, \forall k\in \mathcal{K}$, are not functions of $\mathbf{c}$, $\mathcal{P}_1$ is equivalent to
\begin{equation}
\begin{split}
    \underset{\mathbf{c}}{\text{max}} \: \: & \sum_{k\in \mathcal{K}} u_k C_k\\ 
    \text{s.t.} \: \: \: \;
    & \sum_{k\in \mathcal{K}} C_k \leq R_\text{c}\\
    & \mathbf{c} \geq \mathbf{0},
\end{split}
\end{equation}
which is a simple linear programming and it is easy to see that Lemma \ref{WSR_lemma} is true.
\end{IEEEproof}

Suppose $(\mathbf{P}^\star, \mathbf{c}^\star)$ is optimal in $\mathcal{P}_1$, and $\mathbf{c}^\star$ does not satisfy $C_i = R_\text{c}$ and $C_j^\mathcal{K} = 0, \forall j \in \mathcal{K} \setminus i$. Then, according to Lemma \ref{WSR_lemma}, we can always find another $\mathbf{c}$ that gives a higher WSR than $\mathbf{c}^\star$ given that $\mathbf{P}=\mathbf{P}^\star$ in $\mathcal{P}_1$. By contradiction, $\mathbf{c}^\star$ must satisfy $C_i = R_\text{c}$ and $C_j = 0$, $\forall j \in \mathcal{K} \setminus i$. 

In the cases where $\arg \max_{k \in \mathcal{K}} u_k$ is a set of more than one element, a trivial extension of the above reasoning implies that any $\mathbf{c}$ allocating zero rate to users who are not most weighted is an optimal solution. This includes $C_i^\star = R_\text{c}$ and $C_j^\star = 0, \forall j \in \mathcal{K} \setminus i$, where $i \in \arg \max_{k \in \mathcal{K}} u_k$.

\section{Proof of Proposition \ref{c_opt_prop}}\label{proof of c_opt_prop}
$\mathcal{P}_4$ can be written as follows
\begin{equation}
\begin{split}
    \mathcal{P}_{7}:\;\; \max_{\mathbf{c}}&\;\; \min_k C_k + R_{\text{p},k}\\
    \text{s.t.}&\;\;\;\; \mathbf{c} \succcurlyeq \mathbf{0},\\
    &\;\;\;\; \mathbf{1}^T \mathbf{c} = R_\text{c}.\\
\end{split}
\end{equation}

We introducing a slack variable, $\eta$, and convert $\mathcal{P}_{7}$ into
\begin{equation}
\begin{split}
    \mathcal{P}_{8}:\;\; \max_{\mathbf{c},t}&\;\;\;\;\;\; \eta\\
    \text{s.t.}&\;\;\;\; \mathbf{c} \succcurlyeq \mathbf{0},\\
    &\;\;\;\; \mathbf{1}^T \mathbf{c} = R_\text{c}.\\
    &\;\;\;\; C_k + R_{\text{p},k} \geq \eta, \forall k.
\end{split}
\end{equation}

Let $(\mathbf{c}^\star,\eta^\star)$ denote the solution of $\mathcal{P}_{8}$.
Without loss of generality, we assume $R_{\text{p},1}<R_{\text{p},2}<...<R_{\text{p},K}$, and the solution of $\mathcal{P}_{8}$ leads to $C_k^\star>0$ for $k=1,...,k'$ with $1\leq k'\leq K$, and $C_k^\star=0$ for $k=k'+1,...,K$. We have the following lemma.
\begin{lemma}\label{common_allocation_lemma}
    $C_k^\star + R_{\text{p},k} = \eta^\star$ for $k=1,...,k'$ and some value for $\eta^\star$.
\end{lemma}
\begin{IEEEproof}
    It is trivial to see that $R_{\text{p},k'}<\eta^\star$. Let $\mathcal{K}_1$ and $\mathcal{K}_2$ be a partition of $\{1,...,k'\}$. Suppose $(\mathbf{c}^\star,\eta^\star)$ leads to $C^\star_k + R_{\text{p},k} > \eta^\star$ for $k\in\mathcal{K}_1$, and $C^\star_k + R_{\text{p},k} = \eta^\star$ for $k\in\mathcal{K}_2$. Then, another choice of $\mathbf{c}$, denoted by $\mathbf{c}^{\diamond}$, can be found by $\mathbf{c}^\diamond=\alpha\mathbf{c^\circ}$, where $C^\circ_k=(C^\star_k - R_{\text{p},k} + \eta^\star)/2$ for $k\in\mathcal{K}_1$, $C^\circ_k=C_k^\star$ for $k\in\mathcal{K}_2$, and $\alpha = R_\text{c}/\mathbf{1}^T \mathbf{c}^\circ$. It is trivial to see that $\alpha>1$. Therefore, $\min_{k\in\{1,...,k'\}} C^\diamond_k + R_{\text{p},k} > \min_{k\in\{1,...,k'\}} C^\star_k + R_{\text{p},k}$, which indicates that $\mathbf{c}^\star$ is not the solution of $\mathcal{P}_{11}$. By contradiction, Lemma \ref{common_allocation_lemma} is proved.
\end{IEEEproof}

Lemma \ref{common_allocation_lemma} can be re-written as
\begin{equation}\label{linear equation}
    \mathbf{c}' + \mathbf{d} = \eta\mathbf{1},
\end{equation}
where $\mathbf{d}=[R_{\text{p},1},...,R_{\text{p},k'}]^T$, and $\mathbf{c}'=[C_1,...,C_{k'}]$. Combining (\ref{linear equation}) and the constraint on $\mathbf{1}^T \mathbf{c} = R_\text{c}$, the global optimal solution of $\mathbf{c}'$ and $\eta$, denoted by $\mathbf{c}'^\star$ and $\eta^\star$, can be then obtained by
\begin{equation}\label{c_opt}
    \mathbf{c}'^\star = \eta^\star\mathbf{1} -\mathbf{d},
\end{equation}
and
\begin{equation}\label{t_opt}
    \eta^\star = \frac{R_\text{c}+\mathbf{1}^T\mathbf{d}}{k'}.
\end{equation}

Although $k'$, i.e. the number of users whose are strictly served by the common stream, is still not known, we can test it using (\ref{c_opt}) and (\ref{t_opt}). This is because allocating the common stream rate based on (\ref{c_opt}) and (\ref{t_opt}) to more users than $k'$ will lead to $\mathbf{c}'$ containing negative entries, which is infeasible. Hence, by iteratively guessing the number of users to be served by the common stream, Alg. \ref{c_opt alg} is obtained.

