\begin{rem}\label{rem:heuristic}
   Let us end with some heuristic about regular singular equation, by explaining why the operator $M=
     z^8-(z^2+z^3+\alpha z^7)\phi_2+(1+z)\phi_2^2$ from Remark \ref{rem:inverse} is not regular singular at $0$ when $\alpha \neq 1$ while it is when $\alpha=1$. The associated Newton polygon has two slopes, $-6$ and $-1$ with multiplicity one and exponent $c=1$. We know that there is a truncated solution associated with the first slope, from Lemma~\ref{lem:first_slope} below. Assume that there is a truncated solution associated with the second slope. We choose its coefficients by induction. From Condition \ref{C4}, it would have valuation $1$. For any non-zero $a \in \K[[\lambda-1]]$, 
     $$
     M_\lambda(az^1)\equiv (1-\alpha)az^9 \mod (\lambda- 1).
     $$
     When $\alpha \neq 1$ the first slope of the Newton polygon of the inhomogeneous equation $M(y)=-(1-\alpha)az^9$ is equal to $\frac{7}{2}$. Since its denominator is not coprime with $2$, we cannot build this truncated solution. Thus, the operator is not regular singular at $0$. On the contrary, when $\alpha=1$, such an obstruction does not exists and we can build this truncated solution. Thus, the operator is regular singular at $0$. Since the Newton polygon does not depend on the value of $\alpha$, this emphasizes the fact that, contrary to the differential case, the property of being regular singular cannot be read from the Newton polygon associated with a Mahler equation.
    \end{rem}
    \begin{rem}\label{rem:g_cj}
    Continue with the operator $M$ and set $\alpha=1$ so that the equation is regular singular at $0$. Consider the function $g_{1,2}(\lambda,z)$ associated with $c=1$ and with the second slope $\mu_2=-1$. One can check that
    $$
g_{1,2}(\lambda,z) = \frac{\lambda-1}{\lambda}z+\frac{(\lambda-1)^2}{\lambda}z^{\frac{3}{2}} + \mathcal O(z^2)\,.
    $$
    Since the least common denominator $d$ of the slopes of $\mathcal N(M)$ is equal to $1$ and since $g_{1,2}\notin \K((z))(\lambda)$, $g_{1,2}$ is not a Puiseux series in $z$, although the equations is regular singular at $0$.
    \end{rem}


\section{Newton polygons with one slope}\label{sec:oneslope}
As an application of Theorem \ref{thm_RS_si_solutions_tronquees}, we study here the case of equations whose Newton polygon has only one slope.
We prove that they are always regular singular at $0$.
\begin{prop}\label{prop:one_slope}
   Consider a $p$-Mahler equation over $\Puis$ of the form \eqref{eq:Mahler_at_0} for which the associated Newton polygon has only one slope. Then the Mahler equation is regular singular at $0$.
 \end{prop}

The proposition immediately follows from Theorem \ref{thm_RS_si_solutions_tronquees} and the following lemma.

\begin{lem}\label{lem:first_slope}
   Consider a $p$-Mahler equation over $\Puis$ of the form \eqref{eq:Mahler_at_0}. Let $c$ be an exponent attached to the first slope $\mu_1$ of the associated Newton polygon. Then, the unique solution $g_{c,1}(\lambda,z)$ of Equation \eqref{eq:g_cj} belongs to $\Puis_{\K(\lambda)}$.
\end{lem}
In particular, for any $c$ attached to the first slope, there exists a truncated series $f_{c,1}$ associated with $(c,1)$.
\begin{proof}
By definition of $\theta_1$, introduced at the beginning of Section \ref{sec:Frobenius}, we have $\theta_1=\val a_0 - \mu_1$. Let $r_{c,1}(\lambda) $  be defined by \eqref{eq:cld}. Set 
    $$a_\infty(\lambda,z) = -L_{\lambda}( r_{c,1}(\lambda,z)z^{-\mu_1})+z^{\theta_1}(\lambda - c)^{s_{c,j}+m_{c,j}}.$$
    By \eqref{eq:g_cj-bis}, we have $\val a_\infty(\lambda,z) > \theta_1=\val(a_0(z)) - \mu_1$ and it follows from Lemma~\ref{lem:solutions_inhomo_Puiseux} that the equation
    $  L_{\lambda}(y)=a_\infty(\lambda,z)$ has a Puiseux solution $h \in \Puis_{\K(\lambda)}$.  
Then
     \begin{align*}
     L_{\lambda}(r_{c,1}z^{-\mu_1} + h)&=L_{\lambda}( r_{c,1}(\lambda,z)z^{-\mu_1})+L_{\lambda}(h)
     \\&=L_{\lambda}(r_{c,1}(\lambda,z)z^{-\mu_1})+a_\infty(\lambda,z)
     \\&=z^{\theta_1}(\lambda - c)^{s_{c,j}+m_{c,j}} \,.
     \end{align*}
     Thus
    $r_{c,1}z^{-\mu_1} + h$ satisfies \eqref{eq:g_cj}. Since, from \cite[Proposition 22]{Ro23}, there is only one solution to \eqref{eq:g_cj}, we have $r_{c,1}z^{-\mu_1} + h=g_{c,1}$. In particular, $g_{c,1}(\lambda,z)\in \Puis_{\K(\lambda)}$.
\end{proof}

\begin{rem}\label{rem:Fuchsian}
An equation is said to be \textit{Fuchsian at $0$} if the associated companion matrix $A_L$, defined by \eqref{eq:companion_matrix}, is well-defined and non-singular at $0$. It is not difficult to prove that the following assertions are equivalent:
 \begin{itemize}
        \item the equation is Fuchsian at $0$;
        \item the associated Newton polygon has only one slope which is null;
        \item $\val a_0 = \val a_m =\min_{0\leq i \leq m}\val a_i$.
\end{itemize}
\end{rem}




\section{Regular singularity at \texorpdfstring{$0$}{0} for large \texorpdfstring{$p$}{p} }\label{sec:p_grand}


Consider a $p$-Mahler equation \eqref{eq:Mahler_at_0} with $a_i \in \K[[z]]$ and $p> \max_i(\val(a_i))$. Suppose that the equation is regular singular at $0$. According to Corollary \ref{coro:sensdirect}, one of the following holds: 
\begin{itemize} 
\item the Newton polygon has only one slope;
\item it has exactly two slopes, the second one being null.
\end{itemize} 
This section is organized as follows. We first prove Corollary \ref{coro:sensdirect}. The case when the Newton polygon has only one slope was the subject of the previous section. We study the case with two slopes in Section \ref{sec:twoslopes}. Finally, we prove Theorem \ref{thm:p_varies}.

\subsection{Proof of Corollary \ref{coro:sensdirect}}

Suppose that the Newton polygon of the equation has two slopes or more. The left and right endpoints of the edge corresponding to the second slope are respectively  $(p^i,\val a_i)$ and $(p^j,\val a_j)$, for some integers $i,j$ with $1 < i < j \leq m$. The associated slope is
$$
\mu_2=\frac{\val a_j - \val a_i}{p^j - p^i}\,.
$$
Since the system is regular singular at $0$, it follows from Theorem \ref{thm:slopes} that the denominator of $\mu_2$ is relatively prime with $p$. Thus, $p$ must divide $\val a_j - \val a_i$. However, since $p>\max\{\val a_j,\val a_i\}$, we must have $\val a_i=\val a_j$, that is $\mu_2 = 0$. 

Suppose that there is a third slope.  Arguing as previously, we obtain $\mu_3=0$, which contradicts the fact that $\mu_3 > \mu_2$.
Thus, the Newton polygon has at most two slopes and, in that case, it follows from the first part of the proof that its second slope is null.

\qed


\subsection{Newton polygons with two slopes}\label{sec:twoslopes}
In this section, we consider a $p$-Mahler equation \eqref{eq:Mahler_at_0} and its associated operator $L$, which satisfy the following assumptions :
\begin{itemize}
    \item[$\rm (i)$] $a_i(z) \in \K[[z]]$ ;
    \item[$\rm (ii)$] $p> \max_i \val(a_i)$ ;
    \item[$\rm (iii)$] the Newton polygon $\mathcal N(L)$ has two slopes, the second one being null.
\end{itemize}

Without loss of generality, we may also assume $\min_i \val a_i=0$, otherwise we may divide each of the power series $a_j$ with $z^{\min_i\val a_i}$. We let $k\in [1,m-1]$ be the integer such that the point $(p^k,\val(a_k))$ is the right endpoint of the edge corresponding to the first slope. Since $\mathcal N(L)$ has two slopes and the second slope is null, we have $\val(a_k)=\val(a_m)=0$ and $\val a_0 \geq 1$.

For every integer $i\in [0,m]$, we write $a_i(z)=\sum_{n=0}^\infty a_{i,n}z^n$ and let
$$
\underline{a_i}(z):=\sum_{n=0}^{\val(a_0)} a_{i,n}z^n\, .
$$ 
Recall that $k\in [1,m-1]$ and $1\leq \val(a_0)<p$. Since $\frac{\val(a_0)}{p^k-1}=-\mu_1$, we have $-\mu_1\in(0,1]$. Moreover $-\mu_1 = 1$ if and only if $ k=1$ and $ \val(a_0) = p-1$.

\begin{prop}\label{prop:a_m_tronques}
   We continue with the assumptions $\rm (i)$ to $\rm (iii)$. 
The equation~\eqref{eq:Mahler_at_0} is regular singular at $0$ if and only if for any exponent $c$ attached to the slope $\mu_2=0$, we have
    \begin{equation}
        \label{eq:condition2slopes}
       \sum_{i=0}^m \underline{a_i}(z)\lambda^i
    \in (\lambda - c)^{m_{c,2}}\K[\lambda,z].
    \end{equation}  
\end{prop}
\begin{proof}

We consider the operator
$$
\underline{L}:=\underline{a_m}(z)\puip^m + \cdots +\underline{a_1}(z)\puip+ \underline{a_0}(z)\,,
$$
so that we may write
$$
L = \underline{L} + z^{\val(a_0)+1}\overline{L} \, ,
$$
for some operator $\overline{L}$ over $\K[[z]]$. With this notation, \eqref{eq:condition2slopes} can be rewritten
\begin{equation}
        \label{eq:condition2slopes-bis}
\underline{L}_\lambda(1)  \in (\lambda - c)^{m_{c,2}}\K[\lambda,z] \,.
\end{equation}
Assume that \eqref{eq:Mahler_at_0} is regular singular at $0$ and let $c$ be attached to $\mu_2$. From Theorem~\ref{thm_RS_si_solutions_tronquees} there exists a truncated solution $f_{c,2}$ associated with $(c,2)$. The least common multiple of the
denominators of the slopes is in this case $d = p^k-1$, the denominator of the first slope. Using Condition \ref{C2}, we can write
$$
f_{c,2}(\lambda,z) = p_0(\lambda) + zp_{1}(\lambda)+ \underbrace{q_1(\lambda)z^{\frac{1}{p^k-1}} + \cdots + q_{p^k}(\lambda) z^{\frac{p^k}{p^k-1}}}_{=:q(\lambda,z)}  \, .
$$
Let $\gamma \in \mathbb Q$ have some denominator $\delta$ relatively prime with $p$. Then, the operator $\underline{L}_\lambda$ sends $z^{\gamma}$ to a linear combination over $\K[\lambda]$ of some $z^\mu$, with $\mu \in \mathbb Q$ some rational numbers whose denominators are also equal to $\delta$. Thus, the only terms which are integer powers of $z$ in the sum 
$$
\underline{L}_\lambda(f_{c,2}(\lambda,z)) = p_0(\lambda)\underline{L}_\lambda(1) + p_1(\lambda)\underline{L}_\lambda(z)+ \underline{L}_\lambda(q(\lambda,z))
$$
 are the one coming from $p_0(\lambda)\underline{L}_\lambda(1) + p_1(\lambda)\underline{L}_\lambda(z)$. Since $f_{c,2}$ satisfies \ref{C1} and since $-\mu_1>0$ it follows that
\begin{equation}\label{eq:val_underline_L}
\val \left(p_0(\lambda)\underline{L}_\lambda(1) + p_1(\lambda)\underline{L}_\lambda(z)\ \, \rm mod\,(\lambda -c)^{s_{c,2}+m_{c,2}}\right) > \val a_0\,.
\end{equation}
Let us prove that
\begin{equation}\label{eq:val_underline_L_0}
\val \left(p_0(\lambda)\underline{L}_\lambda(1)\ \, \rm mod\, (\lambda -c)^{s_{c,2}+m_{c,2}}\right) \geq \val a_0+1>\val a_0\,.
\end{equation}
It is immediate when $p_1(\lambda)=0$. When $p_1\neq 0$, then $-\mu_1=1$ and we must have $k=1$ and $\val a_0 = p-1$. Thus
$$\val(p_1(\lambda)\underline{L}_\lambda(z)) \geq p = \val a_0+1=\val a_0 - \mu_1\,.$$
Thus, \eqref{eq:val_underline_L_0} follows from \eqref{eq:val_underline_L}. 

Since the degree in $z$ of $\underline{L}_\lambda$ is at most $\val a_0$, \eqref{eq:val_underline_L_0} implies that 
\begin{equation}\label{eq:p0_null}
p_0(\lambda)\underline{L}_\lambda(1)  \mod (\lambda -c)^{s_{c,2}+m_{c,2}}=0\,.
\end{equation}
Thus
\begin{equation}
\label{eq:simplif}
    p_0(\lambda)\underline{L}_\lambda(1) = (\lambda-c)^{s_{c,2}+m_{c,2}}Q(\lambda,z)\quad \text{ for some } Q(\lambda,z)\in \K[\lambda,z]\, .
\end{equation}
However, $p_0(\lambda)=\cld(f_{c,2}(\lambda,z))$. Then, it follows form \ref{C3} and the definition of $r_{c,2}(\lambda)$ that ${\rm val}_{\lambda-c}p_0(\lambda)=s_{c,2}$. Dividing by $p_0(\lambda)$ in \eqref{eq:simplif}, we obtain \eqref{eq:condition2slopes-bis}.


\medskip
Let us now prove the converse implication. Assume that \eqref{eq:condition2slopes} holds. Assume first that $-\mu_1<1$. Let us check that $f_{c,2}(\lambda,z)=r_{c,2}(\lambda) \mod (\lambda-c)^{m_{c,2}+s_{c,2}}$ is a truncated solution associated with $(c,2)$ (though it does not depend on $z$):
\begin{itemize}
    \item It follows from \eqref{eq:condition2slopes} 
    and the fact that ${\rm val}_{\lambda - c}(f_{c,2}(\lambda,z)) \geq s_{c,2}$
    that \ref{C1} is satisfied;
    \item Conditions \ref{C2}, \ref{C3} and \ref{C5} are trivially satisfied;
    \item Condition \ref{C4} follows from the fact that $\mu_2=0$.
\end{itemize}
Assume now that $-\mu_1\geq 1$. Since $-\mu_1 \leq 1$ (see the explanation before Proposition \ref{prop:a_m_tronques}), then $-\mu_1=1$ and $\val a_0=p-1$. Write $r_{c,2}(\lambda)=\theta(\lambda)(\lambda - c)^{s_{c,2}}$, with $\theta(\lambda)\in \K[[\lambda-c]]$. By definition of the characteristic polynomial $\chi_1$, we may write $\chi_1(\lambda)=\kappa(\lambda)(\lambda-c)^{s_{c,2}}$ with $\kappa(\lambda) \in \K[\lambda-c]$ such that $\kappa(c)\neq 0$. We claim that
 $$f_{c,2}(\lambda,z) := r_{c,2}(\lambda) - z \theta(\lambda)\kappa(\lambda)^{-1} \sum\limits_{i=0}^m a_{i,p}\lambda^i  \mod (\lambda-c)^{m_{c,2}+s_{c,2}}$$ 
is a truncated solution associated with $(c,2)$. Let us check this.
\begin{itemize}
    \item Since $-\mu_1=1$, $\cld L_\lambda(z)=\chi_1(\lambda)$, by Lemma \ref{lem:chi}. Furthermore, $\val L_\lambda(z)=~p$. Thus, modulo $(\lambda-c)^{m_{c,2}+s_{c,2}}$ and modulo $z^{p+1}=z^{\val a_0-\mu_1+1}$, the following holds
    $$
    L_\lambda(f_{c,2}(\lambda,z))\equiv r_{c,2}(\lambda)\left(L_\lambda(1) - z^p\sum\limits_{i=0}^m a_{i,p}\lambda^i \right)\equiv r_{c,2}(\lambda)\underline{L}_\lambda(1) \equiv 0.
    $$
    Let us prove the first congruence. We have $$L_\lambda(f_{c,2}(\lambda,z)) = r_{c,2}(\lambda)L_{\lambda}(1) -  \big(\theta(\lambda)\kappa(\lambda)^{-1} \sum\limits_{i=0}^m a_{i,p}\lambda^i \mod (\lambda-c)^{m_{c,2}+s_{c,2}}\big) L_\lambda(z)\, .$$
    Moreover, $L_\lambda(z)$ is $\chi_1(\lambda)z^p$ modulo $z^{p+1}$, that is $\kappa(\lambda)(\lambda - c)^{s_{c,2}} z^p$ and we conclude using the definition of $\theta(\lambda)$: $r_{c,2}(\lambda)=\theta(\lambda)(\lambda - c)^{s_{c,2}}$.
   The last congruence above follows from the fact that ${\rm val}_{\lambda - c}(r_{c,2}(\lambda,z))\geq s_{c,2}$ and from \eqref{eq:condition2slopes}. Thus, \ref{C1} is satisfied.
    \item Conditions \ref{C2} to \ref{C5} follow immediately.   
\end{itemize}
Thus, in both situations, $f_{c,2}$ is a truncated solution associated with $(c,2)$. Since the same may be done for any $c$ attached to the slope $\mu_2=0$ and since, from Lemma \ref{lem:first_slope}, there exists a truncated solution associated with $(c,1)$ for any $c$ attached to the slope $\mu_1$, it follows from Theorem \ref{thm_RS_si_solutions_tronquees} that the equation is regular singular at $0$.
\end{proof}



\subsection{Proof of Theorem \ref{thm:p_varies}}
We are now ready to prove Theorem \ref{thm:p_varies}. Without any loss of generality, we may and will suppose that $\min \val a_i = 0$.

Suppose that the equation is regular singular at $0$ when $p$ is equal to some integer $p_1> \max_i \val a_i$. Then, it follows from Corollary \ref{coro:sensdirect} that its Newton polygon has either one slope or two slopes, the second one being null. We study separately both situations. 



\subsubsection*{Case 1: The Newton polygon has only one slope}
We consider two subcases.

\subsubsection*{Subcase 1.1: $\val a_0 \geq \val a_m$}
Then $\val a_m=\min_j\val a_j = 0$ and, since the Newton polygon has only one slope, for every integer $i\in [1,m-1]$, 
$$
\frac{\val a_i - \val a_0}{p_1^i - 1} \geq \frac{- \val a_0}{p_1^m - 1}\,.
$$
This can be reformulated as
\begin{equation}\label{eq:val_ai}
\val a_i \geq \val a_0\left(1- \frac{p_1^i - 1}{p_1^m - 1} \right).
\end{equation}
Furthermore, since $p_1 > \val a_0$, we have
$$
\val a_0 \frac{p_1^{i}-1}{p_1^m-1}<\frac{p_1^{i+1}-p_1}{p_1^m-1}<1\, .
$$
Then, it follows from \eqref{eq:val_ai} that $\val a_i > \val a_0 - 1$. Since $\val a_i$ is an integer we eventually obtain $\val a_i \geq \val a_0$. Thus, for any $p\geq 2$, the Newton polygon has only one slope and it follows from Proposition \ref{prop:one_slope} that the equation is regular singular at $0$ for any $p \geq 2$. This proves Subcase 1.1.

\subsubsection*{Subcase 1.2: $\val a_0 < \val a_m$} Since the Newton polygon with the Mahler parameter $p_1$ has only one slope here, then $\val a_0=\min\val a_i = 0$ (see the beginning of this proof) and $\val a_i\geq 1$ for any $i \in [1,m]$. It follows that, for any $p \geq \val a_m$ and any $i \in [1,m]$,
$$
\frac{\val a_i - \val a_0}{p^i - 1} \geq \frac{1}{p^i-1} \geq \frac{1}{p^{m-1}-1} 
\geq \frac{p}{p^m-1} \geq   
\frac{\val a_m}{p^m - 1}=
\frac{\val a_m - \val a_0}{p^m - 1}.
$$
Hence, for any $p \geq \val a_m$, the line from $(1, \val a_0)$ to $(p^m, \val a_m)$ is an edge of the Newton polygon with parameter $p$. Thus, it has only one slope and it follows from Proposition~\ref{prop:one_slope} that the equation is regular singular at $0$. This proves Subcase~1.2.

\medskip


\subsubsection*{Case 2: The Newton polygon has two slopes, the second one being null}
Reasoning as in Subcase 1.1 for each one of the two slopes, we obtain that, for any $p\geq 2$ the Newton polygon has two slopes, the second one being null. Since the equation is regular singular at $0$ when $p$ is equal to $p_1$, it follows from Proposition~\ref{prop:a_m_tronques} that
   $$
    \sum_{i=0}^m \underline{a_i}(z)\lambda^i 
    \in (\lambda - c)^{m_{c,2}}\K[\lambda,z]
    $$
    for all exponent $c$ attached to the slope $\mu_2=0$. 
    However, the above expression do not depend on the integer $p$. Thus, it holds for any $p\geq 2$. Thus, it follows from Proposition \ref{prop:a_m_tronques} that the equation is regular at $0$ for any $p > \max_i \val a_i$. This ends the proof of Theorem \ref{thm:p_varies}.


